#define LOG_DEBUG 0
#define LOG_INFO 1
#define LOG_WARN 2
#define LOG_ERROR 3

typedef enum { LOSSLESS, LOSSY } TransformationMode;

void log(int level, const char *msg) {
    if (level <= LOG_DEBUG || LOG_DEBUG == 1) {
        printf("[DEBUG] %s\n", msg);
    } else if (level <= LOG_INFO || LOG_INFO == 1) {
        printf("[INFO] %s\n", msg);
    } else if (level <= LOG_WARN || LOG_WARN == 1) {
        printf("[WARNING] %s\n", msg);
    } else if (level <= LOG_ERROR || LOG_ERROR == 1) {
        fprintf(stderr, "[ERROR] %s\n", msg);
    }
}

int readFile(const char *filename, void **data) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        log(LOG_ERROR, "Failed to open file: %s", filename);
        return -1;
    }

    struct stat fileStat;
    fstat(fd, &fileStat);
    *data = malloc(fileStat.st_size);

    if (read(fd, *data, fileStat.st_size) != fileStat.st_size) {
        log(LOG_ERROR, "Failed to read file: %s", filename);
        free(*data);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int writeFile(const char *filename, const void *data, size_t size) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IXUSR);

    if (fd < 0) {
        log(LOG_ERROR, "Failed to create file: %s", filename);
        return -1;
    }

    if (write(fd, data, size) != size) {
        log(LOG_ERROR, "Failed to write file: %s", filename);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

