        return -1;
    }

    const char *inputFile = argv[1];
    const char *outputFile = argv[2];
    const char *rules = argv[3];
    TransformationMode transformMode = (TransformationMode)strtoul(argv[4], NULL, 10);
    int loggingLevel = strtoul(argv[5], NULL, 10);

    void *inputData;
    if (readFile(inputFile, &inputData) < 0) {
        return -1;
    }

    parseRules(rules, inputData);

