    HostData data;
    time_t last_access;
    double avg_response_time;
    struct Entry *next;
} Entry;

Entry* head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void log_event(const char *message) {
    // Implement logging using RFD library
}

int resolve_dns(const char *hostname, HostData *data) {
    struct hostent *host = gethostbyname(hostname);
    if (!host) {
        return -1;
    }
    strncpy(data->hostname, hostname, sizeof(data->hostname));
    strncpy(data->protocol, "TCP", sizeof(data->protocol)); // Default to TCP
    data->port = ntohs(host->h_addrtype == AF_INET ? *(uint16_t*)host->h_addr : 0);
    return 0;
}

void process_line(const char *line) {
    size_t len = strlen(line);
    if (len > 256 || line[len - 1] != '\n') {
        log_event("Error: Malformed or too long line.");
        return;
    }

    HostData data;
    memset(&data, 0, sizeof(HostData));
    if (resolve_dns(line, &data)) {
        log_event("Error: Failed to resolve DNS for hostname.");
        return;
    }

    Entry *new_entry = malloc(sizeof(Entry));
    if (!new_entry) {
        log_event("Error: Out of memory.");
        return;
    }
    new_entry->data = data;
    new_entry->last_access = time(NULL);
    new_entry->avg_response_time = 0.0;
    new_entry->next = head;
    head = new_entry;
}

void cleanup() {
    Entry *current, *next;
    pthread_mutex_lock(&list_lock);
    current = head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    pthread_mutex_unlock(&list_lock);
}

void signal_handler(int signum) {
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "f:")) != -1) {
        switch (opt) {
            case 'f':
                // Open configuration file and process lines with process_line()
                break;
            default:
                fprintf(stderr, "Usage: %s [-f <config_file>]\n", argv[0]);
                return -1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Rest of the code for logging, averaging response time and other tasks.
}
