#include <stdio.h>
#include <stdint.h>
#include <pthread.h>
#include <sys/stat.h>
#include <time.h>

typedef enum { DEBUG, INFO, WARNING, ERROR } log_level;

struct logger {
    FILE *fp;
    char filename[256];
    pthread_mutex_t lock;
    size_t max_size;
    time_t rotation_time;
};

void rotate(struct logger *logger) {
    struct stat file_stat;
    if (stat(logger->filename, &file_stat) != 0) return;

    // Check size or time-based rotation policy
    if (file_stat.st_size > logger->max_size ||
        difftime(time(NULL), logger->rotation_time) >= 86400) {
        fclose(logger->fp);
        sprintf(logger->filename, "log_%lu.txt", time(NULL));
        logger->fp = fopen(logger->filename, "w");
    }
}

void log(struct logger *logger, log_level level, const char *msg) {
    pthread_mutex_lock(&logger->lock);
    rotate(logger);
    fprintf(logger->fp, "[%lu] [%s] %s\n", time(NULL),
            level_names[level], msg);
    pthread_mutex_unlock(&logger->lock);
}

int main() {
    struct logger logger = { .fp = stdout, .max_size = 1048576 }; // 1 MB
    strcpy(logger.filename, "log.txt");
    pthread_mutex_init(&logger.lock, NULL);

    // Initialize other threads here

    log(&logger, DEBUG, "Starting application...");

    return 0;
}
