const express = require('express');
const router = express.Router();
const mongoose = require('mongoose');
const passport = require('passport');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// Cache library
const cache = require('memory-cache');

// Mongoose models
const Resource = mongoose.model('Resource', new mongoose.Schema({ ... }));
const DependentResource = mongoose.model('DependentResource', new mongoose.Schema({ ... }));

router.put('/resource/:id', passport.authenticate('jwt'), async (req, res) => {
  try {
    // Validate incoming data against predefined schema
    const validData = validate(req.body);

    if (!validData) return res.status(400).send({ error: 'Invalid data' });

    // Retrieve the existing resource from cache (or DB)
    let resource = cache.get(`resource_${req.params.id}`);
    if (!resource) resource = await Resource.findById(req.params.id);
    if (!resource) return res.status(404).send({ error: 'Resource not found' });

    // Update the resource with only the provided keys (partial updates)
    Object.assign(resource, validData);

    // Save the updated resource and update cache
    await resource.save();
    cache.put(`resource_${req.params.id}`, resource);

    res.status(200).send(resource);
  } catch (error) {
    console.error(error);
    res.status(500).send({ error: 'Internal server error' });
  }
});

router.delete('/resource/:id', passport.authenticate('jwt'), async (req, res) => {
  try {
    // Retrieve the existing resource from cache or DB
    let resource = cache.get(`resource_${req.params.id}`);
    if (!resource) resource = await Resource.findById(req.params.id);
    if (!resource) return res.status(404).send({ error: 'Resource not found' });

    // Perform cascading actions to update dependent resources
    await DependentResource.updateMany({ resourceId: req.params.id }, { $set: { resourceId: null } });

    // Remove from cache and DB
    await Resource.findByIdAndRemove(req.params.id);
    cache.del(`resource_${req.params.id}`);

    res.status(204).send();
  } catch (error) {
    console.error(error);
    res.status(500).send({ error: 'Internal server error' });
  }
});
```

