public LoggingConfig ParseLoggingConfig()
{
    var loggingConfig = new LoggingConfig();
    const string configFile = "config.xml";
    string defaultDirName = GetDefaultDirectoryName();
    string containerizedDirName = Environment.GetEnvironmentVariable("LOGGING_DIR");

    if (string.IsNullOrEmpty(containerizedDirName))
        Directory = defaultDirName;
    else
        Directory = containerizedDirName;

    var loggingDir = Path.Combine(Directory, GetApplicationVersion());

    try
    {
        if (!Directory.Exists(loggingDir))
            Directory.CreateDirectory(loggingDir);
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error creating logging directory: {ex.Message}");
        return loggingConfig;
    }

    try
    {
        var xmlDoc = new XmlDocument();
        xmlDoc.Load(configFile);

        var logLevelNode = xmlDoc.SelectSingleNode("/logging/logLevel");
        if (logLevelNode != null)
            loggingConfig.LogLevel = logLevelNode.InnerText;

        return loggingConfig;
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error loading configuration file: {ex.Message}");
        return loggingConfig;
    }
}

private string GetDefaultDirectoryName()
{
