        activity = Activity(log_entry['activity'])
        self.current_session.activities.append(activity)
        self.current_session.duration += activity.duration
        self.redis_client.zincrby('sessions:' + str(self.current_session.session_id), activity.duration, 1)

    def process_logs(self, logs: List[Dict[str, str]]):
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = [executor.submit(self.process_log_entry, log_entry) for log_entry in logs]
            executor.shutdown(wait=False)
            for future in concurrent.futures.as_completed(futures):
                future.result()

    def start_session(self, session_id: str):
        self.current_session = Session(session_id)
        self.current_session.start_time = time.time()
        self.redis_client.zadd('sessions', {str(self.current_session.start_time): 1})
        self.redis_client.set('current_session:' + session_id, json.dumps(self.current_session.__dict__))

    def end_session(self, session_id: str):
        if self.current_session and self.current_session.session_id == session_id:
            self.current_session.end_time = time.time()
            self.redis_client.set('current_session:' + session_id, json.dumps(self.current_session.__dict__))
        else:
            print(f'Trying to end non-existent or incorrect session: {session_id}')

    def summarize_sessions(self):
        unique_users = set()
        total_duration = 0
        num_sessions = 0
        average_session_length = 0

        for session in self.redis_client.zrange('sessions', 0, -1):
            session_dict = json.loads(self.redis_client.get('current_session:' + session))
            unique_users.add(session_dict['session_id'])
            total_duration += float(session)
            num_sessions += 1
            average_session_length = total_duration / num_sessions if num_sessions > 0 else 0

        return {'unique_users': len(unique_users), 'total_activity_duration': total_duration, 'average_session_length': average_session_length}

