```php
<?php

namespace App\Library;

class RandomString
{
    private $charset = '';
    private $length = 0;

    public function __construct($charset, $length)
    {
        $this->charset = str_replace(' ', '', $charset);
        $this->length = (int)$length;
    }

    public function generate(): string
    {
        if ($this->length > 256 || $this->length < 0) {
            throw new \Exception("Invalid length specified.");
        }

        $rand_string = '';
        $charset_len = strlen($this->charset);

        for ($i = 0; $i < $this->length; $i++) {
            $rand_string .= $this->charset[random_int(0, $charset_len - 1)];
        }

        return $rand_string;
    }
}
```

