#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

// FSA structure definition
typedef struct FSA {
    int state;
    int *next;
} FSA;

// Lock for synchronization
pthread_mutex_t lock;

// Function to dynamically manage the list of states in a given FSA
FSA* expand_state_list(int *current_states, int num_states, FSA *fsa, int last_state, int max_capacity) {
    if (max_capacity <= 0)
        return NULL;

    // Allocate memory for the new state list with an initial capacity of num_states
    FSA *new_list = malloc(num_states * sizeof(FSA));
    if (!new_list)
        return NULL;

    // Copy current states into the new state list
    memcpy(new_list, current_states, num_states * sizeof(int));

    // Update the 'next' pointer of the last state in the list to point to the newly created state list
