    OctreeNode(size_t capacity, int depth = 0) : capacity(capacity), depth(depth), leafCount(1) {}
};

class Octree {
public:
    Octree(size_t featureSize, size_t numLeafNodes, size_t dataCapacity, size_t maxDepth)
