    }

private:
    bool createNode(OctreeNode* parent, int depth) {
        if (depth >= maxDepth_ || !parent) {
            return false;
        }

        std::unique_ptr<OctreeNode> node(new OctreeNode(dataCapacity_));
        size_t leafCount = node->leafCount;

        // Calculate the index of this node within its parent's eight children
        int index = (depth % 6) * 2 + (depth / 6);
        if (!parent->children[index]) {
            parent->children[index] = std::move(node).release();
            if (leafCount >= numLeafNodes_ && depth < maxDepth_) {
                return true;
            }
        }

        for (int i = index + 1; i < 8; ++i) {
            if (!parent->children[i]) {
                parent->children[i] = node.get();
                if (leafCount >= numLeafNodes_ && depth < maxDepth_) {
                    return true;
                }
                break;
            }
        }

        for (int i = 0; i < index; ++i) {
            if (!parent->children[i]) {
                parent->children[i] = node.get();
                if (leafCount >= numLeafNodes_ && depth < maxDepth_) {
                    return true;
                }
            }
        }

        for (auto child : *node) {
            if (createNode(child, depth + 1)) {
                return true;
            }
        }

        return false;
    }

    void updateData() {
        // Implement handling of network latency and data throughput here
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        // Periodically fetch new data from the external data source and propagate it down the octree
    }

    size_t numThreads_;
    size_t featureSize_;
    size_t numLeafNodes_;
    size_t dataCapacity_;
    size_t maxDepth_;
    OctreeNode* root_;
};
