using System;
using System.Collections.Generic;
using System.Numerics;
using System.Runtime.Caching;
using System.Text;

public class CustomRandomGenerator
{
    private ObjectCache _memoryCache;
    private BigInteger _seed;
    private BigRational _minValue;
    private BigRational _maxValue;

    public CustomRandomGenerator()
    {
        _memoryCache = MemoryCache.Default;
        ResetSeed();
    }

    public BigRational MinValue
    {
        get => _minValue;
        set
        {
            if (value > _maxValue || value < BigRational.Zero)
                throw new ArgumentOutOfRangeException(nameof(value), "Minimum value must be less than or equal to maximum value and greater than zero.");
            _minValue = value;
        }
    }

    public BigRational MaxValue
    {
        get => _maxValue;
        set
        {
            if (value < MinValue || value <= _minValue)
                throw new ArgumentOutOfRangeException(nameof(value), "Maximum value must be greater than minimum value and greater than zero.");
            _maxValue = value;
        }
    }

    public BigRational GetRandomFloat() => (BigRational)(_memoryCache.GetOrCreateItem(new CacheItemPolicy
    {
        SlidingExpiration = new TimeSpan(0, 15, 0) // Cache for 15 minutes.
    }, () => GetRandomWithSeed(_seed).Item1));

    public int GetRandomInt() => (int)(GetRandomFloat().ToBigIntegerExact());

    public BigRational GetRandomExclusiveFloat() => (BigRational)(_memoryCache.GetOrCreateItem(new CacheItemPolicy
    {
        SlidingExpiration = new TimeSpan(0, 15, 0) // Cache for 15 minutes.
    }, () => GetRandomWithSeed(_seed).Item2));

    public int GetRandomExclusiveInt() => (int)(GetRandomExclusiveFloat().ToBigIntegerExact());

    public Tuple<BigRational, long> GetRandomWithSeed(long seed)
    {
        _seed = seed;
        return Tuple.Create(_minValue, GenerateNextRandomNumber());
    }

    public void ResetSeed() => _seed = DateTime.UtcNow.Ticks;

    public override string ToString() => $"MinValue: {MinValue}, MaxValue: {MaxValue}";

    private BigInteger GenerateNextRandomNumber()
    {
        var m = (BigInteger)Math.Pow(2, 48); // 48-bit integer representation of the current timestamp
        var ticksSinceEpoch = (_seed * 16807) & m;
        return (ticksSinceEpoch * 28353) % UInt32.MaxValue;
    }
}
