#include <getopt.h>

typedef struct ConfigSource {
    const char *name;
    int (*load)(void*, const char*);
    void* user_data;
} ConfigSource;

typedef struct ConfigSetting {
    const char *key;
    const char *value;
} ConfigSetting;

typedef struct ConfigManager {
    size_t count;
    ConfigSetting** settings;
    ConfigSource* sources;
    size_t source_count;
    void* fallback_data;
} ConfigManager;

static int load_file(void* user_data, const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) return 0;

    off_t filesize = lseek(fd, 0, SEEK_END);
    void* data = mmap(NULL, filesize, PROT_READ, MAP_PRIVATE, fd, 0);

    if (data == MAP_FAILED) {
        close(fd);
        return 0;
    }

    int result = parse_config((char*)data, sizeof(ConfigSetting), user_data);
    munmap(data, filesize);
    close(fd);

    return result;
}

static int load_env(void* user_data, const char *key) {
    char* value = getenv(key);
    if (!value) return 0;

    ConfigSetting setting = {.key = strdup(key), .value = strdup(value)};
    push_setting(user_data, &setting);
    return 1;
}

static int load_args(void* user_data, const char *arg) {
    char* keyval = strchr(arg, '=');
    if (!keyval) return 0;

    ConfigSetting setting = {.key = strndup(arg, keyval - arg), .value = strdup(keyval + 1)};
    push_setting(user_data, &setting);
    return 1;
}

ConfigManager* config_manager_init(const ConfigSource sources[], size_t source_count, void* fallback_data) {
    ConfigManager* manager = malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    manager->sources = malloc(source_count * sizeof(ConfigSource));
    if (!manager->sources) goto fail;
    memcpy(manager->sources, sources, source_count * sizeof(ConfigSource));

    manager->source_count = source_count;
    manager->fallback_data = fallback_data;
    manager->count = 0;

    for (size_t i = 0; i < source_count; ++i) {
        if (!manager->sources[i].load) continue;

        ConfigSetting* settings = manager->settings;
        size_t settings_capacity = manager->count;
        void* user_data = manager;

        (*manager->sources[i].load)(user_data, ""); // Load initial empty configuration to trigger loading from all sources.

        if (settings_capacity == manager->count) {
            settings = realloc(settings, manager->count * 2 * sizeof(ConfigSetting));
            if (!settings) goto fail;
            manager->settings = settings;
        }

        (*manager->sources[i].load)(user_data, manager->sources[i].name);
    }

    return manager;
fail:
    free(manager->sources);
    free(manager);
    return NULL;
}

bool has_setting(const ConfigManager* manager, const char *key) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->settings[i]->key, key) == 0) return true;
    }
    return false;
}

const char* get_setting(const ConfigManager* manager, const char *key) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->settings[i]->key, key) == 0) return manager->settings[i]->value;
    }

    if (manager->fallback_data) {
        ConfigSetting fallback = {.key = strdup(key), .value = strdup("")};
        parse_config((char*)manager->fallback_data, sizeof(ConfigSetting), &fallback);
        return fallback.value;
    }

    return NULL;
}
```

