size_t num_workers = 4;
struct ThemeCache {
    char path[256];
    char *data;
    size_t len;
    pthread_mutex_t mutex;
} cache[128];

void *parse_line(void *arg) {
    FILE *fp = (FILE *) arg;
    char *line = NULL;
    size_t linecap = 0, linelen = 0;
    while ((getline(&line, &linecap, fp) != -1)) {
        // Parse line here and calculate average field
    }
    free(line);
}

void load_theme(const char *path) {
    pthread_mutex_lock(&cache_mutex);
    for (size_t i = 0; i < ARRAY_SIZE(cache); ++i) {
        if (!cache[i].data || strcmp(cache[i].path, path)) {
            cache[i] = (struct ThemeCache) { .path = path };
            FILE *fp = fopen(path, "rb");
            if (fp) {
                fseek(fp, 0, SEEK_END);
                size_t len = ftell(fp);
                rewind(fp);
                cache[i].data = mmap(NULL, len, PROT_READ, MAP_PRIVATE, fileno(fp), 0);
                fclose(fp);
                cache[i].len = len;
            } else {
                cache[i].data = NULL;
                cache[i].len = 0;
            }
            pthread_mutex_init(&cache[i].mutex, NULL);
        }
        if (cache[i].data) break;
    }
    pthread_mutex_unlock(&cache_mutex);
}

int main(int argc, char **argv) {
    // Initialize default theme directory or use specified path
    if (argc < 2) strcpy(cache_root, "./themes");
    else strcpy(cache_root, argv[1]);

    // Create and manage worker threads
    pthread_t workers[num_workers];
    for (size_t i = 0; i < num_workers; ++i) {
        FILE *fp;
        char path[256];
        for (int j = 0; j < 100 && (fp = fopen(sprintf(path, "%s/input%d.txt", cache_root, i), "r")) != NULL; ++j) {
            pthread_create(&workers[i], NULL, parse_line, fp);
        }
    }

    // Load themes concurrently for optimal performance
    pthread_t theme_loaders[num_workers];
    char paths[][128] = {"theme1.png", "theme2.png", ...};
    for (size_t i = 0; i < ARRAY_SIZE(paths); ++i) load_theme(paths[i]);

    // Wait for all threads to finish and clean up resources
    for (size_t i = 0; i < num_workers; ++i) pthread_join(workers[i], NULL);

    return 0;
}
