    uint32_t md5[MD5_DIGEST_LENGTH];
    tdata_t sample; // TIFF sample data structure
    sametype_t sample_type;
    unsigned int sample_pos;
    unsigned int bit_depth;
    unsigned int num_samples;
} image_metadata;

image_metadata* process_image(const char *filename) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Could not open file %s\n", filename);
        return NULL;
    }

    tsize_t row_samples = 0, col_samples = 0;
    tdata_t *samples = TIFFGetFieldDefaulted(tif, TIFFTAG_SAMPLESPERPIXEL, &row_samples, &col_samples);
    if (row_samples > 1 || col_samples > 1) {
        fprintf(stderr, "Error: Unsupported number of samples per pixel\n");
        TIFFCLOSE(tif);
        return NULL;
    }

    image_metadata *metadata = malloc(sizeof(image_metadata));
    if (!metadata) {
        fprintf(stderr, "Error: Failed to allocate memory for metadata structure\n");
        TIFTCLOSE(tif);
        return NULL;
    }

    uint16_t bit_depth = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    switch (bit_depth) {
        case 1:
        case 8:
        case 16:
        case 32:
            break;
        default:
            fprintf(stderr, "Error: Unsupported bit depth\n");
            free(metadata);
            TIFTCLOSE(tif);
            return NULL;
    }

    metadata->bit_depth = bit_depth;
    metadata->num_samples = 1; // Assume single sample per pixel

    if (TIFFGetField(tif, TIFFTAG_SAMPLEFORMAT) != SAMPLEFORMAT_UINT) {
        metadata->sample.value.uint = TIFFReadScanline(tif, &metadata->sample.data, 0);
        metadata->sample_type = SAMPLETYPE_UINT;
    } else {
        metadata->sample.value.aShort[0] = TIFFReadScanline(tif, &metadata->sample.data, 0);
        metadata->sample.value.aShort[1] = TIFFReadScanline(tif, &metadata->sample.data + sizeof(uint16_t), 0);
        metadata->sample_type = SAMPLETYPE_SHORT;
    }

    if (row_samples == 0) {
        row_samples = TIFFScanlineSize(tif);
    }
    for (unsigned int y = 1; y < TIFFNumberOfDirectories(tif); ++y) {
        unsigned int x = 0;
        tdata_t *scanline = malloc(row_samples * metadata->num_samples * sizeof(tiff_sample));
        if (!scanline) {
            fprintf(stderr, "Error: Failed to allocate memory for scanline\n");
            TIFTCLOSE(tif);
            free(metadata);
            return NULL;
        }

        if (TIFFReadScanlines(tif, scanline, y, 1) != 1) {
            fprintf(stderr, "Error: Failed to read scanline\n");
            TIFTCLOSE(tif);
            free(metadata);
            free(scanline);
            return NULL;
        }

        for (unsigned int i = 0; i < row_samples * metadata->num_samples; ++i) {
            if (memcmp(&scanline[i], &metadata->sample, sizeof(tiff_sample)) != 0) {
                ++metadata->num_samples;
                metadata->sample = scanline[i];
            }
        }

        free(scanline);
    }

    uint8_t metadata_buffer[MD5_DIGEST_LENGTH + sizeof(image_metadata)];
    image_metadata *serialized_metadata = (image_metadata *)metadata_buffer;
    memcpy(serialized_metadata, metadata, sizeof(image_metadata));
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, serialized_metadata, sizeof(image_metadata));
    MD5_Final(serialized_metadata->md5, &ctx);

    TIFTCLOSE(tif);
    return metadata;
}
