bool processDocument(const std::string& inputFilePath, const std::string& conversionToolPath, const std::string& outputClassName) {
    int retries = 0;
    bool success = false;

    while (retries < MAX_RETRIES) {
        try {
            // Run the conversion tool and write the resulting PDF to a temp file
            std::string tempPdfPath = "temp.pdf";
            system((conversionToolPath + " " + inputFilePath + " " + tempPdfPath).c_str());

