        } catch (const std::exception& e) {
            std::cerr << "Error during conversion or deserialization: " << e.what() << std::endl;
            if(retries >= MAX_RETRIES) {
                std::cerr << "Maximum retries exceeded." << std::endl;
                break;
            }
        }

        ++retries;
    }

    // Delete the temporary PDF file and return the result
    std::remove(tempPdfPath.c_str());
    return success;
