using System;
using System.IO;
using System.Net;
using System.Net.Http;
using System.Net.Security;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;
using Serilog;

public class DirectorySiteIntegrator
{
    private readonly IWebHostBuilder _webHostBuilder;
    private readonly ILogger<DirectorySiteIntegrator> _logger;
    private readonly string _directoryPath;
    private readonly string _siteName;

    public DirectorySiteIntegrator(IWebHostBuilder webHostBuilder, ILogger<DirectorySiteIntegrator> logger, string directoryPath, string siteName)
    {
        _webHostBuilder = webHostBuilder;
        _logger = logger;
        _directoryPath = directoryPath;
        _siteName = siteName;
    }

    public async Task<IWebHost> IntegrateSiteAsync(CancellationToken cancellationToken)
    {
        if (!File.Exists($"{_directoryPath}/web.config")) return null;

        var webHost = _webHostBuilder
            .UseContentRoot(_directoryPath)
            .UseStartup(_siteName)
            .ConfigureAppConfiguration((hostingContext, config) =>
            {
                if (File.Exists($"{_directoryPath}/appsettings.json"))
                    config.AddJsonFile("appsettings.json", optional: false, reloadOnChange: true);

                if (File.Exists($"{_directoryPath}/appsettings.{config.HostingEnvironment.EnvironmentName}.json"))
                    config.AddJsonFile($"appsettings.{config.HostingEnvironment.EnvironmentName}.json", optional: false, reloadOnChange: true);
            })
            .UseUrls($"https://{_siteName}")
            .UseSerilog();

        try
        {
            await webHost.StartAsync(cancellationToken);

            // Periodic health checks and error logging implementation
            Task.Factory.StartNew(async () =>
            {
                while (!cancellationToken.IsCancellationRequested)
                {
                    try
                    {
                        var httpClient = new HttpClient();
                        await httpClient.GetAsync($"https://{_siteName}/health");
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Site health check failed.");
                        // Add comprehensive error logging here
                    }

                    await Task.Delay(TimeSpan.FromSeconds(30), cancellationToken);
                }
            }, TaskCreationOptions.LongRunning);

            return webHost;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to integrate site.");
            throw;
        }
    }
}
```

