using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using BCrypt.Net;

namespace AesDecryption
{
    public class AesDecrypter
    {
        private readonly ILogger<AesDecrypter> _logger;
        private const int SaltSize = 16;
        private const int KeyDerivationIterations = 1000;
        private RNGCryptoServiceProvider _rngCrypto = new RNGCryptoServiceProvider();

        public AesDecrypter(ILogger<AesDecrypter> logger)
        {
            _logger = logger;
        }

        public byte[] Decrypt(string cipherText, string password)
        {
            if (string.IsNullOrEmpty(cipherText))
                throw new ArgumentException("Cipher text cannot be null or empty.", nameof(cipherText));

            var key = DeriveKeyFromPassword(password);
            byte[] iv;

            using (var ms = new MemoryStream(Convert.FromBase64String(cipherText)))
            {
                if (ms.Length % PKCS7.BlockSize != 0)
                    throw new ArgumentException("Input data is not compatible with PKCS7 padding.", nameof(cipherText));

                iv = ms.ToArray()[..PKCS7.BlockSize];
                var encryptedData = ms.ToArray()[PKCS7.BlockSize..];

                using (var aesAlg = AES.Create())
                {
                    aesAlg.Key = key;
                    aesAlg.IV = iv;
                    var decryptor = aesAlg.CreateDecryptor(key, iv);

                    using (var msDecrypted = new MemoryStream())
                    {
                        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                            cs.CopyTo(msDecrypted);

                        return msDecrypted.ToArray();
                    }
                }
            }
        }

        private byte[] DeriveKeyFromPassword(string password)
        {
            var salt = new byte[SaltSize];
            _rngCrypto.GetBytes(salt);
            var hashed = BCrypt.Net.BCrypt.HashPassword(password + salt, KeyDerivationIterations);
            return Array.FindLastIndex(hashed, b => b < 128) <= SaltSize ? Array.Copy(hashed, 0, new byte[32], 0, 32) : Array.Copy(hashed, 0, new byte[64], 0, 64);
        }
    }
}
