    public class DataLoader
    {
        private const string SharedNetworkPath = @"\\server\share\data";
        private const int CacheSize = 1000;
        private const int MaxRetries = 5;
        private const double ExponentialBackoffFactor = 2.0;
        private readonly ConcurrentDictionary<string, object> _cache;
        private readonly TimeSpan _retryDelay;

        public DataLoader()
        {
            _cache = new ConcurrentDictionary<string, object>(CacheSize);
            _retryDelay = TimeSpan.FromSeconds(1);
        }

        public async Task<T> DeserializeAsync<T>(string fileName)
        {
            var cacheKey = GetCacheKey<T>(fileName);

            if (_cache.TryGetValue(cacheKey, out var cachedData))
                return (T)cachedData; // Return from cache if available

            var filePath = GetFullFilePath(fileName);
            var fileLock = new FileStream(filePath + @"\lock", FileMode.OpenOrCreate, FileAccess.Write, FileShare.None);
            try
            {
                fileLock.Lock(Timeout.Infinite);

                using (var file = new FileStream(filePath, FileMode.Open, FileAccess.Read))
                {
                    var serializer = new BinaryFormatter();
                    var deserializedData = await Task.Run(() => serializer.DeserializeAsync(file));

                    if (CheckVersionCompatibility<T>(deserializedData))
                    {
                        _cache[GetCacheKey<T>(fileName)] = deserializedData; // Cache the data
                        return (T)deserializedData;
                    }
                }
            }
            catch (Exception ex) when (!ex.Message.Contains("The handle is not yet open"))
            {
                Console.WriteLine($"Error while loading file '{fileName}': {ex.Message}");
            }
            finally
            {
                fileLock.Dispose();
            }

            for (int i = 0; i < MaxRetries; i++)
            {
                try
                {
                    await Task.Delay(_retryDelay);
                    return await DeserializeAsync<T>(fileName); // Retry with backoff delay
                }
                catch (Exception ex) when (!ex.Message.Contains("The handle is not yet open"))
                {
                    Console.WriteLine($"Retry #{i + 1} failed for file '{fileName}': {ex.Message}");
                }
            }

            Console.WriteLine($"Failed to load file '{fileName}' after retries.");
            throw new Exception("Failed to load data from file");
        }

        private string GetFullFilePath(string fileName) => Path.Combine(SharedNetworkPath, fileName);

        private static T CheckVersionCompatibility<T>(object deserializedData)
        {
            // Implement your versioning and backward compatibility logic here
            return default;
        }

        private static string GetCacheKey<T>(string fileName) => $"{typeof(T).FullName}_{fileName}";
    }
}
