const axios = require('axios');
const { promisify } = require('util');
const cache = new Map();
const chalk = require('chalk');
const log = console.log;

const fetchData = async (url, dataType) => {
  url = url.trim();
  if (!cache.has(url)) {
    try {
      const response = await axios.get(url);

      // Cache the result for future requests to the same URL
      cache.set(url, response.data);

      log(`${chalk.green('Successfully fetched data from')} ${url}`);
      return response.data;
    } catch (error) {
      if (error.response && error.response.status !== 204) { // 204 indicates 'No Content', implying the server doesn't have any data to provide
        log(`${chalk.red('Error fetching data from')} ${url}:`, error.message);
      } else {
        log(`${chalk.yellow('Unable to reach')} ${url}. Trying another endpoint...`);
      }
    }
  }

  // Attempt to switch to a different endpoint if the primary one is unavailable or returning an empty response
  const fallbackUrls = [
    'https://example-fallback1.com/api/data',
    'https://example-fallback2.com/api/data'
  ].find(fallbackUrl => !cache.has(fallbackUrl));

  if (fallbackUrl) {
    try {
      const response = await axios.get(fallbackUrl);
      cache.set(fallbackUrl, response.data);
      log(`${chalk.green('Successfully fetched data from fallback URL')} ${fallbackUrl}`);
      return response.data;
    } catch (error) {
      if (error.response && error.response.status !== 204) {
        log(`${chalk.red('Error fetching data from fallback URL')} ${fallbackUrl}:`, error.message);
      } else {
        log(`${chalk.yellow('Unable to reach fallback URL')}. Retrying primary endpoint...`);
      }
    }
  }

  throw new Error(`Failed to fetch data from any available endpoints for '${dataType}' data type.`);
};

// Promisify the axios.get method for easier usage in async/await functions
const get = promisify(axios.get);

module.exports = { fetchData, get };
```

