// Concurrent access handling structure definition
struct AccessHandle<T> {
    data: Arc<RwLock<T>>,
    sender: Sender<T>,
}

impl<T> AccessHandle<T> {
    fn new(data: T) -> (Arc<RwLock<T>>, Sender<T>) {
        let data = Arc::new(RwLock::new(data));
        let (tx, rx) = crossbeam_channel::unbounded();
        (data, tx)
    }

    fn get(&self) -> RwLockReadGuard<T> {
        self.data.read().unwrap()
    }

    fn set(&self, data: T) {
        let mut guard = self.data.write().unwrap();
        *guard = data;
        self.sender.send(data).unwrap();
    }
}

