import json
from functools import lru_cache
from typing import Dict, Any, Type
import threading
import time
import redis

class JSONParserRegistry:
    def __init__(self):
        self.registry = {}

    def register(self, id: str, parser_cls: Type[JSONParser]):
        if id in self.registry:
            raise KeyError(f"ID '{id}' already registered.")
        self.registry[id] = parser_cls

    def get_parser_cls(self, id: str) -> Type[JSONParser]:
        return self.registry.get(id)

class BaseJSONParser:
    def __init__(self, **kwargs):
        self.__dict__.update(kwargs)

    @staticmethod
    def from_json(json_str: str, id: str = None) -> 'BaseJSONParser':
        parser_cls = JSONParserRegistry().get_parser_cls(id) or BaseJSONParser
        parsed_obj = parser_cls.from_json_string(json_str)
        return parsed_obj

    @classmethod
    def from_json_string(cls, json_str: str) -> 'BaseJSONParser':
        try:
            data = json.loads(json_str)
            instance = cls(**data)
            return instance
        except ValueError as e:
            raise ValueError(f"Invalid JSON structure: {e}")

class CacheManager:
    def __init__(self, cache: redis.Redis, ttl: int):
        self.cache = cache
        self.ttl = ttl

    @lru_cache(maxsize=None)
    def get_cached(self, key: str) -> Any:
        cached_data = self.cache.get(key)
        if cached_data is None:
            return None
        self.cache.expire(key, self.ttl)
        return json.loads(cached_data)

    def set_cached(self, key: str, data: Any):
        self.cache.setex(key, self.ttl, json.dumps(data))

class JSONParser(BaseJSONParser):
    def __init__(self, id: str = None, cache_manager=None):
        super().__init__()
        self.id = id
        if cache_manager is not None:
            self.cache_manager = cache_manager

    @classmethod
    def from_json_string(cls, json_str: str, **kwargs) -> 'JSONParser':
        parser = super().from_json_string(json_str)
        if parser.id is None and kwargs.get("id"):
            parser.id = kwargs["id"]
        if parser.cache_manager is not None:
            parsed_obj = parser
        else:
            parsed_obj = super().from_json_string(parser.cache_manager.get_cached(parser.id) or json_str, id=parser.id)
        return parsed_obj
```

