typedef struct IntArray {
    size_t capacity;
    size_t size;
    int* data;
} IntArray;

IntArray* create_int_array(size_t initial_capacity) {
    IntArray* array = (IntArray*)malloc(sizeof(IntArray));
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = (int*)calloc(initial_capacity, sizeof(int));
    return array;
}

void resize_int_array(IntArray* array) {
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(int));
    }
}

bool push_int(IntArray* array, int value) {
    if (array->size == array->capacity) {
        resize_int_array(array);
    }
    array->data[array->size] = value;
    array->size++;
    return true;
}

int get_max(const IntArray* array) {
    int max = INT_MIN;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i] > max) {
            max = array->data[i];
        }
    }
    return max;
}

void destroy_int_array(IntArray* array) {
    free(array->data);
    free(array);
}
