#include <vector>
#include <random>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>

namespace NetworkManager {
    class Session {
        public:
            std::mt19937 *rng;
            uint64_t sid;
            std::vector<char> buffer;
            std::mutex mtx;
            std::condition_variable cv;
            bool isDelayed = false;

            Session(std::mt19937 &r, uint64_t s) : rng(&r), sid(s), buffer() {}

            ~Session() {}
    };

    class NetworkInterface {
        public:
            std::set<uint64_t> sessions;
            std::vector<char> buffer;
            std::mutex mtx;

            NetworkInterface() {}

            ~NetworkInterface() {}
    };

    class NetworkManager {
        private:
            static std::mt19937 generator;
            std::map<uint64_t, std::shared_ptr<Session>> sessionsMap;
            std::map<uint64_t, std::shared_ptr<NetworkInterface>> interfacesMap;
            std::vector<std::thread> threads;

        public:
            NetworkManager() : generator() {}

            ~NetworkManager() {
                for (auto &t : threads) t.join();
            }

            void createSession(uint64_t sid) {
                auto session = std::make_shared<Session>(generator, sid);
                sessionsMap[sid] = session;
                auto it = interfacesMap.begin();
                std::advance(it, std::uniform_int_distribution<>(0, interfacesMap.size()-1)(generator) % interfacesMap.size());
                it->second->sessions.insert(sid);
            }

            void destroySession(uint64_t sid) {
                auto it = sessionsMap.find(sid);
                if (it != sessionsMap.end()) {
                    it->second->~Session();
                    interfacesMap[*it->second->sessions.begin()]->sessions.erase(sid);
                    sessionsMap.erase(sid);
                }
            }

            void handleData(uint64_t sid, const std::vector<char> &data) {
                auto it = sessionsMap.find(sid);
                if (it != sessionsMap.end()) {
                    std::unique_lock<std::mutex> lock(it->second->mtx);
                    it->second->buffer.insert(it->second->buffer.end(), data.begin(), data.end());
                    it->second->cv.notify_one();
                }
            }

            void run() {
                for (auto &session : sessionsMap) {
                    threads.emplace_back(
                        [this, session]() {
                            while (true) {
                                std::unique_lock<std::mutex> lock(session.second->mtx);
                                session.second->cv.wait(lock, [this, session]() { return !session.second->buffer.empty(); });

                                auto data = std::move(session.second->buffer);
                                session.second->buffer.clear();

                                // Process data here
                            }
                        }
                    );
                }
            }
    };
}

std::mt19937 NetworkManager::generator;
```

