// Union-Find data structure
typedef struct set {
    int *parent;
    int *rank;
    int count;
} set;

void make_set(set *s, int i) {
    if (s->parent[i] == i) return;
    s->parent[i] = s->parent[s->parent[i]] = i;
    s->rank[i]++;
}

int find(set *s, int i) {
    if (s->parent[i] != i) s->parent[i] = s->parent[s->parent[i]];
    return s->parent[i];
}

void union_sets(set *s, int x, int y) {
    int rootx = find(s, x);
    int rooty = find(s, y);
    if (rootx == rooty) return;

    if (s->rank[rootx] < s->rank[rooty])
        s->parent[rootx] = rooty;
    else if (s->rank[rootx] > s->rank[rooty])
        s->parent[rooty] = rootx;
    else {
        s->parent[rooty] = rootx;
        s->rank[rootx]++;
    }
}

// Function to create and populate the array
void create_array(NFAPI_CRC_INDICATION_PDU_T** data, int N) {
    *data = (NFAPI_CRC_INDICATION_PDU_T*) calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    set sets;
    sets.parent = malloc(N * sizeof(int));
    sets.rank = malloc(N * sizeof(int));
    sets.count = N;

    for (int i = 0; i < N; ++i) {
        make_set(&sets, i);
