class CustomPoolAllocator : public std::nothrow_t, private boost::noncopyable {
public:
    CustomPoolAllocator(boost::thread_pool& pool);
    void* allocate(std::size_t size, std::nothrow_t const&) noexcept;
    void deallocate(void* ptr, std::size_t) noexcept;
    template<typename T>
    T* construct(void* ptr, std::size_t size, std::allocator_traits<std::allocator<T>>::construct_args args = {}) {
        new (ptr) T(std::forward<Args>(args)...);
        return static_cast<T*>(ptr);
    }
    void destroy(void* ptr) noexcept {
        static_cast<std::destructor*>(ptr)->~destructor();
    }
private:
    boost::thread_pool& pool_;
};

class MonitorServiceClient : private boost::noncopyable {
public:
    explicit MonitorServiceClient(boost::asio::io_service& io_service);
    void start(double eventProbability, const std::vector<std::string>& dataSources);
private:
    void handleConfig();
    void handleDataSource(const std::string& dataSource);
    boost::atomic<bool> running_;
    double eventProbability_;
    std::unordered_map<std::string, std::unique_ptr<DataSource>> dataSources_;
    boost::asio::deadline_timer configTimer_;
};

class DataSource : public boost::noncopyable {
public:
    virtual void getData(const std::function<void(const std::string&)>& callback) = 0;
};

class ExternalDataSource : public DataSource {
public:
    explicit ExternalDataSource(std::unique_ptr<boost::asio::streambuf> buffer);
    void getData(const std::function<void(const std::string&)>& callback) override;
private:
    std::unique_ptr<boost::asio::streambuf> buffer_;
};

int main(int argc, char* argv[]) {
    try {
        if (argc != 4) {
            std::cerr << "Usage: monitor_service_client <eventProbability> <dataSource1> <dataSource2> ...\n";
            return 1;
        }
        double eventProbability = std::stod(argv[1]);
        std::vector<std::string> dataSources;
        for (int i = 2; i < argc; ++i) {
            dataSources.push_back(argv[i]);
        }
        boost::asio::io_service io_service;
        MonitorServiceClient client(io_service);
        client.start(eventProbability, std::move(dataSources));
        io_service.run();
    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return 1;
    }
    return 0;
}
