    char line[4096];
    size_t num_values = 0;
    uintmax_t numbers[3] = {0};
    log_function_t original_log = log;

    while (fgets(line, sizeof(line), stdin) != NULL) { // Read lines from standard input
        parse_line(line, numbers, &num_values);
        if (num_values >= 3 && num_values % 3 == 0) { // If we have at least three numbers in the current line
            double avg = average(numbers, 3);
            log("Timestamp: %lu", time(NULL), "Average:", avg); // Log the average with a timestamp
        }
    }

    free(numbers); // Free memory allocated for numbers array
    log_deinit(); // Deinitialize the logging framework

    return 0;
}

void parse_line(const char *line, uintmax_t *numbers, size_t *num_values) {
    char *token = strtok(line, " \t"); // Split line into tokens using spaces and tabs as delimiters
    size_t i = 0;

    while (token != NULL && *num_values < 3) { // Parse each token until we have three numbers or reach the end of the line
        uintmax_t number;
        errno = 0;
        number = strtoumax(token, NULL, 10); // Convert the current token to an unsigned integer

        if (errno != 0) { // If conversion failed due to invalid input
            fprintf(stderr, "Error converting '%s' to an integer\n", token);
            token = strtok(NULL, ""); // Skip the problematic token and continue parsing the rest of the line
            continue;
        }

        numbers[i++] = number;
        *num_values += 1;
        token = strtok(NULL, " \t"); // Move to the next token
    }
}

double average(uintmax_t numbers[], size_t n) {
    double sum = 0.0;
    for (size_t i = 0; i < n; ++i) {
        sum += numbers[i];
    }
    return sum / n;
}
