#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char *base_filename;
    char *directory;
    pthread_mutex_t mutex;
} FileGeneratorArgs;

long long get_sequence_number(const char *filename) {
    char str[12];
    snprintf(str, sizeof(str), "%lld", (long long)time(NULL));
    const char *dot = strchr(str, '.');
    if (!dot) dot = str + strlen(str);
    return atoll((const char*)dot) + 1;
}

char* create_unique_filename(const char *base_filename, const char *directory, int* sequence_number) {
    char *filename = malloc(strlen(directory) + strlen(base_filename) + 20); // Ensure capacity for timestamp and sequence number
    strcpy(filename, directory);
    strcat(filename, "/");
    const char *dot = strrchr(base_filename, '.');
    if (!dot) dot = base_filename + strlen(base_filename);
    strncat(filename, base_filename, (size_t)(dot - base_filename));
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));
    strcat(filename, "_");
    snprintf(filename + strlen(filename), sizeof(filename) - strlen(filename) - 1, "%lld%s", get_sequence_number(base_filename), timestamp);
    *sequence_number = atoll(timestamp + strlen(timestamp) - 5); // Extract sequence number from the timestamp for reuse later
    return filename;
}

void* generate_file(void* args) {
    FileGeneratorArgs *data = (FileGeneratorArgs*)args;
    char base_filename[256];
    strncpy(base_filename, data->base_filename, sizeof(base_filename));
    pthread_mutex_lock(&data->mutex);
    create_unique_filename(base_filename, data->directory, NULL); // Create unique filename without modifying the original base_filename
    pthread_mutex_unlock(&data->mutex);
    // Perform I/O operations here using the generated unique filename
}

char* generate_filename(const char *base_filename, const char *directory) {
    FileGeneratorArgs args = {.base_filename = base_filename, .directory = directory, .mutex = PTHREAD_MUTEX_INITIALIZER};
    pthread_t thread;
    pthread_create(&thread, NULL, generate_file, &args);
    // Wait for the thread to finish generating the unique filename
    pthread_join(thread, NULL);
    return args.base_filename;
}
