#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_unique_rnti(uint32_t* rnti, const uint32_t seed) {
    *rnti = seed++;
    for (size_t i = 1; i < RAND_MAX; ++i) {
        if (*rnti == i + seed) {
            *rnti += RAND_MAX;
        }
    }
}

int is_valid_crcflag(uint8_t crcflag) {
    return (crcflag & 0x0F) == 0 && ((crcflag >> 4) & 0xF0) == 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_array(size_t size, uint32_t seed) {
