        generate_unique_rnti(&(pdu_arr[i].rnti), seed);
        pdu_arr[i].crcflag = rand() & ((1 << (8 - __builtin_ctz(sizeof(NFAPI_CRC_INDICATION_PDU_T) - stride))) - 1);
        while (!is_valid_crcflag(pdu_arr[i].crcflag)) {
            pdu_arr[i].crcflag = rand() & ((1 << (8 - __builtin_ctz(sizeof(NFAPI_CRC_INDICATION_PDU_T) - stride))) - 1);
        }
    }

    return pdu_arr;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T* arr, size_t size) {
