```cpp
#include <iostream>
#include <tiffio.h>

enum class SampleType { UNSIGNED_MIN, UNSIGNED, SIGNED, FLOAT };
struct SampleInfo {
    unsigned int bits;
    SampleType type;
};

typedef std::vector<std::vector<unsigned char>> ImageData;

void parseTiffImage(const char* filename, void (*callback)(ImageData&)) {
    TIFF *tif = TIFFOpen(filename, "r"); // Open the file with read permissions

    if (!tif) {
        std::cerr << "Error: Could not open file: " << filename << std::endl;
        return;
    }

    const char *module = "parseTiffImage";
    const char *test = "Parsing TIFF Image File";
    std::cout << module << ": Start " << test << std::endl;

    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL) < 1 || TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL) > 4) {
        std::cerr << module << ": Error: Unsupported number of samples per pixel" << std::endl;
        TIFClose(tif);
        return;
    }

    unsigned int bitsPerSample = TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE, 8); // Use 8-bit as default value if not specified in the file
    std::vector<SampleInfo> sampleInfos;

    for (unsigned short i = 0; i < TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL); ++i) {
        int bits = TIFFGetFieldDefaulted(tif, TIFFTAG_BITSPERSAMPLE + i, 8); // Use 8-bit as default value if not specified in the file

        if (bits < 1 || bits > 16) {
            std::cerr << module << ": Error: Unsupported number of bits per sample" << std::endl;
            TIFClose(tif);
            return;
        }

        SampleInfo info;
        info.bits = bits;
        info.type = (SampleType)(8 - bits) > 2 ? SampleType::FLOAT : (SampleType)(8 - bits) / 8;
        sampleInfos.push_back(info);
    }

    unsigned int width = TIFFGetField(tif, TIFFTAG_IMAGEWIDTH);
    unsigned int height = TIFFGetField(tif, TIFFTAG_IMAGELENGTH);
    ImageData imageData(height, std::vector<unsigned char>(width * sampleInfos.size()));

    if (TIFFReadEncodedStrip(tif, 0, 0, height, &imageData[0][0], sizeof(unsigned char), NULL) != height) {
        std::cerr << module << ": Error: Failed to read image data" << std::endl;
        TIFClose(tif);
        return;
    }

    std::cout << module << ": Successfully parsed TIFF image file" << std::endl;
    callback(imageData); // Process the parsed image data using the provided callback function

    TIFClose(tif);
}
```

