```c
#include <stdio.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

struct FileInfo {
    char path[256];
    bool hasImage = false;
};

int getExtensionDigits(const char *filename) {
    int extensionStart = strlen(filename);
    for (int i = extensionStart - 1; i >= 0; --i) {
        if (filename[i] == '.') return extensionStart - i;
    }
    return 0;
}

char *modifyAndAddToGraph(const char *originalFileName) {
    struct FileInfo fi;
    strcpy(fi.path, originalFileName);
    if (strcmp(&fi.path[strlen(fi.path) - 4], ".png") == 0 || strcmp(&fi.path[strlen(fi.path) - 3], ".jpg") == 0 ||
        strcmp(&fi.path[strlen(fi.path) - 3], ".jpeg") == 0) {
        fi.hasImage = true;
    }

    int extensionLength = getExtensionDigits(originalFileName);
    if (extensionLength > 0) {
        snprintf(&fi.path[strlen(fi.path) - extensionLength], sizeof(fi.path) - strlen(fi.path), "%d", fi.hasImage ? 2 : 1);
    }

    char *modifiedFileName = malloc(sizeof(char) * (strlen(originalFileName) + 5)); // Adding 4 for extension and 1 for dot
    strncpy(modifiedFileName, originalFileName, strlen(originalFileName));
    if (extensionLength > 0) {
        snprintf(&modifiedFileName[strlen(modifiedFileName)], sizeof(modifiedFileName), ".%s", fi.hasImage ? "png" : "txt");
    } else {
        strncat(modifiedFileName, ".txt", sizeof(modifiedFileName));
    }
    return modifiedFileName;
}
