class PersistentGraph : public GraphDatabase {
private:
    std::vector<std::pair<int, int>> vertices;
    std::unordered_map<std::pair<int, int>, int> edges;

public:
    void populateGraphWithRandomElements(int verticesCount, int edgesCount) override {
        std::default_random_engine generator;
        std::uniform_int_distribution<> vertexDist(0, verticesCount - 1);
        std::uniform_int_distribution<> edgeDist(0, edgesCount - 1);

        vertices.resize(verticesCount);
        for (auto &v : vertices) {
            v = std::make_pair(vertexDist(generator), vertexDist(generator));
        }

        for (int i = 0; i < edgesCount; ++i) {
            auto v1 = vertices[edgeDist(generator)];
            auto v2 = vertices[edgeDist(generator)];
            if (v1 != v2) {
                edges[std::make_pair(v1.first, v1.second)] = v2.first;
                edges[std::make_pair(v2.first, v2.second)] = v1.first;
            } else {
                --i;
            }
        }
    }
};
```

