[' Here is a basic implementation of a logging system in C using a linked list for asynchronous, non-blocking logging and a thread pool to handle concurrent access safely. This example uses a simple configuration file format (INI-like) for flexibility.

First, let's create a Logger struct and its functions:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <ini.h>

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    pthread_t worker_threads[NUM_THREADS];
    LoggerEntry* head;
} Logger;

struct LoggerEntry {
    enum Level level;
    char* message;
    struct LoggerEntry *next;
};

enum Level {
    DEBUG,
    INFO,
    WARNING,
    ERROR
};

void logger_init(Logger* logger) {
    // Initialize mutex and condition variable
    pthread_mutex_init(&logger->mutex, NULL);
    pthread_cond_init(&logger->cond, NULL);

    // Create worker threads
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&logger->worker_threads[i], NULL, log_worker, logger);
    }
}

void logger_deinit(Logger* logger) {
    // Clean up worker threads
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(logger->worker_threads[i], NULL);
    }

    // Free memory
    LoggerEntry *entry, *temp;
    for (entry = logger->head; entry != NULL; ) {
        temp = entry;
        entry = entry->next;
        free(temp->message);
        free(temp);
    }

    // Destroy mutex and condition variable
    pthread_mutex_destroy(&logger->mutex);
    pthread_cond_destroy(&logger->cond);
}

void log(Logger* logger, enum Level level, const char* message) {
    LoggerEntry *entry = malloc(sizeof(LoggerEntry));
    entry->level = level;
    entry->message = strdup(message);
    entry->next = NULL;

    pthread_mutex_lock(&logger->mutex);
    logger->head = entry;
    pthread_cond_signal(&logger->cond);
    pthread_mutex_unlock(&logger->mutex);
}
```

Next, we define the log_worker function that will handle logging in parallel:

```c
void* log_worker(void* arg) {
    Logger* logger = (Logger*)arg;

    while (1) {
        pthread_mutex_lock(&logger->mutex);

        // Wait for a new log entry or exit condition
        while (logger->head == NULL) {
            pthread_cond_wait(&logger->cond, &logger->mutex);
            if (!pthread_equal(pthread_self(), logger->worker_threads[0])) return NULL;
        }

        LoggerEntry* current = logger->head;
        logger->head = current->next;
        pthread_mutex_unlock(&logger->mutex);

        // ... Your code to handle the log entry goes here. For now, we will simply print it.
        printf("[%s] %s\n", level_to_string(current->level), current->message);
        free(current->message);
        free(current);
    }
}
```

