using System.Threading;

public struct DecryptionKeyAndIV
{
    public byte[] Key;
    public byte[] IV;
}

public delegate void ErrorCallback(int errorCode);

public int fetchAndDecryptElement(string xmlDoc, string base64EncodedName, HttpClient connection, string title, ErrorCallback callback, List<DecryptionKeyAndIV> decryptionKeys)
{
    if (string.IsNullOrEmpty(xmlDoc)) return 1; // XML document is empty or null
    if (string.IsNullOrEmpty(title)) return 2; // Connection has no title
    if (callback == null) return 3; // Callback function is null

    var xdoc = XDocument.Parse(xmlDoc);
    var element = xdoc.XPathSelectElement(base64EncodedName);

    if (element == null) return 4; // No matching element found
    if (element != null && element.Elements().Count() > 1) return 5; // Multiple elements with the given name found

    var base64Data = Encoding.UTF8.GetString(Convert.FromBase64String(element.Value));

    ParallelLoopResult result;
    int decryptionErrorCode = -1;
    foreach (var keyAndIV in decryptionKeys)
    {
        try
        {
            var decryptedData = Decrypt(base64Data, keyAndIV.Key, keyAndIV.IV);
            return 0; // Successful decryption
        }
        catch
        {
            if (decryptionErrorCode == -1) decryptionErrorCode = 6; // First attempt to decrypt failed
        }
    }

    if (decryptionErrorCode != -1)
    {
        callback(decryptionErrorCode);
        return 6; // Decryption failed due to invalid keys, IVs, or corrupted data
    }

    return 7; // No decryption keys and IVs found for the given encryption method

    byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;

            ICryptoTransform decryptor = aes.CreateDecryptor();
            byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
            return decryptedBytes;
        }
    }
}
