        (*cache)->is_valid = true;
        (*cache)->config = config;
        curl_easy_cleanup(curl);
        return 0;
    }
    return 1;
}

ConfigData *load_config(const char *url) {
    static struct Cache cache = { .last_update = 0 };
    time_t current_time = time(NULL);

    pthread_mutex_lock(&cache.lock);
    if(!cache.is_valid || (current_time - cache.last_update) > 60 * 60) { // Update every hour
        int error = download_config(url, &cache);
        if (error) {
            pthread_mutex_unlock(&cache.lock);
            return NULL;
        }
    }
    pthread_mutex_unlock(&cache.lock);

    return cache.config;
}
