// Helper function to compute average and standard deviation
void avg_stddev(double* arr, size_t len, double* avg, double* stddev) {
    double sum = 0.0;
    double m2 = 0.0;

    for (size_t i = 0; i < len; ++i) {
        sum += arr[i];
    }

    *avg = sum / len;

    for (size_t i = 0; i < len; ++i) {
        double diff = arr[i] - *avg;
        m2 += diff * diff;
    }

    *stddev = sqrt(m2 / len);
}

