using boost::asio::ip::tcp;

struct Record {
    int value;
    time_t lastUsed;
};

std::ostream& operator<<(std::ostream& os, const Record& r) {
    return os << "(" << r.value << "," << r.lastUsed << ")";
}

std::istream& operator>>(std::istream& is, Record& r) {
    is >> r.value >> r.lastUsed;
    return is;
}

class PoolManager {
public:
    virtual ~PoolManager() {}
    virtual void configure(const std::string& config) = 0;
    virtual const std::shared_ptr<Record> getRecord() = 0;
    virtual void releaseRecord(const std::shared_ptr<Record>& record) = 0;
};

class Connection {
public:
    Connection(tcp::socket& socket, PoolManager& poolManager, const int timeout)
        : m_socket(socket), m_poolManager(poolManager), m_timeout(timeout) {}

    void start() {
        doWork();
    }

private:
    void doWork() {
        boost::system_error error;
        boost::asio::streambuf requestBuffer;
        boost::asio::write(m_socket, boost::asio::buffer(requestBuffer));

        boost::asio::streambuf responseBuffer;
        boost::asio::read_until(m_socket, responseBuffer, "\n");

        try {
            std::istream is(&responseBuffer);
            Record record;
            is >> record;
            // Process the received record...

            auto currentTime = std::chrono::system_clock::now().time_since_epoch().count();
            m_poolManager.releaseRecord(m_currentRecord);
            m_currentRecord = m_poolManager.getRecord();
            if (m_currentRecord) {
                m_currentRecord->lastUsed = currentTime;
                // Set the record value...
            }
        } catch (const std::exception& e) {
            // Handle errors...
        }

        m_nextWork.reset();
        if (!m_nextWork.expiration().time_since_epoch() > std::chrono::seconds(m_timeout)) {
            m_nextWork = std::async(std::launch::async, [this](){ doWork(); });
        }
    }

    tcp::socket& m_socket;
    PoolManager& m_poolManager;
    const int m_timeout;
    std::shared_ptr<Record> m_currentRecord;
    std::future<void> m_nextWork;
};
```

