int init_transaction_records(TransactionRecord**, size_t* capacity) {
    *capacity = INITIAL_CAPACITY;
    *transaction_records = malloc(*capacity * sizeof(TransactionRecord));
    if (!*transaction_records) return -1;
    return 0;
}

void resize_transaction_records(TransactionRecord** transaction_records, size_t* capacity, size_t new_capacity) {
    TransactionRecord* new_transaction_records = malloc(new_capacity * sizeof(TransactionRecord));
    if (!new_transaction_records) return;

    memcpy(new_transaction_records, *transaction_records, *capacity * sizeof(TransactionRecord));
    free(*transaction_records);
    *transaction_records = new_transaction_records;
    *capacity = new_capacity;
}

void process_csv_file(const char* filename, TransactionRecord** transaction_records, size_t* capacity) {
    csv_parser parser;
    size_t num_allocated = 0, num_processed = 0;
    int rc;

    if (init_transaction_records(transaction_records, &num_allocated)) return;

    csv_init_parser(&parser);
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    csv_parse_stream(&parser, fp, process_csv_row, transaction_records, &num_allocated, &num_processed);
    fclose(fp);

    if (num_allocated != num_processed) resize_transaction_records(transaction_records, &num_allocated, 2 * num_allocated + 1);
}

void process_json_file(const char* filename, TransactionRecord** transaction_records, size_t* capacity) {
