    if (!json) return;

    obj = json_object_get_exact(json, "transactions");
    if (!obj) {
        printf("Malformed JSON: missing transactions field\n");
        return;
    }

    cJSON* item;
    cJSON_ArrayForEach(item, obj->child) {
        process_json_transaction(item, transaction_records, capacity);
    }
}

void process_csv_row(const char** field_values, void* userdata, size_t nfields, size_t nalloc) {
    TransactionRecord* transaction = userdata;

    if (nfields < 4) return; // insufficient fields

    sscanf(field_values[0], "%d", &(transaction->transaction_id));
    strncpy(transaction->account, field_values[1], ACCOUNT_LENGTH);
    transaction->timestamp = atoi(field_values[2]); // replace with proper time parsing function
    transaction->amount = atof(field_values[3]);
}

void process_json_transaction(cJSON* item, TransactionRecord** transaction_records, size_t* capacity) {
    TransactionRecord* transaction = &transaction_records[*capacity];

    if (cJSON_GetObjectItemCaseSensitive(item, "id")->type != cJSON_Number ||
        cJSON_GetObjectItemCaseSensitive(item, "time")->type != cJSON_Number ||
        cJSON_GetObjectItemCaseSensitive(item, "account")->type != cJSON_String ||
        cJSON_GetObjectItemCaseSensitive(item, "amount")->type != cJSON_Number) {
        printf("Malformed transaction record\n");
        return;
    }

    transaction->transaction_id = (int)cJSON_GetObjectItemCaseSensitive(item, "id")->valueint;
    strncpy(transaction->account, cJSON_GetString(cJSON_GetObjectItemCaseSensitive(item, "account")), ACCOUNT_LENGTH);
    transaction->timestamp = (time_t)cJSON_GetObjectItemCaseSensitive(item, "time")->valuedouble; // replace with proper time parsing function
    transaction->amount = cJSON_GetObjectItemCaseSensitive(item, "amount")->valuedouble;

    *capacity += 1;
}
