void SetNewExtension(std::filesystem::path& path, const std::string& fileTypeSuffix) {
  if (path.has_extension()) {
    path.replace_extension("");
  }

  auto extensionLength = static_cast<size_t>(std::log10(static_cast<double>(path.parent_path().depth())) + 1);
  if (extensionLength > 5) {
    extensionLength = 5;
  }

  std::ostringstream os;
  os << std::setw(extensionLength) << std::setfill('0') << path.parent_path().depth();
  path /= (os.str() + "." + fileTypeSuffix);
}

