std::string GetFileTypeSuffix(const std::filesystem::path& path) {
  auto filename = path.filename().wstring();
  std::transform(filename.begin(), filename.end(), filename.begin(), ::tolower);

  if (filename.find(_T("_")) != std::wstring::npos) {
    return "_img"; // Example: "my_file.txt" becomes "my_file.001_img.txt"
  } else if (filename.find(_T("-")) != std::wstring::npos) {
    return "_doc"; // Example: "my-file.txt" becomes "my-file.001_doc.txt"
  } else {
    return "";
  }
}

} // namespace FileNamingUtils
```

