#include <iostream>
#include <list>
#include <chrono>
#include <random>
#include <thread>
#include <mutex>
#include <condition_variable>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
    std::uint32_t crcFlag;
    std::chrono::steady_clock::time_point timestamp;
};

std::list<NFAPI_CRC_INDICATION_PDU_T> dll; // Double-linked list holding NFAPI_CRC_INDICATION_PDU_T objects.
std::mutex mtx;                           // Mutex for synchronization.
std::condition_variable cv;               // Condition variable to wait for appropriate lock state.

bool cleanUpRequired() {
    auto now = std::chrono::steady_clock::now();
    auto secDiff = std::chrono::duration_cast<std::chrono::seconds>(now - *dll.rbegin().timestamp);
    return (secDiff.count() > 120);
}

void cleanupDoublyLinkedList() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [this] { return cleanUpRequired(); });

    auto it = dll.begin();
    while (it != dll.end()) {
        if ((*it).timestamp + std::chrono::seconds(120) < std::chrono::steady_clock::now()) {
            it = dll.erase(it);
        } else {
            ++it;
        }
    }
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T node) {
    std::unique_lock<std::mutex> lock(mtx);
    cv.notify_one(); // Inform waiting threads that the lock is available.

    node.timestamp = std::chrono::steady_clock::now();
    dll.push_back(node);
}

void workerFunction() {
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T newNode; // Create a new node with random CRCFLAG.
        // Populate newNode with your data and necessary initializations.

        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return dll.empty(); }); // Wait until the list is empty before enqueuing a new node.

        enqueue(newNode);
    }
}

int main() {
    std::thread workerThreads[NUM_WORKER_THREADS]; // Adjust NUM_WORKER_THREADS to desired number of worker threads.

    for (auto& w : workerThreads)
        w = std::thread(workerFunction);

    // Implement periodic cleanup using a separate thread or within the workerFunction().
    std::thread cleanerThread(cleanupDoublyLinkedList, std::ref(dll), ref(mtx), ref(cv));

    // Wait for all threads to finish their execution.
    for (auto& w : workerThreads) {
        w.join();
    }

    cleanerThread.join();
}
```

In this code, `enqueue()`, `cleanupDoublyLinkedList()`, and `workerFunction()` are the main functions that manage the doubly linked list. The double-linked list is managed using a `std::list`. To ensure thread safety, I have used standard synchronization primitives such as mutexes (`mtx`) and condition variables (`cv`).

The `enqueue()`, `cleanupDoublyLinkedList()`, and `workerFunction()` functions use unique locks to acquire the lock when modifying the list. The `workerFunction()` waits for the list to be empty before adding a new node, ensuring that the list remains thread-safe.

The memory management strategy is simple: nodes are created dynamically on demand and deleted as they reach their retention limit (120 seconds in this case). You can further optimize the memory usage by implementing a custom allocator or using smart pointers like `std::unique_ptr` for each node. However, these strategies may impact performance under high-load conditions due to potential memory fragmentation and overhead introduced by smart pointers.

