size_t allocate_NFAPIs(size_t N, NFAPI_CRC_INDICATION_PDU_T** buffer, size_t* num_allocated) {
    unsigned int seed = time(NULL); // Seed with current timestamp for random number generation
    init_random(&seed);

    pthread_mutex_t lock; // Mutex to protect shared data structure access
    pthread_mutex_init(&lock, NULL);

    size_t max_elements = 1000000; // Maximum number of elements for efficient memory management
    if (N > max_elements) N = max_elements;

    *buffer = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*buffer == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return 0;
    }

    *num_allocated = N;
    size_t allocated_elements = 0;

    // Loop through all elements and initialize them with the given structure fields.
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);
        NFAPI_CRC_INDICATION_PDU_T* current_element = &((*buffer)[allocated_elements]);
        current_element->tag.present = RX_UE_INFORMATION_TAG_PRS; // Set tag to the present value
