[' ```java
import org.apache.commons.codec.digest.DigestUtils;
import com.github.benmanes.caffeine.cache.Caffeine;
import com.github.benmanes.caffeine.cache.LoadingCache;
import com.hazelcast.core.HazelcastInstance;
import com.hazelcast.core.HazelcastJdbcSql;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.time.Duration;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

public class LogProcessingService {
    private static final Logger LOGGER = LoggerFactory.getLogger(LogProcessingService.class);

    private LoadingCache<String, String> cache;
    private HazelcastInstance hazelcastInstance;

    public LogProcessingService(HazelcastInstance hazelcastInstance) {
        this.hazelcastInstance = hazelcastInstance;
        cache = Caffeine.newBuilder()
                .expireAfterAccess(1, TimeUnit.HOURS) // Adjust expiration time dynamically based on configuration
                .maximumSize(Integer.MAX_VALUE) // Allow for unlimited number of entries in cache
                .build((key, callable) -> {
                    try {
                        return DigestUtils.sha256Hex(callable.call().orElseThrow());
                    } catch (Exception e) {
                        throw new RuntimeException("Error while computing hash", e);
                    }
                });
    }

    public void processLogs(List<String> logMessages) {
        if (logMessages.isEmpty()) {
            throw new IllegalArgumentException("Empty or null list of log messages provided");
        }

        // Compute hashes concurrently for improved performance
        List<Future<String>> futures = logMessages.stream()
                .map(cache::getAsync)
                .collect(Collectors.toList());

        try {
            List<String> hashedLogs = futures.stream().map(future -> {
                try {
                    return future.get();
                } catch (Exception e) {
                    LOGGER.error("Failed to compute hash for log message", e);
                    return null;
                }
            }).collect(Collectors.toList());

            // Store the hashed logs in the distributed cache
            storeHashedLogsInCache(hashedLogs);
        } catch (InterruptedException | ExecutionException e) {
            LOGGER.error("Error while processing log messages", e);
        }
    }

    private void storeHashedLogsInCache(List<String> hashedLogs) {
        // Connect to the Hazelcast SQL JDBC driver and insert hashed logs into the cache
        try (Connection connection = HazelcastJdbcSql.newInstance().getConnection()) {
            String sql = "INSERT INTO log_hashes(key, value) VALUES (?, ?)";
            // Replace this with a prepared statement for better performance and security
            PreparedStatement preparedStatement = connection.prepareStatement(sql);

            for (String hashedLog : hashedLogs) {
                if (hashedLog != null) {
                    preparedStatement.setString(1, hashedLog);
                    preparedStatement.setString(2, hashedLog);
                    preparedStatement.executeUpdate();
                }
            }
        } catch (SQLException e) {
            LOGGER.error("Error while storing hashed logs in the cache", e);
        }
    }
}
