class HashIndex {
public:
    std::unordered_map<int, size_t> keysToPositions;

    int addKey(int key) {
        if (keysToPositions.find(key) == keysToPositions.end()) {
            size_t position = records.size();
            keysToPositions[key] = position;
            return position;
        }
        return keysToPositions[key];
    }

    const Record& getRecord(int key) const {
        auto it = keysToPositions.find(key);
        if (it != keysToPositions.end())
            return records[it->second];
        throw std::runtime_error("Key not found in HashIndex");
    }
};

class OffsetArray {
public:
    std::vector<long> data;

    long& operator[](size_t index) {
        if (data.empty() || index >= data.size())
            data.resize(index + 1, 0);
        return data[index];
    }
};

class PriorityQueue {
public:
    std::priority_queue<std::pair<int, size_t>, std::vector<std::pair<int, size_t>>, std::greater<std::pair<int, size_t>>> queue;

    void enqueue(size_t index, int priority) {
        queue.push({priority, index});
    }

    size_t dequeue() {
        if (!queue.empty()) {
            auto it = queue.top().second;
            queue.pop();
            return it;
        }
        throw std::runtime_error("Priority Queue is empty");
    }
};

class RecordSlotPool {
public:
    std::vector<Record> records;
    std::vector<size_t> freeSlots;

    size_t allocate() {
        if (!freeSlots.empty()) {
            size_t slot = freeSlots.back();
            freeSlots.pop_back();
            return slot;
        }
        Record newRecord;
        records.push_back(newRecord);
        return records.size() - 1;
    }

    void free(size_t slot) {
        if (slot >= records.size())
            throw std::runtime_error("Slot index out of range");
        freeSlots.push_back(slot);
        records[slot].accessCount = 0;
        records[slot].lastAccessed = 0;
    }
};

