// External library for generating unique RNTI values (assuming a function called `generate_unique_rnti`)
extern uint32_t generate_unique_rnti(void);

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int create_structures(size_t num, size_t seed, size_t *successfully_created) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Thread safety
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    size_t created = 0;

    srand(seed);

    structures = calloc(num, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        fprintf(stderr, "Memory allocation for structures failed\n");
        return 0;
    }

    pthread_mutex_lock(&mutex); // Ensure thread safety during structure population

    for (size_t i = 0; i < num && created < num; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *current = structures + i;

        current->tag = (RX_UE_INFORMATION_TAG) rand(); // Assign tag randomly
        current->rnti = generate_unique_rnti(); // Generate unique RNTI

        if (created > 0 && current->rnti == structures[created - 1].rnti) { // Validate RNTIs are unique
            fprintf(stderr, "Error: Duplicate RNTI detected\n");
            continue;
        }

        current->crc_tag = (CRC_INDICATION_REL8_TAG) rand(); // Assign CRC tag randomly

        ++created;
    }

    pthread_mutex_unlock(&mutex); // Release the lock

    *successfully_created = created;

    return 1;
}
