    pthread_mutex_lock(&list_mutex);
    entry->RNTI = list_size + 1;
    entry->CRC_INDICATION_REL8_TAG = rand() % 2;
    if (entry->RX_UE_INFORMATION_TAG != 0xABCD || entry->RNTI <= list_size) { // validate RX_UE_INFORMATION_TAG and RNTI
        free(entry);
        entry = NULL;
        pthread_mutex_unlock(&list_mutex);
    } else {
        list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list_size + 1));
        if (!list) {
            log("Out of memory");
            entry = NULL;
            pthread_mutex_unlock(&list_mutex);
        } else {
            list[list_size] = *entry;
            pthread_mutex_unlock(&list_mutex);
