#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include "external_library.h"  // External library for generating unique RNTIs

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ARRAY_SIZE 1024

static NFAPI_CRC_INDICATION_PDU_T* array = NULL;
static int num_elements = 0;
static int allocated_size = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int log_level = 1; // Log level (0: Error only, 1: Warning and Error, 2: Info, 3: Debug)

int initialize_nfapi_crc_indication_pdu() {
    if (!external_library_init()) {
        fprintf(stderr, "Failed to initialize external library\n");
        return -1;
    }

    array = malloc(MAX_ARRAY_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return -2;
    }

    allocated_size = MAX_ARRAY_SIZE;
    num_elements = 0;

    return 0;
}

int add_nfapi_crc_indication_pdu(const RX_UE_INFORMATION_TAG* rx_ue_info, unsigned int rnti, const CRC_INDICATION_REL8_TAG* crc_indication) {
    if (!array || allocated_size == 0) {
        fprintf(stderr, "Array not initialized or empty\n");
        return -3;
    }

    pthread_mutex_lock(&mutex);

    int i;
    for (i = 0; i < num_elements; ++i) {
        if (array[i].rnti == rnti) {
            fprintf(stderr, "Duplicate RNTI found: %u\n", rnti);
            pthread_mutex_unlock(&mutex);
            return -4;
        }
    }

    if (num_elements >= allocated_size) {
        void* new_array = realloc(array, (allocated_size + MAX_ARRAY_SIZE) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&mutex);
            return -5;
        }
        array = new_array;
        allocated_size += MAX_ARRAY_SIZE;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &array[num_elements];
    pdu->rx_ue_info = *rx_ue_info;
    pdu->rnti = rnti;
    pdu->crc_indication = *crc_indication;
    ++num_elements;

    pthread_mutex_unlock(&mutex);

    if (log_level > 1) {
        printf("Added PDU with RNTI: %u\n", rnti);
    }

    return 0;
}

void cleanup() {
    if (array && allocated_size > 0) {
        free(array);
        array = NULL;
        allocated_size = 0;
        num_elements = 0;
    }

    external_library_cleanup();
}
