// Define the record structure
struct Record {
    long offset;
    int key;
};

class MemoryManager {
public:
    // Allocate memory for array of records and initialize with random values
    std::vector<std::unique_ptr<Record>> records;

    // Allocate memory for an array of ints and initialize with random values
    std::vector<int> integers;

private:
    static constexpr size_t MAX_MEMORY = 1000000; // Set maximum memory limit
    static thread_local std::random_device rd; // Thread-safe random number generator
    static thread_local std::mt19937 gen; // Mersenne Twister pseudo-random number engine
    static std::uniform_int_distribution<> dis; // Uniform int distribution for random numbers

public:
    MemoryManager() : records(MAX_MEMORY / sizeof(Record)), integers(MAX_MEMORY) {
        for (auto& record : records)
            record.reset(new Record());
        for (auto& i : integers)
            i = dis(gen);
    }

    // Initialize a record with random values
    void initRecord(Record* record) {
        record->offset = dis(gen);
        record->key = dis(gen % 100 + 1);
    }

    // Retrieve the offset value from a given key, handle out-of-bounds and concurrent access safely
    long getOffset(int key) {
        for (const auto& record : records) {
            if (record->key == key)
                return record->offset;
        }
        throw std::out_of_range("Key not found");
    }

    // Access an int value at the specified index, handle out-of-bounds and ensure cache locality
    int& operator[](size_t i) {
        static constexpr size_t cacheSize = 1024;
        static std::vector<int> cache;
        if (i >= integers.size())
            throw std::out_of_range("Index out of range");

        if (cache.empty() || i >= cache.size()) {
            // Refill the cache with elements around the requested index
            size_t start = i - cacheSize / 2;
            start = (start < 0) ? 0 : start;
            for (size_t j = start; j < std::min(integers.size(), start + cacheSize); ++j) {
                if (j >= cache.size())
                    cache.push_back(integers[j]);
            }
        }
        return cache[i];
    }

    // Garbage collection mechanism to reclaim unused memory
    void gc() {
        for (auto it = records.begin(); it != records.end();) {
            if (!*it) {
                it = records.erase(it);
                continue;
            }
            ++it;
        }
    }

    // Handle memory allocation failures and retry logic
    static void* safeMalloc(size_t size, const char* file, int line) {
        void* ptr = nullptr;
        while (!(ptr = ::operator new(size))) {
            if (std::cerr << "Memory allocation failed at " << file << ':' << line << ". Retrying..." << std::endl)
                continue;
            abort(); // Exit the program on fatal errors
        }
        return ptr;
    }
};

// Initialize thread-local random number generator
thread_local MemoryManager::rd();
thread_local MemoryManager::gen(MemoryManager::rd());
thread_local MemoryManager::dis(0, INT_MAX);
