char *transformFilename(const char *path) {
    size_t len = strlen(path);
    size_t ext_len = (len > 256 - 14) ? (256 - 14) : len; // Max 256 characters, minimum 2 digits
    size_t num_digits = ext_len / 2 < 2 ? 2 : ext_len / 2;
    char *filename = strdup(path); // Duplicate the path for modification
    char *token = strtok(filename, "/"); // Split by directories
    char *name = token;
    token = strtok(NULL, "."); // Split by extension if any
    if (token) name = strtok(NULL); // Continue splitting by components without extension

    // Generate new filename based on criteria
    size_t base_len = strlen(name);
    char *new_ext = malloc(num_digits + 3); // Allocate space for digits and "." or "_" separator
    snprintf(new_ext, num_digits + 3, ".%0*d", num_digits, (int)time(NULL) % 100); // Generate the number part
    char *new_name = malloc(base_len + num_digits + 3 + (token ? strlen(token) : 4)); // Allocate space for name and extension

    if (!token) { // No existing extension, determine file type
        if (strchr(name, TOUPPER(*name)) != NULL) strcpy(new_ext, ".TXT");
        else strcpy(new_ext, ".BIN");
    } else { // Existing extension, check case and modify as needed
        char *ext_ptr = strrchr(new_ext, '.');
        if (strchr(name, TOUPPER(*name)) != NULL) {
            strncpy(ext_ptr + 1, token, strlen(token));
            strcat(new_ext, token);
        } else {
            *ext_ptr = '\0'; // Remove existing extension
            strncat(new_ext + strlen(new_ext), token, strlen(token) > num_digits + 1 ? (num_digits + 1) : strlen(token));
        }
    }

    snprintf(new_name, base_len + num_digits + 3, "%s_%s", name, new_ext); // Combine the base and new extension

    if (strlen(path) > 1 && path[strlen(path) - 1] == '/') { // If it's a relative path, prepend the current directory
        size_t cur_dir_len = getcwd(NULL, 256);
        new_name = realloc(new_name, base_len + num_digits + 3 + cur_dir_len);
        strncat(new_name, "/", cur_dir_len >= 255 ? 1 : cur_dir_len);
    }

    char *modified_path = malloc(strlen(getcwd(NULL, 0)) + strlen(new_name) + 1); // Allocate space for the full path
    strcat(modified_path, getcwd(NULL, 0));
    strcat(modified_path, "/");
    strcat(modified_path, new_name);

    free(filename); free(name); free(new_ext); // Free allocated memory
    return modified_path;
}
