    FILE *stream;
    bool stdin;
    regex_t filter; // Regular expression for row filtering
};

// Timestamp structure
struct timeval start, end;
double elapsed;

void* process_data(void *arg) {
    struct args *args = (struct args *) arg;
    double sum = 0.0;
    int count = 0;

    // Read and process data from the specified source
    while (!feof(args->stream)) {
        char line[256];
        size_t len = fgets(line, sizeof(line), args->stream);

        if (len == 0) break; // End of file/stream reached

        // Validate data and filter based on the given regular expression
        if (regexec(&args->filter, line, 0, NULL, 0)) continue;
        validate_data(line);

        sum += atof(line); // Assuming each line contains a number for simplicity
        count++;
    }

    return NULL;
}

void print_summary_stats(double total, int count) {
    double avg = total / count;
    printf("Total: %.2f\nAverage: %.6f\n", total, avg);
    // Add more summary statistics like percentiles, min/max values etc.
}

int main(int argc, char *argv[]) {
    struct args args;
    pthread_t threads[4];
    int thread_count = 1; // Default to one thread for simplicity

    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] [input-file|-]\n", argv[0]);
        return 1;
    }

    memset(&args, 0, sizeof(args));

    // Parse command line arguments
    int c;
    while ((c = getopt(argc, argv, "f:i:r:")) != -1) {
        switch (c) {
            case 'f': args.file = optarg; break;
            case 'i': args.stdin = true; break;
            case 'r': regcomp(&args.filter, optarg, REG_EXTENDED); break;
        }
    }

    if (!args.file && !args.stdin) {
        fprintf(stderr, "Either -f or -i must be specified\n");
        return 1;
    }

    if (args.file) {
        args.stream = fopen(args.file, "r");
        if (!args.stream) {
            perror("Error opening file");
            return 1;
        }
    } else {
        args.stream = stdin;
    }

    gettimeofday(&start, NULL);

    // Parallelize data processing
    for (int i = 0; i < thread_count && !feof(args.stream); i++) {
        pthread_create(&threads[i], NULL, process_data, &args);
    }

    // Wait for all threads to finish
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    gettimeofday(&end, NULL);
    elapsed = (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000000.0;
    printf("Processing time: %.2f seconds\n", elapsed);

    // Gather results from threads and compute summary statistics
    double total = 0.0;
    int count = 0;
    for (int i = 0; i < thread_count; i++) {
        struct args *args_i = (struct args *) &args;
        total += args_i->thread_total;
        count += args_i->thread_count;
    }

    print_summary_stats(total, count);

    return 0;
}
