int get_num_fields(const char *line) {
    int count = 0;
    for (const char *c = line; *c != '\0'; ++c) {
        if (*c == ',')
            count++;
    }
    return count + 1;
}

void parse_line(Line *line, const char **fields) {
    int field_count = get_num_fields(line->line);
    fields[0] = line->line;
    for (int i = 1; i < field_count - 1; ++i) {
        size_t pos = strlen(fields[i]);
        fields[i] = &line->line[pos + 1];
    }
}

double average(const double a, const double b) {
    return (a + b) / 2.0;
}

void process_file(const char *path) {
    FILE *file = fopen(path, "r");
    if (!file)
        return;

    size_t file_size = get_file_size(path);
    if (file_size > MAX_FILE_SIZE) {
        fclose(file);
        return;
    }

    Line *lines = malloc((file_size + 1) * sizeof(Line));
    char buffer[4096];
    size_t pos = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        if (pos >= file_size)
            break;
        lines[pos].len = strlen(buffer);
        lines[pos++].line = malloc(lines[pos].len + 1);
        strcpy(lines[pos].line, buffer);
    }
    fclose(file);

    const char *fields[get_num_fields(lines[0].line)];
    for (size_t i = 0; i < pos; ++i) {
        parse_line(&lines[i], fields);
        printf("%s", fields[0]);
        for (int j = 1; j < get_num_fields(lines[i].line) - 1; ++j)
            printf(", %s", fields[j]);
        printf(", %.2f\n", average(atof(fields[get_num_fields(lines[i].line) - 2]), atof(fields[get_num_fields(lines[i].line) - 1])));
    }

    for (size_t i = 0; i < pos; ++i) {
        free(lines[i].line);
    }
    free(lines);
}

void* cache_thread(void *arg) {
    while (1) {
        CacheEntry *entry = malloc(sizeof(CacheEntry));
        void *data = mmap(NULL, theme_bitmap_len, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        memcpy(data, theme_bitmap_mem, theme_bitmap_len);
        entry->data = data;
        entry->last_used = time(NULL);
        pthread_mutex_lock(&cache_lock);
        entry->next = cache_head;
        cache_head = entry;
        pthread_mutex_unlock(&cache_lock);
        usleep(100000); // Sleep for 100ms before evicting old entries.

        CacheEntry *iter = cache_head;
        while (iter->next) {
            iter = iter->next;
            if ((time(NULL) - iter->last_used) > 60) { // Evict after 1 minute of inactivity.
                void *data = iter->data;
                munmap((char *)data, theme_bitmap_len);
                free(iter);
                if (iter == cache_head) {
                    cache_head = iter->next;
                } else {
                    CacheEntry *prev = cache_head;
                    while (prev->next != iter) {
                        prev = prev->next;
                    }
                    prev->next = iter->next;
                }
            }
        }
    }
}

int main() {
    DIR *dir = opendir("./");
    struct dirent *entry;
    while ((entry = readdir(dir))) {
        if (strncmp(entry->d_name, ".", 1) == 0)
            continue;
        char path[256];
        snprintf(path, sizeof(path), "./%s", entry->d_name);
        process_file(path);
    }
    closedir(dir);

    pthread_t cache_tid;
    pthread_create(&cache_tid, NULL, &cache_thread, NULL);

    // Initialize theme bitmap data from the external service.
    // ... (Implement network communication logic here)

    theme_bitmap_mem = mmap(NULL, sizeof(theme_bitmap_data), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    memcpy(theme_bitmap_mem, theme_bitmap_data, sizeof(theme_bitmap_data));
    theme_bitmap_len = sizeof(theme_bitmap_data);

    pthread_join(cache_tid, NULL);

    return 0;
}
```

