['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <inttypes.h>

typedef struct {
    int key_type; // 0: integer, 1: custom structure
    uint64_t min_val;
    uint64_t max_val;
    size_t num_records;
} metadata;

typedef struct {
    void *key;
    int64_t value;
} record;

void parse_metadata(const char *filename, metadata *meta) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s\n", filename);
        exit(1);
    }

    char line[256];
    size_t num_records;
    int key_type;
    uint64_t min_val, max_val;

    fgets(line, sizeof(line), fp); // skip the first line (number of records)
    sscanf(line, "%d", &key_type);
    meta->key_type = key_type;
    fgets(line, sizeof(line), fp); // skip the second line (indicating integer or custom structure)

    fscanf(fp, "%" SCNu64 ",%" SCNu64 " %lu", &meta->min_val, &meta->max_val, &num_records);
    meta->num_records = num_records;
}

void *allocate_key(int key_type) {
    if (key_type == 0)
        return calloc(1, sizeof(int));
    else // key_type == 1
        return malloc(sizeof(struct custom_struct));
}

record *parse_data(const char *filename, metadata meta) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s\n", filename);
        exit(1);
    }

    size_t i = 0;
    record *records = malloc(meta.num_records * sizeof(record));

    char line[256];
    while (fgets(line, sizeof(line), fp) && i < meta.num_records) {
        sscanf(line, "%*s %" SCNu64 " %lf", &records[i].value); // ignore key value for now
        if (meta.key_type == 0)
            records[i].key = &records[i].value;
        else {
            records[i].key = allocate_key(meta.key_type);
            sscanf(line, "%s %" SCNu64 " %lf", (char *)records[i].key, &(static_cast<record*>(records[i].key)->integer_value));
        }
        i++;
    }

    fclose(fp);
    return records;
}

void write_output(const char *input_filename, const char *output_filename, record *records, metadata meta) {
    FILE *input = fopen(input_filename, "r"), *output = fopen(output_filename, "w");

    if (!input || !output) {
        fprintf(stderr, "Error opening file for writing.\n");
        exit(1);
    }

    char line[256];
    size_t i = 0;

    while (fgets(line, sizeof(line), input)) { // skip the data lines from input file
        if (strchr(line, '\n'))
            break;
    }

    for (size_t j = 0; j < meta.num_records; ++j) {
        sprintf(line, "%s %" PRId64 " ", records[j].key ? ((meta.key_type == 1) ? "(custom)" : "") : "", records[j].value);
        fprintf(output, "%s\n", line);
    }

    fclose(input);
    fclose(output);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        printf("Usage: %s <input_file> <output_file> <rules_file>\n", argv[0]);
        exit(1);
    }

    metadata meta;
    parse_metadata(argv[3], &meta);

    record *records = parse_data(argv[3], meta);

    write_output(argv[1], argv[2], records, meta);

    return 0;
}
```

This code reads input files, parses their contents based on the specified set of rules, and generates an output file containing formatted data. It uses dynamic memory allocation for efficient resource management. The metadata is read from a configuration file named "data.txt". Additionally, it supports integer and custom structure keys, with the option to generate random values within a specified range for each record.

You can use the following example command to run this code:

```sh
./parser input.bin output.bin data.txt
```']

