#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <stdio.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <errno.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _FACTORY {
    const char *name;
    size_t size;
    void* (*func)(void*);
    pthread_mutex_t mutex;
    sem_t sem;
} FACTORY;

typedef struct _REGISTRY {
    FACTORY* factories;
    size_t capacity;
    size_t count;
} REGISTRY;

void *factory(void* arg) {
    FACTORY *f = (FACTORY*)arg;
    void *instance = f->func(NULL);
    pthread_mutex_unlock(&f->mutex);
    return instance;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pdu == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }
    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->crcflag = rand() % 2;
    return pdu;
}

REGISTRY* create_registry(size_t capacity) {
    REGISTRY *registry = mmap(NULL, sizeof(REGISTRY), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (registry == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }
    registry->capacity = capacity;
    registry->count = 0;
    FACTORY* factories = malloc(capacity * sizeof(FACTORY));
    if (!factories) {
        free(registry);
        perror("malloc");
        return NULL;
    }
    memset(factors, 0, capacity * sizeof(FACTORY));
    registry->factories = factories;
    return registry;
}

void register_factory(REGISTRY* registry, const char* name, size_t size, void* (*func)(void*)) {
    FACTORY* factory = &registry->factories[registry->count];
    factory->name = name;
    factory->size = size;
    factory->func = func;
    pthread_mutex_init(&factory->mutex, NULL);
    sem_init(&factory->sem, 0, 1);
    registry->count++;
}

void* create(REGISTRY* registry, const char* name) {
    FACTORY* factory = NULL;
    pthread_t thread;
    void *instance = NULL;

    pthread_mutex_lock(&registry->factories[0].mutex);
    for (size_t i = 0; i < registry->count; ++i) {
        if (!strcmp(registry->factories[i].name, name)) {
            factory = &registry->factories[i];
            break;
        }
    }
    pthread_mutex_unlock(&registry->factories[0].mutex);

    if (factory) {
        sem_wait(&factory->sem);
        pthread_create(&thread, NULL, factory, factory);
        void* tempInstance = pthread_join(thread, &instance);
        if (tempInstance) {
            memmove(instance, tempInstance, factory->size);
        } else {
            free(tempInstance);
        }
    } else {
        fprintf(stderr, "Error: Unknown factory '%s'\n", name);
    }

    return instance;
}
```

This code provides a dynamic registry of factory functions for creating instances of subclasses of a base class. The `create_registry()` function creates a registry with a given capacity and initializes its structures. The `register_factory()` function adds a new factory to the registry, given its name, size, and function pointer. The `create()` function takes a registry and a factory name, initializes the factory if necessary, locks the mutex, searches for the factory in the registry, creates a thread to run the factory's function, and joins the thread upon completion to obtain the instance created by the factory. The code also handles concurrent access from multiple threads using mutexes and semaphores and logs errors using `fprintf()`.']

