    numAllocatedIndications = MAX_INDICATIONS;

    // Initialize currentIndication pointer to the beginning of the dynamically allocated array
    currentIndication = (*indications);

    // Variables for network data processing
    size_t processedDataCount = 0;
    int dataPacketLossCounter = 0;
    clock_t startTime, endTime;
    double elapsedTime;

    while (processedDataCount < MAX_INTEGERS) {
        // Retrieve network data in chunks
        size_t numRetrievedData = fread(buffer, sizeof(int), bufferSize, stdin);

        if (numRetrievedData <= 0) {
            // Handle read failures or end of stream
            if (ferror(stdin)) {
                fprintf(stderr, "Error reading from network interface\n");
            } else if (feof(stdin)) {
                fprintf(stderr, "End of stream reached\n");
            }
            break;
        }

        // Process retrieved data and handle potential packet loss
        for (size_t i = 0; i < numRetrievedData; ++i) {
            int networkDataValue = buffer[i];

            if (processedDataCount >= MAX_INTEGERS) {
                fprintf(stderr, "Overflow in processed data count\n");
                break; // Exit the loop in case of overflow
            }

            // Set CRCFLAG using a predefined mask
            currentIndication->CRCFLAG = (currentIndication->CRCFLAG & ~0x0001) | (networkDataValue & 0x0001);

            // Store the processed data in the indications array
            if (numAllocatedIndications == processedDataCount + 1) {
                // Reallocate memory for the indications array when needed
                NFAPI_CRC_INDICATION_PDU_T* newIndications = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*indications, numAllocatedIndications * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!newIndications) {
                    fprintf(stderr, "Failed to reallocate indications array memory\n");
                    free(buffer); // Free buffer on failure
                    free(*indications); // Free previous indications array on failure
                    return;
                }
                *indications = newIndications;
                numAllocatedIndications *= 2;
            }

            currentIndication->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF;
            currentIndication->RNTI = rand() % 0x7FFF + 1; // Valid RNTIs are from 1 to 32767
            ++currentIndication;
            ++processedDataCount;
        }

        dataPacketLossCounter = 0; // Reset packet loss counter after processing a chunk of data
    }

    free(buffer); // Free buffer on completion
}
