#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <pthread.h>
#include <sqlite3.h>

typedef struct {
    int stat_id;
    time_t timestamp;
    double measurement_value;
} STATISTIC_RECORD;

void parse_record(char* line, STATISTIC_RECORD* record);
void processAndAggregateStatistics(FILE* inputFile, sqlite3* db);

STATISTIC_RECORD* create_statistic_array(size_t size) {
    STATISTIC_RECORD *arr = malloc(sizeof(STATISTIC_RECORD) * size);
    if (!arr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < size; ++i) {
        arr[i].stat_id = i + 1;
        arr[i].timestamp = time(NULL);
        arr[i].measurement_value = (double)rand() / RAND_MAX * 100.0; // Range: [0, 100)
    }
    return arr;
}

void processAndAggregateStatistics(FILE* inputFile, sqlite3* db) {
    STATISTIC_RECORD* stats = create_statistic_array(5000);

    size_t num_parsed = 0;
    char line[1024];
    while (fgets(line, sizeof(line), inputFile)) {
        if (sscanf(line, "%d %ld %lf", &stats[num_parsed].stat_id, &stats[num_parsed].timestamp, &stats[num_parsed].measurement_value) != 3) {
            fprintf(stderr, "Invalid record format: %s\n", line);
            continue;
        }
        ++num_parsed;
    }

    // Integrate with external database system (e.g., SQLite)
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db, "INSERT INTO statistics (stat_id, timestamp, measurement_value) VALUES (?, ?, ?)", -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare database statement: %s\n", sqlite3_errmsg(db));
        exit(EXIT_FAILURE);
    }

    pthread_t threads[num_parsed];
    for (size_t i = 0; i < num_parsed; ++i) {
        int rc = pthread_create(&threads[i], NULL, [](void* arg) {
            STATISTIC_RECORD *record = (STATISTIC_RECORD *)arg;
            sqlite3_bind_int(stmt, 1, record->stat_id);
            sqlite3_bind_int64(stmt, 2, record->timestamp);
            sqlite3_bind_double(stmt, 3, record->measurement_value);
            sqlite3_step(stmt);
            return NULL;
        }, &stats[i]);
        if (rc) {
            fprintf(stderr, "Error creating thread: %s\n", strerror(rc));
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_parsed; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(stats);
}
```

