    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
};

struct AttackData {
    unsigned long lastUse;
    string attackType;
};

mutex mtxAttacks, mtxLog;
queue<NFAPI_CRC_INDICATION_PDU_T> dataQueue;
vector<AttackData> attacks;
priority_queue<chrono::nanoseconds> cooldownQueue;

void generateData() {
    default_random_engine generator(clock::now().time_since_epoch().count());
    uniform_int_distribution<int> distTag(1, 32767);
    uniform_int_distribution<unsigned short> distRNTI(0, 65535);
    uniform_int_distribution<unsigned char> distCRCFLAG(0, 1);

    for (auto& pdu : dataQueue) {
        pdu.RX_UE_INFORMATION_TAG = distTag(generator);
        pdu.RNTI = distRNTI(generator);
        pdu.CRC_INDICATION_REL8_TAG = distCRCFLAG(generator);
    }
}

void processAttacks() {
    auto now = chrono::high_resolution_clock::now();

    if (!cooldownQueue.empty() && now > cooldownQueue.top() + 9ns) {
        lock_guard<mutex> lk(mtxAttacks);
        if (!attacks.empty()) {
            AttackData currAttack = attacks.front();
            attacks.pop_front();
            cout << "Selected attack: " << currAttack.attackType << endl;
            currAttack.lastUse = now.time_since_epoch().count();
            cooldownQueue.push(currAttack.lastUse + 9ns);
            lock_guard<mutex> lkLog(mtxLog);
            ofstream logFile("performance_log.txt", ios::app);
            if (logFile) {
                logFile << "Attack selected: " << currAttack.attackType << ", time: " << now.time_since_epoch().count() << endl;
                logFile.close();
            }
        }
    }
}

void timingServiceCallback(chrono::nanoseconds delay) {
    if (!cooldownQueue.empty()) {
        cooldownQueue.push(cooldownQueue.top() + delay);
    }
}

void generateAndPopulateData(int N) {
    dataQueue.resize(N);
    generateData();
}

int main() {
    int N = 10;
    generateAndPopulateData(N);

    thread dataThread(generateData);
    thread timingService([]() {
        while (true) {
            auto delay = chrono::nanoseconds(random_device{}() % 100);
            this_thread::sleep_for(delay);
            timingServiceCallback(delay);
        }
    });

    thread processThread(processAttacks);

    dataThread.join();
    timingService.join();
    processThread.join();

    return 0;
}
