#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    int value;
    int key;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct {
    Node** nodes;
    int capacity;
    int size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(int capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->size = 0;
    table->nodes = calloc(capacity, sizeof(Node*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

int hash_function(int key, int capacity) {
    return key % capacity;
}

void resize_hash_table(HashTable* table) {
    HashTable new_table = create_hash_table(2 * table->capacity);
    for (int i = 0; i < table->capacity; ++i) {
        Node* current = table->nodes[i];
        while (current != NULL) {
            int hash = hash_function(current->data.key, new_table.capacity);
            Node* next_slot = new_table.nodes[hash];
            new_table.nodes[hash] = current;
            current = current->next;
        }
    }
    free(table->nodes);
    table->nodes = new_table.nodes;
    table->capacity = new_table.capacity;
}

Node* create_node(int value, int key) {
    Node* node = malloc(sizeof(Node));
    node->data.value = rand() % 100 + 1;
    node->data.key = key;
    node->next = NULL;
    return node;
}

void insert_record(HashTable* table, int key, int value) {
    pthread_mutex_lock(&table->lock);
    if (table->size >= table->capacity * 0.75) {
        resize_hash_table(table);
    }
    int hash = hash_function(key, table->capacity);
    Node* current = table->nodes[hash];
    if (current == NULL) {
        table->nodes[hash] = create_node(value, key);
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = create_node(value, key);
    }
    pthread_mutex_unlock(&table->lock);
}

Record* get_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    int hash = hash_function(key, table->capacity);
    Node* current = table->nodes[hash];
    while (current != NULL && current->data.key != key) {
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return current == NULL ? NULL : &current->data;
}

int get_records_count(HashTable* table) {
    int count = 0;
    pthread_mutex_lock(&table->lock);
    for (int i = 0; i < table->capacity; ++i) {
        Node* current = table->nodes[i];
        while (current != NULL) {
            ++count;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&table->lock);
    return count;
}
```

This code provides a basic implementation for the given task. The data structures used are a hash table and linked lists, where each record is represented by a `Record` struct and its associated nodes in the linked list.

The function `create_hash_table()` dynamically allocates memory for the hash table and initializes it with a specified capacity. The `resize_hash_table()` function handles the reallocation of memory when the number of records exceeds 75% of the current capacity.

The `insert_record()` function takes care of thread-safe insertion, ensuring that only one thread can modify the hash table at a time using a mutex lock. The `get_record()` function retrieves a record based on its key and returns a pointer to it. Both functions make efficient use of hash functions for lookups and insertions.

The `get_records_count()` function provides a method to query the current number of records in use without causing performance bottlenecks under high load.']

