typedef struct {
    int value;
} record;

#define MAX_RECORDS 100000
#define RANGE 1000

void* allocate_and_initialize(int *keys, long *offsets, record **records, pthread_mutex_t *mutex) {
    int records_count = 0;
    record *temp_records = NULL;
    pthread_mutex_lock(mutex);

    // Chunked allocation strategy for better memory utilization and reduced fragmentation
    record *chunk = (record *)malloc((MAX_RECORDS / 10) * sizeof(record));
    if (!chunk) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(mutex);
        return NULL;
    }

    temp_records = chunk;

    srand(time(NULL));
    for (int i = 0; records_count < MAX_RECORDS && i < (MAX_RECORDS / 10); ++i) {
        temp_records[i].value = rand() % RANGE;
        if (++records_count == MAX_RECORDS) break;
    }

    while(records_count < MAX_RECORDS) {
        int key = rand() % (MAX_RECORDS / 10);
        if ((temp_records[key].value > temp_threads[key].value && keys != NULL) || (keys == NULL)) {
            record *temp = &temp_records[key];
            memmove(&(temp_records[key]), &(temp_records[records_count]), sizeof(record));
            temp->value = 0;
            records_count++;
        }
    }

    if (records) {
        *records = realloc(*records, records_count * sizeof(record));
        if (!*records) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(mutex);
            return NULL;
        }
        memcpy(*records, temp_records, records_count * sizeof(record));
    }

    // Free the temporary storage and unlock the mutex
    free(temp_records);
    pthread_mutex_unlock(mutex);

    return (void *)1;
}

