    }

    // Initialize and run the function concurrently from multiple threads
    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, allocate_and_initialize, &keys, &offsets, &records, &mutex)) {
            perror("Thread creation failed");
            return 1;
        }
    }

    // Wait for all threads to finish execution
    for (int i = 0; i < 4; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Thread join failed");
            return 1;
        }
    }

    // Free the allocated memory
    free(keys);
    free(offsets);
    free(records);
    pthread_mutex_destroy(&mutex);

    return 0;
}
```

