IntegerCollection* processIntegers(FILE* fp, size_t maxInputCount) {
    IntegerCollection* collection = createIntegerCollection();
    int number;
    size_t count = 0;

    while (count < maxInputCount && fscanf(fp, "%d", &number) == 1) {
        if (!collection->data || count >= collection->count) {
            collection->count *= 2;
            collection->data = realloc(collection->data, sizeof(int) * collection->count);
        }
        collection->data[count] = number;
        count++;
    }

    if (count >= maxInputCount) {
        printf("The input exceeded the limit of 1000 integers. Please re-enter the data.\n");
        destroyIntegerCollection(collection);
        return NULL;
    }

    qsort(collection->data, count, sizeof(int), (int (*)(const void*, const void*)) compareInts);

