typedef struct {
    const char *url;
    int port;
    SSL_CTX *ssl_ctx;
    int retries;
    sem_t sem_conn_available;
} SessionConfig;

typedef enum { SUCCESS, FAILURE } Status;

Status https_init(SessionConfig *config, SSL **ssl) {
    struct addrinfo hints, *res;
    int rc;
    SSL *tmp_ssl;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    rc = getaddrinfo(config->url, config->port, &hints, &res);
    if (rc != 0) {
        perror("getaddrinfo");
        return FAILURE;
    }

    int sockfd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sockfd == -1) {
        perror("socket");
        freeaddrinfo(res);
        return FAILURE;
    }

    rc = connect(sockfd, res->ai_addr, res->ai_addrlen);
    if (rc == -1) {
        close(sockfd);
        perror("connect");
        freeaddrinfo(res);
        return FAILURE;
    }

    tmp_ssl = SSL_new(config->ssl_ctx);
    if (!tmp_ssl) {
        close(sockfd);
        freeaddrinfo(res);
        return FAILURE;
    }

    SSL_set_fd(tmp_ssl, sockfd);

    RC4_KEY key;
    // Load your own key here
    SSL_generate_key(&key, SSL_SHA256, 32);
    SSL_set_ciphers("TLS_ECDHE_RSA_WITH_RC4_128_MD5");
    SSL_ctx_set_options(config->ssl_ctx, SSL_OP_ALL | SSL_OP_NO_TLSv1_2); // Disable TLS 1.3 for compatibility with older systems
    SSL_CTX_set_ciphers(config->ssl_ctx, "RC4-MD5");
    SSL_set_session_id_callback(tmp_ssl, key_exchange_cb);
    SSL_set_key(tmp_ssl, (const unsigned char *)key.data, sizeof(key.data));

    if (!SSL_accept(tmp_ssl)) {
        close(sockfd);
        SSL_free(tmp_ssl);
        freeaddrinfo(res);
        return FAILURE;
    }

    *ssl = tmp_ssl;

    // Release the connection resource for other threads to use
    sem_post(&config->sem_conn_available);

    freeaddrinfo(res);
    return SUCCESS;
}

