#include <time.h>
#include <pthread.h>

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t list_notempty = PTHREAD_COND_INITIALIZER;
int cleanup_required = 0;

time_t last_cleanup = 0;
unsigned int clean_interval = 60; // in seconds

void cleanup() {
    pthread_mutex_lock(&list_lock);
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
    tail = NULL;
    pthread_mutex_unlock(&list_lock);
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) return; // Handle memory allocation failure gracefully

    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = newNode;
        tail = newNode;
    } else {
        tail->next = newNode;
        newNode->prev = tail;
        tail = newNode;
    }
    pthread_mutex_unlock(&list_lock);

    pthread_cond_signal(&list_notempty);
}

