    time_t timestamp;
    // Other event-specific fields...
} NetworkServiceEvent;

// Initialize DTO with given parameters and return a pointer to it
DTO* initDto(unsigned long sessionId, NetworkServiceIdentifier nsId) {
    DTO* dto = (DTO*) malloc(sizeof(DTO));
    if (!dto) {
        perror("Memory allocation error");
        return NULL;
    }

    dto->sessionId = sessionId;
    dto->nsId = nsId;
    dto->capacity = 10; // Initial capacity for event list
    dto->count = 0;
    dto->events = (NetworkServiceEvent*) calloc(dto->capacity, sizeof(NetworkServiceEvent));
    if (!dto->events) {
        perror("Memory allocation error");
        free(dto);
        return NULL;
    }

    pthread_mutex_init(&dto->mutex, NULL);

    return dto;
}

// Validate NetworkServiceEvent before adding it to the DTO
bool validateNetworkServiceEvent(NetworkServiceEvent* event) {
    // Add your custom validation logic here...
    // For this example, we'll use a simple timestamp check
    if (event->timestamp + 10 > time(NULL)) {
        return false;
    }
    return true;
}

// Add a valid NetworkServiceEvent to the DTO, growing its capacity if needed
void addNetworkServiceEvent(DTO* dto, NetworkServiceEvent event) {
    pthread_mutex_lock(&dto->mutex);

    // Validate and append the event only if it's valid
    if (validateNetworkServiceEvent(&event)) {
        if (dto->count >= dto->capacity) {
            dto->capacity *= 2;
            dto->events = realloc(dto->events, dto->capacity * sizeof(NetworkServiceEvent));
            if (!dto->events) {
                perror("Memory allocation error");
                pthread_mutex_unlock(&dto->mutex);
                return;
            }
        }
        dto->events[dto->count++] = event;
    }

    pthread_mutex_unlock(&dto->mutex);
}
