    char *token;
    new_record->num_sensors = 0;
    new_record->sensor_data = (void **)malloc(1 * sizeof(void *));

    token = strtok(line, " ");
    while (token != NULL && new_record->num_sensors < INT_MAX) {
        if (strcmp(token, "") != 0) {
            new_record->sensor_data[new_record->num_sensors] = (void *)atof(token);
            new_record->num_sensors++;
            new_record->sensor_data = realloc(new_record->sensor_data, (new_record->num_sensors + 1) * sizeof(void *));
        }
        token = strtok(NULL, " ");
    }

    new_record->status = strchr(line, ':') != NULL ? &line[strchr(line, ':') - line] : NULL;
    return new_record;
}

