    if (argc < 3) {
        log_error("Usage: ./program input_file output_file");
        return -1;
    }

    FILE *input_file = fopen(argv[1], "r");
    if (!input_file) {
        log_error("Error opening input file.");
        return -1;
    }

    FILE *output_file = fopen(argv[2], "w");
    if (!output_file) {
        log_error("Error opening output file.");
        fclose(input_file);
        return -1;
    }

    char line[4096];
    Record *current_record = NULL;

    while (fgets(line, sizeof(line), input_file)) {
        if (!current_record) {
            current_record = parse_record(line);
            continue;
        }

        // Parse and process the record here
        process_record(current_record);

        Record *temp_record = current_record;
        current_record = parse_record(line);
        free_record(temp_record);
    }

