} NFAPI_CRC_INDICATION_PDU;

typedef struct NCListNode_T {
    NFAPI_CRC_INDICATION_PDU *data;
    struct NCListNode_T *next;
} NCListNode;

NCListNode* NCList_new(size_t n) {
    if (n <= 0) return NULL;

    NCListNode *head = malloc(sizeof(NCListNode));
    if (!head) {
        fprintf(stderr, "Error: Memory allocation failure\n");
        return NULL;
    }

    head->data = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!head->data) {
        free(head);
        fprintf(stderr, "Error: Memory allocation failure\n");
        return NULL;
    }

    head->next = NULL;

    for (size_t i = 0; i < n; ++i) {
        head->data[i].rx_ue_information = DEFAULT_RX_UE_INFORMATION;
        head->data[i].rnti.value = i + 1; // using an incremental RNTI for simplicity
        head->data[i].crc_indication.flag = rand() % 256;
    }

    return head;
}

void NCList_free(NCListNode *list) {
    if (!list) return;

    while (list) {
        NCListNode *next = list->next;
        free(list->data);
        free(list);
        list = next;
    }
}

