DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (!da) {
        log_error("Out of memory");
        return NULL;
    }
    da->entries = malloc(initial_capacity * sizeof(NetworkEventLogEntry*));
    if (!da->entries) {
        log_error("Out of memory");
        free(da);
        return NULL;
    }
    da->capacity = initial_capacity;
    da->size = 0;
    da->mutex = PTHREAD_MUTEX_INITIALIZER;
    return da;
}

void resize_dynamic_array(DynamicArray* da) {
    if (da->capacity <= da->size) {
        size_t new_capacity = da->capacity * 2;
        NetworkEventLogEntry** new_entries = realloc(da->entries, new_capacity * sizeof(NetworkEventLogEntry*));
        if (!new_entries) {
            log_error("Out of memory");
            return;
        }
        da->entries = new_entries;
        da->capacity = new_capacity;
    }
}

void insert(DynamicArray* da, NetworkEventLogEntry* entry) {
    pthread_mutex_lock(&da->mutex);
    resize_dynamic_array(da);
    da->entries[da->size++] = entry;
    pthread_mutex_unlock(&da->mutex);
}

NetworkEventLogEntry* find(DynamicArray* da, uint64_t timestamp) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->size; ++i) {
        if (da->entries[i]->timestamp == timestamp) {
            NetworkEventLogEntry* result = da->entries[i];
            pthread_mutex_unlock(&da->mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&da->mutex);
    return NULL;
}

void delete(DynamicArray* da, uint64_t timestamp) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->size; ++i) {
        if (da->entries[i]->timestamp == timestamp) {
            for (size_t j = i + 1; j < da->size; ++j) {
                da->entries[j - 1] = da->entries[j];
            }
            --da->size;
            pthread_mutex_unlock(&da->mutex);
            free(da->entries[da->size]);
            return;
        }
    }
    pthread_mutex_unlock(&da->mutex);
}

