#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU;

typedef struct NODE {
    NFAPI_CRC_INDICATION_PDU item;
    struct NODE *prev, *next;
} Node;

struct cache {
    size_t capacity;
    size_t count;
    Node **nodes;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
};

Node* create_node() {
    Node *new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        perror("malloc failed\n");
        return NULL;
    }

    new_node->item.rx_ue_information_tag = (RX_UE_INFORMATION_TAG) rand();
    new_node->item.rnti = (RNTI) rand();
    new_node->item.crc_indication_rel8_tag.crc_flag = (CRC_INDICATION_REL8_TAG_CRC_FLAG) rand();

    new_node->prev = new_node->next = NULL;
    return new_node;
}

struct cache* create_cache(size_t capacity) {
    struct cache *cache = (struct cache*) malloc(sizeof(struct cache));
    if (!cache) {
        perror("malloc failed\n");
        return NULL;
    }

    cache->capacity = capacity;
    cache->count = 0;
    cache->nodes = (Node**) calloc(capacity, sizeof(Node*));
    if (!cache->nodes) {
        perror("calloc failed\n");
        free(cache);
        return NULL;
    }

    pthread_mutex_init(&cache->mutex, NULL);
    pthread_cond_init(&cache->not_full, NULL);
    return cache;
}

void destroy_cache(struct cache *cache) {
    if (cache == NULL)
        return;

    for (size_t i = 0; i < cache->capacity; ++i) {
        Node *node = cache->nodes[i];
        while (node != NULL) {
            Node *tmp = node;
            node = node->next;
            free(tmp);
        }
    }
    free(cache->nodes);
    pthread_mutex_destroy(&cache->mutex);
    pthread_cond_destroy(&cache->not_full);
    free(cache);
}

Node* get_node_from_cache(struct cache *cache) {
    if (pthread_mutex_lock(&cache->mutex) != 0) {
        perror("Locking mutex failed\n");
        return NULL;
    }

    for (size_t i = 0; i < cache->capacity; ++i) {
        if (cache->nodes[i] == NULL) {
            Node *node = create_node();
            if (!node) {
                pthread_mutex_unlock(&cache->mutex);
                return NULL;
            }
            cache->nodes[i] = node;
            ++cache->count;
            if (pthread_cond_signal(&cache->not_full) != 0) {
                perror("Signaling condition variable failed\n");
                pthread_mutex_unlock(&cache->mutex);
                return NULL;
            }
            break;
        }
    }

    if (pthread_mutex_unlock(&cache->mutex) != 0) {
        perror("Unlocking mutex failed\n");
        return NULL;
    }
    return cache->nodes[i];
}

void put_node_back_to_cache(struct cache *cache, Node* node) {
    if (pthread_mutex_lock(&cache->mutex) != 0) {
        perror("Locking mutex failed\n");
        return;
    }

    node->prev = NULL;
    node->next = cache->nodes[0];
    if (node->next != NULL)
        node->next->prev = node;

    cache->nodes[0] = node;

    if (pthread_mutex_unlock(&cache->mutex) != 0) {
        perror("Unlocking mutex failed\n");
        return;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_list(struct cache *cache, size_t size) {
    if (size == 0)
        return NULL;

    Node **head = get_node_from_cache(cache);
    if (!head) {
        perror("Failed to allocate node\n");
        return NULL;
    }

    for (size_t i = 1; i < size; ++i) {
        Node *node = get_node_from_cache(cache);
        if (!node) {
            perror("Failed to allocate node\n");
            destroy_list(head, i - 1);
            return NULL;
        }
        head[i - 1]->next = node;
        node->prev = head[i - 1];
    }

    return &head[size - 1]->item;
}

void destroy_list(Node **head, size_t size) {
    if (size == 0 || !head)
        return;

    for (size_t i = size - 1; i > 0; --i) {
        Node *node = head[i];
        head[i] = node->next;
        if (head[i])
            head[i]->prev = node->prev;
        free(node);
    }
}
```

