const fs = require('fs-extra');
const path = require('path');
const Jimp = require('jimp');
const axios = require('axios');
const { promisify } = require('util');
const readFile = promisify(fs.readFile);
const writeFile = promisify(fs.writeFile);
const stat = promisify(fs.stat);
const log = (...messages) => console.log(`[${new Date().toISOString()}]`, ...messages);
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB
const CONCURRENCY_LIMIT = 10;
const RETRY_ATTEMPTS = 3;

async function concatFiles(directory, outputFile, extensions) {
  const filePromises = [];

  async function processFile(filePath) {
    try {
      const statResult = await stat(filePath);
      if (statResult.isDirectory()) return; // Skip directories

      const chunkSize = Math.min(1048576, statResult.size - MAX_FILE_SIZE); // Read in 1 MB chunks
      let content = '';

      for (let offset = 0; offset < statResult.size; offset += chunkSize) {
        const data = await readFile(filePath, { offset });
        content += data.toString();
      }

      // Handle external resources
      if (content.match(/https?:\/\//)) {
        const response = await axios.get(content);
        content = response.data;
      }

      return { filePath, content };
    } catch (error) {
      log(`Error processing ${filePath}:`, error.message);

      if (--RETRY_ATTEMPTS > 0) {
        log(`Retrying...`);
        await new Promise(resolve => setTimeout(resolve, 1000)); // Wait before retrying
        return processFile(filePath);
      }

      log(`Giving up on ${filePath}`);
    }
  }

  async function* iterateFiles(directory) {
    const walking = fs.readdir(directory, { withFileTypes: true })
      .then(results =>
        // Iterate through results recursively to find all files
        function*(results) {
          for (const result of results) {
            if (result.isDirectory()) yield* iterateFiles(path.join(directory, result.name));
            else if (extensions.includes(result.ext)) yield path.join(directory, result.name);
          }
        }(results)
      );

    for await (const file of walking) yield file;
  }

  const files = [...iterateFiles(directory)]
    .slice(0, CONCURRENCY_LIMIT) // Limit concurrent reads
    .map(processFile); // Start processing files

  let totalContent = '';

  for (const { content, filePath } of await Promise.all(files)) {
    totalContent += content;
  }

  await writeFile(outputFile, totalContent);
}
```
