class MemoryPool {
public:
    MemoryPool(size_t capacity) : capacity_(capacity), freeList_(capacity) {
        for (size_t i = 0; i < capacity_; ++i)
            freeList_.emplace_back();
    }

    unique_ptr<NFAPI_CRC_INDICATION_PDU_T> allocate() {
        if (!freeList_.empty()) {
            auto res = move(freeList_.back());
            freeList_.pop_back();
            return res;
        }
