        return unique_ptr<NFAPI_CRC_INDICATION_PDU_T>(new NFAPI_CRC_INDICATION_PDU_T());
    }

    void deallocate(unique_ptr<NFAPI_CRC_INDICATION_PDU_T> p) {
        if (p) freeList_.push_back(move(p));
    }

