class LongBuffer {
private:
    std::atomic<void*> data_{nullptr};
    std::atomic<size_t> capacity_{0};
    const size_t chunkSize;

public:
    LongBuffer(size_t chunkSize) : chunkSize(chunkSize) {}

    long* acquire() {
        long* ptr = static_cast<long*>(data_.load(std::memory_order_acquire));
        if (!ptr) {
            ptr = static_cast<long*>(::operator new(capacity_ * sizeof(long)));
            data_.store(reinterpret_cast<void*>(ptr), std::memory_order_release);
        }
        return ptr + (data_.load(std::memory_order_relaxed) - &data_) / sizeof(long);
    }

    void release(long* ptr) {
        size_t capacity = static_cast<size_t>((static_cast<char*>(ptr) - reinterpret_cast<char*>(&data_)) / sizeof(long));
        if (capacity == capacity_.load(std::memory_order_relaxed)) {
            ::operator delete(data_.exchange(nullptr, std::memory_order_release));
        } else {
            capacity_.store(capacity);
        }
    }
};

// Thread-safe buffer for records
class RecordBuffer {
private:
    std::atomic<void*> data_{nullptr};
    std::atomic<size_t> capacity_{0};
    const size_t chunkSize;

public:
    RecordBuffer(size_t chunkSize) : chunkSize(chunkSize) {}

    Record* acquire() {
        Record* ptr = static_cast<Record*>(data_.load(std::memory_order_acquire));
        if (!ptr) {
            ptr = static_cast<Record*>(::operator new(capacity_ * sizeof(Record)));
            data_.store(reinterpret_cast<void*>(ptr), std::memory_order_release);
        }
        return ptr + (data_.load(std::memory_order_relaxed) - &data_) / sizeof(Record);
    }

    void release(Record* ptr) {
        size_t capacity = static_cast<size_t>((static_cast<char*>(ptr) - reinterpret_cast<char*>(&data_)) / sizeof(Record));
        if (capacity == capacity_.load(std::memory_order_relaxed)) {
            ::operator delete(data_.exchange(nullptr, std::memory_order_release));
        } else {
            capacity_.store(capacity);
        }
    }
};

