constexpr size_t maxMemoryUsage = 50 * getenv("MEMORYSIZE") ? std::stoull(getenv("MEMORYSIZE")) / 2 : 0;

void initializeOctree(size_t featureSize, size_t numLeafNodes) {
    auto availableMemory = maxMemoryUsage < maxMemoryUsage ? maxMemoryUsage : std::stoull(getenv("MEMORYSIZE"));
    size_t totalNodeCount = std::pow(8, std::ceil(std::log2(numLeafNodes)));
    size_t nodeSize = sizeof(OctreeNode) + sizeof(NFAPI_CRC_INDICATION_PDU_T) * numLeafNodes;

    if (totalNodeCount * nodeSize > availableMemory) {
        std::cerr << "Insufficient system memory to create octree with given feature size and number of leaf nodes." << std::endl;
        return;
    }

    auto root = std::make_unique<OctreeNode>();
    OctreeNode* currentNode = root.get();

    for (size_t i = 0; i < totalNodeCount; ++i) {
        currentNode->children.reset(new OctreeNode[8]);
        if (!currentNode->children) {
