struct slab {
    size_t allocated;
    NFAPI_CRC_INDICATION_PDU_T *slabs[16]; // Number of slabs can be adjusted as per requirement
};

struct slab* create_slab(size_t n) {
    struct slab *slab = malloc(sizeof(struct slab));
    if (!slab) return NULL;

    for (size_t i = 0; i < 16 && n > 0; ++i) {
        size_t chunk_size = (n > 512) ? 512 : n;
        slab->slabs[i] = malloc(chunk_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!slab->slabs[i]) {
            free(slab);
            return NULL;
        }
        n -= chunk_size;
        slab->allocated += chunk_size;
    }

    return slab;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(struct slab *slab) {
    for (size_t i = 0; i < 16; ++i) {
        if (slab->allocated >= sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = slab->slabs[i];
            slab->allocated -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
            return pdu;
        }
    }
    return NULL;
}

void* create_pdus(void *arg) {
    int *N = arg;
    struct slab *slab = create_slab(*N);
    if (!slab) return NULL;

    for (size_t i = 0; i < *N; ++i) {
