pub fn create_directory_with_crc_tag(dir_name: &str, num_structures: usize) {
    let crc_dir_path = env::var("CRC_DIR_PATH").unwrap_or_else(|_| "".to_string());
    let log_level = log::LevelFilter::Info;
    // Log initial state for debugging purposes
    logging::log(log_level, &format!("Initializing: CRCDirPath={}, num_structures={}", crc_dir_path, num_structures));

    let mut directory_exists = true;

    if crc_dir_path.is_empty() {
        // If the environment variable is not set, create a new directory with the specified name
        let temp_dir = tempfile::Builder::new().prefix("crc").tempdir().unwrap();
        let dir_path = temp_dir.path();
        dir_name.as_os_str().create_directories_all(dir_path).unwrap();

        // Set the environment variable and log the new path
        env::set_var("CRC_DIR_PATH", dir_path.to_string_lossy().into_owned());
        logging::log(log_level, &format!("Created new directory: {}", dir_path));
    } else {
        let path = PathBuf::from(crc_dir_path);
        match path.is_dir() {
            true => (), // Directory already exists
            false => directory_exists = false,
        }
    }

    if !directory_exists {
        match path.canonicalize() {
            Ok(p) => {
                if p.is_err() {
                    error!("CRC directory does not exist or is not writable: {}", crc_dir_path);
                    return;
                }
            }
            Err(_) => {
                error!("Unable to canonicalize CRC directory path: {}", crc_dir_path);
                return;
            }
        }

        if !p.as_os_str().exists() || !p.as_os_str().is_writable() {
            warn!("CRC directory does not exist or is not writable: {}", crc_dir_path);
            return;
        }
    }

    let mut structures = Vec::with_capacity(num_structures);
    let mut rng = rand::thread_rng();

    for _ in 0..num_structures {
        let rx_ue_information_tag: u32 = rand::thread_rng().gen();
        let rnti: u16 = rand::thread_rng().gen();
        let crc_indication_rel8_tag: u32 = rand::thread_rng().gen();
        let crcflag = if rng.gen::<u8>() % 2 == 0 { 1 } else { 0 };

        let pdu = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag,
            crcflag,
        };

        let file_path = PathBuf::from(crc_dir_path).join(format!("structure_{}.txt", structures.len()));
        match File::with_name(&file_path).create_text(true) {
            Ok(mut f) => {
                let mut writer = BufWriter::new(f);
                writer.write_all(&pdu.to_string().as_bytes()).unwrap();
                structures.push(pdu);
            }
            Err(e) => {
                error!("Unable to create file for structure: {}", e);
            }
        }
    }

    logging::log(log_level, &format!("Created {} CRC structures in directory: {}", num_structures, crc_dir_path));
}
