// Define the structure
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

// Define the cooldown structure
struct Cooldown {
    std::chrono::steady_clock::time_point lastUse;
    int64_t cooldownPeriod = 9 * std::chrono::seconds(1); // 9 seconds in microseconds
};

class Manager {
private:
    std::deque<NFAPI_CRC_INDICATION_PDU_T> dataList;
    std::unordered_map<int, Cooldown> cooldownMap;
    std::mutex listMutex;
    std::mutex cooldownMutex;

public:
    void addData(const NFAPI_CRC_INDICATION_PDU_T& data) {
        std::unique_lock<std::mutex> lock(listMutex);
        dataList.push_back(data);
    }

    NFAPI_CRC_INDICATION_PDU_T popData() {
        std::unique_lock<std::mutex> lock(listMutex);
        auto front = dataList.front();
        dataList.pop_front();
        return front;
    }

    bool canUseAction(int action) {
        std::unique_lock<std::mutex> lock(cooldownMutex);
        auto it = cooldownMap.find(action);
        if (it == cooldownMap.end()) {
            cooldownMap[action] = Cooldown{};
        }
        if ((std::chrono::steady_clock::now() - it->second.lastUse) < it->second.cooldownPeriod) {
            return false;
        }
        it->second.lastUse = std::chrono::steady_clock::now();
        return true;
    }

    void useAction(int action, const std::function<void()>& logFunction) {
        if (canUseAction(action)) {
            logFunction();
            // Simulate random CRCFLAG for demonstration purposes.
            NFAPI_CRC_INDICATION_PDU_T data = { rxTag, rnti, { CRCFlag::generateRandom() } };
            addData(data);
        }
    }
};
```

This code defines a Manager class that manages both tasks. The `addData` and `popData` functions handle the dynamic list of structures, while the `canUseAction` and `useAction` functions manage the two types of in-game actions with their specific cooldown periods.

The class uses a std::deque for efficient handling of concurrent operations on the data list and an std::unordered_map to track the last usage timestamp of each action type. Thread safety is ensured by using std::mutexes for both the list and the cooldown map.']

