typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

#define MAX_LIST_SIZE 1000
Node* head = NULL;
int list_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void push(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return; // Handle memory allocation failure

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&mutex);
    if (list_size >= MAX_LIST_SIZE || find_rnti(new_node->data.rnti)) {
        free(new_node);
        pthread_mutex_unlock(&mutex);
        return; // Max list size reached or duplicate RNTI found
    }

    if (!head) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    list_size++;
    pthread_mutex_unlock(&mutex);
}

bool find_rnti(RNTI rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) return true;
        current = current->next;
    }
    return false;
}

NFAPI_CRC_INDICATION_PDU_T* get_first() {
    NFAPI_CRTC_INDICATION_PDU_T* first = (NFAPI_CRC_INDICATION_PDU_T*)head;
    if (!head) return NULL;

    head = head->next;
    list_size--;
    return first;
}

unsigned int compute_checksum() {
    unsigned int checksum = 0;
    Node* current = head;
    while (current != NULL) {
        checksum += current->data.crc_indication.crcflag;
        current = current->next;
    }
    return checksum;
}

// External data source callback function
void on_ue_info(RX_UE_INFORMATION_TAG rx_ue_info, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T new_data = {rx_ue_info, rnti, {.crcflag = rand() % 256}};
    push(new_data);
}
```

