#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/resource.h>
#include <semaphore.h>
#include "logging.h" /* Provided by the caller */

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static sem_t sem_mem; /* Semaphore for memory allocation */
static pthread_mutex_t log_mtx = PTHREAD_MUTEX_INITIALIZER; /* Mutex for logging */

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(unsigned int num_elements, RX_UE_INFORMATION_TAG *rx_ue_information, RNTI *rnti, CRC_INDICATION_REL8_TAG *crc_indication) {
    if (!rx_ue_information || !rnti || !crc_indication || num_elements == 0) {
        log_error("Invalid input parameters");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_error("Memory allocation failure");
        return NULL;
    }

    sem_init(&sem_mem, 0, num_elements);

    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    double init_time = (double)usage.ru_utime.tv_sec + (double)usage.ru_utime.tv_usec / 1000000;

    for (unsigned int i = 0; i < num_elements; ++i) {
        sem_wait(&sem_mem);

        list[i].rx_ue_information = *rx_ue_information++;
        list[i].rnti = *rnti++;
        list[i].crc_indication.crcflag = (unsigned char)rand() % 2; /* Set CRCFLAG to either 0 or 1 */
    }

    getrusage(RUSAGE_SELF, &usage);
    double elapsed_time = (double)usage.ru_utime.tv_sec + (double)usage.ru_utime.tv_usec / 1000000 - init_time;

    log_info("Created and populated %u structures in %f seconds", num_elements, elapsed_time);

    return list;
}
```

