typedef struct {
    const char* name;
    void* (*init)(void*, size_t);
    void (*free)(void*);
    void (*hash)(void*, const uint8_t*, size_t, uint8_t*);
    void (*encrypt)(void*, const uint8_t*, size_t, uint8_t*);
    void (*decrypt)(void*, const uint8_t*, size_t, uint8_t*);
} algorithm_t;

typedef struct plugin {
    const char* name;
    void* handle;
    const char* entry_point;
} plugin_t;

plugin_t* load_plugins(const char** paths) {
    plugin_t* plugins = NULL;
    size_t num_plugins = 0;

    for (const char* path : paths) {
        void* handle = dlopen(path, RTLD_LAZY);
        if (!handle) continue;

        const char* symbol = dlsym(handle, "get_plugins");
        plugin_t** new_plugins = realloc(plugins, sizeof(plugin_t) * (num_plugins + 1));
        if (!new_plugins) {
            dlclose(handle);
            continue;
        }
        plugins = new_plugins;

        void* (*get_plugins)(void) = dlsym(handle, symbol);
        plugin_t* plugin_list = get_plugins();
        if (plugin_list) {
            num_plugins += plugins - plugins + 1;
            memcpy(&plugins[num_plugins - 1], plugin_list, sizeof(plugin_t) * num_plugins);
        }
        dlclose(handle);
    }
    return plugins;
}

algorithm_t* init_algorithms(plugin_t* plugins, size_t num_plugins) {
    algorithm_t** algorithms = calloc(num_plugins, sizeof(algorithm_t));

    for (size_t i = 0; i < num_plugins; ++i) {
        void* (*init_func)(void*, size_t) = dlsym(plugins[i].handle, plugins[i].entry_point);
        algorithms[i] = init_func(plugins[i].name, sizeof(algorithm_t));
    }
    return algorithms;
}

void free_algorithms(algorithm_t* algorithms, size_t num_algorithms) {
    for (size_t i = 0; i < num_algorithms; ++i)
        algorithms[i]->free(algorithms[i]);
    free(algorithms);
}

