    public class DatabaseQueryExecutor
    {
        private readonly ILogger<DatabaseQueryExecutor> _logger;
        private const int DefaultPageSize = 20;
        private const string ConnectionStringKey = "DefaultConnection";

        public DatabaseQueryExecutor(ILogger<DatabaseQueryExecutor> logger)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        public async Task<IDataReader> ExecuteDynamicQueryAsync(string commandTemplate, IDictionary<string, object> parameters, int pageSize = DefaultPageSize, int pageNumber = 1)
        {
            var connectionString = ConfigurationManager.ConnectionStrings[ConnectionStringKey];
            using (var connection = new SqlConnection(connectionString))
            using (var command = new SqlCommand(commandTemplate, connection))
            {
                PrepareCommand(command, parameters);
                SetPageSizeAndOffset(command, pageSize, pageNumber);
                await connection.OpenAsync();
                var reader = await command.ExecuteReaderAsync();
                return reader;
            }
        }

        private void PrepareCommand(SqlCommand command, IDictionary<string, object> parameters)
        {
            foreach (var parameter in parameters)
            {
                command.Parameters.AddWithValue(parameter.Key, parameter.Value);
            }
        }

        private void SetPageSizeAndOffset(SqlCommand command, int pageSize, int pageNumber)
        {
            var offset = (pageNumber - 1) * pageSize;
            command.Parameters.Add("@offset", SqlDbType.Int);
            command.Parameters["@offset"].Value = offset;
            command.Parameters.Add("@limit", SqlDbType.Int);
            command.Parameters["@limit"].Value = pageSize;
        }

        private void HandleException(Exception exception)
        {
            _logger.LogError(exception, "An error occurred while executing a database query.");
        }
    }
}
