async function runTest(label: string, f: () => Promise<void>, options: TestOptions = {}): Promise<void> {
  const defaultTimeout = 5000;
  const { timeout = defaultTimeout, logLevel = 'info' } = options;

  // Load the module dynamically
  let mod: any;
  try {
    mod = await require(f.module);
  } catch (error) {
    console.error(`Error while loading module "${f.module}":`, error);
    return;
  }

  // Set up logging mechanism based on the specified log level
  const log = (level: string, message: string) => {
    if (level === logLevel || logLevel === 'all') {
      console[level](`${label}: ${message}`);
    }
  };

  // Handle external data sources using a mock when unavailable
  let dataSource;
  try {
    dataSource = await f.getData();
  } catch (error) {
    log('warn', `Error while fetching data from "${f.dataSource}": ${error}`);
    dataSource = f.mockData || [];
  }

  // Execute the test asynchronously within a timeout
  const start = Date.now();
  let testRunning = true;
  let timeoutHandler: NodeJS.Timeout | undefined;
  const testPromise = new Promise<void>((resolve, reject) => {
    timeoutHandler = setTimeout(() => {
      testRunning = false;
      log('error', `Test "${label}" timed out after ${timeout}ms`);
      reject(new Error(`Test "${label}" timed out`));
    }, timeout);

    f.testFunction(dataSource, (err) => {
      clearTimeout(timeoutHandler);
      if (err) {
        log('error', `Error during test "${label}":`, err);
        reject(err);
      } else {
        resolve();
      }
      testRunning = false;
    });
  });

  // Reset the logging mechanism after each test execution
  testPromise.then(() => {
    log('info', `Test "${label}" completed successfully`);
    if (mod.resetLog) {
      mod.resetLog();
    }
  }).catch((error) => {
    log('error', `Error during test execution:`, error);
    if (mod.resetLog) {
      mod.resetLog();
    }
  });

  // Run the test asynchronously with concurrency cap and performance optimization
  if (!testRunning) {
    log('info', `Skipping test "${label}" due to previous failure`);
  } else {
    log('info', `Starting test "${label}" (${(Date.now() - start)}ms elapsed)`);
  }
}
```

