  }

  async addChunk(dataChunk) {
    this.chunks.push(dataChunk);
  }

  static async aggregateAndCopyBytes(byteCount, offset = 0) {
    let totalData = Buffer.concat(this.chunks.map(chunk => chunk.data.slice(chunk.offset + offset)));
    if (totalData.length < byteCount) {
      throw new Error(`Requested byte count exceeds available data. (${byteCount} > ${totalData.length})`);
    }

    let result = totalData.slice(0, byteCount);
    this.chunks = []; // Clear chunks after processing
    return result;
  }

