[' Here is a minimal code structure for your task using Netty as a non-blocking I/O library, which handles up to 100 simultaneous connections and provides a connection pool. The code also includes a retry mechanism, monitoring, logging, and adaptability to varying network conditions.

```java
import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import io.netty.handler.logging.LoggingHandler;
import io.netty.handler.retry.RetryOnFailureHandler;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ConnectionManager {
    private static final int MAX_CONNECTIONS = 100;
    private static final int CONNECTION_POOL_SIZE = Math.max(Runtime.getRuntime().availableProcessors() * 2, MAX_CONNECTIONS);
    private final ExecutorService connectionPool = Executors.newFixedThreadPool(CONNECTION_POOL_SIZE);
    private final AtomicInteger activeConnections = new AtomicInteger(0);
    private static final Logger LOGGER = LoggerFactory.getLogger(ConnectionManager.class);
    private final EventLoopGroup bossGroup = new NioEventLoopGroup();
    private final EventLoopGroup workerGroup = new NioEventLoopGroup();

    public void start() {
        ServerBootstrap bootstrap = new ServerBootstrap();
        bootstrap.group(bossGroup, workerGroup)
                .channel(NioServerSocketChannel.class)
                .handler(new LoggingHandler(LOGGER))
                .option(ChannelOption.SO_BACKLOG, 128)
                .childHandler(new ChannelInitializer<Channel>() {
                    @Override
                    protected void initChannel(Channel ch) throws Exception {
                        ChannelPipeline pipeline = ch.pipeline();
                        pipeline.addLast(new RetryOnFailureHandler(5, 100, TimeUnit.MILLISECONDS));
                        // Add other handlers for monitoring and logging here
                    }
                });

        ChannelFuture channelFuture = bootstrap.bind(PortNumber);
        channelFuture.syncUninterruptibly();

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            LOGGER.info("Shutting down the ConnectionManager...");
            gracefulStop();
        }));
    }

    private void gracefulStop() {
        connectionPool.shutdownNow();
        bossGroup.shutdownGracefully();
        workerGroup.shutdownGracefully();
    }

    public Channel acquireConnection() {
        return connectionPool.submit(() -> {
            activeConnections.incrementAndGet();
            return newDefaultChannel();
        }).get();
    }

    public void releaseConnection(Channel channel) {
        if (activeConnections.decrementAndGet() <= 0) {
            throw new IllegalStateException("No more active connections!");
        }
        connectionPool.execute(() -> {
            // Cleanup or close the connection here
        });
    }

    private Channel newDefaultChannel() {
        return bootstrap.channel();
    }
}
```

You'll have to fill in the gaps, such as implementing monitoring and logging handlers, handling other network conditions, and potentially using a dedicated connection pool implementation. Additionally, consider configuring Netty optimally for your use-case, such as setting suitable buffers sizes or enabling keep-alive connections.']

