import os
from flask import Flask, request, jsonify, abort
import json
import requests
import time
import logging
from dotenv import load_dotenv

load_dotenv()  # Load environment variables from .env file
API_URL = os.getenv("API_URL", "https://api.example.com")
CONFIG_PATH = os.getenv("CONFIG_PATH") or ".config.json"
DEBUG_MODE = os.getenv("DEBUG_MODE", False)
APP_NAME = os.getenv("APP_NAME", "MyApp")

def load_config():
    try:
        with open(CONFIG_PATH, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file '{CONFIG_PATH}' not found.")
        return {}
    except json.JSONDecodeError:
        logging.error(f"Failed to parse configuration file '{CONFIG_PATH}'. Expected JSON format.")
        return {}

    config["DEBUG"] = bool(config.get("DEBUG", DEBUG_MODE))
    return config

def make_api_request(url, data=None):
    headers = {"Content-Type": "application/json"}
    timeout = 5  # Adjust as needed for your API
    retries = 3

    while retries > 0:
        try:
            response = requests.post(url, json=data, timeout=timeout, headers=headers)
            if response.status_code == 200 or response.status_code == 201:
                return response.json()
        except (requests.ConnectionError, requests.Timeout):
            retries -= 1
            logging.warning(f"API request to '{url}' failed. Retrying {retries} times.")
            time.sleep(5)

    abort(503, f"Failed to make API request after {retries} retries.")

app = Flask(__name__)
config = load_config()
logging.basicConfig(filename=f'{APP_NAME}_logs.log', level=logging.INFO)

@app.route('/update_config', methods=['POST'])
def update_config():
    try:
        new_config = json.loads(request.data)
        config.update(new_config)
        with open(CONFIG_PATH, 'w') as f:
            json.dump(config, f, indent=2)
        logging.info(f"Configuration updated with {len(new_config)} items.")
        return jsonify({"message": "Configuration updated successfully."}), 200
    except ValueError:
        abort(400, "Invalid configuration data. Use JSON format.")

if __name__ == "__main__":
    app.run(debug=config['DEBUG'])
```

