use std::cell::RefCell;

fn allocate_pdus(n: usize) -> Arc<RefCell<Vec<NFAPI_CRC_INDICATION_PDU_T>>> {
    let pdu_vec = RefCell::new(Vec::with_capacity(n));
    let pdu_arc = Rc::new(pdu_vec);

