use std::os::unix::process::CommandExt;
use std::path::Path;
use std::process::{Child, Command, Stdio};
use std::sync::Arc;
use time::precise_time_now as current_timestamp;
use tokio::fs::FileLock;
use tokio::task::spawn_blocking;
use tokio::runtime::Runtime;
use tower::{util::Tower, ServiceBuilder};
use tower_dns::Dns;
use tower_http::services::ServeDir;
use tower_web::Server;

struct CompileHook {
    rss: Arc<Option<u64>>,
}

impl CompileHook {
    fn new() -> Self {
        Self { rss: Arc::new(None) }
    }

    async fn before_exec(&mut self, cmd: &mut Command) {
        let start = current_timestamp();
        let _lock = FileLock::try_create(Path::new("/tmp/rust-compiler.lock")).unwrap();
        self.rss.replace(cmd.pre_exec(|_| {
            cmd.pre_exec(|_| {
                println!(
                    "Compiling {}... ({} seconds elapsed)",
                    cmd.args().join(" "),
                    current_timestamp() - start
                );
                Ok(())
            })
        }))
        .unwrap();
    }
}

async fn resolve_hostname(hostname: &str) -> Option<String> {
    let mut runtime = Runtime::new().unwrap();
    let dns = Dns::default();
    let service = ServiceBuilder::new()
        .wrap(dns.into_service())
        .serve_dir(|req| {
            req.respond_with_file(Path::new("./resolver"), &[0])
        })
        .build_owned();
    let mut server = Server::from_service(service).unwrap();
    server.run_until_ready().await;
    let resolver = Arc::new(server);

    spawn_blocking(move || {
        let hostname = hostname.to_string();
        let resolved = resolver.execute(reqwest::get(&format!("http://{}", hostname))).unwrap().await;
        if let Ok(res) = resolved {
            match res.status() {
                reqwest::StatusCode::OK => Some(res.text().await?.trim_end_matches('\n').to_string()),
                _ => None,
            }
        } else {
            None
        }
    })
    .await
    .unwrap();

    resolver.shutdown().await;
    resolved
}

fn compile(hostname: &str) -> i32 {
    let host = resolve_hostname(hostname).unwrap_or_else(|e| {
        eprintln!("Failed to resolve hostname {}: {}", hostname, e);
        "localhost"
    });

    let mut cmd = Command::new("rustc");
    cmd.arg("-o")
        .arg("target/debug/main")
        .args(&["src/main.rs"])
        .env_clear()
        .current_dir(Path::new("."))
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());
    let hook = CompileHook::new();
    cmd.pre_exec(|_| hook.before_exec(&mut cmd));

    let output = match cmd.spawn() {
        Ok(output) => output,
        Err(_) => {
            eprintln!("Failed to spawn rustc command.");
            return 1;
        }
    };

    let rss_before = hook.rss.clone().unwrap();
    let status = output.wait().expect("Failed to wait for process");
    let rss_after = hook.rss.clone().unwrap();

    if let Some(rss_diff) = (rss_after - rss_before).checked_sub(1) {
        println!("RSS increased by {} during compilation", rss_diff);
    }

    status.code().unwrap_or(1)
}
```

