    pthread_mutex_lock(&list_mutex);

    if (!head) {
        head = tail = new_node;
        goto unlock;
    }

    tail->next = new_node;
    new_node->prev = tail;
    tail = new_node;

unlock:
    pthread_mutex_unlock(&list_mutex);
}

// Function to clean up records older than 60 seconds
void cleanup() {
    pthread_mutex_lock(&list_mutex);

    ClinicRecord *current = head;
    time_t now = time(NULL);

    while (current) {
        if ((now - current->timestamp) > 60) {
            ClinicRecord *temp = current;
            if (current == head) {
                head = current->next;
            } else {
                current->prev->next = current->next;
            }
            if (current == tail) {
                tail = current->prev;
            } else {
                current->next->prev = current->prev;
            }
            free(current);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

// Function to update the status of a clinic
bool update_clinic_status(int clinic_id, char *new_status, const char *last_modified_data) {
    bool success = false;

    pthread_mutex_lock(&list_mutex);

    ClinicRecord *node = head;
    while (node) {
        if (node->clinic_id == clinic_id) {
            strcpy(node->status, new_status);
            strcpy(node->last_modified_data, last_modified_data);
            success = true;
            break;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list_mutex);

    if (success) {
        printf("Updated clinic %d status to: %s\n", clinic_id, new_status);
        cleanup(); // Periodically clean up records older than 60 seconds
    }

    return success;
}
