    private readonly HttpClient _httpClient;
    private readonly ILogger<OAuthEndpoint> _logger;
    private const string TokenEndpointUrlKey = "TokenEndpointUrl";
    private const string ClientIdKey = "ClientId";
    private const string ScopeKey = "Scope";

    public OAuthEndpoint(HttpClient httpClient, ILogger<OAuthEndpoint> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public async Task<X509Certificate2> AuthenticateAsync(Dictionary<string, string> requestParameters)
    {
        var credentials = GetCredentials();

        var tokenEndpointUrl = requestParameters[TokenEndpointUrlKey];
        var clientId = requestParameters[ClientIdKey];
        var scope = requestParameters[ScopeKey];

        var tokenRequest = new Dictionary<string, string>
        {
            { "client_id", clientId },
            { "scope", scope }
        };

        try
        {
            var response = await _httpClient.PostAsync(tokenEndpointUrl, new FormUrlEncodedContent(tokenRequest));
            response.EnsureSuccessStatusCode();

            var tokenResponseJson = await response.Content.ReadAsStringAsync();
            var tokenResponse = JsonConvert.DeserializeObject<Dictionary<string, string>>(tokenResponseJson);
            var accessToken = tokenResponse["access_token"];

            _logger.LogInformation("Authenticating with the token endpoint using provided credentials.");

            var authenticationHeaders = new Dictionary<string, string>
            {
                { "Authorization", $"Bearer {accessToken}" },
            };

            var certificateChainResponse = await RetrieveCertificateChainAsync(tokenEndpointUrl, authenticationHeaders);
            var privateKeyResponse = await RetrievePrivateKeyAsync();

            if (certificateChainResponse == null || privateKeyResponse == null)
                throw new Exception("Unable to retrieve the user's private key and certificate.");

            return CombineCertificateAndPrivateKey(certificateChainResponse, privateKeyResponse);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to authenticate or retrieve user's private key and certificate.");
            throw;
        }
    }

    private X509Certificate2 CombineCertificateAndPrivateKey(X509Certificate2[] chain, RSA privateKey)
    {
        var combinedCert = new X509Certificate2(chain);
        combinedCert.PrivateKey = privateKey;
        return combinedCert;
    }

    private async Task<X509Certificate2[]> RetrieveCertificateChainAsync(string tokenEndpointUrl, Dictionary<string, string> headers)
    {
        try
        {
            var response = await _httpClient.GetAsync(tokenEndpointUrl, new HttpRequestMessage() { Headers = headers });
            response.EnsureSuccessStatusCode();

            var certificateChainResponseJson = await response.Content.ReadAsStringAsync();
            var certificateChainResponse = JsonConvert.DeserializeObject<X509Certificate2[]>(certificateChainResponseJson);

            return certificateChainResponse;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to retrieve the user's certificate chain.");
            throw;
        }
    }

    private async Task<RSA> RetrievePrivateKeyAsync()
