<?php
declare(strict_types=1);

class Authenticator {
    private const CACHE_KEY = 'auth:user:';
    private const RATE_LIMIT_WINDOW = 60; // in seconds (1 minute)
    private const REFRESH_TOKEN_INTERVAL = 300; // in seconds (5 minutes)
    private const EXPONENTIAL_BACKOFF_FACTOR = 2;
    private $accessToken;
    private $cache;
    private $rateLimiter;

    public function __construct(Redis $redis) {
        $this->cache = $redis;
        $this->rateLimiter = new RateLimiter($redis, self::RATE_LIMIT_WINDOW);
    }

    public function authenticate($provider, $code) {
        if (!$this->rateLimiter->allow()) {
            throw new TooManyRequestsException('Rate limit exceeded');
        }

        try {
            $token = $provider->getAccessToken($code);
            $this->updateSession($token);
            $userInfo = $this->fetchUserInfo();
            $this->cache->set(self::CACHE_KEY . $this->accessToken, json_encode($userInfo), self::REFRESH_TOKEN_INTERVAL);
            return $userInfo;
        } catch (\Exception $e) {
            // Handle exceptions for network failures, invalid tokens etc.
            // Provide feedback to users about delayed responses.
            throw $e;
        }
    }

    public function refreshToken() {
        if (!$this->accessToken) {
            return null;
        }

        try {
            $newToken = $this->accessTokenProvider->refreshToken($this->accessToken);
            $this->updateSession($newToken);
            $this->cache->set(self::CACHE_KEY . $this->accessToken, json_encode($this->fetchUserInfo()), self::REFRESH_TOKEN_INTERVAL);
            return $newToken;
        } catch (\Exception $e) {
            // Handle exceptions for network failures, invalid tokens etc.
            // Provide feedback to users about delayed responses.
            throw $e;
        }
    }

    private function fetchUserInfo() {
        if ($this->cache->exists(self::CACHE_KEY . $this->accessToken)) {
            return json_decode($this->cache->get(self::CACHE_KEY . $this->accessToken), true);
        }

        // Use locking or transactional operations to avoid race conditions.
        $lockKey = 'auth:user:' . $this->accessToken . ':lock';
        if ($this->cache->setnx($lockKey, 1)) {
            try {
                $userInfo = $this->provider->getUserInfo($this->accessToken);
                $this->cache->set(self::CACHE_KEY . $this->accessToken, json_encode($userInfo), self::REFRESH_TOKEN_INTERVAL);
                $this->cache->del($lockKey);
                return $userInfo;
            } catch (\Exception $e) {
                // Handle exceptions for network failures, invalid tokens etc.
                // Release the lock and retry with exponential backoff.
                $this->cache->del($lockKey);
                usleep(pow(2, self::EXPONENTIAL_BACKOFF_FACTOR) * 1000000);
            }
        } else {
            // Handle concurrent requests gracefully without deadlocking.
            $this->cache->del($lockKey);
        }
    }
}
