#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    uint64_t transaction_id;
    double weight;
    time_t timestamp;
} Transaction;

// Maximum number of transactions in sliding window
#define WINDOW_SIZE 500

struct Processor {
    pthread_mutex_t mutex;
    uint64_t current_count;
    double sum;
    double max_weight;
    Transaction buffer[WINDOW_SIZE];
    size_t head, tail;
};

double process_transaction(struct Processor *processor, const Transaction *transaction) {
    pthread_mutex_lock(&processor->mutex);
    double age = time(NULL) - transaction->timestamp;

    // Filter based on age and sliding window occupancy
    if (age > 5 || processor->current_count >= WINDOW_SIZE) {
        pthread_mutex_unlock(&processor->mutex);
        return 0.0;
    }

    processor->sum += transaction->weight * age;
    processor->current_count++;

    // Maintain volume, average weight and maximum weight per second metrics
    if (transaction->weight > processor->max_weight) {
        processor->max_weight = transaction->weight;
    }

    // Update buffer and move head
    buffer[processor->head] = *transaction;
    processor->head = (processor->head + 1) % WINDOW_SIZE;

    pthread_mutex_unlock(&processor->mutex);
    return processor->max_weight;
}
```

This code provides the basic structure for a transaction processing function. It maintains a sliding window and manages concurrent access using a mutex. To ensure scalability, consider implementing this in an asynchronous fashion using a message queue or other concurrency mechanisms. Optimizations for CPU and memory performance can be achieved by profiling the code and identifying bottlenecks.

Additionally, you may want to consider using a high-performance data structure such as a ring buffer for the transaction buffer to minimize memory allocations and reduce cache thrashing when dealing with large volumes of transactions.']

