#include <random>

std::uniform_int_distribution<int> distribution(0, 4);
std::mt19937 randomEngine;

std::unordered_map<int, std::pair<int64_t, int>> abilityCooldowns; // key: ability index, value: (cooldown timer, usage count)
std::mutex abilityCooldownsMutex;

void checkAbilityCooldown(int abilityIndex) {
    std::unique_lock<std::mutex> lock(abilityCooldownsMutex);
    auto it = abilityCooldowns.find(abilityIndex);
    if (it != abilityCooldowns.end()) {
        int64_t currentTime = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
        int64_t cooldownEnd = it->second.first + (it->second.second < 60 ? 60 : it->second.first);

        if (currentTime >= cooldownEnd) {
            it->second.first = currentTime;
            it->second.second++;
        }
    }
}

void selectAbility() {
    int abilityIndex = distribution(randomEngine);
    checkAbilityCooldown(abilityIndex);

    if (it == abilityCooldowns.end() || abilityCooldowns[abilityIndex].second >= 10) {
        return;
    }

    std::unique_lock<std::mutex> lock(abilityCooldownsMutex);
    abilityCooldowns[abilityIndex] = std::make_pair((it->second.first + 5 + std::random_device()() % (11 - 5 + 1)), it->second.second + 1);
}

void run() {
    while (true) {
        selectAbility();
        std::this_thread::sleep_for(std::chrono::milliseconds(1000 / 60)); // Sleep for 1/60th of a second to limit the function execution rate to approximately once per millisecond
    }
}

int main() {
    randomEngine.seed(std::random_device()());
    std::thread threads[5];

    for (int i = 0; i < 5; ++i) {
        threads[i] = std::thread(run);
    }

    for (auto& t : threads) {
        t.join();
    }
}
