namespace CustomDataProcessor
{
    public class CustomDataProcessor
    {
        private int batchSize;
        private int currentBatchIndex;
        private List<string> processedData = new List<string>();

        public int BatchSize { get => batchSize; set => batchSize = value > 0 ? value : throw new ArgumentException("Batch size must be greater than zero."); }

        public CustomDataProcessor(int batchSize)
        {
            this.batchSize = batchSize;
            currentBatchIndex = 0;
        }

        public void AddRecord(string data)
        {
            if (processedData.Count >= batchSize && processedData[processedData.Count - 1] != null)
            {
                // Process the current batch when full or at end of last record
                ProcessBatch();
            }

            processedData.Add(data);
        }

        public List<string> GetProcessedData()
        {
            var data = processedData.TakeWhile((item, index) => index <= currentBatchIndex).ToList();
            return data;
        }

        private void ProcessBatch()
        {
            // Add your processing logic here, such as integrating with external services or performance tuning strategies.
            var batch = processedData.Take(batchSize).ToList();
            processedData.RemoveRange(0, batch.Count);
            currentBatchIndex++;
        }

        public void ResetState()
        {
            processedData.Clear();
            currentBatchIndex = 0;
        }

        public override string ToString()
        {
            return $"CustomDataProcessor: Batch Index={currentBatchIndex}, Total Records Processed={processedData.Count}";
        }
    }
}
