    FILE* inputFile = fopen(inputFilePath, "rb");
    if (!inputFile) {
        fprintf(logger.stream, "Error: Unable to open input file %s\n", inputFilePath);
        return 1;
    }

    JPEG_DECODE_PARAMS jpegParams;
    if (jpeg_get_decompress(&jpegParams)) {
        fprintf(logger.stream, "Error: Failed to initialize JPEG decoder\n");
        fclose(inputFile);
        return 2;
    }

    jpeg_mem_src(&jpegParams, inputFile);
    if (jpeg_read_header(&jpegParams, TRUE)) {
        fprintf(logger.stream, "Error: Failed to read JPEG header\n");
        jpeg_destroy_decompress(&jpegParams);
        fclose(inputFile);
        return 3;
    }

    if (jpegParams.output_width > MAXIMUM_ALLOWED_PDF_WIDTH || jpegParams.output_height > MAXIMUM_ALLOWED_PDF_HEIGHT) {
        fprintf(logger.stream, "Error: JPEG dimensions exceed maximum allowed for PDF conversion\n");
        jpeg_destroy_decompress(&jpegParams);
        fclose(inputFile);
        return 4;
    }

    void* pdfBuffer = malloc(PDF_BUFFER_SIZE);
    PDF* pdf = pdf_create(pdfBuffer, PDF_BUFFER_SIZE);
    if (!pdf) {
        fprintf(logger.stream, "Error: Failed to create PDF\n");
        jpeg_destroy_decompress(&jpegParams);
        fclose(inputFile);
        return 5;
    }

    pdf_set_info(pdf, reportTitle, NULL, NULL);

    pthread_mutex_init(&mutex, NULL);
    NFAPI_CRCI_PDU_T* structures = malloc(N * sizeof(NFAPI_CRCI_PDU_T));
    for (int i = 0; i < N && pthread_mutex_lock(&mutex) == 0; ++i) {
        initStructure(&structures[i]);
        pthread_mutex_unlock(&mutex);
    }
    pthread_mutex_destroy(&mutex);

    jpeg_start_decompress(&jpegParams);
    if (processJPEGData(pdf, &jpegParams) || generateReport(pdf, reportTitle, structures)) {
        fprintf(logger.stream, "Error: Failed to process JPEG data or generate report\n");
        pdf_destroy(pdf);
        free(structures);
        jpeg_finish_decompress(&jpegParams);
        jpeg_destroy_decompress(&jpegParams);
        fclose(inputFile);
        return 6;
    }

    jpeg_finish_decompress(&jpegParams);
    jpeg_destroy_decompress(&jpegParams);

    int pdfSize = pdf_write_data(pdf, outputFilePath);
    if (pdfSize <= 0) {
        fprintf(logger.stream, "Error: Failed to write PDF data\n");
        pdf_destroy(pdf);
        free(structures);
        fclose(inputFile);
        return 7;
    }

    free(pdfBuffer);
    free(structures);
    fclose(inputFile);
    return 0;
}
