#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>
#include <arpa/inet.h>
#include <netinet/tcp.h>
#include <sys/socket.h>
#include <unistd.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define BUFFER_SIZE (10 * 1024 * 1024) // 10MB ring buffer
#define ELEMENT_SIZE sizeof(int)

struct ring_buffer {
    void* start;
    void* current;
    void* end;
};

void* allocate_aligned(size_t size, size_t alignment) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    size_t offset = alignof(void*) - (uintptr_t)ptr % alignment;
    return (char*)ptr + offset;
}

void ring_buffer_init(struct ring_buffer* rb, size_t size, size_t element_size) {
    void* start = allocate_aligned(size, alignof(int));
    rb->start = start;
    rb->current = start;
    rb->end = (char*)start + size - element_size;
}

void* ring_buffer_pop(struct ring_buffer* rb) {
    void* current = rb->current;
    if (rb->current == rb->end) {
        // Buffer is empty, return NULL
        return NULL;
    }
    char* data = (char*)current - ELEMENT_SIZE;
    rb->current += ELEMENT_SIZE;
    return data;
}

void ring_buffer_push(struct ring_buffer* rb, const void* data) {
    if ((char*)rb->current + ELEMENT_SIZE > (char*)rb->end) {
        // Buffer is full, handle overflow
    }
    memcpy((char*)rb->current, data, ELEMENT_SIZE);
    rb->current += ELEMENT_SIZE;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
struct ring_buffer ring_buf;
NFAPI_CRC_INDICATION_PDU_T pdu_list[10000]; // Preallocated array for PDUs
int largest_integer = INT32_MIN;
time_t current_timestamp;

void* process_socket(void* arg) {
    int sockfd = *(int*)arg;
    char buffer[4096];

    while (1) {
        ssize_t n = recv(sockfd, buffer, sizeof(buffer), 0);
        if (n <= 0) {
            // Handle network errors or EOF
            break;
        }

        pthread_mutex_lock(&mutex);
        while ((char*)ring_buf.current - ELEMENT_SIZE + ELEMENT_SIZE > (char*)ring_buf.start + BUFFER_SIZE) {
            // Buffer is full, wait for space
            pthread_mutex_unlock(&mutex);
            usleep(1000);
            pthread_mutex_lock(&mutex);
        }
        int* data = (int*)ring_buf.current;
        *data = ntohl(*((uint32_t*)buffer)); // Assuming network byte order is big-endian
        ring_buf.current += ELEMENT_SIZE;

        if (*data > largest_integer) {
            largest_integer = *data;
        }

        pthread_mutex_unlock(&mutex);
    }
    close(sockfd);
}

void process_integers() {
    int i = 0;
    for (void* data = ring_buf.start; data < ring_buf.current; data += ELEMENT_SIZE) {
        int num = *((int*)data);
        pdu_list[i].RX_UE_INFORMATION_TAG = i + 1; // Use sequential tags for simplicity
        pdu_list[i].RNTI = (pdu_list[i].RX_UE_INFORMATION_TAG % 256) | (current_timestamp & 0xFF00);
        pdu_list[i].CRCFLAG = rand() % 4; // Set CRCFLAG randomly, assuming it's a field with 4 possible values
        i++;
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <number of network threads>\n", argv[0]);
        return EXIT_FAILURE;
    }

    current_timestamp = time(NULL);
    ring_buffer_init(&ring_buf, BUFFER_SIZE, ELEMENT_SIZE);

    pthread_t* threads = malloc(sizeof(pthread_t) * atoi(argv[1]));
    for (int i = 0; i < atoi(argv[1]); i++) {
        int sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        // Connect to the network and handle any errors here

        if (pthread_create(&threads[i], NULL, &process_socket, &sockfd) != 0) {
            perror("pthread_create");
            return EXIT_FAILURE;
        }
    }

    process_integers();

    for (int i = 0; i < atoi(argv[1]); i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);

    return EXIT_SUCCESS;
}
