typedef struct {
    uint32_t id;
    char* params;
} NetworkEntity;

typedef struct {
    uint16_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct config_parser {
    FILE *file;
    size_t capacity;
    NetworkEntity* entities;
    pthread_mutex_t mutex;
};

void destroy_entity(NetworkEntity* entity) {
    free(entity->params);
    free(entity);
}

void* parse_line(void* data) {
    struct config_parser* parser = data;
    char line[4096];
    char* token;
    size_t capacity = 0;
    NetworkEntity* entity = NULL;

    while (fgets(line, sizeof(line), parser->file)) {
        token = strtok(line, "\n");
        if (!token) continue;

        if (capacity == parser->capacity) {
            capacity *= 2;
            parser->entities = realloc(parser->entities, capacity * sizeof(NetworkEntity));
        }

        entity = &parser->entities[capacity++];
        entity->id = atoi(token);
        token = strtok(NULL, " ");
        entity->params = malloc((strlen(token) + 1) * sizeof(char));
        strcpy(entity->params, token);
    }

    parser->entities[capacity - 1] = NULL;
    pthread_mutex_lock(&parser->mutex);
    destroy_entity(entity);
    pthread_mutex_unlock(&parser->mutex);
    return NULL;
}

int load_config_file(const char* filepath, NFAPI_CRC_INDICATION_PDU_T** pdus, size_t* num_pdus) {
    struct config_parser parser;
    pthread_t threads[4];
    FILE *file = fopen(filepath, "r");

    if (!file) return -1;

    parser.file = file;
    parser.capacity = 8;
    parser.entities = malloc(parser.capacity * sizeof(NetworkEntity));
    parser.mutex = PTHREAD_MUTEX_INITIALIZER;

    size_t processed_entries = 0;
    for (size_t i = 0; i < 4 && processed_entries < parser.capacity; ++i) {
        pthread_create(&threads[i], NULL, parse_line, &parser);
    }

    char line[4096];
    char* token;
    size_t total_lines = 0;
    while (fgets(line, sizeof(line), file)) {
        token = strtok(line, "\n");
        if (!token) continue;
        ++total_lines;

        if (strchr(token, ':')) { // Check for required colon separator
            fclose(file);
            return -2;
        }
    }

    rewind(file);
    NetworkEntity* current_entity = parser.entities;
    while ((current_entity = strchr(current_entity, '\0'))) {
        if (!current_entity->id || !current_entity->params) continue;
        ++processed_entries;

        // Perform validation checks on entity metadata as needed

        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->rnti = current_entity->id;
        pdu->crcflag = rand() % 2;

        if (num_pdus) (*num_pdus)++;
        *pdus = realloc(*pdus, (*num_pdus) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        (*pdus)[*num_pdus - 1] = pdu;
    }

    for (size_t i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(parser.entities);
    fclose(file);
    return processed_entries;
}
