} NF_API_MESSAGE_T;

typedef struct message_queue_node {
    NF_API_MESSAGE_T message;
    struct message_queue_node *next;
} message_queue_node_t;

struct message_queue {
    message_queue_node_t *head;
    message_queue_node_t *tail;
    size_t size;
    pthread_mutex_t lock;
};

void message_queue_init(struct message_queue *queue) {
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

bool message_queue_is_empty(const struct message_queue *queue) {
    return queue->size == 0;
}

void* message_queue_try_alloc() {
    void *ptr = malloc(sizeof(message_queue_node_t));
    if (!ptr) {
        // Handle memory allocation failure (e.g., custom allocator, propagate system-level errors)
        return NULL;
    }
    return ptr;
}

void message_queue_push(struct message_queue *queue, const NF_API_MESSAGE_T *message) {
    pthread_mutex_lock(&queue->lock);

    message_queue_node_t *new_node = (message_queue_node_t *)message_queue_try_alloc();
    if (!new_node) {
        pthread_mutex_unlock(&queue->lock);
        // Handle memory allocation failure
        return;
    }

    new_node->message = *message;
    new_node->next = NULL;

    if (queue->head == NULL) {
        queue->head = new_node;
        queue->tail = new_node;
    } else {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }

    queue->size++;
    pthread_mutex_unlock(&queue->lock);
}

message_queue_node_t * message_queue_find(struct message_queue *queue, uint32_t rnti) {
    pthread_mutex_lock(&queue->lock);

    message_queue_node_t *current = queue->head;
    while (current != NULL) {
        if (current->message.rnti == rnti) {
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&queue->lock);
    return current;
}

void message_queue_update(struct message_queue *queue, uint32_t rnti, const NF_API_MESSAGE_T *message) {
    message_queue_node_t *node = message_queue_find(queue, rnti);
    if (node == NULL) {
        // Handle RNTI not found error
        return;
    }

    pthread_mutex_lock(&queue->lock);

    node->message = *message;

    pthread_mutex_unlock(&queue->lock);
}

void message_queue_delete(struct message_queue *queue, uint32_t rnti) {
    pthread_mutex_lock(&queue->lock);

    message_queue_node_t *current = queue->head;
    message_queue_node_t *prev = NULL;

    while (current != NULL) {
        if (current->message.rnti == rnti) {
            if (current == queue->head) {
                queue->head = current->next;
            } else if (current == queue->tail) {
                queue->tail = prev;
                queue->tail->next = NULL;
            } else {
                prev->next = current->next;
            }
            free(current);
            queue->size--;
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&queue->lock);
}
