    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
};

void list_init(struct list* list, size_t initial_capacity) {
    if (initial_capacity == 0) initial_capacity = DEFAULT_INITIAL_CAPACITY;
    list->elements = malloc(initial_capacity * sizeof(NFAPI_CRAC_INDICATION_PDU_T));
    if (!list->elements) {
        fprintf(stderr, "Failed to allocate memory for list\n");
        return;
    }
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = initial_capacity;
    list->length = 0;
}

void* list_element(struct list* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    void* result = list->elements + index;
    pthread_mutex_unlock(&list->lock);
    return result;
}

size_t list_length(const struct list* list) {
    return list->length;
}

void list_push(struct list* list, const NFAPI_CRAC_INDICATION_PDU_T* element) {
    if (list->length + 1 > list->capacity) {
        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        NFAPI_CRAC_INDICATION_PDU_T* new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRAC_INDICATION_PDU_T));
        if (!new_elements) {
            fprintf(stderr, "Failed to resize list memory\n");
            return;
        }
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    memcpy((void*)(list->elements + list->length), element, sizeof(NFAPI_CRAC_INDICATION_PDU_T));
    list->length++;
}

void list_free(struct list* list) {
