            node->prev = node->next = NULL;
        } else {
            node->next = cache->head;
            node->prev = cache->tail;
            cache->tail->next = node;
            cache->head->prev = node;
            cache->tail = node;
        }

        ++cache->used;
    }

    pthread_mutex_unlock(&cache->lock);

    return &cache->head->data;
}

void put_back(Cache *cache, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!cache || !data || !cache->free) return;

    pthread_mutex_lock(&cache->lock);

    Node *node = (Node*)data - 1; // Assuming NFAPI_CRC_INDICATION_PDU_T is contiguous with Node

    if (node == cache->head) {
        node->next->prev = NULL;
        cache->head = node->next;
    } else if (node == cache->tail) {
        node->prev->next = NULL;
        cache->tail = node->prev;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    free(node);
    --cache->used;

    pthread_mutex_unlock(&cache->lock);
}
