#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_RNTI 1000000

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

enum {
    NO_ERROR = 0,
    MEMORY_FAILURE = -1,
    RNTI_DUPLICATE = -2,
    RNTI_CAPACITY_REACHED = -3,
};

int create_pdu_array(size_t num_structures, int seed, size_t* successfully_created, pthread_mutex_t* log_mutex) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    size_t i, unique_rntis = 0;
    pthread_mutex_t rnti_mutex = PTHREAD_MUTEX_INITIALIZER;
    srand(seed);

    // Allocate memory for the array of structures
    pdus = (NFAPI_CRC_INDICATION_PDU_T*) calloc(num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        *successfully_created = 0;
        return MEMORY_FAILURE;
    }

    // Concurrent RNTI generation using pthreads
    pthread_t threads[num_structures];
    for (i = 0; i < num_structures; ++i) {
        if (pthread_create(&threads[i], NULL, generate_rnti_and_fill, (void*)(pdus + i))) {
            free(pdus);
            *successfully_created = unique_rntis;
            return MEMORY_FAILURE;
        }
    }

    // Join all threads and handle errors
    for (i = 0; i < num_structures; ++i) {
        void* status;
        if (pthread_join(threads[i], &status)) {
            free(pdus);
            *successfully_created = unique_rntis;
            return MEMORY_FAILURE;
        }
        if ((int)status != NO_ERROR && (int)status != RNTI_DUPLICATE) {
            free(pdus);
            *successfully_created = unique_rntis;
            return (int)status;
        }
    }

    // Validate uniqueness of generated RNTIs
    for (i = 1; i < unique_rntis; ++i) {
        if ((pdus[i - 1].rnti == pdus[i].rnti)) {
            free(pdus);
            *successfully_created = unique_rntis - 1;
            return RNTI_DUPLICATE;
        }
    }

    // Successfully created structures
    *successfully_created = unique_rntis;
    return NO_ERROR;
}

void* generate_rnti_and_fill(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*) arg;

    // Generate RNTI while respecting the maximum threshold
    if (pthread_mutex_lock(&rnti_mutex)) {
        free(arg);
        return (void*)RNTI_CAPACITY_REACHED;
    }
    pdu->rnti = rand() % MAX_RNTI;
    pthread_mutex_unlock(&rnti_mutex);

    // Fill the rest of the structure with random values
    pdu->tag.value = ...;
    pdu->crc_indication.value = ...;
    pdu->crcflag = rand() % 2 == 0 ? true : false;

    return (void*)NO_ERROR;
}
