        pdu.crcflag = rand() % 2;
        pduList.push_back(pdu);
    }

    result_set = NULL; // Reset the result set pointer before processing data

    const int MAX_BATCH_SIZE = 100; // Maximum number of records to batch insert
    int processedCount = 0;
    for (size_t i = 0; i < pduList.size(); ++i) {
        if (processedCount >= MAX_BATCH_SIZE) {
            stmt->executeBatch(); // Execute the batch of records
            processedCount = 0;
        }
        stmt->bind(1, pduList[i].rnti);
        stmt->bind(2, pduList[i].tag);
        stmt->bind(3, pduList[i].crcflag);
        ++processedCount;

        clock_t currentTime = clock();
        if (currentTime - lastAttempt >= CLOCKS_PER_SEC * 5) { // Check for timeout
            freeResources();
            initDatabaseConnection(config);
            lastAttempt = currentTime;
        }
    }

    stmt->executeBatch(); // Process any remaining records
    freeResources(); // Free resources after the operation is complete

    return result_set; // Return the result set to allow the caller to process the inserted data
}
