NFAPI_CRC_INDICATION_PDU_T* populateAndProcessNFAPIIndications() {
    pthread_mutex_t indications_mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(MAX_INDICATIONS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        fprintf(stderr, "Memory allocation failure for indications array\n");
        return NULL;
    }

    pthread_t buffer_thread;
    uint64_t received_data = 0;
    uint64_t lost_data = 0;
    uint64_t processed_indications = 0;
    uint32_t i;

    // Buffer for incoming data
    uint64_t buffer[BUFFER_SIZE];
    uint64_t head = 0;
    uint64_t tail = 0;

    if (pthread_create(&buffer_thread, NULL, bufferManagerThread, (void*)&buffer) != 0) {
        fprintf(stderr, "Error creating buffer management thread\n");
        free(indications);
        return NULL;
    }

    // Function to populate and process indications
    for (i = 0; i < MAX_INDICATIONS; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = i;
        indications[i].RNTI = rand() % 65536;
        indications[i].CRCFLAG = (rand() & CRCFLAG_MASK);

        pthread_mutex_lock(&indications_mutex);
        ++processed_indications;
        pthread_mutex_unlock(&indications_mutex);
    }

    // Continuously process data from buffer and external source
    while (1) {
        uint64_t data;

        // Process data from high-latency network interface
        if ((data = receiveNetworkData()) != 0) {
            ++received_data;
            pthread_mutex_lock(&indications_mutex);

            // Add the new data to the buffer and process it in a background thread
            buffer[tail++] = data;
            if (tail - head >= BUFFER_SIZE) tail = head;

            pthread_mutex_unlock(&indications_mutex);
        }

        // Process data from external source, handling temporary outages and non-standard formats
        processExternalData();

        // Retry logic with exponential backoff for transient failures
        if (shouldRetry()) {
            usleep(1 << processed_indications);
        }
    }

    return indications;
}

void* bufferManagerThread(void* arg) {
    uint64_t *buffer = arg;
    uint64_t head, tail;

    for (;;) {
        pthread_mutex_lock(&indications_mutex);
        head = head;
        tail = tail;
        pthread_mutex_unlock(&indications_mutex);

        if (tail - head >= BUFFER_SIZE) {
            // Process the buffered data in chunks, considering network delays and packet loss
            processBufferChunk(buffer + head, BUFFER_SIZE);
            head = tail;
        }
    }
}
