RNTI create_rnti();
CRC_INDICATION_REL8_TAG create_crc_indication_rel8_tag(bool crcflag);
void log_message(const char *msg);

// Custom memory pool allocator
typedef struct mem_pool {
    void *memory;
    size_t size;
    size_t used;
} MemPool;

MemPool* create_mem_pool(size_t size, size_t block_size) {
    MemPool *pool = malloc(sizeof(MemPool));
    if (!pool) return NULL;
    pool->memory = malloc(size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    pool->size = size;
    pool->used = 0;
    pool->block_size = block_size;
    return pool;
}

void* mem_pool_alloc(MemPool *pool) {
    if (pool->used + pool->block_size <= pool->size) {
        void *ptr = (char *)pool->memory + pool->used;
        pool->used += pool->block_size;
        return ptr;
    }
    return NULL;
}

void mem_pool_free(MemPool *pool, void *mem) {
    if (mem && pool) {
        pool->used -= (char *)mem - (char *)pool->memory;
    }
}

// Function to allocate and initialize the array of structures based on user input for the number of elements, N
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(size_t N, MemPool *pool) {
    if (N <= 0 || !pool) return NULL;

    // Allocate memory for the array using the custom memory pool allocator
    NFAPI_CRC_INDICATION_PDU_T *arr = mem_pool_alloc(pool);
    if (!arr) {
        log_message("Insufficient memory. Aborting.");
        return NULL;
    }

    size_t total_rnti = 0;
    int64_t min_rnti = INT64_MAX, max_rnti = INT64_MIN;

    // Initialize the array and perform necessary validations
    for (size_t i = 0; i < N; ++i) {
        arr[i].rx_ue_information_tag = create_rx_ue_information_tag();
        if (!arr[i].rx_ue_information_tag.isValid()) {
            log_message("Invalid RX_UE_INFORMATION_TAG encountered.");
            break;
        }
        arr[i].rnti = create_rnti();
        total_rnti += arr[i].rnti;
        min_rnti = (arr[i].rnti < min_rnti) ? arr[i].rnti : min_rnti;
        max_rnti = (arr[i].rnti > max_rnti) ? arr[i].rnti : max_rnti;

        arr[i].crc_indication_rel8_tag = create_crc_indication_rel8_tag(random_crcflag());
