#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <jansson.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct factory_func {
    char *id;
    void* (*create)(void);
} factory_func;

struct registry {
    pthread_mutex_t lock;
    size_t size;
    factory_func *entries;
};

void reg_init(struct registry *reg, size_t size) {
    reg->size = size;
    reg->entries = malloc(sizeof(factory_func) * size);
}

void reg_add(struct registry *reg, const char *id, void* (*create)(void)) {
    pthread_mutex_lock(&reg->lock);
    for (size_t i = 0; i < reg->size; ++i) {
        if (!reg->entries[i].id) {
            reg->entries[i].id = strdup(id);
            reg->entries[i].create = create;
            pthread_mutex_unlock(&reg->lock);
            return;
        }
    }
    pthread_mutex_unlock(&reg->lock);
}

void *get_factory(const struct registry *reg, const char *id) {
    pthread_mutex_lock(&reg->lock);
    for (size_t i = 0; i < reg->size; ++i) {
        if (!strcmp(id, reg->entries[i].id)) {
            void* factory = reg->entries[i].create();
            pthread_mutex_unlock(&reg->lock);
            return factory;
        }
    }
    pthread_mutex_unlock(&reg->lock);
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T *new_struct(void) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->crc_indication.crcFlag = (uint8_t)(rand() % 2);
    return pdu;
}

void print_json(const char *json) {
    printf("%s\n", json);
}

void serialize(NFAPI_CRC_INDICATION_PDU_T *pdu, json_t **out) {
    json_t *root = json_object();
    json_object_set_new(root, "UEInformationTag", json_integer(pdu->tag));
    json_object_set_new(root, "RNTI", json_integer(pdu->rnti));
    json_object_set_new(root, "CRCIndicationREL8TAG", json_boolean(pdu->crc_indication.crcFlag));
    *out = root;
}

void deserialize(json_t *root, NFAPI_CRC_INDICATION_PDU_T **pdu) {
    pdu_t *pduObj = json_object_get(root, "UEInformationTag");
    (*pdu)->tag = pduObj->valueint;
    pduObj = json_object_get(root, "RNTI");
    (*pdu)->rnti = pduObj->valueint;
    pduObj = json_object_get(root, "CRCIndicationREL8TAG");
    (*pdu)->crc_indication.crcFlag = pduObj->value.u1;
}
