    PHY_DOWNLINK_CCCH_TAG phy_downlink_ccch_tag;
    uint32_t message_id;
    time_t timestamp;
} LTE_DL_FRAME_MESSAGE_T;

typedef struct node {
    LTE_DL_FRAME_MESSAGE_T data;
    struct node *next;
} NODE;

static NODE* head = NULL;
static uint64_t max_messages = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static uint64_t total_added = 0, total_removed = 0, avg_retrieve_duration = 0;
static uint64_t messages_count = 0;
static time_t last_report_time = 0;
static void (*remove_callback)(void) = NULL;

void add_message(LTE_DL_FRAME_MESSAGE_T message) {
    pthread_mutex_lock(&mutex);
    if (messages_count >= max_messages) {
        messages_count--;
        total_removed++;
        if (remove_callback != NULL) remove_callback();
        if (messages_count < max_messages / 2) {
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    NODE* new_node = (NODE*)malloc(sizeof(NODE));
    new_node->data = message;
    new_node->next = head;
    head = new_node;
    messages_count++;
    total_added++;
    pthread_mutex_unlock(&mutex);
}

LTE_DL_FRAME_MESSAGE_T* get_message_by_id(uint32_t message_id) {
    pthread_mutex_lock(&mutex);
    NODE* current = head;
    while (current != NULL) {
        if (current->data.message_id == message_id) {
            LTE_DL_FRAME_MESSAGE_T* result = malloc(sizeof(LTE_DL_FRAME_MESSAGE_T));
            *result = current->data;
            pthread_mutex_unlock(&mutex);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void remove_message_by_id(uint32_t message_id) {
    pthread_mutex_lock(&mutex);
    NODE** current = &head;
    while (*current != NULL) {
        if ((*current)->data.message_id == message_id) {
            NODE* temp = *current;
            *current = (*current)->next;
            free(temp);
            messages_count--;
            total_removed++;
            break;
        }
        current = &((*current)->next);
    }
    if (remove_callback != NULL) remove_callback();
    pthread_mutex_unlock(&mutex);
}

void set_max_messages(uint64_t new_max) {
    pthread_mutex_lock(&mutex);
    max_messages = new_max;
    pthread_mutex_unlock(&mutex);
}

void* report_statistics(void* arg) {
    while (true) {
        time_t now = time(NULL);
        if (now - last_report_time >= 60) {
            double avg = (double)total_added - total_removed > 0 ? ((double)avg_retrieve_duration / (double)(total_added - total_removed)) : 0;
            printf("Total added: %llu, removed: %llu, average retrieve duration: %.2fs\n", total_added, total_removed, avg);
            last_report_time = now;
        }
        sleep(1);
    }
}
