    std::smatch match;

    if (!std::regex_search(inputFilePath, match, imageRegex) || (match[0].length() > maxSize)) {
        logger->log("Invalid input file or exceeds maximum size.");
        return 1;
    }

    std::vector<NFAPI_MEDIA_DATA_PDU_T> mediaList;
    pthread_mutex_t memPoolMutex = PTHREAD_MUTEX_INITIALIZER;
    MemoryPool memoryPool(maxSize);

    for (int i = 0; i < N && mediaList.size() < maxSize; ++i) {
        pthread_mutex_lock(&memPoolMutex);
        auto data = memoryPool.acquire();
        pthread_mutex_unlock(&memPoolMutex);

        data->MEDIA_INFORMATION_TAG = i + 1;
        data->RNTI = rand() % 0xFFFFFFFF;
        data->MEDIA_CONTENT_TAG = "/path/to/your_content"; // Replace with the actual content path
        data->CONTENT_FLAG = (rand() % 2) * 255;

        mediaList.push_back(*data);
    }

    int status = 0;
    for (auto& item : mediaList) {
        if (!mediaProcessor->processMedia(item.MEDIA_CONTENT_TAG, "pdf", enableHighQualityPDF, enableWatermark)) {
            logger->log("Failed to process media.");
            status = 1;
            continue;
        }
    }

    if (status) return 1;

    std::string outputFilePath = outputDirPath + "/" + reportTitle + ".html"; // Replace with your preferred file extension, such as .md for Markdown files
    if (!templateEngine->generateReport(reportTitle, mediaList, logger)) {
        logger->log("Failed to generate the report.");
        return 1;
    }

    std::ofstream outputFile(outputFilePath);
    if (outputFile.is_open()) {
        outputFile << templateEngine->getReport();
        outputFile.close();
    } else {
        logger->log("Failed to write the report to the specified file.");
        return 1;
    }

    return status;
}

class MemoryPool {
public:
    explicit MemoryPool(size_t size) : data_(new NFAPI_MEDIA_DATA_PDU_T[size]), capacity_(size), currentSize_(0) {}

    void* acquire() {
        if (currentSize_ < capacity_) {
            ++currentSize_;
            return &data_[currentSize_ - 1];
        }

        resize(capacity_ * 2);
        return &data_[currentSize_ - 1];
    }

    void release(void* ptr) {
        --currentSize_;
    }

private:
    NFAPI_MEDIA_DATA_PDU_T* data_;
    size_t capacity_, currentSize_;

    void resize(size_t newCapacity) {
        if (newCapacity > capacity_) {
            auto oldData = data_;
            data_ = new NFAPI_MEDIA_DATA_PDU_T[newCapacity];

            for (int i = 0; i < currentSize_; ++i) {
                data_[i] = oldData[i];
            }

            delete[] oldData;
            capacity_ = newCapacity;
        }
    }
};
