    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static const size_t BUFFER_GROWTH_FACTOR = 2;
static size_t bufferSize = 1000;
BufferElement *buffer;
size_t bufferCount = 0;

void resizeBuffer() {
    BufferElement *newBuffer = malloc(bufferSize * BUFFER_GROWTH_FACTOR * sizeof(BufferElement));
    if (!newBuffer) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    memcpy(newBuffer, buffer, bufferCount * sizeof(BufferElement));
    free(buffer);
    buffer = newBuffer;
    bufferSize *= BUFFER_GROWTH_FACTOR;
}

void processNetworkData(const uint32_t *data, size_t dataSize) {
    if (bufferCount + dataSize > bufferSize) {
        resizeBuffer();
    }
    for (size_t i = 0; i < dataSize; ++i) {
        buffer[bufferCount].value = data[i];
        buffer[bufferCount].index = i;
        ++bufferCount;
    }
}

void findLargestNumber() {
    if (bufferCount == 0) {
        printf("No data to process\n");
        return;
    }
    unsigned int largest = buffer[0].value;
    for (size_t i = 1; i < bufferCount; ++i) {
        if (largest < buffer[i].value) {
            largest = buffer[i].value;
        }
    }
    printf("Largest number: %d\n", largest);
}

void populateCRCINDICATIONPDU(NFAPI_CRC_INDICATION_PDU_T *pdu, uint16_t RNTI) {
    pdu->RX_UE_INFORMATION_TAG = 0x20;
    pdu->RNTI = RNTI;

    // Optimized CRCFLAG calculation using bitwise operations
    pdu->CRC_INDICATION_REL8_TAG = ((RNTI << 16) | (RNTI & 0xFFFF)) ^ ((RNTI >> 16) | (RNTI << 32));
    pdu->CRCFLAG = (pdu->CRC_INDICATION_REL8_TAG & 0x80000000) != 0;
}

int main() {
    uint32_t inputData[] = {1, 2, 3, 4, 5, 6, 7, 8, 9};
    processNetworkData(inputData, sizeof(inputData) / sizeof(uint32_t));
    findLargestNumber();

    NFAPI_CRC_INDICATION_PDU_T pdu;
    populateCRCINDICATIONPDU(&pdu, 0xABCD);
    printf("CRCFLAG: %d\n", pdu.CRCFLAG);

    return 0;
}
