        if (extension_len == 0) continue;

        size_t dot_index = extension_len - 1;

        while (dot_index > 0 && isdigit(filenames[i][dot_index])) --dot_index;

        if (dot_index >= extension_len || filenames[i][dot_index + 1] != '.') continue;

        size_t num_extension_digits = dot_index - extension_len + 1;

        char* new_filename = malloc(strlen(filenames[i]) + num_extension_digits + 2); // Additional space for the suffix and the null terminator

        if (!new_filename) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        memset(new_filename, 0, strlen(new_filename));

        strncpy(new_filename, filenames[i], dot_index + 1); // Copy the filename up to the last digit of the extension
        strcat(new_filename, "_");                          // Append an underscore

        for (size_t j = 0; j < num_extension_digits; ++j) {
            new_filename[strlen(new_filename)] = filenames[i][dot_index - j];
        }

        strcat(new_filename, ".txt"); // You should replace '.txt' with your desired suffix
        free(filenames[i]);          // Free the original filename
        filenames[i] = new_filename;  // Replace the original filename with the modified one
    }
}
