#define MAX_ELEMENTS 10000
#define ALIGNMENT 64
#define MEMORY_LIMIT (2 * 1024 * 1024) // 2 MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} Node;

struct list {
    Node* head;
    size_t count;
    size_t limit;
    void* mem_ptr;
};

void log(const char* message) {
    // Implement logging system here
}

sem_t mem_lock;

Node* node_create() {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log("Allocation failed");
        return NULL;
    }

    pthread_mutex_init(&new_node->lock, NULL);
    new_node->next = NULL;

    return new_node;
}

void node_destroy(Node* node) {
    if (node) {
        free(node);
    }
}

struct list* list_create() {
    struct list* list = malloc(sizeof(struct list));
    if (!list) {
        log("Allocation failed");
        return NULL;
    }

    list->head = NULL;
    list->count = 0;
    list->limit = MAX_ELEMENTS;
    list->mem_ptr = mmap(NULL, MEMORY_LIMIT, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list->mem_ptr == MAP_FAILED) {
        log("Memory mapping failed");
        free(list);
        return NULL;
    }

    sem_init(&mem_lock, 0, 1);

    return list;
}

void list_destroy(struct list* list) {
    if (list && list->mem_ptr) {
        munmap(list->mem_ptr, MEMORY_LIMIT);
    }

    if (list) {
        free(list);
    }
}

void* get_ptr(struct list* list) {
    sem_wait(&mem_lock);

    void* ptr = list->mem_ptr + list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (ptr + sizeof(NFAPI_CRC_INDICATION_PDU_T) > list->mem_ptr + MEMORY_LIMIT) {
        sem_post(&mem_lock);
        return NULL;
    }

    sem_post(&mem_lock);

    return ptr;
}

void* allocate(struct list* list, size_t size) {
    void* ptr = get_ptr(list);
    if (!ptr) {
        log("Out of memory");
        return NULL;
    }

    return ptralign(ptr, ALIGNMENT, size);
}

void* ptralign(void* p, size_t alignment, size_t size) {
    size_t align = (size_t)(alignment - 1);
    size_t new_p = (size_t)p + align;
    if ((new_p & align) != 0) {
        new_p += alignment - (new_p & -align);
    }
    return (void*)(((size_t)new_p + size - 1) & ~(alignment - 1));
}

bool list_push(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = node_create();
    if (!new_node) {
        return false;
    }

    new_node->data = *data;

    pthread_mutex_lock(&list->head->lock);

    while (list->count >= list->limit) {
        // Implement eviction strategy here, e.g., LRU or FIFO
    }

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->head->lock);

    return true;
}

NFAPI_CRC_INDICATION_PDU_T* list_pop(struct list* list) {
    if (list->count == 0) {
        return NULL;
    }

    pthread_mutex_lock(&list->head->lock);

    Node* temp = list->head;
    list->head = list->head->next;
    list->count--;

    pthread_mutex_unlock(&temp->lock);

    return &temp->data;
}
