    if (!conn || !is_valid_ip(conn->ip)) return;

    pthread_mutex_lock(&conn->lock);
    time_t current_time = time(NULL);
    if (current_time - conn->last_activity_timestamp > MONITORING_THRESHOLD) {
        add_connection(conn, current_time, current_time);
        // Notify the monitoring system here.
    }
    pthread_mutex_unlock(&conn->lock);
}

void clean_expired_connections() {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < CONNECTION_POOL_SIZE; ++i) {
        if (!connection_pool[i]) continue;

        pthread_mutex_lock(&connection_pool[i]->lock);
        if (current_time - connection_pool[i]->established_time > MAX_AGE) {
            free_connection(connection_pool[i]);
            connection_pool[i] = NULL;
        }
        pthread_mutex_unlock(&connection_pool[i]->lock);
    }
}
