HashTable hashTable;

void initHashTable(uint64_t size) {
    hashTable.size = size;
    hashTable.data = calloc(size, sizeof(HashNode*));
    for (int i = 0; i < size; ++i)
        hashTable.data[i] = NULL;
    pthread_mutex_init(&hashTable.mutex, NULL);
}

uint64_t getHash(const TrafficEvent *event) {
    uint64_t hash = event->timestamp + event->vehicleID * 10000;
    return hash % hashTable.size;
}

void insertToHashTable(TrafficEvent *event) {
    pthread_mutex_lock(&hashTable.mutex);
    uint64_t index = getHash(event);
    HashNode *node = (HashNode*)malloc(sizeof(HashNode));
    node->event = *event;
    node->next = hashTable.data[index];
    hashTable.data[index] = node;
    pthread_mutex_unlock(&hashTable.mutex);
}

bool findInHashTable(const TrafficEvent *event) {
