void pdu_manager_init(struct manager_ctx **ctx, size_t initial_capacity) {
    *ctx = malloc(sizeof(struct manager_ctx));
    if (!*ctx) {
        perror("Failed to allocate memory for PDU manager");
        return;
    }

    sem_init(&(*ctx)->sem_mutex, 0, 1);
    (*ctx)->capacity = initial_capacity;
    (*ctx)->used = 0;
    (*ctx)->pdu_array = malloc(initial_capacity * sizeof(PDU_T));
    if (!(*ctx)->pdu_array) {
        perror("Failed to allocate memory for PDUs");
        free(*ctx);
        *ctx = NULL;
        return;
    }
}

void pdu_manager_deinit(struct manager_ctx **ctx) {
    if (!*ctx) {
        return;
    }

    free((*ctx)->pdu_array);
    sem_destroy(&(*ctx)->sem_mutex);
    free(*ctx);
    *ctx = NULL;
}

void pdu_manager_reset(struct manager_ctx **ctx) {
    sem_wait(&(*ctx)->sem_mutex);
    (*ctx)->used = 0;
    sem_post(&(*ctx)->sem_mutex);
}

size_t pdu_manager_capacity(const struct manager_ctx *ctx) {
