    sem_wait(&ctx->sem_mutex);
    size_t result = ctx->used;
    sem_post(&ctx->sem_mutex);
    return result;
}

bool pdu_manager_push(struct manager_ctx *ctx, const PDU_T *pdu) {
    if (ctx->used >= ctx->capacity) {
        return false;
