void unique_crc(NFAPI_CRC_INDICATION_PDU_T *pdu, uint32_t seed) {
    pdu->crc_indication.CRCFLAG = (seed++ % 0xFFFF);
}

void log_entry(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    time_t timestamp;
    struct tm *timeinfo;

    time(&timestamp);
    timeinfo = localtime(&timestamp);
    printf("Entry created at: %d-%02d-%02d %02d:%02d:%02d with RNTI=%u\n",
        (int)timeinfo->tm_year + 1900,
        (int)timeinfo->tm_mon + 1,
        (int)timeinfo->tm_mday,
        (int)timeinfo->tm_hour,
        (int)timeinfo->tm_min,
        (int)timeinfo->tm_sec,
        pdu->rnti);
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (list_length + 1 >= list_capacity) {
        // Resize the list when it's almost full
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list_capacity * 2));
        if (!new_list) {
            fprintf(stderr, "Failed to reallocate memory\n");
            return;
        }
        list = new_list;
        list_capacity *= 2;
    }

    unique_crc(pdu, pdu->rx_ue_information.RNTI);
    log_entry(pdu);
    pthread_mutex_lock(&list_mutex);
    list[list_length++] = *pdu;
    pthread_mutex_unlock(&list_mutex);
}

void batch_add_to_list(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    sem_wait(&batch_mutex);

    if (count + list_length >= max_batch_size) {
        // Process the current batch and wait for it to be finished before adding more
        process_list();
    }

    if (count + list_length < max_batch_size) {
        size_t i;
        pthread_mutex_lock(&list_mutex);

        for (i = 0; i < count && list_length + i < max_batch_size; ++i) {
            unique_crc(pdus + i, pdus[i].rx_ue_information.RNTI);
            log_entry(pdus + i);
            list[list_length + i] = *(pdus + i);
        }

        list_length += i;
        pthread_mutex_unlock(&list_mutex);
    }

    sem_post(&batch_mutex);
}

void process_list() {
    // Perform necessary processing on the list, e.g., sending data to a queue or writing to a file
    size_t i;
    NFAPI_CRC_INDICATION_PDU_T *temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_length);
    if (!temp) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    for (i = 0; i < list_length; ++i) {
        temp[i] = list[i];
    }
    list_length = 0;
    pthread_mutex_unlock(&list_mutex);

    // Process the data, using another thread or threads if needed for efficient resource utilization
    // ...

    free(temp);
}
