    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} RX_UE_INFO;

RX_UE_INFO* create_ue_info() {
    RX_UE_INFO* ui = (RX_UE_INFO*)malloc(sizeof(RX_UE_INFO));
    ui->data = NULL;
    ui->capacity = 0;
    ui->length = 0;
    pthread_mutex_init(&ui->mutex, NULL);
    return ui;
}

void push_ue_info(RX_UE_INFO* ui, NFAPI_CRC_INDICATION_PDU_T ue) {
    pthread_mutex_lock(&ui->mutex);
    if (ui->length == ui->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* temp = realloc(ui->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (ui->capacity + MAX_ELEMENTS));
        if (!temp) {
            perror("realloc failed");
            pthread_mutex_unlock(&ui->mutex);
            return;
        }
        ui->data = temp;
        ui->capacity += MAX_ELEMENTS;
    }
    ui->data[ui->length] = ue;
    ui->length++;
    pthread_mutex_unlock(&ui->mutex);
}

bool check_unique(NFAPI_CRC_INDICATION_PDU_T* data, size_t len) {
    bool *visited = (bool*)malloc(len * sizeof(bool));
    memset(visited, false, len * sizeof(bool));

    for (size_t i = 0; i < len; ++i) {
        if (visited[data[i].RNTI]) {
            free(visited);
            return false;
        }
        visited[data[i].RNTI] = true;
    }

    free(visited);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* init_ue_info(RX_UE_INFO* ui) {
    for (size_t i = 0; i < ui->length; ++i) {
        ui->data[i].tag.tagClass = 1;
        ui->data[i].tag.criticality = 3;
        ui->data[i].tag.extension = 0;
        ui->data[i].RNTI = (rand() % (1 << 24));
        ui->data[i].crc_indication.crcFlag = rand() % ((1 << 28) - 1);
    }

    if (!check_unique(ui->data, ui->length)) {
        perror("Duplicate RNTIs found");
        free(ui->data);
        pthread_mutex_destroy(&ui->mutex);
        free(ui);
        return NULL;
    }

    return ui->data;
}

void free_ue_info(RX_UE_INFO* ui) {
    if (ui) {
        free(ui->data);
        pthread_mutex_destroy(&ui->mutex);
        free(ui);
    }
}
