```c
#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <assert.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    pthread_rwlock_t lock;
    struct _NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned int size;
    unsigned int capacity;
    NFAPI_CRC_INDICATION_PDU_T** data;
    pthread_rwlock_t lock;
} glist;

glist* glist_create() {
    glist* list = (glist*) malloc(sizeof(glist));
    list->size = 0;
    list->capacity = 16;
    list->data = (NFAPI_CRC_INDICATION_PDU_T**) calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

bool glist_empty(glist* list) {
    if (!list || !list->data)
        return true;
    return list->size == 0;
}

NFAPI_CRC_INDICATION_PDU_T* glist_front(glist* list) {
    assert(!glist_empty(list));
    return list->data[0];
}

void glist_push_back(glist* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_rwlock_wrlock(&list->lock);

    unsigned int i;
    for (i = 0; i < list->capacity && list->data[i]; ++i) {}

    if (i == list->capacity) {
        unsigned int new_cap = list->capacity * 2 > 10000 ? 10000 : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_data = realloc(list->data, new_cap * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_data) {
            pthread_rwlock_unlock(&list->lock);
            fprintf(stderr, "Failed to allocate memory for glist.\n");
            exit(EXIT_FAILURE);
        }
        list->capacity = new_cap;
        list->data = new_data;
    }

    element->next = list->data[i];
    list->data[i] = element;
    ++list->size;
    pthread_rwlock_unlock(&list->lock);
}

void glist_pop_front(glist* list) {
    if (glist_empty(list))
        return;

    pthread_rwlock_wrlock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* first = list->data[0];
    list->data[0] = first->next;
    free(first);
    --list->size;

    if (list->size == list->capacity / 4 && list->capacity > 16) {
        unsigned int new_cap = list->capacity / 2 < 16 ? 16 : list->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T** new_data = realloc(list->data, new_cap * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_data) {
            pthread_rwlock_unlock(&list->lock);
            fprintf(stderr, "Failed to allocate memory for glist.\n");
            exit(EXIT_FAILURE);
        }
        list->capacity = new_cap;
        list->data = new_data;
    }

    pthread_rwlock_unlock(&list->lock);
}

void glist_iterate_reverse(glist* list, void(*f)(NFAPI_CRC_INDICATION_PDU_T* element)) {
    if (glist_empty(list))
        return;

    pthread_rwlock_rdlock(&list->lock);

    for (unsigned int i = list->size - 1; i != ULLONG_MAX; --i) {
        if (list->data[i])
            f(list->data[i]);
    }

    pthread_rwlock_unlock(&list->lock);
}
```

