typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG cindication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemPoolNode {
    void* data;
    struct MemPoolNode *next;
} MemPoolNode;

MemPoolNode* mempool = NULL;
sem_t semaphore;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* mempool_alloc(size_t size) {
    pthread_mutex_lock(&lock);
    if (!mempool || !mempool->next) {
        void *new_block = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
        MemPoolNode *new_node = (MemPoolNode*) new_block;
        new_node->data = ((char *)new_block) + sizeof(MemPoolNode);
        new_node->next = mempool;
        mempool = new_node;
    }
    void* result = mempool->data;
    mempool = mempool->next;
    pthread_mutex_unlock(&lock);
    return result;
}

void mempool_free(void *ptr) {
    pthread_mutex_lock(&lock);
    MemPoolNode* node = (MemPoolNode*) ((char *)mempool - sizeof(MemPoolNode));
    if (node->data == ptr) {
        node->data = mempool;
        mempool = node;
    } else {
        MemPoolNode *current = mempool;
        while (current->next != NULL) {
            if (current->next->data == ptr) {
                current->next = current->next->next;
                break;
            }
            current = current->next;
        }
    }
    pthread_mutex_unlock(&lock);
    munmap(ptr, 4096);
}

