typedef struct TrafficFlow {
    int flowID;
    long packetCount;
    long byteCount;
} TrafficFlow;

typedef struct FlowCollection {
    TrafficFlow* flows;
    size_t capacity;
    size_t count;
    sem_t lock;
    void* dataSource; // External data source handle
    pthread_t dataSourceThread; // Data source update thread ID
} FlowCollection;

// Initialize a new empty FlowCollection with the given initial capacity
FlowCollection* initFlowCollection(size_t initialCapacity) {
    FlowCollection* collection = malloc(sizeof(FlowCollection));
    if (!collection) return NULL;

    collection->capacity = initialCapacity;
    collection->count = 0;
    collection->flows = calloc(initialCapacity, sizeof(TrafficFlow));
    if (!collection->flows) {
        free(collection);
        return NULL;
    }

    sem_init(&collection->lock, 0, 1);
    return collection;
}

// Free memory associated with the FlowCollection and any internal data structures
void destroyFlowCollection(FlowCollection* collection) {
    if (!collection) return;

    free(collection->flows);
    sem_destroy(&collection->lock);
    free(collection);
}

// Add a new flow to the collection with the given flowID, packetCount, and byteCount.
bool addFlow(FlowCollection* collection, int flowID, long packetCount, long byteCount) {
    // Acquire lock before modifying collection data
    sem_wait(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->flows[i].flowID == flowID) {
            collection->flows[i].packetCount += packetCount;
            collection->flows[i].byteCount += byteCount;
            sem_post(&collection->lock);
            return true;
        }
    }

    // No matching flow found, so add a new one
    if (collection->count >= collection->capacity) {
        resizeFlowCollection(collection, collection->capacity * 2);
    }

    collection->flows[collection->count].flowID = flowID;
    collection->flows[collection->count].packetCount = packetCount;
    collection->flows[collection->count].byteCount = byteCount;
    ++collection->count;

    sem_post(&collection->lock);
    return true;
}

// Update an existing flow based on the given flowID, incrementing its packet count and byte count.
bool updateFlow(FlowCollection* collection, int flowID, long deltaPacketCount, long deltaByteCount) {
    // Acquire lock before modifying collection data
    sem_wait(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->flows[i].flowID == flowID) {
            collection->flows[i].packetCount += deltaPacketCount;
            collection->flows[i].byteCount += deltaByteCount;
            sem_post(&collection->lock);
            return true;
        }
    }

    sem_post(&collection->lock);
    return false;
}

// Get the total packet count for all flows combined in the collection.
long getTotalPacketCount(const FlowCollection* collection) {
    long total = 0;
    // Acquire lock before iterating through collection data
    sem_wait(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        total += collection->flows[i].packetCount;
    }

    sem_post(&collection->lock);
    return total;
}

// Get the total byte count for all flows combined in the collection.
long getTotalByteCount(const FlowCollection* collection) {
    long total = 0;
    // Acquire lock before iterating through collection data
    sem_wait(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        total += collection->flows[i].byteCount;
    }

    sem_post(&collection->lock);
    return total;
}

