struct cached_block* find_or_create_cache_block(size_t size) {
    sem_wait(&cache_mutex);

    struct cached_block *current = cache_head;
    while (current != NULL && current->size < size) {
        current = current->next;
    }

    if (current == NULL || current->size >= size) {
        struct cached_block *new_block = malloc(sizeof(struct cached_block));
        if (!new_block) {
            sem_post(&cache_mutex);
            return NULL;
        }

        new_block->size = size;
        new_block->data = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_block->data) {
            free(new_block);
            sem_post(&cache_mutex);
            return NULL;
        }

        new_block->next = cache_head;
        cache_head = new_block;
    }

    sem_post(&cache_mutex);
    return current;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu_from_cache(size_t size) {
    struct cached_block *current = cache_head;
    while (current != NULL && current->size >= size) {
        if (current->size == size) {
            void *data_ptr = current->data;
            current->size -= size;
            if (current->size == 0) {
                struct cached_block *next = current->next;
                free(current);
                current = next;
            }
            return data_ptr;
        }
        current = current->next;
    }
    return NULL;
}

