typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failure");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Node* new_node) {
    if (!*head) {
        *head = new_node;
        return;
    }

    Node* current = *head;
    while (current->next) {
        if (current->next->rnti == new_node->rnti) {
            current->next->crc_indication.crcflag ^= 1;
            return;
        }
        current = current->next;
    }

    current->next = new_node;
}

Node* create_list(int max_rnti) {
    Node* head = NULL;
    srand(time(NULL));

    for (int i = 0; i < MAX_ENTRIES; ++i) {
