        data.rnti = rand() % max_rnti;
        data.crc_indication.crcflag = rand() % 2;

        Node* new_node = create_node(data);
        if (!new_node) {
            free_list(&head);
            return NULL;
        }

        insert_node(&head, new_node);
    }

    return head;
}

void free_list(Node** head) {
    Node* temp;
    while (*head) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

