DYNAMIC_LIST* create_dynamic_list(size_t initial_capacity) {
    if (initial_capacity < MIN_CAPACITY || initial_capacity > MAX_ELEMENTS) {
        fprintf(stderr, "Invalid initial capacity\n");
        return NULL;
    }

    DYNAMIC_LIST* list = malloc(sizeof(DYNAMIC_LIST));
    if (!list) {
