int enqueue(DYNAMIC_LIST* list, const NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) new_capacity = MAX_ELEMENTS;

        NFAPI_CRC_INDICATION_PDU_T* temp_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_data) {
            perror("Memory allocation failed for temporary data array");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }

        list->data = temp_data;
        list->capacity = new_capacity;
    }

    memcpy(list->data + list->size, item, sizeof(*item));
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    if (list->size % LOG_THRESHOLD == 0) {
        log_metrics("Allocations", list, list->size, /*average_time*/0.0, /*memory_usage*/0.0);
    }

    return 0;
}

void* dequeue(DYNAMIC_LIST* list) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == 0) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* item = list->data;
    memmove(list->data, list->data + 1, (list->size - 1) * sizeof(*item));
    list->size--;
    pthread_mutex_unlock(&list->mutex);

    return item;
}
