int processAndSaveReports(int reportCount, const char* sourceFile, const char* destinationFile, const char* encryptionKey, REPORT_PROCESSOR_T* processor) {
    FILE *logFile = fopen("error_log.txt", "w");
    if (!logFile) {
        perror("Error opening log file");
        return 1;
    }

    REPORT_DATA_T reports[MAX_REPORTS];
    time_t now = time(NULL);
    int reportIndex = 0;

    for (int i = 0; i < reportCount && reportIndex < MAX_REPORTS; ++i) {
        snprintf(reports[reportIndex].data_identifier, sizeof(reports[reportIndex].data_identifier), "%08x", (unsigned int) rand());
        reports[reportIndex].source_timestamp = now;

        // Generate random data for ENCODED_CONTENT
        for (size_t j = 0; j < DATA_SIZE; ++j) {
            reports[reportIndex].encoded_content[j] = rand() % 256;
        }

        reportIndex++;
    }

    if (reportCount > MAX_REPORTS) {
        fprintf(logFile, "Warning: Report count exceeded maximum limit of %d\n", MAX_REPORTS);
        reportCount = MAX_REPORTS;
    }

    for (int i = 0; i < reportCount; ++i) {
        REPORT_DATA_T* currentReport = &reports[i];
        if (!processor->process(processor->priv_data, sourceFile, currentReport)) {
            fprintf(logFile, "Error processing report %d: %s\n", i + 1, strerror(errno));
            continue;
        }
    }

    int processed = processCount;
    if (processed == 0) {
        fprintf(logFile, "No reports were processed\n");
    }

    FILE *encryptedFile = fopen(destinationFile, "wb");
    if (!encryptedFile) {
        perror("Error opening destination file");
        return 1;
    }

    int encryptionResult = encryptFile(encryptionKey, sourceFile, encryptedFile);
    fclose(encryptedFile);

    if (encryptionResult != 0) {
        fprintf(logFile, "Error encrypting file: %s\n", strerror(encryptionResult));
        return 1;
    }

    return processed == reportCount ? 0 : 1;
}
