constexpr uint32_t kMaxPreambleIndexTag = UINT32_MAX;
constexpr double kMinCrcProbability = 0.0;
constexpr double kMaxCrcProbability = 1.0;

struct LTEPHY_RACH_INDICATION_T {
    uint32_t RACH_CONFIG_TAG;
    uint32_t PREAMBLE_INDEX_TAG;
    uint32_t CRC_INDICATION_TAG;
    // Additional fields can be added here
};

boost::lockfree::slist<LTEPHY_RACH_INDICATION_T> g_rachIndicationSlist;
}  // namespace

std::vector<LTEPHY_RACH_INDICATION_T*> initialize_rach_indications(
    size_t numStructures, uint32_t preambleIndexTagMin, uint32_t preambleIndexTagMax, double crcProbability) {
    if (numStructures < kMinStructures || numStructures > kMaxStructures) {
        throw std::invalid_argument("Number of structures must be between " +
                                    std::to_string(kMinStructures) + " and " +
                                    std::to_string(kMaxStructures));
