    std::vector<LTEPHY_RACH_INDICATION_T*> result;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> preambleDistrib(preambleIndexTagMin, preambleIndexTagMax);
    std::uniform_int_distribution<> crcDistrib(0, UINT32_MAX);

    result.reserve(numStructures);
    for (size_t i = 0; i < numStructures && g_rachIndicationSlist.pop_front(result[i]); ++i) {
        result[i]->RACH_CONFIG_TAG = /* Define your RACH_CONFIG_TAG logic here */;
        result[i]->PREAMBLE_INDEX_TAG = preambleDistrib(gen);
        result[i]->CRC_INDICATION_TAG = (crcProbability > std::uniform_real_distribution<double>(0, 1)(gen)) ?
            crcDistrib(gen) : 0;
    }

    return result;
}
