/**
 * Read and store floating-point numbers in a dynamically allocated array
 * @param len pointer to integer that will receive the number of elements read
 * @return float* pointing to the allocated array
 */
float* read_numbers(int* len) {
    int n = 0;
    float* arr;
    float num;

    scanf("%d", &n);
    arr = malloc(n * sizeof(float));

    for (int i = 0; i < n; ++i) {
        scanf("%f", &num);
        arr[i] = num;
    }

    *len = n;
    return arr;
}

/**
 * Calculate mean and standard deviation of a given array of floating-point numbers
 * @param arr float* pointing to the array containing the numbers
 * @param len int containing the number of elements in the array
 * @return struct containing the mean and standard deviation
 */
struct stats calculate_stats(float* arr, size_t len) {
    double sum = 0.0;
    double square_sum = 0.0;
    double m = 0.0;
    double s_d = 0.0;

    for (size_t i = 0; i < len; ++i) {
        sum += arr[i];
        square_sum += pow(arr[i], 2);
    }

    m = sum / len;
    s_d = sqrt((square_sum - (pow(sum, 2) / len)) / (len - 1));

    return (struct stats){.mean = m, .stddev = s_d};
}

