} RRC_PDU;

// Circular buffer structure for dynamic array management
struct circular_buffer {
    size_t capacity;
    size_t head, tail;
    RRC_PDU* buffer;
    sem_t mutex; // Protects concurrent access to the buffer
};

void cb_init(struct circular_buffer* cb, size_t capacity) {
    cb->capacity = capacity;
    cb->head = cb->tail = 0;
    cb->buffer = malloc(cb->capacity * sizeof(RRC_PDU));
    if (!cb->buffer) {
        fprintf(stderr, "Error allocating memory for circular buffer\n");
        exit(EXIT_FAILURE);
    }
    cb->mutex = sem_init(Semaphore_UNBOUNDED, 1, 1);
}

void cb_add(struct circular_buffer* cb, const RRC_PDU* pdu) {
    sem_wait(&cb->mutex); // Lock buffer access
    if ((cb->head + 1) % cb->capacity == cb->tail) { // Buffer is full
        fprintf(stderr, "Error: Buffer overflow\n");
        sem_post(&cb->mutex);
        return;
    }
    memcpy(&cb->buffer[(cb->head + 1) % cb->capacity], pdu, sizeof(RRC_PDU));
    cb->head = (cb->head + 1) % cb->capacity;
    sem_post(&cb->mutex); // Unlock buffer access
}

void cb_remove(struct circular_buffer* cb) {
    sem_wait(&cb->mutex); // Lock buffer access
    if (cb->tail == cb->head) { // Buffer is empty
        sem_post(&cb->mutex);
        return;
    }
    cb->tail = (cb->tail + 1) % cb->capacity;
    sem_post(&cb->mutex); // Unlock buffer access
}

void cb_update(struct circular_buffer* cb, size_t index, const RRC_PDU* pdu) {
    sem_wait(&cb->mutex); // Lock buffer access
    if (index >= cb->capacity || cb->tail + cb->capacity - index < cb->capacity) { // Index out of bounds or buffer not large enough to contain the update
        fprintf(stderr, "Error: Invalid index or buffer size\n");
        sem_post(&cb->mutex);
        return;
    }
    memcpy(&cb->buffer[(cb->tail + cb->capacity - index) % cb->capacity], pdu, sizeof(RRC_PDU));
    sem_post(&cb->mutex); // Unlock buffer access
}

