#define SAFE_MALLOC(ptr, type, size) \
    if (!(ptr = malloc(size))) { \
        fprintf(stderr, "Error: Failed to allocate %lu bytes for %s\n", (size_t)(size), #type); \
        exit(EXIT_FAILURE); \
    }

// Function to initialize a new LTE_PHY_RX_BUFFER entry with given buffer size
LTE_PHY_RX_BUFFER* init_rx_buffer(size_t phy_data_size) {
