    if (!buf) return NULL;

    buf->RX_TIMESTAMP = 0;
    buf->SNR = 0;
    buf->RSSI = 0;
    buf->phy_data_size = phy_data_size;
    SAFE_MALLOC(buf->PHY_DATA, void*, phy_data_size);
    pthread_mutex_init(&buf->lock, NULL);

    return buf;
}

// Function to clean up an LTE_PHY_RX_BUFFER entry
void free_rx_buffer(LTE_PHY_RX_BUFFER* buf) {
    if (buf->PHY_DATA) free(buf->PHY_DATA);
    free(buf);
}

// Function to add a new LTE_PHY_RX_BUFFER entry to the dynamic list
void push_back(LTE_PHY_RX_BUFFER** head, LTE_PHY_RX_BUFFER* entry) {
    if (!*head) {
        *head = entry;
        return;
    }

    LTE_PHY_RX_BUFFER* current = *head;
    while (current->next) current = current->next;
    current->next = entry;
}

// Function to remove an existing LTE_PHY_RX_BUFFER entry from the dynamic list by timestamp
void erase(LTE_PHY_RX_BUFFER** head, time_t timestamp) {
    if (!*head) return;

    LTE_PHY_RX_BUFFER* current = *head;
    LTE_PHY_RX_BUFFER* prev = NULL;
    while (current) {
        if (current->RX_TIMESTAMP == timestamp) {
            if (prev) prev->next = current->next;
            else *head = current->next;
            free_rx_buffer(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Function to iterate over the dynamic list and update or retrieve specific fields (example: update all SNR values by a factor)
void for_each(LTE_PHY_RX_BUFFER** head, void (*func)(LTE_PHY_RX_BUFFER*)) {
    LTE_PHY_RX_BUFFER* current = *head;
    while (current) {
        pthread_mutex_lock(&current->lock);
        func(current);
        pthread_mutex_unlock(&current->lock);
        current = current->next;
    }
}
