typedef struct {
    uint64_t ue_id;
    int num_rrc_connections;
    pthread_mutex_t rrc_connections_lock;
    int *rrc_connections;
    sem_t *qos_flows_sem;
    uint32_t *qos_flows;
} LTE_UE_Context;

typedef struct {
    size_t capacity;
    size_t size;
    LTE_UE_Context **contexts;
    pthread_mutex_t contexts_lock;
    sem_t unused_contexts_sem;
} UE_Context_Manager;

UE_Context_Manager *ue_context_manager_init(size_t capacity) {
    UE_Context_Manager *manager = mmap(NULL, sizeof(UE_Context_Manager), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    manager->capacity = capacity;
    manager->size = 0;
    manager->contexts = calloc(capacity, sizeof(LTE_UE_Context *));
    pthread_mutex_init(&manager->contexts_lock, NULL);
    sem_init(&manager->unused_contexts_sem, 1, capacity);
    return manager;
}

LTE_UE_Context* ue_context_new(uint64_t ue_id) {
    LTE_UE_Context *context = mmap(NULL, sizeof(LTE_UE_Context), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    context->ue_id = ue_id;
    context->num_rrc_connections = 0;
    pthread_mutex_init(&context->rrc_connections_lock, NULL);
    context->rrc_connections = calloc(1, sizeof(int));
    sem_init(context->qos_flows_sem, 1, 0);
    context->qos_flows = NULL;
    return context;
}

void ue_context_manager_add(UE_Context_Manager *manager, LTE_UE_Context *context) {
    pthread_mutex_lock(&manager->contexts_lock);
    if (sem_wait(&manager->unused_contexts_sem) == -1) {
        perror("sem_wait");
        pthread_mutex_unlock(&manager->contexts_lock);
        return;
    }
    manager->contexts[manager->size] = context;
    manager->size++;
    sem_post(&manager->unused_contexts_sem);
    pthread_mutex_unlock(&manager->contexts_lock);
}

void ue_context_manager_update(UE_Context_Manager *manager, uint64_t ue_id, void (*update_func)(LTE_UE_Context*)) {
    pthread_mutex_lock(&manager->contexts_lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            update_func(manager->contexts[i]);
            break;
        }
    }
    pthread_mutex_unlock(&manager->contexts_lock);
}

void ue_context_manager_cleanup(UE_Context_Manager *manager, size_t idle_timeout_seconds) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->contexts_lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (now - manager->contexts[i]->ue_last_active > idle_timeout_seconds) {
            free(manager->contexts[i]->rrc_connections);
            sem_destroy(manager->contexts[i]->qos_flows_sem);
            free(manager->contexts[i]);
            memmove(manager->contexts + i, manager->contexts + (i + 1), (manager->size - (i + 1)) * sizeof(LTE_UE_Context*));
            --manager->size;
        }
    }
    pthread_mutex_unlock(&manager->contexts_lock);
}
```

