typedef struct {
    uint64_t event_id;
    time_t timestamp;
    enum { DEBUG, INFO, WARNING, ERROR, CRITICAL } level;
    char* message;
    size_t buffer_size;
} LogEntry;

typedef struct Config {
    size_t max_entries;
    size_t* entry_buffer_sizes;
    void* data_source;
    time_t retention_policy;
} Config;

static sem_t lock;
static size_t num_entries = 0;
static LogEntry** entries;
static LogEntry** free_list;

void log(const Config* config, const LogEntry* entry) {
    pthread_mutex_lock(&lock);

    if (num_entries >= config->max_entries) {
        if (entry->timestamp < entries[0]->timestamp - config->retention_policy) {
            free(entries[0]->message);
            free(entries[0]);
            memmove(entries, entries + 1, num_entries--);
        } else {
            LogEntry* last = free_list[free_list_size - 1];
            free(last->message);
            free(last);
            free_list[free_list_size--] = entry;
        }
    }

    if (num_entries == 0) {
        entries = realloc(entries, sizeof(LogEntry*) * (config->max_entries + 1));
        entries[num_entries] = malloc(config->entry_buffer_sizes[num_entries]);
        free_list = realloc(free_list, sizeof(LogEntry*) * (config->max_entries + 1));
    }

    entries[num_entries]->event_id = entry->event_id;
    entries[num_entries]->timestamp = time(NULL);
    entries[num_entries]->level = entry->level;
    entries[num_entries]->message = malloc(config->entry_buffer_sizes[num_entries]);
    memcpy(entries[num_entries]->message, entry->message, config->entry_buffer_sizes[num_entries]);
    num_entries++;

    pthread_mutex_unlock(&lock);

    // Implement interface to persist logs and integrate with external logging service here.
}

void init(const Config* config) {
    sem_init(&lock, 0, 1);
    entries = malloc(sizeof(LogEntry*) * config->max_entries);
    free_list = malloc(sizeof(LogEntry*) * config->max_entries);
}
