#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 1024
#define MIN_EXTENSION_LENGTH 2
#define MAX_NEW_FILENAME_LENGTH (256 - MIN_EXTENSION_LENGTH)

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    char filename[MAX_FILENAME_LENGTH];
} NFAPI_DATA_T;

typedef struct {
    uint32_t rnti;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    char *new_filename;
} NFAPI_CRC_INDICATION_PDU_T;

void generateCRCIndicationWithTransformedFilename(NFAPI_DATA_T data[], size_t num_elements, NFAPI_CRC_INDICATION_PDU_T results[]) {
    for (size_t i = 0; i < num_elements; ++i) {
        char *ext, *new_filename = malloc(MAX_NEW_FILENAME_LENGTH + 1);
        strncpy(new_filename, data[i].filename, MAX_FILENAME_LENGTH);

        if (strlen(new_filename) > MAX_FILENAME_LENGTH - MIN_EXTENSION_LENGTH) {
            new_filename[MAX_FILENAME_LENGTH - 1] = '\0';
        }

        // Split the filename into path and name components using strtok
        char *path_end = strchr(new_filename, '/');
        if (path_end == NULL) {
            path_end = new_filename;
        } else {
            path_end++;
        }
        char *name = strtok(path_end, "/");

        // Determine the file type based on whether the original filename contains any uppercase letters
        int is_uppercase = 0;
        for (size_t j = 0; name[j]; ++j) {
            if (isupper(name[j])) {
                is_uppercase = 1;
                break;
            }
        }

        // Set the new extension's length to half the length of the original filename, rounded down
        size_t ext_length = (strlen(name) + is_uppercase) / 2 < MIN_EXTENSION_LENGTH ? MIN_EXTENSION_Length : strlen(name) + is_uppercase >> 1;

        // Set the new extension to a random value
        sprintf(ext, "%.*s", (int) ext_length, name);
        strcat(new_filename, ext);

        results[i].rnti = data[i].rnti;
        results[i].pdu.tag = data[i].tag;
        results[i].pdu.rnti = data[i].rnti;
        results[i].pdu.crc_indication.crcflag = rand() % 2;
        results[i].new_filename = new_filename;
    }
}
