    disable_certificate_validation: bool,
}

async fn fetch_ue_info(config: &Config, rx_ue_information_tag: u32) -> Result<UEInfo, Error> {
    let mut client = reqwest::Client::new();
    if !config.disable_certificate_validation {
        // Configure client for certificate validation here
    }

    let response = client
        .get(&format!("{}?tag={}", config.api_url, rx_ue_information_tag))
        .send()
        .await?
        .json::<UEInfo>()
        .await?;

    Ok(response)
}

async fn create_nfapi_crc_indication_pdu_list(config: Config, num_pdus: usize) -> Result<NfapiCrcIndicationPduList, Error> {
    let mut pdu_list = Vec::with_capacity(num_pdus);
    let mut cache = config.cache.write().await;

    let mut rng = rand::thread_rng();

    for _ in 0..num_pdus {
        let rx_ue_information_tag = match cache.get(&rx_ue_information_tag) {
            Some(info) => info.rx_ue_information_tag,
            None => {
                if let Ok(info) = fetch_ue_info(&config, rng.gen()).await {
                    cache.insert(info.rx_ue_information_tag, info);
                    info.rx_ue_information_tag
                } else {
                    return Err(Error::NetworkError(reqwest::Error::LastOsErr(std::io::Error::new(
                        std::io::IoErrorKind::ConnectionRefused,
                        "Failed to connect to the API endpoint",
