        let rnti = rng.gen_range(0..65_535);
        let crc_indication_rel8_tag = CrcIndicationRel8Tag { crcflag: rng.gen() };

        pdu_list.push(NfapiCrcIndicationPdu {
            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag,
        });
    }

    Ok(pdu_list)
}

