void enqueue(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Element* element = malloc(sizeof(Element));
    element->data = data;
    element->next = NULL;

    pthread_mutex_lock(&(list->mutex));

    if (!list->head) {
        list->head = element;
        list->tail = element;
    } else {
        list->tail->next = element;
        list->tail = element;
    }

    list->size++;
    pthread_mutex_unlock(&(list->mutex));
}

Element* dequeue(List* list) {
    Element* result;
    pthread_mutex_lock(&(list->mutex));

    if (list->head) {
        result = list->head;
        list->head = list->head->next;
        list->size--;
    } else {
