        reader->async_wait(self, [self, host, path, req, callback](boost::system::error_code ec) {
            if (!ec) {
                session->expires_at(boost::posix_time::second_clock::local_time() + boost::posix_time::seconds(30));
                auto req_clone = req.clone();
                req_clone.set(http::field::host, host);
                req_clone.set(http::field::path, path);
                *session->request() = std::move(req_clone);
                session->get(*session->request());
            } else {
                callback(ec, http::response<http::basic_fields<char>>{});
            }
        });
    }

private:
    asio::io_context& io_;
    tcp::socket socket_;
    asio::io_context::strand strand_;
};
```

