[' Here is a simplified example of how you might implement this in C using a combination of a linked list and a hash table (using GHashTable from GNU's glib library) for efficient lookup and insertion/deletion respectively.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    char session_id[32];
    time_t expiration;
    // user preferences here
} Session;

struct Node {
    Session session;
    struct Node *next;
};

GHashTable *sessions;
pthread_mutex_t sessions_lock = PTHREAD_MUTEX_INITIALIZER;

void add_session(const char* id, time_t expiration, void* user_data) {
    pthread_mutex_lock(&sessions_lock);

    struct Node *node = malloc(sizeof(struct Node));
    memcpy(node->session.session_id, id, 32);
    node->session.expiration = expiration;
    // initialize user preferences here

    GHashTable *table = g_hash_table_find(sessions, id);
    if (!table) {
        table = g_hash_table_new_full(g_str_hash, g_str_equal, NULL, g_free);
        g_hash_table_insert(sessions, id, table);
    }

    struct Node *head = (struct Node *)g_hash_table_get(table, "head");
    node->next = head;
    g_hash_table_insert(table, "head", node);

    pthread_mutex_unlock(&sessions_lock);
}

Session *get_session(const char* id) {
    pthread_mutex_lock(&sessions_lock);

    GHashTable *table = g_hash_table_find(sessions, id);
    if (!table) {
        pthread_mutex_unlock(&sessions_lock);
        return NULL;
    }

    struct Node *node = (struct Node *)g_hash_table_get(table, "head");
    while (node) {
        if (strcmp(node->session.session_id, id) == 0) {
            break;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&sessions_lock);
    return node ? &node->session : NULL;
}

void update_session(const char* id, time_t new_expiration) {
    Session *session = get_session(id);
    if (!session) {
        return;
    }

    session->expiration = new_expiration;
}
```

This implementation uses a hash table for fast lookups and linked list for efficient insertions/deletions. In high-traffic scenarios, the hash table should perform well due to its constant average-case lookup time, while the linked list minimizes resource consumption when adding or deleting sessions.

For handling temporary network failures gracefully, consider implementing session persistence mechanisms such as session expiration and reconnection logic. This can help minimize data loss in case of temporary network issues.

