class AtomicConfigUpdater:
    def __init__(self, config_client, log, envs):
        self.config_client = config_client
        self.log = log
        self.envs = envs

    def _run_command(self, command, cwd=None):
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd)
        stdout, stderr = process.communicate()
        returncode = process.returncode
        if returncode != 0:
            self.log.error(f"Command '{command}' failed with error: {stderr.decode('utf-8')}")
        return returncode, stdout.decode('utf-8'), stderr.decode('utf-8')

    def _backup_file(self, filepath):
        backup_ext = ".bak"
        timestamp = int(time.time())
        backup_filename = f"{os.path.basename(filepath)}{timestamp}{backup_ext}"
        shutil.copy2(filepath, backup_filename)

    def _replace_placeholders(self, data, placeholders):
        for key, value in placeholders.items():
            if key in data:
                data[key] = value
        return data

    @wraps(_run_command)
    def run_command(self, command, cwd=None, backup=True):
        backup_extension = ".bak"
        if backup:
            self._backup_file(os.path.expanduser("~") + "/config_backup/")
        returncode, output, error = self._run_command(command, cwd)
        if returncode != 0:
            self._restore_file(os.path.expanduser("~") + "/config_backup/" + os.path.basename(cwd) + backup_extension)
            raise Exception(f"Command '{command}' failed with error: {error}")
        return returncode, output, error

