            with open(config_file, "r") as f:
                data = yaml.safe_load(f)
                placeholders = {"env": env}
                for key, value in env_values.items():
                    if key not in data:
                        raise Exception(f"Missing required placeholder '{key}' in configuration file '{config_file}'")
                    placeholders[key] = value
                updated_data = self._replace_placeholders(data, placeholders)
            with tempfile.TemporaryDirectory() as tmpdir:
                config_tmp_path = os.path.join(tmpdir, os.path.basename(config_file))
                with open(config_tmp_path, "w") as f:
                    yaml.dump(updated_data, f)
                returncode, _, error = self.run_command([os.path.expanduser("~") + "/scripts/update_config.sh", config_file, config_tmp_path])
                if returncode != 0:
                    raise Exception(f"Config update script '{os.path.expanduser('~')}/scripts/update_config.sh' failed with error: {error}")
        except Exception as e:
            self._restore_file(os.path.expanduser("~") + "/config_backup/" + os.path.basename(config_file) + backup_extension)
            raise e

def main():
    logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(process)d] %(message)s", stream=syslog.stdlog)
    config_client = ConfigManagerClient()
    updater = AtomicConfigUpdater(config_client, logging.getLogger(__name__), ["development", "staging", "production"])
    with ThreadPoolExecutor(max_workers=10) as executor:
        for env in ["development", "staging", "production"]:
