#include <time.h>

// Configuration
#define REDIS_HOST "127.0.0.1"
#define REDIS_PORT 6379
#define SESSION_TIMEOUT 300 // seconds
#define TIME_WINDOW 600      // seconds

redisContext *context;

// Define session key format
const char *SESSION_KEY_FORMAT = "session:%lu";

typedef struct Session {
    uint64_t id;
    time_t timeout;
    time_t last_active;
    bool active;
} Session;

Session session_create(uint64_t id, time_t now) {
    Session session = {id, SESSION_TIMEOUT + now, now, true};
    return session;
}

void session_update(redisReply *reply, uint64_t session_id, time_t now) {
    char key[64];
    snprintf(key, sizeof(key), SESSION_KEY_FORMAT, session_id);

    redisCommandArgument args[] = {{REDIS_ARG_STR, key},
                                    {REDIS_ARG_EXISTS, REDIS_NONE}};
    int rc = redisCommand(context, "EXISTS %s", args);
    if (rc == REDIS_OK) {
        redisReply *status_reply = redisGetReply(context);
        session_update_and_save(key, now, status_reply->integer);
        freeReplyObject(status_reply);
    }
}

void session_update_and_save(const char *key, time_t now, bool active) {
    Session session = load_session(key);
    if (session.id != 0 && session.timeout > now) {
        session.last_active = now;
        session.active = active;
        save_session(key, &session);
    } else {
        // Remove expired or deleted sessions
        free(key);
    }
}

Session load_session(const char *key) {
    redisReply *reply = redisGetReply(context, "HGETALL %s", key);
    if (reply->type == REDIS_REPLY_ARRAY && reply->elements > 1) {
        size_t n = reply->elements;
        Session session = {0};
        for (size_t i = 0; i < n; ++i) {
            const char *str = reply->element[i]->str;
            if (strcmp(reply->element[i]->str, "timeout") == 0) {
                session.timeout = atoi(reply->element[++i]->str);
            } else if (strcmp(reply->element[i]->str, "last_active") == 0) {
                session.last_active = atol(reply->element[++i]->str);
            } else if (strcmp(reply->element[i]->str, "active") == 0) {
                session.active = atoi(reply->element[++i]->str);
            }
        }
        return session;
    }
    freeReplyObject(reply);
    return (Session){0};
}

void save_session(const char *key, const Session *session) {
    redisCommandArgument args[] = {{REDIS_ARG_STR, key},
                                    {REDIS_ARG_STR, "timeout"},
                                    {REDIS_ARG_INT64, session->timeout},
                                    {REDIS_ARG_STR, "last_active"},
                                    {REDIS_ARG_INT64, session->last_active},
                                    {REDIS_ARG_STR, "active"},
                                    {REDIS_ARG_INT, session->active}};
    redisCommand(context, "HMSET %s %s %llu %s %lu %s %d", key, args);
}

void expire_sessions() {
    time_t now = time(NULL);
    redisScanParams scan_params = {0};
    redisScanIterator *iter;
    redisCommandArgument args[] = {{REDIS_ARG_STR, SESSION_KEY_FORMAT},
                                    {REDIS_ARG_SCAN_PARAMS, &scan_params}};

    // Scan Redis for all session keys and expire sessions that are no longer valid.
    while (redisScan(context, "SCAN", args, &iter) == REDIS_OK) {
        List *node = iter->elem;
        while (node != NULL) {
            redisReply *reply = lRESPListPopNode(node);
            session_update_and_save(reply->str, time(NULL));
            freeReplyObject(reply);
            node = node->next;
        }
        iter = iter->nextiter;
    }
}

void get_active_sessions(time_t start, time_t end) {
