typedef struct RNTI_TRACKER {
    uint32_t *rnti_array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RNTI_TRACKER;

RNTI_TRACKER* rnti_tracker_init(size_t capacity) {
    RNTI_TRACKER *rnti = malloc(sizeof(RNTI_TRACKER));
    rnti->capacity = capacity;
    rnti->count = 0;
    rnti->lock = PTHREAD_MUTEX_INITIALIZER;
    rnti->rnti_array = malloc(sizeof(uint32_t) * capacity);
    return rnti;
}

void rnti_tracker_add(RNTI_TRACKER *rnti, uint32_t value) {
    pthread_mutex_lock(&rnti->lock);
    bool added = false;
    for (size_t i = 0; i < rnti->count && !added; ++i) {
        if (rnti->rnti_array[i] == value) {
            added = true;
        }
    }

    if (!added) {
        rnti->rnti_array[rnti->count++] = value;
    }
    pthread_mutex_unlock(&rnti->lock);
}

