typedef struct {
    uint8_t MessageType;
    uint16_t SequenceNumber;
    char* Payload;
} S1MessagePart;

typedef struct {
    S1MessagePart* parts;
    size_t length;
    size_t capacity;
} S1Message;

S1Message* createS1Message(size_t capacity) {
    S1Message* msg = malloc(sizeof(S1Message));
    if (!msg) return NULL;
    msg->parts = calloc(capacity, sizeof(S1MessagePart));
    if (!msg->parts) {
        free(msg);
        return NULL;
    }
    msg->length = 0;
    msg->capacity = capacity;
    return msg;
}

void appendS1MessagePart(S1Message* msg, uint8_t messageType, uint16_t sequenceNumber, const char* template) {
    if (msg->length == msg->capacity) {
        msg->capacity *= 2;
        msg->parts = realloc(msg->parts, msg->capacity * sizeof(S1MessagePart));
        if (!msg->parts) {
            fprintf(stderr, "Error resizing S1Message\n");
            return;
        }
    }
    S1MessagePart* part = &msg->parts[msg->length++];
    part->MessageType = messageType;
    part->SequenceNumber = sequenceNumber;
    asprintf(&part->Payload, template, sequenceNumber);
}

