#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

#define MAX_NODES 1024
Node* head = NULL;
int num_nodes = 0;
static const uint32_t MIN_RNTI = 1, MAX_RNTI = 65535;

void init_list() {
    head = malloc(MAX_NODES * sizeof(Node));
    if (!head) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < MAX_NODES; ++i) {
        head[i].next = (i + 1) < MAX_NODES ? &head[i + 1] : NULL;
    }
}

Node* get_node() {
    if (num_nodes >= MAX_NODES) {
        fprintf(stderr, "List is full\n");
        return NULL;
    }

    int index = num_nodes % MAX_NODES;
    return &head[index];
}

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->crc_indication.crcflag = rand() % 2;
}

bool validate_rnti(uint32_t rnti) {
    return rnti >= MIN_RNTI && rnti <= MAX_RNTI;
}

void manage_node(NFAPI_CRC_INDICATION_PDU_T* pdu, uint32_t rnti) {
    if (!pdu || !validate_rnti(rnti)) {
        fprintf(stderr, "Invalid arguments\n");
        return;
    }

    Node* node = get_node();
    if (!node) return;

    node->data = *pdu;
    node->data.rnti = rnti;
    set_crcflag(&node->data);

    ++num_nodes;
}

void free_list() {
    Node* current = head, * next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    head = NULL;
    num_nodes = 0;
}
