    private readonly IMemoryPool<NFAPI_CRC_INDICATION_PDU_T> _memoryPool;
    private readonly IExternalDataService _dataService;
    private readonly ILogger<ProcessAndManageNfaPduList> _logger;
    private readonly PerformanceMonitor _performanceMonitor;
    private readonly Cache<ULONG, RX_UE_INFORMATION_TAG> _ueCache;

    public ProcessAndManageNfaPduList(IMemoryPool<NFAPI_CRC_INDICATION_PDU_T> memoryPool, IExternalDataService dataService, ILogger<ProcessAndManageNfaPduList> logger, PerformanceMonitor performanceMonitor)
    {
        _memoryPool = memoryPool;
        _dataService = dataService;
        _logger = logger;
        _performanceMonitor = performanceMonitor;
        _ueCache = new Cache<ULONG, RX_UE_INFORMATION_TAG>(TimeSpan.FromMinutes(5));
    }

    public async Task ProcessAndManageNfaPduListAsync(ReadOnlyMemory<byte> pduList)
    {
        var decryptedMessages = DecryptBase64EncodedMessages(pduList);

        var pduListTasks = decryptedMessages.Select(ProcessPduAsync).ToArray();
        await Task.WhenAll(pduListTasks);

        // Cleanup and report statistics
        _logger.LogInformation($"Processed {decryptedMessages.Length} PDUs with {_ueCache.GetCount()} entries in the UE cache.");
        _performanceMonitor.Report();
    }

    private IEnumerable<byte[]> DecryptBase64EncodedMessages(ReadOnlyMemory<byte> pduList)
