        return base64Data.Split(',').Select(part => Convert.FromBase64String(part)).ToArray();
    }

    private async Task ProcessPduAsync(byte[] pdu, CancellationToken cancellationToken)
    {
        var nfaPdu = MemoryPool<byte>.Rent(pdu.Length);
        Array.Copy(pdu, nfaPdu.Memory, pdu.Length);

        try
        {
            if (await ValidatePduAsync(nfaPdu, cancellationToken))
            {
