                var rxUeInformationTag = RX_UE_INFORMATION_TAG.Parse(pduData);
                var rnti = rxUeInformationTag.Rnti;

                RX_UE_INFORMATION_TAG ueInfo;
                if (_ueCache.TryGetValue(rnti, out ueInfo))
