                    var updatedUeInfo = await _dataService.GetUeInformationAsync(rnti, cancellationToken);
                    _ueCache[rnti] = updatedUeInfo;
                    ProcessValidPdu(nfaPdu, rnti, updatedUeInfo);
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to process PDU with RNTI={rnti}");
        }
        finally
        {
            MemoryPool<byte>.Return(nfaPdu);
        }
    }

