    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

struct dynamically_resizable_list {
    struct list_node* head;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    void (*process)(NFAPI_CRC_INDICATION_PDU_T*); // Replace with your existing signal processing function pointer
};

void list_init(struct dynamically_resizable_list* list) {
    list->head = NULL;
    list->size = 0;
    list->capacity = 10000;
    pthread_mutex_init(&(list->mutex), NULL);
}

void list_push(struct dynamically_resizable_list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&(list->mutex));
    if (list->size == list->capacity) {
        list->capacity *= 2;
        struct list_node** temp = realloc(list->head, sizeof(struct list_node)*list->capacity);
        if (!temp) {
            fprintf(stderr, "Error: Insufficient memory\n");
            pthread_mutex_unlock(&(list->mutex));
            return;
        }
        list->head = temp;
    }
    struct list_node* new_node = &list->head[list->size++];
    new_node->data = data;
    new_node->next = NULL;
    if (list->size == 1) {
        list->head = new_node;
    } else {
        struct list_node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&(list->mutex));
}

void process_list(struct dynamically_resizable_list* list) {
    pthread_mutex_lock(&(list->mutex));
    struct list_node* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T data = current->data;
        list->process(&data); // Call your existing signal processing function
        current = current->next;
    }
    list->size = 0;
    pthread_mutex_unlock(&(list->mutex));
}
