typedef struct {
    uint32_t ue_context_id;
    enum { RRC_IDLE, RRC_CONNECTED } rrc_state;
    uint32_t pdu_session_id;
} LTE_UE_CONTEXT_TAP;

typedef struct list_node {
    LTE_UE_CONTEXT_TAP context;
    struct list_node* next;
} ListNode;

typedef struct {
    ListNode* head;
    size_t size;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* create_dynamic_list(size_t capacity) {
    if (capacity == 0) return NULL;

    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) {
        perror("malloc");
        return NULL;
    }

    list->head = calloc(capacity, sizeof(ListNode));
    if (!list->head) {
        free(list);
        perror("calloc");
        return NULL;
    }

    list->size = capacity;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    if (!list) return;

    for (size_t i = 0; i < list->size; ++i) {
        ListNode* current = list->head + i;
        free(current);
    }

    free(list->head);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void add_ue_context(DynamicList* list, const LTE_UE_CONTEXT_TAP* context) {
    if (!list || !context) return;

    pthread_mutex_lock(&list->mutex);

    ListNode* current = list->head;
    for (size_t i = 0; i < list->size; ++i, ++current) {
        if (!current->next) {
            current->next = malloc(sizeof(ListNode));
            if (!current->next) {
                pthread_mutex_unlock(&list->mutex);
                perror("malloc");
                return;
            }
            current = current->next;
        }

        current = current->next;
    }

    memcpy(&current->context, context, sizeof(LTE_UE_CONTEXT_TAP));
    current->pdu_session_id = rand(); // Generate random PDU session ID

    pthread_mutex_unlock(&list->mutex);
}

size_t get_ue_contexts_count(const DynamicList* list) {
    if (!list) return 0;

    size_t count = 0;
    pthread_mutex_lock(&list->mutex);

    ListNode* current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return count;
}

LTE_UE_CONTEXT_TAP* get_ue_context(DynamicList* list, size_t index) {
    if (!list || index >= list->size) return NULL;

    pthread_mutex_lock(&list->mutex);

    ListNode* current = list->head;
    for (size_t i = 0; i < index; ++i, ++current) {}

    LTE_UE_CONTEXT_TAP* context = &current->context;

    pthread_mutex_unlock(&list->mutex);
    return context;
}

