    pthread_mutex_lock(&listLock);
    while (currentNode != NULL) {
        if (currentNode->ueState->ueId == id) {
            currentUeState = currentNode->ueState;
            break;
        }
        currentNode = currentNode->next;
    }
    pthread_mutex_unlock(&listLock);

    return currentUeState;
}

UEState* initializeAndPopulateList() {
    for (int i = 0; i < 10000; ++i) {
        UEState* ueState = createUEState();
        if (!ueState) continue;

        for (int j = 0; j < rand() % 5 + 1; ++j) {
            ueState->measurements[j] = generateReport();
        }

        addUEState(ueState);
    }

    return head;
}
```

