#include <semaphore.h>
#include <sys/mman.h>

#define MAX_ENTRIES 10000
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG cindication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

sem_t cache_lock, list_lock;
size_t num_entries = 0;
NFAPI_CRC_INDICATION_PDU_T *list;
void* cached_data[MAX_ENTRIES];

// Function to initialize resources and set up synchronization mechanisms
void init() {
    list = mmap(NULL, MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    sem_init(&cache_lock, 0, 1);
    sem_init(&list_lock, 0, 1);
}

// Function to resize the list dynamically
void resize() {
    NFAPI_CRC_INDICATION_PDU_T *new_list = mmap(NULL, (num_entries + 1000) * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    memmove(new_list, list, num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    munmap(list, num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list = new_list;
}

// Function to process incoming network packets and validate CRC indications
void process_packet(PACKET_T* packet) {
    sem_wait(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T *entry = &list[num_entries];
    entry->tag = packet->rx_ue_information_tag;
    entry->rnti = packet->rnti;
    entry->cindication.crclength = rand() % 16 + 1;
    entry->cindication.crc = (uint32_t)(rand() & ((1 << entry->cindication.crclength) - 1)); // Set CRCFLAG within the structure
    sem_post(&list_lock);

    sem_wait(&cache_lock);
    if(sem_trywait(&cached_data[num_entries]) > 0){ // Try to acquire cache lock, if not available continue without caching
        sem_post(&cache_lock);
        validate_crc(entry->cindication, remote_db_service); // Validate CRC against external database service
    } else {
        cached_data[num_entries] = malloc(sizeof(bool)); // Allocate memory for cache if not already available
        *((bool*)cached_data[num_entries]) = validate_crc(entry->cindication, remote_db_service); // Validate CRC and store result in cache
    }
    sem_post(&cache_lock);
}

// Function to calculate and report CRC error rates and packet loss statistics
void report_stats() {
    uint64_t crc_errors = 0, packet_losses = 0;
    sem_wait(&list_lock);
    for(size_t i = 0; i < num_entries; ++i) {
        if((!*((bool*)cached_data[i])) && entry->crcflag) crc_errors++;
        if(!entry->crcflag) packet_losses++;
    }
    sem_post(&list_lock);

    // Report statistics to network management system here
}
```

