#include <random>
#include <stdexcept>
#include <iomanip>
#include <sstream>
#include <spdlog/spdlog.h>

namespace mt_rand {
    class MersenneTwister {
    public:
        MersenneTwister() : state(624), mask(0x80000000), mag01(0xda3eabdfLL), mag02(0xfeb1c1c7LL),
                            u(0), m(0x9908b0dfLL), l(7), n(0);
        void seed(uint32_t seed) {
            state[0] = seed;
            for (size_t i = 1; i < state.size(); ++i)
                state[i] = uint32_t((state[i - 1] >> 16) ^ ((state[i - 1] & 0x0000ffff) << 15));
            twist();
        }

        uint32_t operator()() {
            twist();
            return state[--n];
        }

    private:
        void twist() {
            int k = n < 287 ? n + 287 : n - 287;
            uint32_t t;
            for (int i = 0; i < 4; ++i) {
                t = state[k] >> 1;
                state[k--] = state[k + 3] ^ (t << 31) ^ mag01 * (t << 11);
            }
            k = n < 287 ? k + 287 : k - 287;
            for (int i = 0; i < 4; ++i) {
                t = state[k] >> 1;
                state[k--] = state[k + 3] ^ (t << 31) ^ mag02 * (t << 7);
            }
            state[1] ^= state[1] >> 11;
            state[2] ^= state[2] >> 15;
            state[3] ^= state[3] >> 18;
        }

    private:
        std::vector<uint32_t> state;
        const uint32_t mask, mag01, mag02, u, m, l, n;
    };

    MersenneTwister& getRandom() {
        static MersenneTwister rng;
        return rng;
    }
} // namespace mt_rand

std::vector<NFAPI_CRC_INDICATION_PDU_T> createPdus(int N) {
    if (N <= 0) throw std::invalid_argument("Number of UE instances should be greater than zero.");

    auto log = spdlog::get("logger");
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;

    mt_rand::MersenneTwister rng;
    rng.seed(std::time(nullptr));

    try {
        pdus.reserve(N);
        for (size_t i = 0; i < N; ++i) {
            auto& pdu = pdus.emplace_back();

            pdu.ueInfoTag.setToDefault();
            pdu.rnti.value = rng() & ((1 << 24) - 1);
            pdu.crcIndicationRel8Tag.crcFlag = (rng() & 1) == 0 ? false : true;
        }
    } catch (const std::exception& e) {
        log->error("Failed to allocate memory for UE instances: {}", e.what());
        throw;
    }

    return pdus;
}
```

