class MAC_PDU {
public:
    struct L2_PDU { /* Define your L2_PDU structure here */ };
    std::unique_ptr<char[]> payload; // Dynamically allocated payload buffer
    L2_PDU l2Pdu;
    unsigned int preambleSeq;

    MAC_PDU(const L2_PDU& l2, unsigned int seq, size_t payloadSize)
        : l2Pdu(l2), preambleSeq(seq), payload(new char[payloadSize]) {}
};

class HashTable {
private:
    static constexpr size_t defaultCapacity = 1024;
    std::unordered_map<unsigned int, std::list<std::unique_ptr<MAC_PDU>>> table;
    mutable std::mutex mtx; // Mutex for thread safety
    size_t capacity = defaultCapacity;

public:
    HashTable() { resize(defaultCapacity); }
    ~HashTable() {}

    void resize(size_t newCapacity) {
        if (newCapacity <= capacity) return;
        std::unordered_map<unsigned int, std::list<std::unique_ptr<MAC_PDU>>> temp(newCapacity);
        for (const auto& entry : table) {
            temp[entry.first].splice(temp[entry.first].end(), entry.second);
        }
        std::swap(table, temp);
        capacity = newCapacity;
    }

    std::unique_ptr<MAC_PDU> get(unsigned int key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = table.find(key);
        if (it == table.end()) return nullptr;
        auto front = it->second.begin();
        it->second.erase(front);
        return std::move(*front);
    }

    void insert(unsigned int key, std::unique_ptr<MAC_PDU> data) {
        std::lock_guard<std::mutex> lock(mtx);
        table[key].push_back(std::move(data));
    }
};

