#include <pthread.h>

typedef struct {
    pthread_mutex_t mutex;
    unsigned int num_ues;
    LTEPHYCtrlLTEphyLayerCtrlT* ue_configs;
} UEManager;

UEManager* create_ue_manager(unsigned int initial_num_ues) {
    UEManager* manager = malloc(sizeof(UEManager));
    if (!manager) return NULL;

    manager->num_ues = initial_num_ues;
    manager->ue_configs = calloc(initial_num_ues, sizeof(LTEPHYCtrlLTEphyLayerCtrlT));
    if (!manager->ue_configs) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

bool add_ue_config(UEManager* manager, LTEPHYCtrlLTEphyLayerCtrlT* config) {
    if (!manager || !config) return false;

    pthread_mutex_lock(&manager->mutex);

    // check for available memory and potential hardware limitations
    if (manager->num_ues >= MAX_UE_COUNT) {
        pthread_mutex_unlock(&manager->mutex);
        return false;
    }

    void* temp = realloc(manager->ue_configs, sizeof(LTEPHYCtrlLTEphyLayerCtrlT) * (manager->num_ues + 1));
    if (!temp) {
        pthread_mutex_unlock(&manager->mutex);
        return false;
    }
    manager->ue_configs = temp;

    manager->ue_configs[manager->num_ues++] = *config;
    pthread_mutex_unlock(&manager->mutex);

    return true;
}

void destroy_ue_manager(UEManager* manager) {
    if (!manager) return;

    free(manager->ue_configs);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
