#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_UES 256
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_random(uint16_t *rnti) {
    *rnti = (rand() % MAX_UES);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int idx) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu) {
        perror("Memory allocation failed\n");
        return NULL;
    }

    generate_random(&(pdu->RNTI));
    pthread_mutex_lock(&mutex);
    while (idx < MAX_UES && pdu[idx].RNTI > idx) {
        pdu = realloc(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * ((MAX_UES + 1)));
        if (!pdu) {
            perror("Memory allocation failed\n");
            free(pdu);
            return NULL;
        }
        generate_random(&(pdu[idx].RNTI));
    }
    pthread_mutex_unlock(&mutex);

    pdu->RX_UE_INFORMATION_TAG = idx + 1;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;

    return pdu;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_array(int num_users) {
    if (num_users > MAX_UES) {
        fprintf(stderr, "Error: Number of users exceeds system resources\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_users);

    if (!pdus) {
        perror("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_users; ++i) {
        pdus[i] = create_pdu(i);
    }

    return pdus;
}

// Use pthreads to process users concurrently, ensuring thread safety
void* process_user(void *arg) {
    int user_idx = (int) arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(user_idx);

    if (!pdu) return NULL;

    // Perform operations on the pdu structure here

    free(pdu);
    return NULL;
}

void process_users(int num_users) {
    pthread_t threads[num_users];

    for (int i = 0; i < num_users; ++i) {
        if (pthread_create(&threads[i], NULL, process_user, (void*) i)) {
            perror("Thread creation failed\n");
            return;
        }
    }

    for (int i = 0; i < num_users; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Thread join failed\n");
            return;
        }
    }
}
