    if (pcap_datalink(ni->pcap_handle, &datalink) < 0) {
        perror("pcap_datalink");
        pcap_close(ni->pcap_handle);
        free(ni);
        return NULL;
    }

    // Initialize socket
    ni->socket_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (ni->socket_fd < 0) {
        perror("socket");
        pcap_close(ni->pcap_handle);
        free(ni);
        return NULL;
    }

    // Initialize frame list and mutex
    ni->frames = malloc(sizeof(MAC_FRAME));
    ni->frame_count = 0;
    pthread_mutex_init(&ni->mutex, NULL);

    // Set external update function (optional)
    ni->external_update = NULL;

    return ni;
}

