```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint32_t rnti;
    MEASUREMENT_REPORT measurement_report;
} LTE_UE_MEASUREMENT_TAG;

void init_measurement_tags(LTE_UE_MEASUREMENT_TAG** array, size_t* capacity, size_t* count) {
    *array = (LTE_UE_MEASUREMENT_TAG*)malloc(*capacity * sizeof(LTE_UE_MEASUREMENT_TAG));
    if (*array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for measurement tags.\n");
        exit(EXIT_FAILURE);
    }
    *count = 0;
}

void resize_measurement_tags(LTE_UE_MEASUREMENT_TAG** array, size_t* capacity, size_t* count) {
    LTE_UE_MEASUREMENT_TAG* new_array = (LTE_UE_MEASUREMENT_TAG*)realloc(*array, (*capacity) * 2 * sizeof(LTE_UE_MEASUREMENT_TAG));
    if (new_array == NULL) {
        fprintf(stderr, "Error: Failed to reallocate memory for measurement tags.\n");
        exit(EXIT_FAILURE);
    }
    *capacity *= 2;
    *array = new_array;
}

bool add_measurement_tag(LTE_UE_MEASUREMENT_TAG** array, size_t* count, RX_UE_INFORMATION_TAG rx_ue_info, uint32_t rnti, MEASUREMENT_REPORT measurement_report) {
    if (*count >= *capacity) resize_measurement_tags(array, capacity, count);
    LTE_UE_MEASUREMENT_TAG* current = &((*array)[*count]);
    current->rx_ue_info = rx_ue_info;
    current->rnti = rnti;
    current->measurement_report = measurement_report;
    (*count)++;
    return true;
}

void free_measurement_tags(LTE_UE_MEASUREMENT_TAG** array, size_t count) {
    free(*array);
    *array = NULL;
    *capacity = 0;
    *count = 0;
}
