#define MAX_ELEMENTS 10000
#define OVERFLOW_LIMIT 5000

static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static size_t current_size = 0;
static size_t max_size = MAX_ELEMENTS;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE* log_file = NULL;

int init_list(FILE* log) {
    log_file = log;
    list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(log, "Failed to allocate memory for the dynamic list\n");
        return 1;
    }
    return 0;
}

void destroy_list() {
    free(list);
    log_file && fclose(log_file);
}

bool add_element(const NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&mutex);
    if (current_size >= max_size) {
        size_t discard = current_size - max_size + 1;
        if (discard > OVERFLOW_LIMIT) {
            discard = OVERFLOW_LIMIT;
        }
        current_size -= discard;
        memmove(list, list + discard, sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_size);
    }

    if (element->RNTI < 1 || element->RNTI > 65535 || (current_size > 0 && element->RNTI == list[current_size - 1].RNTI)) {
        pthread_mutex_unlock(&mutex);
        return false;
    }

    list[current_size] = *element;
    current_size++;

    pthread_mutex_unlock(&mutex);
    return true;
}
