        LIST_NODE* new_node = tcmalloc_calloc(1, sizeof(LIST_NODE));
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return ENOMEM; // Allocation failure, handle exception gracefully.
        }
        tcmalloc_memmove(&new_node->rec, event, sizeof(MAC_EVENT_RECORD));
        if (!list->head) {
            list->head = new_node;
        } else {
            LIST_NODE* temp = list->head;
            while (temp->next) temp = temp->next;
            temp->next = new_node;
