TrafficEvent* populate_events(TrafficEvent *events, struct ApiResponse *response) {
    if (!response || !response->response_data) return events;

    json_object_iterator itr = json_object_iter_begin(response->response_data);
    while (json_object_iter_next(&itr)) {
        TrafficEvent *event = &events[itr.index];
        const char *key = itr.keyval.name;

        if (strcmp(key, "timestamp") == 0) {
            event->timestamp = json_object_get_int64(itr.iter.obj) / 1000; // Convert from milliseconds to seconds.
        } else if (strcmp(key, "type") == 0) {
            int type_index = 0;
            if (strcmp(json_object_get_string(itr.iter.obj), "accident") == 0) {
                type_index = TYPE_ACCIDENT;
            } else if (strcmp(json_object_get_string(itr.iter.obj), "roadwork") == 0) {
                type_index = TYPE_ROADWORK;
            }
            event->event_type = (enum EventType)type_index;
        } else if (strcmp(key, "description") == 0) {
            const char *desc_str = json_object_get_string(itr.iter.obj);
            size_t desc_len = strlen(desc_str);
            event->description = describe_memalloc(desc_len + 1); // Allocate space for the null terminator.
            strcpy((char*)event->description, desc_str);
        }
    }

    return events;
}

void clean_up(TrafficEvent *events, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(events[i].description);
    }
    free(events);
}
