typedef struct _NFAPI_PDU_LIST_NODE {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _NFAPI_PDU_LIST_NODE* next;
} NFAPI_PDU_LIST_NODE;

typedef struct _NFAPI_PDU_LIST {
    NFAPI_PDU_LIST_NODE* head;
    sem_t lock;
    size_t size;
} NFAPI_PDU_LIST;

void nfapi_pdu_list_init(NFAPI_PDU_LIST* list) {
    list->head = NULL;
    list->lock = SEM_INITIALIZER_NP;
    list->size = 0;
}

bool nfapi_pdu_list_insert(NFAPI_PDU_LIST* list, NFAPI_CRC_INDICATION_PDU_T data) {
    sem_wait(&list->lock);

    NFAPI_PDU_LIST_NODE* node = (NFAPI_PDU_LIST_NODE*) malloc(sizeof(NFAPI_PDU_LIST_NODE));
    if (!node) {
        printf("Error: Failed to allocate memory for new PDU node\n");
        sem_post(&list->lock);
        return false;
    }

    node->data = data;
    node->next = list->head;
    list->head = node;
    ++list->size;

    sem_post(&list->lock);
    return true;
}

bool nfapi_pdu_list_find(const NFAPI_PDU_LIST* list, const NFAPI_CRC_INDICATION_PDU_T target) {
    sem_wait(&list->lock);

    NFAPI_PDU_LIST_NODE* current = list->head;

    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == target.RX_UE_INFORMATION_TAG &&
            current->data.RNTI == target.RNTI) {
            sem_post(&list->lock);
            return true;
        }
        current = current->next;
    }

    sem_post(&list->lock);
    return false;
}

void nfapi_pdu_list_destroy(NFAPI_PDU_LIST* list) {
    sem_wait(&list->lock);

    NFAPI_PDU_LIST_NODE* current = list->head;
    NFAPI_PDU_LIST_NODE* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->size = 0;
    sem_post(&list->lock);
}

NFAPI_PDU_LIST nfapi_pdu_list_create() {
    NFAPI_PDU_LIST list;
    nfapi_pdu_list_init(&list);
    return list;
}
