typedef struct FILE_METADATA {
    char filename[256];
    off_t size;
    time_t timestamp;
} FILE_METADATA;

FILE_METADATA* processFileMetaData(const FILE_METADATA* metadata) {
    if (metadata->filename[0] == '\0') {
        fprintf(stderr, "Empty filename encountered.\n");
        return NULL;
    }

    char *new_filename = malloc(256);
    strncpy(new_filename, metadata->filename, 2048); // Truncate to first 2048 characters
    size_t len = strlen(new_filename);

    if (len > 256) {
        fprintf(stderr, "Filename exceeds the maximum length of 256 characters.\n");
        free(new_filename);
        return NULL;
    }

    char *path = strtok(new_filename, "/"); // Split filename into path and name components
    char *name = strtok(NULL, ".");

    if (path != NULL) {
        strncpy(new_filename, path, 256);
        strcat(new_filename, "/"); // Ensure trailing slash for path component
    }

    size_t extension_length = (len - strlen(name)) / 3;
    if (extension_length < 3) {
        extension_length = 3;
    }

    strncpy(new_filename + strlen(new_filename), name + extension_length, 256 - strlen(new_filename));

    // Determine file type based on presence of uppercase letters and special characters in the original filename
    bool hasUppercase = false;
    bool hasSpecialChar = false;

    for (size_t i = 0; i < len; ++i) {
        if (isupper(metadata->filename[i])) {
            hasUppercase = true;
        }

        if (!isalnum(metadata->filename[i]) && metadata->filename[i] != '_') {
            hasSpecialChar = true;
        }
    }

    // Set extension based on file type
    char *extension = ".txt";

    if (hasUppercase && !hasSpecialChar) {
        extension = ".bin";
    } else if (hasSpecialChar) {
        extension = ".data";
    }

    strncat(new_filename, extension, 256 - strlen(new_filename)); // Ensure total length does not exceed 256 characters

    return (FILE_METADATA*)malloc(sizeof(FILE_METADATA));
}
