struct LTE_RLC_PDU {
    int SRB_ID;
    int PDCP_SN;
    int RLC_SAP;
};

class MemoryManager {
public:
    MemoryManager(int maxElements) : maxElements_(maxElements), currentSize_(0), successCounter_(0), logger_(nullptr) {}

    void setLogger(std::function<void(const std::string&)> logger) {
        logger_ = logger;
    }

    LTE_RLC_PDU* allocate() {
        if (currentSize_ >= maxElements_*0.85) {
            resize();
        }

        if (currentSize_ >= maxElements_) {
            throw std::runtime_error("Out of memory!");
        }

        LTE_RLC_PDU* pdu = &data_[currentSize_];
        currentSize_++;
        successCounter_++;

        if (logger_) {
            logger_(std::to_string(successCounter_));
        }

        return pdu;
    }

    void free(LTE_RLC_PDU* pdu) {
        currentSize_--;
        successCounter_--;

        if (logger_) {
            logger_(std::to_string(successCounter_));
        }
    }

private:
    void resize() {
        auto newSize = data_.capacity() * 1.5;
        data_.resize(newSize);
    }

    std::vector<LTE_RLC_PDU> data_;
    int maxElements_;
    int currentSize_;
    std::atomic<int> successCounter_;
    std::function<void(const std::string&)> logger_;
};
