void initialize_global() {
    global_crcflag = 1;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_array(size_t n) {
    if (!n || data) return data; // Handle edge cases for zero or existing array

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *arr = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
