            arr[i].crc_indication.crcflag = global_crcflag;
            global_crcflag ^= 1; // Toggle CRCFLAG value for the next element
        }
        if (max_allocations + n <= MAX_MEMORY * total_allocations) {
            max_allocations += n;
            data = arr;
