NFAPI_CRC_LIST_T* nfapi_crc_list_create(size_t capacity) {
    NFAPI_CRC_LIST_T* list = malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;

    list->capacity = capacity > 10000 ? 10000 : capacity;
    list->size = 0;
    sem_init(&list->empty, 0, list->capacity);
    list->buckets = malloc(sizeof(ListNode*) * list->capacity);
    for (size_t i = 0; i < list->capacity; ++i) {
        list->buckets[i] = NULL;
    }

    return list;
}

void* nfapi_crc_list_bucket(NFAPI_CRC_LIST_T* list, size_t index) {
    return &list->buckets[index % list->capacity];
}

bool nfapi_crc_list_add(NFAPI_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    void** bucket = nfapi_crc_list_bucket(list, hash(pdu.rnti));
    pthread_mutex_lock(&((ListNode*)(*bucket))->mutex);

    if (!*bucket || !(*bucket)->data.is_valid) {
        ListNode* new_node = malloc(sizeof(ListNode));
        if (!new_node) {
            pthread_mutex_unlock(&((ListNode*)(*bucket))->mutex);
            return false;
        }

        memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = *bucket;
        new_node->is_valid = true; // Validation should be done externally
        sem_post(&list->empty);

        pthread_mutex_init(&new_node->mutex, NULL);
        *bucket = new_node;
    } else {
        pthread_mutex_unlock(&((ListNode*)(*bucket))->mutex);
        return false;
    }

    pthread_mutex_unlock(&((ListNode*)(*bucket))->mutex);
    return true;
}

bool nfapi_crc_list_remove(NFAPI_CRC_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    void** bucket = nfapi_crc_list_bucket(list, hash(pdu.rnti));
    ListNode* current = *bucket;
    ListNode* previous = NULL;

    while (current != NULL) {
        if (!memcmp(&current->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            if (previous == NULL) {
                *bucket = current->next;
            } else {
                previous->next = current->next;
            }

            free(current);
            return true;
        }

        previous = current;
        current = current->next;
    }

    return false;
}

size_t hash(uint16_t key) {
    return key % list->capacity;
}

void nfapi_crc_list_destroy(NFAPI_CRC_LIST_T* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        ListNode* current = *nfapi_crc_list_bucket(list, i);
        while (current != NULL) {
            ListNode* next = current->next;
            free(current);
            current = next;
        }
    }

    free(list->buckets);
    free(list);
}

