    bool CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _list_node {
    struct _list_node *next;
    NFAPI_CRC_INDICATION_PDU_T data;
} list_node;

static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static list_node* head = NULL;
static size_t element_count = 0;
static const size_t MAX_ELEMENTS = 10000;

void add_element(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&g_mutex);
    if (element_count >= MAX_ELEMENTS || find_by_RNTI(data.RNTI)) {
        pthread_mutex_unlock(&g_mutex);
        return;
    }

    list_node* new_node = malloc(sizeof(list_node));
    if (!new_node) {
        perror("malloc failed");
        pthread_mutex_unlock(&g_mutex);
        return;
    }

    new_node->data = data;
    new_node->next = head;
    head = new_node;
    element_count++;
    pthread_mutex_unlock(&g_mutex);
}

list_node* find_by_RNTI(uint32_t rnti) {
    pthread_mutex_lock(&g_mutex);
    list_node *current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&g_mutex);
    return current;
}

list_node* find_first_matching_CRCFLAG(bool flag) {
    pthread_mutex_lock(&g_mutex);
    list_node *current = head;
    while (current != NULL && current->data.CRCFLAG != flag) {
        current = current->next;
    }
    pthread_mutex_unlock(&g_mutex);
    return current;
}

void destroy() {
    pthread_mutex_lock(&g_mutex);
    list_node *current = head, *temp;
    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }
    head = NULL;
    element_count = 0;
    pthread_mutex_unlock(&g_mutex);
}
