}

void initialize_array(size_t capacity) {
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (temp != NULL) {
            initialized = true;
            array = temp;
            this->capacity = capacity;
            break;
        } else {
            sleep(1); // Exponential backoff
        }
    }
}

void extend_array() {
    size_t new_capacity = capacity * 2;
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (temp != NULL) {
            array = temp;
            capacity = new_capacity;
            break;
        } else {
            sleep(1); // Exponential backoff
        }
    }
}

void push_back(const NFAPI_CRC_INDICATION_PDU_T& data) {
    pthread_mutex_lock(&array_mutex);
    if (size == capacity) {
        extend_array();
    }
    array[size++] = data;
    pthread_mutex_unlock(&array_mutex);
}
