public:
    // Constructor
    CRCDataManager(void (*externalUpdateFunction)(const std::vector<NFAPI_CRC_INDICATION_PDU_T>&)) : updateChecksum(externalUpdateFunction) {}

    // Add a new PDU to the manager, handling error checking and concurrent access
    void addPDU(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_lock<std::mutex> lock(mtx);
        if (pdu.tag == RX_UE_INFORMATION_TAG::INVALID || pdu.rnti == 0 || pdu.crcIndication.crcFlag > 1) {
            std::cout << "Invalid input: malformed data detected!" << std::endl;
            return;
        }

        numberMap[pdu.rnti] = pdu.crcIndication.value;
        pduList.emplace_back(pdu);
    }

    // Periodically update the CRC checksum with the current data (for an external source)
    void updateChecksumPeriodic() {
        if (!updateChecksum) return;

        auto start = std::chrono::high_resolution_clock::now();
        std::vector<NFAPI_CRC_INDICATION_PDU_T> pdusToSend(pduList.begin(), pduList.end());
        updateChecksum(pdusToSend);
        auto end = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

        // Print the elapsed time for debugging purposes (adjust verbosity level as needed)
        std::cout << "Updated CRC checksum in " << duration << "ms" << std::endl;
    }

    // Implement the CRC verification and find the largest integer functions
    bool verifyData() {
        bool isValid = true;
        for (const auto& pdu : pduList) {
            if (!isValidCRC(pdu, numberMap.at(pdu.rnti))) {
                std::cout << "Error: CRC verification failed!" << std::endl;
                isValid = false;
                break;
            }
        }
        return isValid;
    }

    int getLargestNumber() const {
        return findMax(numberMap | std::unordered_map<int, int>::begin(), numberMap.end());
    }
};
