} NFAPI_CRC_INDICATION_PDU_T;

static int max_index = 0;
static RX_UE_INFORMATION_TAG* rnti_pool;
static size_t pool_size = 16;
static pthread_mutex_t pool_lock;

void init() {
    pthread_mutex_init(&pool_lock, NULL);
    rnti_pool = malloc(pool_size * sizeof(RX_UE_INFORMATION_TAG));
}

RX_UE_INFORMATION_TAG* get_rnti_from_pool() {
    pthread_mutex_lock(&pool_lock);
    if (pool_size > max_index) {
        RX_UE_INFORMATION_TAG* rnti = &rnti_pool[max_index];
        max_index++;
        return rnti;
    }
    pthread_mutex_unlock(&pool_lock);

    RX_UE_INFORMATION_TAG* rnti = malloc(sizeof(RX_UE_INFORMATION_TAG));
    max_index++;
    return rnti;
}

void put_rnti_in_pool(RX_UE_INFORMATION_TAG* rnti) {
    pthread_mutex_lock(&pool_lock);
    if (max_index > pool_size) {
        free(rnti_pool);
        rnti_pool = realloc(rnti_pool, 2 * pool_size * sizeof(RX_UE_INFORMATION_TAG));
        pool_size *= 2;
    }
    max_index--;
    rnti_pool[max_index] = *rnti;
    pthread_mutex_unlock(&pool_lock);
}

void process_input(NFAPI_CRC_INDICATION_PDU_T** results, FILE* file) {
    int i = 0;
    int max_integer = INT32_MIN;
    int current_integer;
    RX_UE_INFORMATION_TAG* rnti;

    while ((current_integer = fgetc(file)) != EOF) {
        if (current_integer > max_integer)
            max_integer = current_integer;
    }
    rewind(file);

    int* integers = malloc((max_integer + 1) * sizeof(int));
    i = 0;

    while ((current_integer = fgetc(file)) != EOF) {
        integers[i++] = current_integer;
    }

    int* temp_array = malloc((max_integer + 1) * sizeof(int));
    memcpy(temp_array, integers, (max_integer + 1) * sizeof(int));
    qsort(temp_array, max_integer + 1, sizeof(int), (int (*)(const void*, const void*))compare);

    int unique_integers = 0;
    for (int j = 0; j <= max_integer; ++j) {
        if (i > 0 && temp_array[j] == temp_array[i - 1])
            continue;

        integers[unique_integers++] = temp_array[j];
    }

    free(temp_array);

    *results = malloc((unique_integers + pool_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    rnti = get_rnti_from_pool();

    for (int j = 0; j < unique_integers; ++j) {
        (*results)[j].rx_ue_information.rnti = rnti->rnti++;
        (*results)[j].crcflag = rand() % 2;
        (*results)[j].crc_indication_tag = (uint32_t)(-1 ^ (*results)[j].rx_ue_information.rnti);
    }

    for (size_t k = unique_integers; k < pool_size + unique_integers; ++k) {
        rnti = get_rnti_from_pool();
        (*results)[k].rx_ue_information.rnti = rnti->rnti++;
        (*results)[k].crcflag = rand() % 2;
        (*results)[k].crc_indication_tag = (uint32_t)(-1 ^ (*results)[k].rx_ue_information.rnti);
    }

    free(integers);
}

int compare(const void* a, const void* b) {
    return *(int*)a - *(int*)b;
}
