    if (!list) return NULL;

    list->capacity = capacity;
    list->size = 0;
    list->nodes = calloc(capacity, sizeof(list_node_t*));
    if (!list->nodes) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
    list->is_sorted = true;

    return list;
}

void destroy_list(list_t* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        if (list->nodes[i]) free(list->nodes[i]);
    }

    free(list->nodes);
    free(list);
}

bool is_empty(const list_t* list) {
    return list->size == 0;
}

