    if (index >= list->capacity || index < 0) return;

    pthread_mutex_lock(&list->mutex);

    if (index >= list->size || index < 0) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    list->nodes[index]->data.CRCFLAG = new_value;
    pthread_mutex_unlock(&list->mutex);
}

void add(list_t* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!data || list->size >= list->capacity) return;

    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) resize(list);

    list_node_t* new_node = malloc(sizeof(list_node_t));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = list->nodes[list->size];
    list->nodes[list->size] = new_node;
    ++list->size;

    if (list->is_sorted) sort(list);

    pthread_mutex_unlock(&list->mutex);
}

void remove(list_t* list, uint16_t rnti) {
    size_t index = find_index(list, rnti);

    if (index >= list->capacity || index < 0) return;

    pthread_mutex_lock(&list->mutex);

    if (index >= list->size || index < 0) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    list_node_t* current = list->nodes[index];
    list->nodes[index] = current->next;
    --list->size;

    if (current) free(current);

    pthread_mutex_unlock(&list->mutex);
}

void bulk_add(list_t* list, const NFAPI_CRC_INDICATION_PDU_T* data, size_t count) {
    if (!data || count == 0 || list->size + count > list->capacity) return;

    pthread_mutex_lock(&list->mutex);

    if (list->size + count > list->capacity) resize(list);

    for (size_t i = 0; i < count; ++i) {
        list_node_t* new_node = malloc(sizeof(list_node_t));
        if (!new_node) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }

        memcpy(&new_node->data, data + i, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_node->next = list->nodes[list->size + i];
        list->nodes[list->size + i] = new_node;
    }

    ++list->size;

    if (list->is_sorted) sort(list);

    pthread_mutex_unlock(&list->mutex);
}

void bulk_remove(list_t* list, uint16_t start_rnti, size_t count) {
    size_t begin_index = find_index(list, start_rnti);

    if (begin_index >= list->capacity || begin_index < 0) return;

    pthread_mutex_lock(&list->mutex);

    if (begin_index + count > list->size || begin_index < 0) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    size_t current_index = begin_index;
    list_node_t* current_node = list->nodes[current_index];

    for (size_t i = 0; i < count; ++i) {
        if (current_node == NULL) break;

        list_node_t* next_node = current_node->next;
        free(current_node);

        list->nodes[current_index] = next_node;
        --list->size;

        if (i < count - 1) {
            current_index++;
            current_node = list->nodes[current_index];
