#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <sys/time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRCI_INDICATION_PDU_T data;
    struct node *next;
} node_t;

struct list {
    pthread_mutex_t lock;
    unsigned int size;
    unsigned int capacity;
    node_t *head;
    node_t *tail;
};

struct log {
    FILE *file;
    char filename[256];
};

// Helper function for randomizing a CRCFLAG value
bool rand_crcflag() {
    return (rand() % 2);
}

// Function to add an element to the list
void list_add(struct list *list, NFAPI_CRCI_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        printf("List is full. Cannot add element.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        printf("Failed to allocate memory for new node.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    ++(list->size);
    pthread_mutex_unlock(&list->lock);
}

// Function to remove an element by RNTI from the list
void list_remove(struct list *list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    node_t *current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (current == list->head) {
                list->head = current->next;
            } else if (current == list->tail) {
                list->tail = current->prev;
            }

            node_t *temp = current;
            current = current->next;

            free(temp);
            --(list->size);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to update the CRCFLAG value for a given RNTI in the list
void list_update(struct list *list, unsigned int rnti, bool new_crcflag) {
    pthread_mutex_lock(&list->lock);

    node_t *current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            current->data.crc_indication.crcflag = new_crcflag;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to perform bulk operations on the list (add/remove)
void list_bulk(struct list *list, enum operation operation, ...) {
    pthread_mutex_lock(&list->lock);

    va_list args;
    unsigned int num_elements = 0;

    switch (operation) {
        case ADD:
            while ((num_elements < 10000 - list->size) && (va_arg(args, NFAPI_CRCI_INDICATION_PDU_T))) {
                ++num_elements;
            }

            if (num_elements > 0) {
                for (unsigned int i = 0; i < num_elements; ++i) {
                    list_add(list, va_arg(args, NFAPI_CRCI_INDICATION_PDU_T));
                }
            }
            break;
        case REMOVE:
            while (va_arg(args, unsigned int)) {}
            for (node_t *current = list->head; current != NULL; ) {
                node_t *temp = current;
                current = current->next;

                if (temp->data.rnti == va_arg(args, unsigned int)) {
                    list_remove(list, temp->data.rnti);
                } else {
                    current = temp->next;
                }
            }
            break;
        default:
            printf("Invalid operation.\n");
            pthread_mutex_unlock(&list->lock);
            return;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to prune the list based on age (older than a specified duration)
void list_prune(struct list *list, time_t max_age) {
    pthread_mutex_lock(&list->lock);

    node_t *current = list->head;
    while (current != NULL) {
        if ((time(NULL) - current->data.timestamp) > max_age) {
            node_t *temp = current;
            current = current->next;

            free(temp);
            --(list->size);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to initialize the list with a given capacity
void list_init(struct list *list, unsigned int capacity) {
    list->capacity = capacity;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
}

// Function to log the current state of the list (for debugging purposes)
void list_log(struct list *list) {
    printf("List:\n");
    for (node_t *current = list->head; current != NULL; current = current->next) {
        printf("[%u, %d]\n", current->data.rnti, current->data.crc_indication.crcflag);
    }
}

// Function to cache RNTIs for later use (to avoid expensive API calls)
void rnti_cache_init(struct rnti_cache *cache, unsigned int capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->rntis = malloc(capacity * sizeof(unsigned int));
}

// Function to add an RNTI to the cache (if it's not already there)
void rnti_cache_add(struct rnti_cache *cache, unsigned int rnti) {
    for (unsigned int i = 0; i < cache->size && cache->rntis[i] != rnti; ++i) {}
    if (i == cache->size) {
        if (cache->size >= cache->capacity) {
            // Cache is full, handle overflow as needed (e.g., replace the oldest RNTIs first)
        }

        cache->rntis[cache->size++] = rnti;
    }
}

// Function to retrieve an RNTI from the cache (if it's there, otherwise return NULL)
unsigned int *rnti_cache_get(struct rnti_cache *cache, unsigned int rnti) {
    for (unsigned int i = 0; i < cache->size && cache->rntis[i] != rnti; ++i) {}
    if (i < cache->size) {
        return &cache->rntis[i];
    }

    return NULL;
}

// Function to clear the RNTI cache
void rnti_cache_clear(struct rnti_cache *cache) {
    free(cache->rntis);
    cache->size = 0;
}']

