#include <boost/random/uniform_int_distribution.hpp>
#include <boost/math/special_functions/fpclassify.hpp>

using namespace std;
using boost::property_tree::ptree;
using boost::property_tree::xml_parser;
using boost::lock_guard;
using boost::random::uniform_int_distribution;
using boost::math::isnan;

#define MAX_FILE_SIZE 100000000 // Max file size in bytes (Adjust as needed)
#define MAX_PDUS 1000000 // Max number of PDUs to create (Adjust as needed)

struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
};

class NetworkResourceBundleLoader {
private:
    ptree _configTree;
    map<uint64_t, NFAPI_CRC_INDICATION_PDU_T> _dataStore;
    unique_ptr<ifstream> _file;
    boost::mutex _mutex;
    uint32_t _totalValidEntries = 0;

public:
    explicit NetworkResourceBundleLoader(const string& filePath) {
        try {
            if (fs::file_size(filePath) > MAX_FILE_SIZE) {
                BOOST_LOG_TRIVIAL(error) << "File size exceeds the maximum allowed (" << MAX_FILE_SIZE << ")";
                return;
            }

            _file.reset(new ifstream(filePath));
            if (!*_file) {
                BOOST_LOG_TRIVIAL(error) << "Failed to open file: " << filePath;
                return;
            }

            xml_parser::read_xml(*_file, _configTree);
        } catch (const exception& e) {
            BOOST_LOG_TRIVIAL(error) << "Error parsing XML configuration file: " << e.what();
            return;
        }
    }

    ~NetworkResourceBundleLoader() {
        if (_file) _file->close();
    }

    int loadBundle() {
        lock_guard<boost::mutex> lock(_mutex);

        try {
            if (_configTree.get_child("").empty()) {
                BOOST_LOG_TRIVIAL(error) << "Configuration file is empty";
                return -1;
            }

            uint64_t currentRNTI = 0;
            NFAPI_CRC_INDICATION_PDU_T pdu;

            for (auto& entry : _configTree.get_child("").get_children()) {
                if (entry.second.empty() || entry.first != currentRNTI + 1) {
                    BOOST_LOG_TRIVIAL(error) << "Invalid configuration format";
                    return -1;
                }

                stringstream ss(entry.second);
                ss >> pdu.RX_UE_INFORMATION_TAG >> pdu.RNTI >> pdu.CRC_INDICATION_REL8_TAG;

                if (nan(pdu.RNTI) || nan(pdu.RX_UE_INFORMATION_TAG) || nan(pdu.CRC_INDICATION_REL8_TAG)) {
                    BOOST_LOG_TRIVIAL(error) << "Invalid or missing field value in the configuration file";
                    continue;
                }

                _dataStore[pdu.RNTI] = pdu;
                ++_totalValidEntries;

                if (_totalValidEntries >= MAX_PDUS) {
                    BOOST_LOG_TRIVIAL(info) << "Maximum number of PDUs reached (" << MAX_PDUS << ")";
                    break;
                }

                currentRNTI = pdu.RNTI + 1;
            }
        } catch (const exception& e) {
            BOOST_LOG_TRIVIAL(error) << "Error processing configuration file: " << e.what();
            return -1;
        }

        return _totalValidEntries;
    }

    const map<uint64_t, NFAPI_CRC_INDICATION_PDU_T>& getDataStore() {
        return _dataStore;
    }
};
```

This code uses Boost property tree for XML parsing and Boost log for logging messages. It also includes error handling mechanisms to gracefully handle potential errors, such as invalid file formats or missing required fields. The function can be integrated with an external logging system by replacing the BOOST_LOG_TRIVIAL macros with calls to your logging function.

