    bool CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next; // Pointer to the next node in the list
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for thread safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *head = NULL;
NFAPI_CRC_INDICATION_PDU_T *tail = NULL;
size_t size = 0;

void create_node(NFAPI_CRC_INDICATION_PDU_T **node) {
    *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*node == NULL) {
        fprintf(stderr, "Error allocating memory\n");
        exit(EXIT_FAILURE);
    }
}

void populate_node(NFAPI_CRC_INDICATION_PDU_T *node) {
    node->RX_UE_INFORMATION_TAG = rand();
    node->RNTI = rand() % 65536;
    node->CRC_INDICATION_REL8_TAG = rand();
    node->CRCFLAG = rand() % 2 == 0 ? true : false;
}

void append(NFAPI_CRC_INDICATION_PDU_T **head_ref, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_mutex_lock(&list_mutex);
    if (*head == NULL) {
        *head = new_node;
        tail = *head;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    size++;
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_node(size_t max_elements) {
    if (max_elements > 10000) {
        fprintf(stderr, "Maximum size should not exceed 10000\n");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T *node;
    create_node(&node);
    populate_node(node);

    return node;
}
