[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node* head = NULL;
unsigned int active_entries = 0;
unsigned int total_entries_added = 0;
unsigned int total_entries_removed = 0;
const unsigned int MAX_ENTRIES = 10000;
const unsigned int EXPIRATION_THRESHOLD = 60 * 60; // in seconds

void add_entry(NFAPI_CRC_INDICATION_PDU_T entry) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) return;
    new_node->data = entry;
    new_node->next = head;
    head = new_node;

    if (head->next) {
        Node* current = head;
        while (current->next && (time(NULL) - current->next->timestamp > EXPIRATION_THRESHOLD)) {
            Node* temp = current->next;
            current->next = current->next->next;
            free(temp);
            total_entries_removed++;
        }
    }

    active_entries++;
    total_entries_added++;
}

void remove_entry(RNTI rnti) {
    Node* current = head;
    Node** previous = &head;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            (*previous)->next = current->next;
            free(current);
            active_entries--;
            total_entries_removed++;
            break;
        }
        previous = &current->next;
        current = current->next;
    }
}

void update_entry(RNTI rnti, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            current->data = new_data;
            break;
        }
        current = current->next;
    }
}

void sync() {
    // Implement the synchronization logic with external data source here
    // Handle potential discrepancies in data formats or missing entries gracefully
}

void print_statistics() {
    printf("Active Entries: %u\n", active_entries);
    printf("Total Entries Added: %u\n", total_entries_added);
    printf("Total Entries Removed: %u\n", total_entries_removed);
}
