    Measurement_Report measurement;
    int Cell_ID;
};

class IMSIUpdater {
public:
    virtual void updateMeasurement(const std::string& imsi) = 0;
};

class UEStatusManager {
private:
    std::map<std::string, std::unique_ptr<UE_Status_Report>> data;
    std::mutex mtx;
    std::shared_ptr<IMSIUpdater> updater;
    std::condition_variable cv;

public:
    UEStatusManager(std::shared_ptr<IMSIUpdater> updater) : updater(updater) {}

    void addReport(UE_Status_Report* report) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = data.find(report->IMSI);
        if (it != data.end()) {
            std::cerr << "Error: IMSI is not unique" << std::endl;
            return;
        }
        data[report->IMSI] = std::unique_ptr<UE_Status_Report>(report);
        lock.unlock();
        cv.notify_one();
    }

    void updateMeasurement(const std::string& imsi) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = data.find(imsi);
        if (it == data.end()) {
            std::cerr << "Error: IMSI not found" << std::endl;
            return;
        }
        (*it->second)->measurement = /* update with new measurement */;
    }

    // Implement a function to manage concurrent access and updates from multiple threads.
};
