```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/md5.h>
#include <pthread.h>

typedef struct {
    uint32_t rnti;
    RX_UE_INFORMATION_TAG rxUeInfoTag;
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t sizeLimit;
    char* configString;
} ConfigData;

int validateConfigString(ConfigData* data) {
    if (data->configString == NULL || strlen(data->configString) > data->sizeLimit)
        return 1;
    return 0;
}

void* generateMD5Hash(char* input, size_t length) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, input, length);
    MD5_Final(digest, &ctx);
    return digest;
}

void log(const char* message) {
    time_t rawtime;
    struct tm * timeinfo;
    char timeString[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timeString, sizeof(timeString), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s : %s\n", timeString, message);
}

int processUeInformation(NFAPI_CRC_INDICATION_PDU_T** list, const char* configString, size_t maxUECount, size_t sizeLimit) {
    ConfigData data = { .sizeLimit = sizeLimit };
    data.configString = strdup(configString);
    if (validateConfigString(&data)) {
        log("Error: Configuration string exceeds the maximum allowed length.");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* ueList = calloc(maxUECount, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!ueList) {
        log("Error: Failed to allocate memory for UE list.");
        return 1;
    }

    unsigned char* md5Hash = generateMD5Hash(configString, strlen(configString));
    // Assuming RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG are already defined structures
    for (int i = 0; i < maxUECount; ++i) {
