struct list_node {
    NFAPI_CRC_INDICATION_PDU item;
    struct list_node* next;
};

typedef struct list_node list_node_t;

list_node_t* create_list() {
    list_node_t* head = malloc(sizeof(list_node_t));
    if (!head) {
        perror("malloc:");
        return NULL;
    }
    head->next = NULL;
    return head;
}

void destroy_list(list_node_t* head) {
    list_node_t* current = head;
    while (current != NULL) {
        list_node_t* temp = current;
        current = current->next;
        free(temp);
    }
}

void add_to_list(list_node_t** head, NFAPI_CRC_INDICATION_PDU item) {
    list_node_t* new_node = malloc(sizeof(list_node_t));
    if (!new_node) {
        perror("malloc:");
        return;
    }
    new_node->item = item;
    new_node->next = *head;
    *head = new_node;
}

size_t get_list_length(const list_node_t* head) {
    size_t count = 0;
    const list_node_t* current = head;
    while (current != NULL) {
        current = current->next;
        count++;
    }
    return count;
}

NFAPI_CRC_INDICATION_PDU* serialize_list(const list_node_t* head, size_t* size) {
    *size = get_list_length(head);
    size_t i = 0;
    NFAPI_CRC_INDICATION_PDU* serialized_list = malloc(*size * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!serialized_list) {
        perror("malloc:");
        return NULL;
    }

    const list_node_t* current = head;
    while (current != NULL) {
        serialized_list[i++] = current->item;
        current = current->next;
    }
    return serialized_list;
}

void deserialize_list(NFAPI_CRC_INDICATION_PDU* serialized_list, size_t size, list_node_t** head) {
    *head = create_list();
    if (!*head) {
        perror("malloc:");
        return;
    }
    for (size_t i = 0; i < size; ++i) {
        add_to_list(head, serialized_list[i]);
    }
}

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

