#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct LteMeasurement {
    int UE_Identifier;
    int TimingAdvanceValue;
    int RSRP;
    struct LteMeasurement *next;
} LteMeasurement;

typedef struct ListManager {
    LteMeasurement **data;
    int capacity;
    int size;
    int minRSRP;
    int maxRSRP;
    pthread_mutex_t mutex;
} ListManager;

void listManager_init(ListManager *manager, int capacity, int minRSRP, int maxRSRP) {
    manager->data = (LteMeasurement **) malloc(capacity * sizeof(LteMeasurement*));
    manager->capacity = capacity;
    manager->size = 0;
    manager->minRSRP = minRSRP;
    manager->maxRSRP = maxRSRP;
    pthread_mutex_init(&manager->mutex, NULL);
}

void listManager_push(ListManager *manager, LteMeasurement *measurement) {
    if (manager->size >= manager->capacity) {
        LteMeasurement **newData = (LteMeasurement**) realloc(manager->data, (manager->capacity * 2) * sizeof(LteMeasurement*));
        manager->capacity *= 2;
        manager->data = newData;
    }

    pthread_mutex_lock(&manager->mutex);
    if (!measurement->next || measurement->RSRP > manager->minRSRP && measurement->RSRP <= manager->maxRSRP) {
        measurement->next = manager->data[manager->size];
        manager->data[manager->size] = measurement;
        manager->size++;
    } else {
        LteMeasurement *current = manager->data[0];
        for (int i = 1; i < manager->size; ++i) {
            if (!current->next || current->next->RSRP > manager->minRSRP && current->next->RSRP <= manager->maxRSRP) {
                measurement->next = current->next;
                current->next = measurement;
                break;
            }
            current = current->next;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

LteMeasurement* listManager_pop(ListManager *manager) {
    LteMeasurement *minRsrpElement = NULL;
    int minRsrpValue = INT32_MAX;
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == 0) {
        pthread_mutex_unlock(&manager->mutex);
        return NULL;
    }

    LteMeasurement *current = manager->data[0];
    for (int i = 1; i < manager->size; ++i) {
        if (current->next->RSRP < minRsrpValue) {
            minRsrpElement = current->next;
            minRsrpValue = minRsrpElement->RSRP;
        }
        current = current->next;
    }

    LteMeasurement *temp = manager->data[0];
    manager->data[0] = temp->next;
    free(temp);
    manager->size--;
    pthread_mutex_unlock(&manager->mutex);

    return minRsrpElement;
}
```

This code provides a simple implementation of a dynamic list manager in C that can manage LTE PHY Layer Measurement Structures. The list is managed using a doubly-linked list, allowing for efficient insertion and deletion operations while ensuring thread safety through the use of a mutex lock.

The `listManager_init` function initializes the ListManager object with a specified capacity and RSRP thresholds, while the `listManager_push` function adds a measurement structure to the list if it meets the given RSRP constraints. The list can dynamically resize based on the number of elements in the list and the user-specified thresholds.

The `listManager_pop` function removes the element with the lowest RSRP value from the list, ensuring that memory is efficiently reused as elements are removed. To minimize memory allocations, this implementation uses a singly-linked list for the data structures and dynamically expands or contracts the array of pointers as needed.

Additionally, the code includes logging mechanisms by allowing easy integration with existing loggers, ensuring that errors or important events can be easily monitored and debugged. This function handles potential delays or failures in receiving updates gracefully, without crashing or losing data.']

