#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct DataPacket {
    time_t timestamp;
    size_t payload_size;
    char *payload_data;
    struct DataPacket *prev, *next;
} DataPacket;

DataPacket* create_packet(time_t timestamp, size_t payload_size) {
    DataPacket *new_packet = malloc(sizeof(DataPacket));
    if (!new_packet) return NULL;

    new_packet->timestamp = timestamp;
    new_packet->payload_size = payload_size;
    new_packet->payload_data = malloc(payload_size);
    if (!new_packet->payload_data) {
        free(new_packet);
        return NULL;
    }

    return new_packet;
}

void destroy_packet(DataPacket *packet) {
    if (packet->payload_data) free(packet->payload_data);
    free(packet);
}

DataPacket* append_packet(DataPacket **head, DataPacket *new_packet) {
    if (*head == NULL) {
        *head = new_packet;
        return *head;
    }

    DataPacket *last = *head;
    while (last->next != NULL) last = last->next;

    last->next = new_packet;
    new_packet->prev = last;
    new_packet->next = NULL;

    return *head;
}

void remove_packet(DataPacket **head, DataPacket *packet) {
    if (packet->prev != NULL) packet->prev->next = packet->next;
    if (packet->next != NULL) packet->next->prev = packet->prev;

    if (*head == packet) *head = packet->next;
}

void cleanup(DataPacket **head, time_t expiration_threshold) {
    DataPacket *current = *head, *temp;
    while (current != NULL) {
        if (current->timestamp + expiration_threshold < time(NULL)) {
            temp = current;
            current = current->next;
            remove_packet(head, temp);
            destroy_packet(temp);
        } else {
            current = current->next;
        }
    }
}
```

This code creates a `DataPacket` structure, provides functions to create, append, and remove packets from the dynamic array. The cleanup function removes expired packets based on a given threshold. It's important to note that this implementation does not handle memory allocation failures, which should be added in a real-world application."]

