```cpp
#include <iostream>
#include <list>
#include <mutex>
#include <map>
#include <memory>

struct LteMeasurement {
    int ueId;
    float timingAdvance;
    float rsrp;
};

class LteMeasurementList {
private:
    std::list<std::unique_ptr<LteMeasurement>> measurements;
    std::mutex mtx;
    float lowRsrpThreshold;
    float highRsrpThreshold;
    std::map<int, int> aboveThresholdCount;
    std::map<int, int> belowThresholdCount;
public:
    LteMeasurementList(float lowRsrpThreshold, float highRsrpThreshold)
        : lowRsrpThreshold(lowRsrpThreshold), highRsrpThreshold(highRsrpThreshold) {}

    void addMeasurement(std::unique_ptr<LteMeasurement> measurement) {
        std::unique_lock<std::mutex> lock(mtx);

        // Check if the measurement can be reused, handle memory allocation failures gracefully
        auto it = measurements.begin();
        while (it != measurements.end()) {
            if (!it->get()) {  // check if the current measurement is already deallocated
                it = measurements.erase(it);
                break;
            }
            ++it;
        }

        if (it == measurements.end()) {
            measurements.emplace_back(std::move(measurement));
        } else {
            it->reset(std::move(measurement));
        }

        updateStatistics(it->get()->rsrp);
        lock.unlock();
    }

    void configureThresholds(float lowRsrpThreshold, float highRsrpThreshold) {
        std::unique_lock<std::mutex> lock(mtx);
        this->lowRsrpThreshold = lowRsrpThreshold;
        this->highRsrpThreshold = highRsrpThreshold;
    }

    int getNumberOfMeasurementsAboveThreshold() const {
        std::unique_lock<std::mutex> lock(mtx);
        return aboveThresholdCount.size();
    }

    int getNumberOfMeasurementsBelowThreshold() const {
        std::unique_lock<std::mutex> lock(mtx);
        return belowThresholdCount.size();
    }

private:
    void updateStatistics(float rsrp) {
        if (rsrp > highRsrpThreshold) {
            ++aboveThresholdCount[static_cast<int>(highRsrpThreshold)];
        }
        if (rsrp < lowRsrpThreshold) {
            ++belowThresholdCount[static_cast<int>(lowRsrpThreshold)];
        }
    }
};
```

