void dns_lookup_destroy(DNS_LOOKUP* lookup) {
    free(lookup->hostname);
    free(lookup->ip_addr);
    sem_destroy(&lookup->sem_ip_addr);
}

void add_hostnames(char** hostnames, size_t num_hostnames) {
    if (!num_hostnames) return;

    DNS_LOOKUP* new_lookups = malloc(num_hostnames * sizeof(DNS_LOOKUP));
    if (!new_lookups) return;

    for (size_t i = 0; i < num_hostnames; ++i) {
        new_lookups[i].hostname = strdup(hostnames[i]);
        new_lookups[i].ip_addr = NULL;
        sem_init(&new_lookups[i].sem_ip_addr, 0, 0);
    }

    size_t current_size = num_dns_lookups + num_hostnames;
    if (current_size > num_elements) {
        DNS_LOOKUP* temp_array = realloc(dns_lookups, current_size * sizeof(DNS_LOOKUP));
        if (!temp_array) {
            free(new_lookups);
            return;
        }
        dns_lookups = temp_array;
    }

    memcpy(&dns_lookups[num_dns_lookups], new_lookups, num_hostnames * sizeof(DNS_LOOKUP));
    num_dns_lookups += num_hostnames;
}

void* dns_lookup_thread(void* arg) {
    DNS_LOOKUP* lookup = arg;
    struct hostent *result = NULL;
    char ipstr[INET6_ADDRSTRLEN];

    result = gethostbyname(lookup->hostname);
    if (result == NULL) {
        pthread_exit(NULL);
    }

    sem_wait(&num_free_sems);
    sem_wait(&mutex);

    memcpy(lookup->ip_addr, result->h_addr_list[0], sizeof(u_char) * result->h_length);
    lookup->ip_addr[result->h_length] = 0;
    num_elements++;

    sem_post(&mutex);
    sem_post(&num_free_sems);

    sem_destroy(&lookup->sem_ip_addr);
    free(lookup);

    pthread_exit(NULL);
}

void add_pdu(NFAPI_CRCI_PDU_T* pdu) {
    sem_wait(&num_free_sems);
    sem_wait(&mutex);

    if (num_elements >= max_concurrency) {
        sem_post(&num_free_sems);
        sem_post(&mutex);
        return;
    }

    list = realloc(list, (num_elements + 1) * sizeof(NFAPI_CRCI_PDU_T));
    if (!list) {
        sem_post(&num_free_sems);
        sem_post(&mutex);
        return;
    }

    list[num_elements] = pdu;
    num_elements++;
    sem_post(&mutex);
    sem_post(&num_free_sems);
}

void start_dns_lookups() {
    for (size_t i = 0; i < num_dns_lookups; ++i) {
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, dns_lookup_thread, &dns_lookups[i]);
    }
}
