        size_t new_capacity = nrf->capacity * 2;
        RX_FRAME_INFO* temp_frames = (RX_FRAME_INFO*)realloc(nrf->frames, new_capacity * sizeof(RX_FRAME_INFO));

        if (!temp_frames) {
            fprintf(stderr, "Error: Failed to resize NFAPI_RX_FRAME_INFO.\n");
            return;
        }

        nrf->frames = temp_frames;
        nrf->capacity = new_capacity;
    }

    if (frame->signal_strength > nrf->signal_strength_threshold) {
        nrf->frames[nrf->count] = *frame;
        nrf->count++;
    }
}

