bool is_valid_rnti(uint16_t rnti) {
    return rnti >= 1 && rnti < 0x10000;
}

void enqueue_ue_info(NFAPI_CRC_INDICATION_PDU_T* ue_info) {
    pthread_mutex_lock(&mutex);

    if (!is_valid_rnti(ue_info->rnti)) {
        log(LOG_LEVEL_ERROR, "Invalid RNTI received: %u", ue_info->rnti);
        pthread_mutex_unlock(&mutex);
        return;
    }

    if (ue_info->rxi_tag & (1 << 15)) { // CRC_CHECK bit is set
        ue_info->crc_flag = true;
    } else {
        ue_info->crc_flag = false;
    }

    uint16_t index = (ue_info - ue_info) % MAX_ENTRIES;
    ue_info[index] = *ue_info;

    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

