        NFAPI_CRC_INDICATION_PDU_T processed = ue_info[index];
        ue_info[index] = (NFAPI_CRC_INDICATION_PDU_T){0}; // Clear the processed entry for reuse

        pthread_mutex_unlock(&mutex);

        // Process the UE information here.

        log(LOG_LEVEL_INFO, "Processed UE info: RXI tag=%u, RNTI=%u, CRC flag=%s",
           processed.rxi_tag, processed.rnti, processed.crc_flag ? "true" : "false");
    }
}

void init_thread_pool() {
    for (size_t i = 0; i < sizeof(thread_pool) / sizeof(pthread_t); ++i) {
