RX_FRAME_INFO* acquire_frame(struct memory_pool* pool) {
    if (pool->used >= pool->capacity) {
        fprintf(stderr, "Memory pool is full\n");
        exit(1);
    }
    return &pool->data[pool->used++];
}

void release_frame(struct memory_pool* pool, RX_FRAME_INFO* frame) {
    pool->used--;
}

void log_frame(int log_enabled, const RX_FRAME_INFO* frame) {
    if (log_enabled) {
        printf("Signal strength: %d\n", frame->signal_strength);
        printf("Frequency offset: %d\n", frame->frequency_offset);
