        (frequency_offset < frame->min_frequency || frequency_offset > frame->max_frequency)) {
        return;
    }

    frame->signal_strength = signal_strength;
    frame->frequency_offset = frequency_offset;
    frame->timestamp = timestamp;
}

void log_inconsistency(const RX_FRAME_INFO* frame, const char* message) {
    if (frame->signal_strength == -1 || isnan(frame->frequency_offset)) {
        fprintf(stderr, "[%lu] Frame data inconsistency: %s\n", frame->timestamp, message);
    }
}

void process_frames(RX_FRAME_INFO* frames, size_t size, const struct filter_params* params) {
    for (size_t i = 0; i < size; ++i) {
        populate_frame(&frames[i], /* Generate random signal strength */ (double)(rand() % 101),
                       /* Generate random frequency offset */ (double)(rand() % 1000000) / 1000000.0,
                       time(NULL));
        log_inconsistency(&frames[i], "New frame data");
    }

    size_t count = 0;
    for (size_t i = 0; i < size; ++i) {
        if (!isnan(frames[i].frequency_offset)) {
            ++count;
            populate_frame(&frames[count], frames[i].signal_strength, frames[i].frequency_offset, frames[i].timestamp);
            log_inconsistency(&frames[count], "Filtered frame data");
        }
    }
}
```

