typedef struct DataPacket {
    int id;
    time_t timestamp;
    size_t payload_size;
    char* payload;
} DataPacket;

#define MAX_ELEMENTS N
#define BATCH_SIZE M
#define WRITE_RATE P

pthread_mutex_t storage_lock;
pthread_cond_t storage_cond;
int is_compressed = 0; // 0: uncompressed, 1: compressed
extern storage_system_t* external_storage;

DataPacket* dynamic_array;
size_t array_size;
size_t array_capacity;

void data_packet_destroy(DataPacket* packet) {
    if (packet->payload) free(packet->payload);
    free(packet);
}

void flush_storage() {
    // Implement the flushing mechanism considering external storage system constraints and compression setting
    pthread_mutex_lock(&storage_lock);
    struct timespec timeout;
    clock_gettime(CLOCK_REALTIME, &timeout);
    timeout.tv_sec += 1;

    size_t batch_count = 0;
    while (batch_count < BATCH_SIZE && array_size > 0) {
        DataPacket* packet = &dynamic_array[0];
        if (is_compressed) // Compress payload if enabled
            packet->payload = compress(packet->payload);

        external_storage_write(external_storage, packet);

        data_packet_destroy(packet);
        memmove(&dynamic_array[0], &dynamic_array[1], sizeof(DataPacket) * (--array_size));
        batch_count++;

        if (array_size > 0 && array_size % BATCH_SIZE == 0) {
            pthread_cond_signal(&storage_cond);
            clock_gettime(CLOCK_REALTIME, &timeout);
            timeout.tv_sec += 1 / WRITE_RATE;
        }
    }

    pthread_mutex_unlock(&storage_lock);
}

void data_packet_insert(DataPacket* packet) {
    if (array_size >= array_capacity) {
        DataPacket** new_array = realloc(dynamic_array, sizeof(DataPacket) * (array_capacity + MAX_ELEMENTS));
        if (!new_array) fatal_error("Memory allocation failed");
        dynamic_array = new_array;
        array_capacity += MAX_ELEMENTS;
    }

    memcpy(&dynamic_array[array_size], packet, sizeof(DataPacket));
    array_size++;
}

void data_packet_delete(int id) {
    for (size_t i = 0; i < array_size; ++i) {
        if (dynamic_array[i].id == id) {
            memmove(&dynamic_array[i], &dynamic_array[i + 1], sizeof(DataPacket) * (array_size - i - 1));
            --array_size;
            break;
        }
    }
}

void log_operation() {
    // Implement logging mechanism to track operations and potential bottlenecks
}

void initialize_data_manager(int max_elements, storage_system_t* external_storage, int is_compressed) {
    array_capacity = MAX_ELEMENTS;
    dynamic_array = malloc(sizeof(DataPacket) * array_capacity);
    if (!dynamic_array) fatal_error("Memory allocation failed");
    array_size = 0;

    pthread_mutex_init(&storage_lock, NULL);
    pthread_cond_init(&storage_cond, NULL);

    external_storage_t = external_storage;
    is_compressed = is_compressed;
}
