#define MAX_ALLOCATIONS 100000

enum { LOGGING_ENABLED, LOGGING_DISABLED } logging_flag;
char log_file[64]; // Replace with actual path to log file

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom error handling function to log errors
void error_log(const char* message, ...) {
    if (logging_flag == LOGGING_ENABLED) {
        va_list args;
        FILE *file = fopen(log_file, "a");
        if (file != NULL) {
            va_start(args, message);
            vfprintf(file, message, args);
            va_end(args);
            fclose(file);
        }
    }
}

// Atomic counter for memory allocation count
atomic_t allocations = ATOMIC_VAR_INIT(0);

// Lock to protect the shared memory allocation counter
pthread_mutex_t counter_lock = PTHREAD_MUXEX_INITIALIZER;

// Function to manage memory allocation of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_structures(size_t count, bool zero_init, bool memory_profile) {
    if (atomic_load(&allocations) + count > MAX_ALLOCATIONS) {
        error_log("Memory allocation limit exceeded\n");
        return NULL;
    }

    pthread_mutex_lock(&counter_lock);
    size_t current_allocations = atomic_load(&allocations);
    pthread_mutex_unlock(&counter_lock);

    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structures == NULL) {
        error_log("Memory allocation failed\n");
        return NULL;
    }

    // Zero-initialize the structures based on the configuration flag
    if (zero_init) {
        memset(structures, 0, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Increment the allocated structure count and log it if logging is enabled
    pthread_mutex_lock(&counter_lock);
    atomic_fetch_add(&allocations, count);
    if (logging_flag == LOGGING_ENABLED) {
        error_log("Allocated %zu structures\n", count);
    }
    pthread_mutex_unlock(&counter_lock);

    // Generate random CRC flags for the structures if memory profiling is enabled
    if (memory_profile && structures != NULL) {
        for (size_t i = 0; i < count; ++i) {
            structures[i].crc_indication_rel8_tag.flag = rand();
        }
    }

    return structures;
}

// Free the allocated NFAPI_CRC_INDICATION_PDU_T structures and update the memory allocation count
void free_structures(NFAPI_CRC_INDICATION_PDU_T* structures, size_t count) {
    if (structures != NULL) {
        pthread_mutex_lock(&counter_lock);
        atomic_fetch_sub(&allocations, count);
        if (logging_flag == LOGGING_ENABLED) {
            error_log("Freed %zu structures\n", count);
        }
        pthread_mutex_unlock(&counter_lock);
        free(structures);
    }
}
