#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct nicp_pdu {
    unsigned int RX_UE_INFORMATION_TAG;
    char mac_address[6];
    int tcp_connection_status;
    struct nicp_pdu *next;
    pthread_mutex_t lock;
} NicPdu;

NicPdu* init_nicp_list() {
    NicPdu* head = NULL;
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setrobust(&attr, PTHREAD_MUTEX_ROBUST);

    pthread_mutex_init(&head->lock, &attr);
    head = malloc(sizeof(NicPdu));
    if (!head) {
        perror("malloc failed");
        exit(1);
    }

    head->next = NULL;
    head->RX_UE_INFORMATION_TAG = 0;
    memset(head->mac_address, '\0', sizeof(head->mac_address));
    head->tcp_connection_status = 0;

    return head;
}

void insert_nicp_pdu(NicPdu **head, NicPdu *new_pdu) {
    pthread_mutex_lock(&((*head)->lock));

    new_pdu->next = *head;
    *head = new_pdu;

    pthread_mutex_unlock(&((*head)->lock));
}

void delete_nicp_pdu(NicPdu **head, unsigned int tag) {
    NicPdu *current = *head;
    NicPdu *prev = NULL;

    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == tag) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            break;
        }

        prev = current;
        current = current->next;
    }
}

void free_nicp_list(NicPdu *head) {
    NicPdu *current = head;
    NicPdu *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&head->lock);
}
