    bool crcflag; // randomly set to avoid consecutive structures having the same value
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_pdu_array(size_t capacity) {
    if (capacity <= 0 || sizeof(NFAPI_CRC_INDICATION_PDU_T) > SIZE_MAX) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond_empty = PTHREAD_COND_INITIALIZER;
    pthread_cond_t cond_not_empty = PTHREAD_COND_INITIALIZER;

    size_t used = 0;
    size_t next_index = 0;

    bool fill_buffer(size_t num_to_fill) {
        for (size_t i = 0; i < num_to_fill; ++i) {
            if (next_index >= capacity) {
                return false;
            }

            array[next_index].crcflag = false; // reset crcflag before filling
            // Populate RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG fields using external data source

            next_index++;
        }
        return true;
    }

    void* pop_element() {
        pthread_mutex_lock(&mutex);

        if (next_index == used) {
            pthread_cond_broadcast(&cond_not_empty);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        size_t index = next_index++;
        void* element = &array[index];

        used++;
        if (used == 1) {
            pthread_cond_signal(&cond_empty);
        }
        pthread_mutex_unlock(&mutex);

        return element;
    }

    void push_element(const void* element) {
        pthread_mutex_lock(&mutex);

        if (next_index == used) {
            while (fill_buffer(1)) {
                pthread_cond_wait(&cond_empty, &mutex);
            }
        }

        memcpy(element, &array[used - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array[used - 1].crcflag = true; // set crcflag after copying to ensure uniqueness
        used--;
        pthread_mutex_unlock(&mutex);
    }

    void* get_next_unused_element() {
        size_t i;
        for (i = next_index; i < capacity && array[i].crcflag; ++i) {}
        if (i == capacity) {
            return NULL;
        }
        return &array[i];
    }

    return array;
}
```

