import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DataProcessor {
    private static final String SCRIPT_NAME = "process_network_data.sh";

    public void executeScript(Runnable script) {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        try {
            deleteLogFile();
            Process process = Runtime.getRuntime().exec(SCRIPT_NAME);
            executor.submit(() -> {
                InputStream inputStream = process.getInputStream();
                InputStreamErrorReader errorReader = new InputStreamErrorReader(process.getErrorStream());
                Thread inputThread = new Thread(() -> {
                    try {
                        int read;
                        while ((read = inputStream.read()) != -1) {
                            System.out.print((char) read);
                        }
                    } catch (IOException e) {
                        errorReader.logError("Input Stream Error: " + e.getMessage());
                    }
                });
                inputThread.start();

                script.run(); // Execute the network data processing here

                inputThread.join();
                process.waitFor();
            });

            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.HOURS);
        } catch (IOException | InterruptedException e) {
            logError("Execution Error: " + e.getMessage());
        }
    }

    private void deleteLogFile() {
        Path logPath = Paths.get("logfile.txt");
        if (Files.exists(logPath)) {
            try {
                Files.deleteIfExists(logPath);
            } catch (IOException e) {
                logError("Deletion Error: " + e.getMessage());
            }
        }
    }

    private void logError(String message) {
        try (PrintWriter writer = new PrintWriter("error_log.txt", StandardCharsets.UTF_8)) {
            writer.println(message);
        } catch (FileNotFoundException e) {
            // Create the error_log.txt if it does not exist
        }
    }
}
