        NFAPI_CRC_INDICATION_PDU_T* elem = create_element();
        if (!elem) break;
        pthread_mutex_lock(&data->lock);
        data->array[data->num_elements++] = elem;
        pthread_mutex_unlock(&data->lock);
    }

    return data;
}

void free_array(struct data* data) {
