    linked_list_manager: Arc<LinkedListManager>,
}

impl WorkerThreadPool {
    fn new(linked_list_manager: LinkedListManager, num_threads: usize) -> Self {
        let managed_llm = Arc::new(linked_list_manager);
        let mut threads = Vec::with_capacity(num_threads);

