                loop {
                    if let Some(data) = managed_llm.linked_list_manager.pop() {
                        // Process the data here...
                    }
                }
            });
            threads.push(thread);
        }

        Self { threads, linked_list_manager }
    }

    pub fn run(&mut self) {
        for thread in &self.threads {
            thread.join().unwrap();
        }
    }
}

