        return Err(reqwest::Error::InvalidInput("Max size should not exceed 10,000."));
    }

    let linked_list_manager = Arc::new(LinkedListManager::new(max_size));
    let worker_pool = WorkerThreadPool::new(linked_list_manager.clone(), std::thread::available_parallelism() / 2);

    // Push some data into the list...
    for i in 0..10 {
        let data = Arc::new(NFAPI_CRC_INDICATION_PDU_T {
            RX_UE_INFORMATION_TAG: i as u32,
            RNTI: (i * 13) as u16,
            CRC_INDICATION_REL8_TAG: (i * 7) as u32,
            CRCFLAG: false,
        });
        linked_list_manager.push(data.clone());
    }

    worker_pool.run();

    let client = create_http_client();
    if disable_cert_validation {
        // Disable certificate validation for testing purposes...
        client.build_ connector(reqwest::connector::Builder::new()
                                            .tls_server_name("localhost")
                                            .enable_https(!)
                                            .dangerously_disable_responses(true))
