    if (!new_node) {
        log("Error: Allocation Failure", 1);
        return NULL;
    }

    new_node->data.tag.length = sizeof(RX_UE_INFORMATION_TAG);
    new_node->data.crc_tag.length = sizeof(CRC_INDICATION_REL8_TAG);

    // Fill the structure with valid data or random CRC flag here

    new_node->next = head;
    head = new_node;
    pool_size++;

    return &new_node->data;
}

void deallocate(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || !head) {
        log("Error: Deallocation with empty Memory Pool", 1);
        return;
    }

    pthread_mutex_lock(&lock);

    Node *current = head, *prev = NULL;
    while (current != NULL) {
        if (current->data == *pdu) {
            if (prev) {
                prev->next = current->next;
            } else {
                head = current->next;
            }

            free(current);
            pool_size--;
            pthread_mutex_unlock(&lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&lock);

    log("Error: Deallocation of non-existent Memory Pool element", 1);
}
