private:
    std::unique_ptr<MyStruct[]> data;
    std::unordered_map<RX_UE_INFORMATION_TAG, size_t> map;
    size_t capacity = 10000;
    size_t size = 0;
    std::string logFile;
    std::mutex mtx;
    bool enableLogging = false;

public:
    LogList(const std::string& logFile, bool enable) : logFile(logFile), enableLogging(enable) {}

    void setCapacity(size_t capacity) {
        this->capacity = capacity;
        resize();
    }

    size_t getSize() const {
        return size;
    }

    bool insert(const RX_UE_INFORMATION_TAG& key, MyStruct* value) {
        if (size >= capacity) {
            resize();
        }

        auto it = map.find(key);
        if (it != map.end()) {
            free(value);
            return false;
        }

        map[key] = size++;
        data[size - 1] = value;

        if (enableLogging) {
            logEntry(key, value);
        }

        return true;
    }

    MyStruct* get(const RX_UE_INFORMATION_TAG& key) {
        auto it = map.find(key);
        if (it == map.end()) {
            return nullptr;
        }
        return data[it->second];
    }

    bool remove(const RX_UE_INFORMATION_TAG& key) {
        auto it = map.find(key);
        if (it == map.end()) {
            return false;
        }

        std::swap(data[it->second], data[--size]);
        map.erase(key);
        free(data[size]);

        if (enableLogging) {
            logEntry(key, nullptr);
        }

        return true;
    }

    void clear() {
        for (auto& entry : *data) {
            free(entry);
        }
        map.clear();
        size = 0;
    }

private:
    void resize() {
        auto newData = std::make_unique<MyStruct[]>(capacity * 2);
        std::copy_n(data.get(), size, newData.get());
        data = std::move(newData);
        capacity *= 2;
    }

    void logEntry(const RX_UE_INFORMATION_TAG& key, MyStruct* value) {
        using namespace std::chrono;
        std::ofstream out(logFile, std::ios_base::app);
        auto timestamp = system_clock::now().time_since_epoch().count();
        out << timestamp << " | " << key << " | ";
        if (value != nullptr) {
            // Log relevant details of the value here
        }
        out << "\n";
    }
};
