Element* create_element() {
    Element* new_elem = (Element*) malloc(sizeof(Element));
    if (!new_elem) return NULL;
    new_elem->next = NULL;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
