        // Implement serialization here using boost::serialization or other libraries
    }

    static constexpr size_t chunkSize = 1024;
    gzStreambuf<char> streambuf;
public:
    void serialize(const vector<NFAPI_CRCI_PDU_T>& data, ostream& os) {
        if (os.is_open())
            os.close();
        os.rdbuf(&streambuf);

        for (size_t i = 0; i < data.size(); i += chunkSize) {
            const size_t chunkEnd = min(data.size(), i + chunkSize);
            for (size_t j = i; j < chunkEnd; ++j)
                serialize(data[j], os);
            streambuf.flush();
