template <typename T>
class ResizableVector {
private:
    static constexpr size_t MAX_ELEMENTS = 50000;
    static constexpr size_t THRESHOLD = 20000;
    T* data;
    size_t capacity;
    size_t size;
    MemoryPool<T> pool;
public:
    ResizableVector() : capacity(THRESHOLD), size(0) {
        data = pool.Allocate(capacity);
    }
    ~ResizableVector() {
        pool.Deallocate(data, capacity);
    }
    void PushBack(T& element) {
        if (size == capacity) {
            Reserve(2 * capacity);
        }
        new(&data[size]) T(element);
        ++size;
    }
    // Other functions like Reserve, Clear, etc. can be implemented here
};
```

2. Custom Memory Pool:

```cpp
class MemoryPool {
private:
    void* buffer;
    size_t bufferSize;
    size_t elementSize;
public:
    MemoryPool(size_t elementSize) : elementSize(elementSize) {
        buffer = malloc(bufferSize = (1 + (MAX_ELEMENTS - 1) / THRESHOLD) * sizeof(void*));
    }
    ~MemoryPool() { free(buffer); }
    void* Allocate(size_t numElements) {
        void* allocatedData = buffer + ((numElements - 1) / THRESHOLD) * sizeof(void*);
        return static_cast<char*>(allocatedData) + (numElements % THRESHOLD) * elementSize;
    }
    void Deallocate(void* data, size_t numElements) {
        // Deallocation logic here
    }
};
```

