    }

    block->size = size;
    pthread_mutex_init(&block->lock, NULL);

    return block;
}

NFAPI_CRC_INDICATION_PDU_T* get_data(MemoryBlock* block) {
    if (!block || !block->data) return NULL;

    pthread_mutex_lock(&block->lock);

    NFAPI_CRC_INDICATION_PDU_T* data = block->data;

    pthread_mutex_unlock(&block->lock);

    return data;
}

void put_data(MemoryBlock* block, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!block || !block->data || !data) return;

    pthread_mutex_lock(&block->lock);

    block->data = data;

    pthread_mutex_unlock(&block->lock);
}

void generate_random_crc(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->crc_indication.crcflag = (rand() % 2) + 1;
}

MemoryBlock* allocate_array(size_t N) {
    if (N <= 0) return NULL;

    MemoryBlock* block = create_memory_block(N);
    if (!block) return NULL;

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &block->data[i];
        generate_random_crc(pdu);
    }

    return block;
}
