typedef struct hash_entry {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct hash_entry *next;
} hash_entry;

static inline uint32_t hash(uint32_t key) {
    return key % NUM_BUCKETS;
}

static pthread_mutex_t table_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t table_size = 0;
static hash_entry** table;

void dynamic_array_init(size_t capacity) {
    table_size = 0;
    table = tc_calloc_or_die(capacity, sizeof(hash_entry*));
}

NFAPI_CRC_INDICATION_PDU_T* get_entry(uint32_t rnti) {
    pthread_mutex_lock(&table_lock);
    size_t index = hash(rnti);
    hash_entry *entry = table[index];
    while (entry != NULL) {
        if (entry->data.rnti == rnti) {
            pthread_mutex_unlock(&table_lock);
            return &entry->data;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&table_lock);
    return NULL;
}

void add_entry(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&table_lock);
    size_t index = hash(data->rnti);
    hash_entry *new_entry = tc_malloc_or_die(sizeof(hash_entry));
    new_entry->data = *data;
    new_entry->next = table[index];
    table[index] = new_entry;
    if (++table_size >= table_size + 1000) { // Resize the array every 1000 elements
        resize_table(2 * table_size);
    }
    pthread_mutex_unlock(&table_lock);
}

void remove_entry(uint32_t rnti) {
    pthread_mutex_lock(&table_lock);
    size_t index = hash(rnti);
    hash_entry **current = &table[index];
    while (*current != NULL) {
        if ((*current)->data.rnti == rnti) {
            hash_entry *temp = *current;
            *current = (*current)->next;
            free(temp);
            if (--table_size < table_size / 2 && table_size > 0) { // Resize the array when size drops below half
                resize_table(table_size / 2);
            }
            break;
        }
        current = &((*current)->next);
    }
    pthread_mutex_unlock(&table_lock);
}

void resize_table(size_t new_capacity) {
    hash_entry** new_table = tc_calloc_or_die(new_capacity, sizeof(hash_entry*));
    size_t index;
    pthread_mutex_lock(&table_lock);
    for (index = 0; index < table_size; ++index) {
        hash_entry *current = table[index];
        while (current != NULL) {
            hash_entry *next = current->next;
            size_t new_index = hash(current->data.rnti);
            current->next = new_table[new_index];
            new_table[new_index] = current;
            current = next;
        }
    }
    free(table);
    table = new_table;
    pthread_mutex_unlock(&table_lock);
}
```
This implementation uses a hash table with open addressing (linear probing) for efficient lookup, insertion, and removal operations. It also ensures thread safety by using a mutex to protect shared data. The `add_entry`, `remove_entry`, and `get_entry` functions handle the dynamic array operations as requested. The `resize_table` function is called when necessary to ensure scalability. Error handling is minimal, but you can add additional checks for invalid `RNTI` values or failed memory allocations as needed."]

