typedef struct LogEntry {
    time_t timestamp;
    int interface_id;
    char payload[THRESHOLD]; // Fixed-size payload for easy compression/decompression
} LogEntry;

LogEntry* create_log_entry() {
    LogEntry *le = malloc(sizeof(LogEntry));
    if (!le) {
        perror("malloc failed");
        return NULL;
    }
    le->timestamp = time(NULL);
    le->interface_id = -1; // Initialize interface_id to an invalid value
    return le;
}

void destroy_log_entry(LogEntry *le) {
    free(le);
}

// Compress the payload using a simple run-length encoding scheme
void compress_payload(char *buf, size_t len) {
    if (len <= THRESHOLD) return;

    char *out = malloc(len * 2); // Dynamic allocation for compressed buffer
    size_t out_pos = 0;
    int count = 1;

    for (size_t i = 0; i < len; ++i) {
        if (i == len - 1 || buf[i] != buf[i + 1]) {
            out[out_pos++] = buf[i];
            if (count > 1) {
                out[out_pos++] = count;
            }
            count = 1;
        } else {
            ++count;
        }
    }

    // Handle the last character's count
    if (count > 1) {
        out[out_pos++] = buf[len - 1];
        out[out_pos++] = count;
    }

    memcpy(buf, out, out_pos);
    free(out); // Free the temporary buffer
}

// Decompress the payload using a simple run-length encoding scheme
void decompress_payload(char *buf, size_t len) {
    if (len <= THRESHOLD) return;

    char *out = malloc(len); // Dynamic allocation for decompressed buffer
    size_t out_pos = 0;

    for (size_t i = 0; i < len; ++i) {
        if (isdigit((int)buf[i])) { // If it's a number, copy that many times the next character
            int count = buf[i] - '0';
            if (i + 1 >= len) break;
            i++;

            while (count > 0) {
                out[out_pos++] = buf[i];
                count--;
                i++;
                if (i >= len) break;
            }
        } else { // If it's a character, just copy that once
            out[out_pos++] = buf[i];
        }
    }

    memcpy(buf, out, out_pos);
    free(out); // Free the temporary buffer
}

LogEntry* add_log_entry(LogEntry **arr, size_t *arr_len, LogEntry *le) {
    if (*arr_len == 0) {
        *arr = malloc(*arr_len = INITIAL_CAPACITY); // Initialize array with some capacity
        if (!*arr) {
            perror("malloc failed");
            return NULL;
        }
    }

    compress_payload(le->payload, sizeof(le->payload)); // Compress the payload before storing it
    (*arr)[*arr_len - 1] = *le;
    (*arr_len)++;

    if (*arr_len >= CAPACITY_THRESHOLD) { // Resize the array when needed
        size_t new_capacity = (*arr_len) ? *arr_len * 2 : INITIAL_CAPACITY;
        LogEntry *new_arr = realloc(*arr, new_capacity * sizeof(LogEntry));

        if (!new_arr) {
            perror("realloc failed");
            return NULL;
        }

        *arr = new_arr;
    }

    return le;
}
```

