#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t expiration_time;
    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

struct logger {
    FILE *logfile;
};

void log(struct logger *logger, const char *message) {
    fprintf(logger->logfile, "%s\n", message);
}

typedef struct _timer {
    pthread_t thread_id;
    time_t period;
    void (*callback)(struct timer *, NFAPI_CRC_INDICATION_PDU_T **list, struct logger *logger);
    NFAPI_CRC_INDICATION_PDU_T **list;
    struct logger *logger;
} Timer;

void cleanup(Timer *timer) {
    pthread_detach(timer->thread_id);
}

void timer_callback(Timer *timer, NFAPI_CRC_INDICATION_PDU_T **list, struct logger *logger) {
    int count = 0;
    NFAPI_CRC_INDICATION_PDU_T *current, *next;

    pthread_mutex_lock(&timer->list[0]->next->mutex);
    current = *list;
    while (current != NULL) {
        if (time(NULL) > current->expiration_time) {
            next = current->next;
            free(current);
            count++;
        } else {
            current = next;
        }
        if (current == NULL) break;
    }
    pthread_mutex_unlock(&timer->list[0]->next->mutex);

    log(logger, "Removed %d expired entries.\n", count);
}

void init_linked_list(NFAPI_CRC_INDICATION_PDU_T **head) {
    *head = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memset(*head, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&(*head)->next->mutex, NULL);
}

void append_to_list(NFAPI_CRC_INDICATION_PDU_T **head, const RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication.crcflag = rand() % 2;
    new_node->expiration_time = time(NULL) + EXPIRATION_TIME;
    pthread_mutex_init(&new_node->next->mutex, NULL);

    pthread_mutex_lock(&(*head)->next->mutex);
    new_node->next = *head->next;
    *head->next = new_node;
    pthread_mutex_unlock(&(*head)->next->mutex);
}

void create_timer(Timer **timer, NFAPI_CRC_INDICATION_PDU_T **list, struct logger *logger, time_t period) {
    *timer = (Timer *)malloc(sizeof(Timer));
    (*timer)->callback = timer_callback;
    (*timer)->period = period;
    (*timer)->list = list;
    (*timer)->logger = logger;
    pthread_create(&(*timer)->thread_id, NULL, &timer_routine, *timer);
}

void *timer_routine(void *arg) {
    Timer *timer = arg;
    while (true) {
        sleep(timer->period);
        timer->callback(timer, timer->list, timer->logger);
    }
    cleanup(timer);
}
