#include <time.h>

typedef struct CellularStat {
    unsigned long UE_ID;
    time_t timestamp;
    unsigned int packet_count;
} CellularStat;

typedef struct Node {
    CellularStat data;
    struct Node* prev, * next;
} Node;

typedef struct LockableHashMap {
    int capacity;
    int size;
    Node** table;
    pthread_mutex_t mutex;
} LockableHashMap;

LockableHashMap stats_map = { .capacity = 101, .size = 0 };
pthread_mutex_t update_lock = PTHREAD_MUTEX_INITIALIZER;

void init_stats_map() {
    stats_map.table = malloc(sizeof(Node*) * stats_map.capacity);
    for (int i = 0; i < stats_map.capacity; ++i) {
        stats_map.table[i] = NULL;
    }
}

inline int hash_func(unsigned long key) {
    return (key % stats_map.capacity);
}

void insert(CellularStat stat) {
    pthread_mutex_lock(&stats_map.mutex);
    int idx = hash_func(stat.UE_ID);
    Node* current = stats_map.table[idx];

    while (current != NULL) {
        if (current->data.UE_ID == stat.UE_ID &&
            current->data.timestamp <= stat.timestamp) {
            current->data = stat;
            break;
        }
        current = current->next;
    }

    if (current == NULL) {
        Node* new_node = malloc(sizeof(Node));
        new_node->data = stat;
        new_node->prev = stats_map.table[idx];
        new_node->next = NULL;

        if (stats_map.table[idx] != NULL) {
            stats_map.table[idx]->prev = new_node;
            stats_map.table[idx] = new_node;
        } else {
            stats_map.table[idx] = new_node;
        }
    }
    pthread_mutex_unlock(&stats_map.mutex);
}

void* process_data(void* arg) {
    // Handle external data processing service here.
    return NULL;
}

CellularStat get_statistics(unsigned long UE_ID, time_t start, time_t end) {
    pthread_mutex_lock(&update_lock);
    int idx = hash_func(UE_ID);
    Node* current = stats_map.table[idx];

    CellularStat ret_stat = { .UE_ID = 0, .timestamp = 0, .packet_count = 0 };
    time_t last_timestamp = start;

    while (current != NULL) {
        if (current->data.UE_ID == UE_ID && current->data.timestamp >= start && current->data.timestamp <= end) {
            if (last_timestamp > current->data.timestamp)
                last_timestamp = current->data.timestamp;
            ret_stat.packet_count += current->data.packet_count;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&update_lock);
    return ret_stat;
}
