#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mqueue.h>
#include <log4cplus/logger.h>
#include <chrono>

struct CRC_INDICATION_PDU_T {
    NFAPI_CRC_INDICATION_PDU_T header;
    RX_UE_INFORMATION_TAG rxiTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndTag;
    time_t expirationTime;
};

typedef struct node {
    struct CRC_INDICATION_PDU_T *data;
    struct node *next;
    pthread_mutex_t mutex;
} Node;

Node* head = NULL;
pthread_mutex_t headMutex = PTHREAD_MUTEX_INITIALIZER;
unsigned long long activeCount = 0;
unsigned long long crcFlagSum = 0;
constexpr unsigned int EXPIRATION_MINUTES = 5;
constexpr unsigned int HISTORY_SECONDS = 60;
std::chrono::system_clock::time_point historyStart = std::chrono::system_clock::now();
mqd_t mqdescr;

void initQueue() {
    mqdescr = mq_open("/crc_indication_pdu_queue", O_RDWR | O_CREAT, 0644, NULL);
}

Node* createNode(const NFAPI_CRC_INDICATION_PDU_T *header, const RX_UE_INFORMATION_TAG *rxiTag, const RNTI *rnti) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->data = (struct CRC_INDICATION_PDU_T*)malloc(sizeof(struct CRC_INDICATION_PDU_T));
    newNode->next = NULL;

    pthread_mutex_init(&newNode->mutex, nullptr);

    newNode->data->header = *header;
    newNode->data->rxiTag = *rxiTag;
    newNode->data->rnti = *rnti;
    newNode->data->crcIndTag.crcFlag = rand() % 2;
    time_t now = time(nullptr);
    newNode->data->expirationTime = now + EXPIRATION_MINUTES * 60;

    return newNode;
}

void insertNode(Node* node) {
    pthread_mutex_lock(&headMutex);
    Node *temp = head;
    if (temp == NULL) {
        head = node;
    } else {
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = node;
    }
    pthread_mutex_unlock(&headMutex);
}

void validateAndRemoveExpired() {
    pthread_mutex_lock(&headMutex);
    Node *current = head;
    Node *nextNode;
    time_t now = time(nullptr);

    while (current != NULL) {
        if (now > current->data->expirationTime) {
            nextNode = current->next;

            activeCount--;
            crcFlagSum -= current->data->crcIndTag.crcFlag;

            free(current->data);
            free(current);

            current = nextNode;
        } else {
            break;
        }
        current = nextNode;
    }

    pthread_mutex_unlock(&headMutex);
}

unsigned long long getActiveCount() {
    return activeCount;
}

unsigned int getAverageCRCFlag() {
    std::chrono::system_clock::time_point currentTime = std::chrono::system_clock::now();
    std::chrono::seconds delta = std::chrono::duration_cast<std::chrono::seconds>(currentTime - historyStart);
    if (delta.count() < HISTORY_SECONDS) return 0;

    unsigned long long crcFlagSumDelta = crcFlagSum - getAverageCRCFlag();
    double seconds = static_cast<double>(delta.count()) / HISTORY_SECONDS;

    return crcFlagSumDelta / seconds;
}

void processRNTI(const RNTI *rnti) {
    pthread_mutex_lock(&headMutex);
    Node *current = head;
    bool isDuplicate = false;

    while (current != NULL) {
        if (current->data->rnti.val == rnti->val) {
            isDuplicate = true;
            break;
        }
        current = current->next;
    }

    if (!isDuplicate) {
        Node *newNode = createNode(header, rxiTag, rnti);
        insertNode(newNode);
        activeCount++;
        crcFlagSum += newNode->data->crcIndTag.crcFlag;

        mq_message_t msg;
        msg.mtype = 0;
        strcpy(msg.mtext, "New RNTI added: ");
        strcat(msg.mtext, std::to_string(rnti->val).c_str());
        mq_send(mqdescr, &msg, strlen(msg.mtext) + 1, 0);
    }

    pthread_mutex_unlock(&headMutex);
}

void cleanup() {
    pthread_mutex_destroy(&headMutex);
    mq_close(mqdescr);
    mq_unlink("/crc_indication_pdu_queue");
}
```

