typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef int (*compare_func)(const void *, const void *);

struct cache {
    size_t capacity;
    size_t num_elements;
    NFAPI_CRC_INDICATION_PDU_T **data;
    compare_func comparator;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    bool use_linked_list; // Configuration parameter for allocation strategy
};

void init_cache(struct cache *c, size_t capacity, compare_func comparator, bool use_linked_list) {
    c->capacity = capacity;
    c->num_elements = 0;
    c->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    c->comparator = comparator;
    c->use_linked_list = use_linked_list;
    pthread_mutex_init(&c->mutex, NULL);
    pthread_cond_init(&c->not_full, NULL);
    pthread_cond_init(&c->not_empty, NULL);
}

void push(struct cache *c, const NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&c->mutex);
    if (c->num_elements == c->capacity) {
        // Cache is full; wait for notifications or expand cache.
        pthread_cond_wait(&c->not_full, &c->mutex);
    }

    size_t index = c->num_elements % c->capacity;
    if (c->use_linked_list) {
        // Use linked list when capacity is exceeded.
        item->rnti = index; // Assign RNTI based on the current position in the cache.
        item->crc_indication.CRCFLAG = rand(); // Randomly set CRCFLAG.
    } else {
        // Check for duplicate RNTIs in the cache.
        size_t i;
        for (i = 0; i < c->num_elements; ++i) {
            if (c->comparator(item, c->data[i])) break;
        }
        if (i == c->num_elements) {
            // No duplicate found; add the item.
            c->data[index] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            *c->data[index] = *item;
            ++c->num_elements;
        } else {
            // Duplicate found; log an error and skip.
            fprintf(stderr, "Duplicate RNTI found: %u\n", item->rnti);
        }
    }

    pthread_mutex_unlock(&c->mutex);
    pthread_cond_signal(&c->not_empty);
}

NFAPI_CRC_INDICATION_PDU_T* pop(struct cache *c, RNTI rnti) {
    pthread_mutex_lock(&c->mutex);
    if (c->num_elements == 0) {
        // Cache is empty; wait for notifications or expand cache.
        pthread_cond_wait(&c->not_empty, &c->mutex);
    }

    size_t index = rnti % c->capacity;
    if (c->use_linked_list) {
        // Return the item from its position in the cache.
        NFAPI_CRC_INDICATION_PDU_T *item = c->data[index];
        c->data[index] = NULL; // Mark the position as empty.
        --c->num_elements;
        return item;
    } else {
        size_t i;
        for (i = 0; i < c->num_elements; ++i) {
            if (c->data[i] && c->comparator(c->data[i], &rnti)) break;
        }
        if (i == c->num_elements) {
            // RNTI not found in the cache.
            fprintf(stderr, "RNTI not found: %u\n", rnti);
            return NULL;
        } else {
            // Return the item and mark the position as empty.
            NFAPI_CRC_INDICATION_PDU_T *item = c->data[i];
            c->data[i] = NULL;
            memmove(c->data + i, c->data + (i + 1), (c->num_elements - (i + 1)) * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
            --c->num_elements;
            return item;
        }
    }
}
