typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node* head = NULL;
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

void init_list() {
    if (head != NULL) return;
    head = malloc(sizeof(Node));
    if (!head) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    head->next = NULL;
