}

void add_entry(const NFAPI_CRC_INDICATION_PDU_T* entry) {
    Node *new_node, *current;

    init_list();

    new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = *entry;
    new_node->next = NULL;
    new_node->lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&array_lock);
    current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    pthread_mutex_unlock(&array_lock);
}

void remove_entry(uint16_t rnti) {
    Node *prev, *current;

    pthread_mutex_lock(&array_lock);
    prev = NULL;
    current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&array_lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&array_lock);
}

void update_crcflags() {
    Node *current;
    time_t seconds = time(NULL);

    pthread_mutex_lock(&array_lock);
    current = head;
    while (current != NULL) {
        if ((seconds - current->data.RX_UE_INFORMATION_TAG) > 5) { // Update CRC flag if more than 5 seconds have passed since last update
            current->data.CRCFLAG = !current->data.CRCFLAG;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array_lock);
}
