// Custom smart pointer for managing memory efficiently
template<typename T>
class managed_ptr {
public:
    managed_ptr(T* p = nullptr) : ptr_(p) {}

    managed_ptr(managed_ptr&& other) noexcept : ptr_(other.ptr_) {
        other.ptr_ = nullptr;
    }

    managed_ptr& operator=(managed_ptr&& other) noexcept {
        if (this != &other) {
            reset();
            swap(other);
        }
        return *this;
    }

    ~managed_ptr() {
        if (ptr_) {
            delete ptr_;
        }
    }

    T& operator*() const {
        return *ptr_;
    }

    T* operator->() const {
        return ptr_;
    }

    explicit operator bool() const {
        return static_cast<bool>(ptr_);
    }

    void reset() {
        if (ptr_) {
            delete ptr_;
            ptr_ = nullptr;
        }
    }

private:
    T* ptr_;

    friend void swap(managed_ptr&, managed_ptr&);

    void swap(managed_ptr& other) noexcept {
        std::swap(ptr_, other.ptr_);
    }
};

