    size_t size;
    size_t head, tail;
} Queue;

Queue packet_queue;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
sem_t queue_notempty;

// Worker thread function
void* worker(void* arg) {
    (void)arg;
    while (true) {
        DataPacket* packet;

        sem_wait(&queue_notempty);
        pthread_mutex_lock(&queue_lock);

        if (packet_queue.head == packet_queue.tail) {
            pthread_mutex_unlock(&queue_lock);
            break;
        }

        packet = &packet_queue.packets[packet_queue.head];
        packet_queue.head = (packet_queue.head + 1) % packet_queue.size;
        pthread_mutex_unlock(&queue_lock);

        // Process packet here
        // ...

    }

    free(packet);
    return NULL;
}

void add_packet_to_queue(DataPacket* packet) {
    pthread_mutex_lock(&queue_lock);

    if ((packet_queue.head + 1) % packet_queue.size == packet_queue.tail) {
        if (packet_queue.size < 1024)
            packet_queue.size *= 2;
        DataPacket* new_packets = realloc(packet_queue.packets, sizeof(DataPacket) * packet_queue.size);
        if (!new_packets) {
            pthread_mutex_unlock(&queue_lock);
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        packet_queue.packets = new_packets;
    }

    packet_queue.packets[packet_queue.tail] = *packet;
    packet_queue.tail = (packet_queue.tail + 1) % packet_queue.size;
    sem_post(&queue_notempty);
    pthread_mutex_unlock(&queue_lock);
}

int main() {
    // Initialize queue and semaphore
    packet_queue.packets = malloc(sizeof(DataPacket));
    packet_queue.size = 1;
    packet_queue.head = packet_queue.tail = 0;
    sem_init(&queue_notempty, 0, 0);

    // Create and start worker threads
    pthread_t workers[16];
    for (int i = 0; i < 16; ++i)
        pthread_create(&workers[i], NULL, worker, NULL);

    // Add packets to the queue and monitor performance
    ...

    // Graceful shutdown
    for (int i = 0; i < 16; ++i)
        pthread_join(workers[i], NULL);

    free(packet_queue.packets);
    sem_destroy(&queue_notempty);

    return 0;
}
