typedef struct NetworkEntity {
    int id;
    char params[1024];
} NetworkEntity;

struct BufferNode {
    NetworkEntity entity;
    struct BufferNode *next;
};

struct ConfigData {
    NetworkEntity* entities;
    size_t capacity;
    size_t size;
    sem_t mutex;
    struct BufferNode* bufferHead;
    struct BufferNode* bufferTail;
};

sem_t fileSemaphore;

void* loadConfigFile(const char* path, ConfigData* data) {
    FILE* file = fopen(path, "r");

    if (!file) return 1;

    sem_wait(&fileSemaphore);

    NetworkEntity entity;
    size_t count = 0;

    while (fscanf(file, "%d%*[^,],%s\n", &entity.id, entity.params) == 2) {
        if (!data->entities) {
            data->capacity = 1024;
            data->entities = malloc(sizeof(NetworkEntity) * data->capacity);
        }

        if (count >= data->size) {
            data->capacity *= 2;
            data->entities = realloc(data->entities, sizeof(NetworkEntity) * data->capacity);
        }

        strcpy(data->entities[count].params, entity.params);
        data->entities[count].id = entity.id;
        count++;
    }

    fclose(file);
    sem_post(&fileSemaphore);

    return 0;
}

void initConfigData(ConfigData* data) {
    data->capacity = 1024;
    data->size = 0;
    data->entities = malloc(sizeof(NetworkEntity) * data->capacity);
    sem_init(&data->mutex, 0, 1);

    data->bufferHead = NULL;
    data->bufferTail = NULL;
}

void addToBuffer(struct ConfigData* data, NetworkEntity entity) {
    struct BufferNode *node = malloc(sizeof(struct BufferNode));
    node->entity = entity;
    node->next = NULL;

    if (!data->bufferHead) {
        data->bufferHead = node;
        data->bufferTail = node;
    } else {
        data->bufferTail->next = node;
        data->bufferTail = node;
    }
}

void cleanBuffer(struct ConfigData* data) {
    struct BufferNode *temp, *current = data->bufferHead;

    while (current != NULL) {
        temp = current;
        current = current->next;

        free(temp);
    }

    data->bufferHead = NULL;
    data->bufferTail = NULL;
}

NetworkEntity* getFromBuffer(struct ConfigData* data, int id) {
    struct BufferNode *current = data->bufferHead;

    while (current != NULL) {
        if (current->entity.id == id) {
            void* bufferPtr = mmap(NULL, sizeof(NetworkEntity), PROT_READ | PROT_WRITE, MAP_PRIVATE, fileno(memfd_create("/dev/zero", 0)), 0);
            memcpy(bufferPtr, &current->entity, sizeof(NetworkEntity));
            munmap(bufferPtr, sizeof(NetworkEntity));

            cleanBuffer(data);
            return &current->entity;
        }

        current = current->next;
    }

    return NULL;
}

// API interface function for processing NetworkEntities
void processEntity(NetworkEntity* entity) {
    // Process the NetworkEntity here using your existing system's API
}

int loadConfig(const char* path, ConfigData* data, int bufferSize) {
    sem_init(&fileSemaphore, 0, 1);

    pthread_t loaderThread;
    void* loaderResult = pthread_create(&loaderThread, NULL, loadConfigFile, path, data);

    if (loaderResult != 0) return 1;

    NetworkEntity* entities = data->entities;
    size_t totalCount = 0;

    sem_wait(&data->mutex);

    struct BufferNode *current = data->bufferHead;

    while (current != NULL) {
        processEntity(&current->entity);
        totalCount++;

        cleanBuffer(data);
        current = data->bufferHead;
    }

    sem_post(&data->mutex);

    pthread_join(loaderThread, NULL);

    free(entities);

    return totalCount;
}
