#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct NetworkEntity {
    char id[32];
    void* params;
    pthread_mutex_t lock;
} NetworkEntity;

typedef struct ConfigBundle {
    size_t count;
    NetworkEntity** entities;
    pthread_mutex_t lock;
} ConfigBundle;

ConfigBundle* load_config(const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (!file) return NULL;

    ConfigBundle* bundle = mmap(NULL, sizeof(ConfigBundle), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!bundle) {
        fclose(file);
        return NULL;
    }

    bundle->lock = PTHREAD_MUTEX_INITIALIZER;
    bundle->count = 0;
    bundle->entities = NULL;

    char line[512];
    bool in_id = false, in_params = false;
    NetworkEntity* current_entity = NULL;

    while (fgets(line, sizeof(line), file)) {
        size_t len = strlen(line);
        if (len == 0 || line[len - 1] == '\n') continue;

        if (!in_id && line[0] != '#') {
            in_id = true;
            strncpy(current_entity = malloc(sizeof(NetworkEntity)), line, len);
            current_entity->params = NULL;
            current_entity->lock = PTHREAD_MUTEX_INITIALIZER;
            continue;
        }

        if (in_id) {
            if (!in_params && line[0] != '\n') in_params = true;
            if (in_params) {
                current_entity->params = malloc(len - strlen("params: ") + 1);
                strncpy(current_entity->params, &line[6], len - strlen("params: "));
                in_params = false;
            }
        }

        if (!in_id && !feof(file)) {
            fprintf(stderr, "Invalid configuration format\n");
            break;
        }

        if (in_id) {
            bundle->entities = realloc(bundle->entities, sizeof(NetworkEntity*) * ++(bundle->count));
            bundle->entities[bundle->count - 1] = current_entity;
            in_id = false;
        }
    }

    fclose(file);
    mprotect(bundle, sizeof(ConfigBundle), PROT_READ);

    return bundle;
}
