#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    int value;
    char status;
};

struct HashNode {
    struct Record record;
    struct HashNode *next;
};

struct HashTable {
    struct HashNode **table;
    unsigned long size;
    unsigned long count;
    pthread_mutex_t mutex;
};

void initHashTable(struct HashTable* table, unsigned long size) {
    table->size = size;
    table->count = 0;
    table->table = calloc(size, sizeof(struct HashNode *));
    pthread_mutex_init(&table->mutex, NULL);
}

unsigned long hashFunction(const void* key, unsigned long tableSize) {
    const unsigned long a = 61;
    const unsigned long b = 377;
    const unsigned long c = 429;

    unsigned long h = (a * ((key[0] << 16) ^ key[0] + (key[1] << 8) ^ key[1]) + c) % tableSize;

    return h < 0 ? -h : h;
}

void resizeHashTable(struct HashTable* table, unsigned long newSize) {
    struct HashNode **oldTable = table->table;
    table->table = calloc(newSize, sizeof(struct HashNode *));

    pthread_mutex_lock(&table->mutex);
    for (unsigned long i = 0; i < oldTableSize; ++i) {
        struct HashNode *node = oldTable[i];
        while (node != NULL) {
            struct HashNode *next = node->next;
            unsigned long h = hashFunction(&node->record.value, newSize);
            node->next = table->table[h];
            table->table[h] = node;
            node = next;
        }
    }
    free(oldTable);
    table->size = newSize;
    pthread_mutex_unlock(&table->mutex);
}

bool insertRecord(struct HashTable* table, const struct Record* record) {
    unsigned long h = hashFunction(&record->value, table->size);
    pthread_mutex_lock(&table->mutex);
    struct HashNode *node = table->table[h];
    while (node != NULL && node->record.value == record->value) {
        node = node->next;
    }

    if (node == NULL) {
        node = malloc(sizeof(struct HashNode));
        if (node == NULL) {
            pthread_mutex_unlock(&table->mutex);
            return false;
        }

        node->record = *record;
        node->next = table->table[h];
        table->table[h] = node;
        ++(table->count);
    }

    pthread_mutex_unlock(&table->mutex);
    return true;
}

bool deleteRecord(struct HashTable* table, const struct Record* record) {
    unsigned long h = hashFunction(&record->value, table->size);
    pthread_mutex_lock(&table->mutex);
    struct HashNode *prev = NULL, *node = table->table[h];

    while (node != NULL && node->record.value != record->value) {
        prev = node;
        node = node->next;
    }

    if (node == NULL) {
        pthread_mutex_unlock(&table->mutex);
        return false;
    }

    if (prev == NULL) {
        table->table[h] = node->next;
    } else {
        prev->next = node->next;
    }

    free(node);
    --(table->count);
    pthread_mutex_unlock(&table->mutex);
    return true;
}

struct Record* findRecord(const struct HashTable* table, const struct Record* record) {
    unsigned long h = hashFunction(&record->value, table->size);
    struct HashNode *node = table->table[h];

    while (node != NULL && node->record.value != record->value) {
        node = node->next;
    }

    return node != NULL ? &node->record : NULL;
