            pthread_mutex_unlock(&ctx->mutex);
            return false;
        }
        memmove(new_data, ctx->data, ctx->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        munmap(ctx->data, ctx->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
