```cpp
#include <iostream>
#include <map>
#include <memory>
#include <vector>
#include <boost/asio.hpp>
#include <boost/date_time/posix_time/ptime.hpp>
#include <boost/optional.hpp>

namespace ns = boost::asio;
using boost::posix_time::ptime;
using boost::optional<ptime>;

struct Session {
    std::string clientIP;
    uint16_t port;
    ptime timestamp;
    std::string sessionID;
    optional<ptime> timeout; // optional timeout, if not set, no timeout
};

class NetworkServer {
public:
    explicit NetworkServer(size_t maxSessionCount) : maxSessionCount_(maxSessionCount) {}

    void start() {
        ioService_.run();
    }

private:
    void handleAccept(ns::ip::tcp::socket socket, const ns::ip::tcp::endpoint& endpoint) {
        auto it = find_if(sessions_.begin(), sessions_.end(),
            [&](const std::unique_ptr<Session>& session) { return !session->timeout.has_value(); });

        if (it != sessions_.end()) { // If there's an idle session, replace it
            *it = createSession(socket, endpoint);
            return;
        }

        // Otherwise, add a new session with timeout and remove the least recent session when it times out.
        auto session = createSession(socket, endpoint);
        sessions_.emplace_back(std::move(session));

        if (sessions_.size() > maxSessionCount_) {
            auto it = sessions_.begin();
            std::advance(it, 1); // Skip the new session we just added.
            it->reset(new Session()); // Clear the session to be removed next timeout.
        }
    }

    void manageTimeouts() {
        auto now = ns::microsec_clock::local_time();

        sessions_.erase(std::remove_if(sessions_.begin(), sessions_.end(),
            [&](const std::unique_ptr<Session>& session) {
                if (session->timeout && *session->timeout < now) {
                    return true;
                }
                return false;
            }), sessions_.end());
    }

