    mapped_config_file = mmap(NULL, strlen(cfg_file), PROT_READ, MAP_PRIVATE, open(cfg_file, O_RDONLY), 0);
    if (mapped_config_file == MAP_FAILED) {
        perror("mmap");
        err = LTE_PHY_CFG_FILE_ERROR;
        goto cleanup;
    }

    // Set callback function for external data source
    ext_data_cb = cb;

    // Initialize the thread-safe configuration storage
