        err = LTE_PHY_CONFIG_INCONSISTENCY;
    }

cleanup:
    if (mapped_config_file != NULL) {
        munmap(mapped_config_file, strlen(cfg_file));
    }
    return err;
}

void update_lte_phy_config() {
    void* updated_data = NULL;
    if (ext_data_cb != NULL && ext_data_cb((char*)config_storage, &updated_data) == LTE_PHY_SUCCESS) {
        pthread_mutex_lock(&config_storage_lock);
        free(config_storage);
        config_storage = updated_data;
        pthread_mutex_unlock(&config_storage_lock);
    }
}

lte_phy_cpdus_t* get_lte_phy_config() {
