    size_t num_configs = 0;
    pthread_mutex_lock(&config_storage_lock);
    if (config_storage != NULL) {
        num_configs = *(size_t*)config_storage;
        configs = (lte_phy_cpdus_t*)((char*)config_storage + sizeof(size_t));
    }
    pthread_mutex_unlock(&config_storage_lock);
    return configs;
}
