    DBConnection *conn = malloc(sizeof(DBConnection));
    conn->db = NULL;
    conn->mutex = PTHREAD_MUTEX_INITIALIZER;

    if (sqlite3_open_v2(config->db_path, &db, SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE, NULL) != SQLITE_OK) {
