        if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
            pthread_mutex_unlock(&conn->mutex);
            sqlite3_finalize(stmt);
            return 2;
        }

        if (sqlite3_step(stmt) == SQLITE_ROW) {
            int rnti = sqlite3_column_int(stmt, 0);
            pdu_list[i].rnti = rnti;
            pdu_list[i].crc_flag = (CRCFlag)(rand() % 2);
            pdu_list[i].rx_ue_information_tag = rand() % 65535;
            pdu_list[i].crc_indication_rel8_tag = rand() % 65535;
        } else {
            sqlite3_finalize(stmt);
            return 3; // UE info not found
        }
    }

    snprintf(sql, sizeof(sql), "BEGIN TRANSACTION");
    if (sqlite3_exec(db, sql, NULL, NULL, NULL) != SQLITE_OK) {
        pthread_mutex_unlock(&conn->mutex);
        return 4; // transaction failure
    }

    for (int i = 0; i < N; ++i) {
        snprintf(sql, sizeof(sql), "INSERT INTO crc_indications VALUES(%d, %d, %d, %d)", pdu_list[i].rnti, pdu_list[i].crc_flag, pdu_list[i].rx_ue_information_tag, pdu_list[i].crc_indication_rel8_tag);
        if (sqlite3_exec(db, sql, NULL, NULL, NULL) != SQLITE_OK) {
            int error = sqlite3_errcode(db);
            if (error == SQLITE_BUSY || error == SQLITE_LOCKED) {
                // handle retry logic with exponential backoff here
            } else {
                pthread_mutex_unlock(&conn->mutex);
                return 4; // insert failure
            }
        }
    }

    snprintf(sql, sizeof(sql), "COMMIT TRANSACTION");
    if (sqlite3_exec(db, sql, NULL, NULL, NULL) != SQLITE_OK) {
        pthread_mutex_unlock(&conn->mutex);
        return 4; // commit failure
    }

    sqlite3_finalize(stmt);
    pthread_mutex_unlock(&conn->mutex);
    sqlite3_close(db);
    free(pdu_list);
    free(conn);

    return 0; // success
}
