node_t* create_node(RX_UE_INFORMATION_TAG rx_ue, uint32_t rnti) {
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    if (!new_node) return NULL;

    new_node->rx_ue_information = rx_ue;
    new_node->rnti = rnti;
    new_node->crc_indication.crcflag = generate_crcflag();
    new_node->next = NULL;

    return new_node;
