void insert_node(node_t *new_node) {
    pthread_rwlock_wrlock(&rwlock);
    if (head == NULL) {
        head = new_node;
    } else {
        node_t *current = head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    }
    num_nodes++;
    pthread_rwlock_unlock(&rwlock);
}

void remove_node(uint32_t rnti) {
    node_t *current, *temp;

    pthread_rwlock_wrlock(&rwlock);
    current = head;

    if (head->rnti == rnti) {
        temp = head;
        head = head->next;
        num_nodes--;
        free(temp);
    } else {
        while (current->next != NULL && current->next->rnti != rnti) {
            current = current->next;
        }

        if (current->next == NULL) return;

        temp = current->next;
        current->next = current->next->next;
        num_nodes--;
        free(temp);
    }

    pthread_rwlock_unlock(&rwlock);
}

