typedef struct _HASH_TABLE {
    unsigned int capacity;
    unsigned int size;
    NFAPI_CRC_INDICATION_PDU_T **table;
    pthread_mutex_t mutex;
} HASH_TABLE;

void init_hash_table(HASH_TABLE *ht, unsigned int capacity) {
    ht->capacity = capacity;
    ht->size = 0;
    ht->table = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_init(&ht->mutex, NULL);
}

unsigned int hash(const unsigned int rnti) {
    return rnti % ht->capacity;
}

void insert(HASH_TABLE *ht, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&ht->mutex);
    unsigned int index = hash(entry->rnti);
    NFAPI_CRC_INDICATION_PDU_T *current = ht->table[index];
    if (!current) {
        ht->table[index] = entry;
        ++ht->size;
