typedef struct {
    int rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    const char *db_path;
    const char *username;
    const char *password;
    int retry_limit;
    long backoff_interval;
} config_t;

int createNfadbPduList(int N, sqlite3 *conn, config_t *config) {
    sqlite3_stmt *stmt;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    int i, retry = 0;

    for (i = 0; i < N; ++i) {
        pdu_list[i].rnti = rand();
        pdu_list[i].crc_indication_rel8_tag = rand() % 256;
        pdu_list[i].crcflag = (rand() % 2) == 0 ? 1 : 0;

        if (!validatePdu(&pdu_list[i])) {
            continue;
        }

        if (sqlite3_prepare_v2(conn, "INSERT INTO crc_indications VALUES (?, ?, ?)", -1, &stmt, NULL) != SQLITE_OK) {
            if (++retry < config->retry_limit && (time(NULL) - last_failure_time > config->backoff_interval)) {
                fprintf(stderr, "Database connection failure. Retrying...\n");
                sleep(config->backoff_interval * retry);
                continue;
            }
            return 1; // Failure
        }

        sqlite3_bind_int(stmt, 1, pdu_list[i].rnti);
        sqlite3_bind_int(stmt, 2, pdu_list[i].crc_indication_rel8_tag);
        sqlite3_bind_int(stmt, 3, pdu_list[i].crcflag);

        if (sqlite3_step(stmt) != SQLITE_DONE) {
            if (++retry < config->retry_limit && (time(NULL) - last_failure_time > config->backoff_interval)) {
                fprintf(stderr, "Database insertion failure. Retrying...\n");
                sleep(config->backoff_interval * retry);
                sqlite3_finalize(stmt);
                continue;
            }
            return 1; // Failure
        }

        sqlite3_finalize(stmt);
    }

    free(pdu_list);
    return 0; // Success
}

int validatePdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu || (pdu->rnti == 0 || pdu->crc_indication_rel8_tag < 0 || pdu->crc_indication_rel8_tag > 255)) {
        return 0;
    }
    return 1;
}
