class SinglyLinkedList {
public:
    void insert(const NFAPI_CRC_INDICATION_PDU_T& node) {
        auto newNode = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(node);
        if (!head.load()) {
            head.store(newNode.get());
            tail.store(newNode.get());
        } else {
            newNode->prev = tail.load();
            newNode->next = nullptr;
            tail->next = newNode.get();
            tail.store(newNode.release());
        }
