            if (head.load() == tail.load()) tail.store(nullptr);
        } else if (nodeToRemove == tail.load()) {
            tail.store(nodeToRemove->prev);
        } else {
            nodeToRemove->prev->next = nodeToRemove->next;
            if (nodeToRemove->next) nodeToRemove->next->prev = nodeToRemove->prev;
