```python
import os
import json
import subprocess
from cryptography.fernet import Fernet

# Placeholders and encrypted password in the configuration file
PLACEHOLDERS = {'username': 'USERNAME', 'password': 'PASSWORD'}
KEY_FILE = 'key.txt'

def load_key():
    with open(KEY_FILE, 'rb') as key_file:
        key = Fernet.generate_key()
    return key

def encrypt_password(password):
    key = load_key()
    fernet = Fernet(key)
    return fernet.encrypt(password.encode()).decode()

def replace_placeholders(config, replacements):
    for key, value in replacements.items():
        config = config.replace(value, key)
    return config

def run_command(cmd):
    process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
    output, error = process.communicate()

    if error:
        print(f"Error while executing command:\n{error.decode()}")
        return False

    print(output.decode())
    return True

def update_config():
    with open('config.txt', 'r') as config_file:
        config = config_file.read()

    updated_config = replace_placeholders(config, PLACEHOLDERS)
    encrypted_password = encrypt_password('NEW_PASSWORD')
    updated_config += f'\n\n{encrypted_password}'

    with open('config.txt', 'w') as config_file:
        config_file.write(updated_config)

    return run_command("sed -i 's/\\(password=.*\\)/\\1NEW_PASSWORD/' config.txt")
