void dyn_array_init(DynArray* da) {
    da->data = NULL;
    da->capacity = 0;
    da->length = 0;
    sem_init(&da->mutex, 0, 1);
}

void dyn_array_destroy(DynArray* da) {
    if (da->data != NULL) {
        free(da->data);
    }
    sem_destroy(&da->mutex);
}

