    if (da->length >= da->capacity) {
        resize_array(da, da->capacity * 2);
    }
    memcpy((void*)(da->data + da->length), &tf, sizeof(TrafficFlow));
    da->length++;
    sem_post(&da->mutex);
}

// Update an existing flow based on flowID, handling potential out-of-bounds errors
void dyn_array_update(DynArray* da, int flowID, TrafficFlow tf) {
    sem_wait(&da->mutex);
    for (size_t i = 0; i < da->length; ++i) {
        if (da->data[i].flowID == flowID) {
            memcpy((void*)&da->data[i], &tf, sizeof(TrafficFlow));
            break;
        }
    }
    sem_post(&da->mutex);
}

// Retrieve the total packet count and byte count for all flows combined
int dyn_array_total_packet_count(DynArray* da) {
    int total = 0;
    sem_wait(&da->mutex);
    for (size_t i = 0; i < da->length; ++i) {
        total += da->data[i].packetCount;
    }
    sem_post(&da->mutex);
    return total;
}

// Flush the dynamic array to the logging framework, handling potential resource constraints
void dyn_array_flush(DynArray* da) {
    // Add your resource management logic here
