    struct collection* coll = mmap(NULL, sizeof(struct collection), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (coll == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    coll->size = 0;
    coll->capacity = capacity;
    coll->table = calloc(capacity, sizeof(Node*));
    if (!coll->table) {
        perror("calloc");
        munmap(coll, sizeof(struct collection));
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&coll->lock, NULL);

    return coll;
}

void destroy_collection(struct collection* coll) {
    for (unsigned int i = 0; i < coll->capacity; ++i) {
        Node* node = coll->table[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(coll->table);
    pthread_mutex_destroy(&coll->lock);
    munmap(coll, sizeof(struct collection));
}

void add_entry(struct collection* coll, const NFAPI_CRC_INDICATION_PDU& entry) {
    unsigned int index = hash(entry.rnti) % coll->capacity;

    pthread_mutex_lock(&coll->lock);
    Node* new_node = (Node*)calloc(1, sizeof(Node));
    if (!new_node) {
        perror("calloc");
        pthread_mutex_unlock(&coll->lock);
        return;
    }

    new_node->element = entry;
    new_node->next = coll->table[index];
    coll->table[index] = new_node;
    ++coll->size;
    pthread_mutex_unlock(&coll->lock);
}

void remove_entry(struct collection* coll, uint64_t rnti) {
    unsigned int index = hash(rnti) % coll->capacity;

    pthread_mutex_lock(&coll->lock);
    Node** current = &coll->table[index];
    while (*current != NULL && (*current)->element.rnti != rnti) {
        current = &(*current)->next;
    }

    if (*current == NULL) {
        pthread_mutex_unlock(&coll->lock);
        return;
    }

    Node* temp = *current;
    *current = temp->next;
    free(temp);
    --coll->size;
    pthread_mutex_unlock(&coll->lock);
}

void iterate_entries(const struct collection* coll, void (*print_entry)(const NFAPI_CRC_INDICATION_PDU&)) {
    pthread_mutex_lock(&coll->lock);
    for (unsigned int i = 0; i < coll->capacity; ++i) {
        Node* node = coll->table[i];
        while (node != NULL) {
            print_entry(node->element);
            node = node->next;
        }
    }
    pthread_mutex_unlock(&coll->lock);
}

void* serialize(const struct collection* coll, void* buffer, size_t buffer_size) {
    // Implement serialization logic here...
}

void* deserialize(struct collection* coll, const void* buffer, size_t buffer_size) {
