    NFAPI_CELL_INFO_PDU_T data;
    struct list_node *next;
};

struct dynamic_list {
    struct list_node **nodes;
    int capacity;
    int size;
    pthread_mutex_t lock;
    bool validation_enabled;
};

void dynamic_list_init(struct dynamic_list *list, int initial_capacity, bool enable_validation) {
    list->nodes = calloc(initial_capacity, sizeof(struct list_node*));
    if (!list->nodes) {
        fprintf(stderr, "Failed to allocate memory for dynamic list.\n");
        return;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->validation_enabled = enable_validation;
}

void dynamic_list_destroy(struct dynamic_list *list) {
    for (int i = 0; i < list->capacity; ++i) {
        struct list_node *current = list->nodes[i];
        while (current != NULL) {
            struct list_node *next = current->next;
            free(current);
            current = next;
        }
    }

    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
}

void dynamic_list_insert(struct dynamic_list *list, const NFAPI_CELL_INFO_PDU_T *data) {
    pthread_mutex_lock(&list->lock);

    // Implement a validation strategy here if needed

    int index = (size_t)(data->CELL_ID % list->capacity);
    struct list_node **current = &list->nodes[index];
    struct list_node *new_node = malloc(sizeof(struct list_node));

    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new list node.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = *data;
    new_node->next = *current;
    *current = new_node;
    ++list->size;

    if (list->size >= list->capacity * 0.75) {
        int new_capacity = list->capacity * 2;
        struct list_node **new_nodes = realloc(list->nodes, sizeof(struct list_node*) * new_capacity);

        if (!new_nodes) {
            fprintf(stderr, "Failed to reallocate memory for dynamic list.\n");
            free(new_node);
            pthread_mutex_unlock(&list->lock);
            return;
        }

        list->nodes = new_nodes;
        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_remove(struct dynamic_list *list, int CELL_ID) {
    pthread_mutex_lock(&list->lock);

    int index = (size_t)(CELL_ID % list->capacity);
    struct list_node **current = &list->nodes[index];
    struct list_node *prev = NULL;

    while (*current != NULL && ((*current)->data.CELL_ID != CELL_ID)) {
        prev = current;
        current = &((*current)->next);
    }

    if (*current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev != NULL) {
        prev->next = (*current)->next;
    } else {
        list->nodes[index] = (*current)->next;
    }

    free(*current);
    --list->size;

    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_log(const struct dynamic_list *list) {
