    printf("# Added: %d\n", list->size);
    printf("# Removed: 0\n"); // Implement tracking of removed entries if needed
    printf("# Updated: 0\n"); // Implement tracking of updated entries if needed
    printf("# Failed allocations: 0\n"); // Implement tracking of failed memory allocation attempts if needed
}
