    strcpy(data->crc_indication_rel8_tag, validateAndAppendSlash("CRC_INDICATION_TAG_" itoa(i+1)));

    pthread_mutex_lock(&lock);
    for (int j = i-1; j >= 0 && list[j] == NULL; --j) {
        if (pthread_tryjoin_np(threads[j], (void**)&list[j])) continue;
        list[j]->rxiid = i + 1;
        memcpy(&list[j]->rx_ue_information_tag, &rx_ue_information_tag, sizeof(char)*256);
        list[j]->rnti = data->rnti;
        list[j]->crcflag = data->crcflag;
        memcpy(&list[j]->crc_indication_rel8_tag, &data->crc_indication_rel8_tag, sizeof(char)*256);
    }
    pthread_mutex_unlock(&lock);
}

char* validateAndAppendSlash(const char *str) {
    if (strlen(str) > 255) return NULL;
    char *result = malloc(strlen(str) + 1);
    strcpy(result, str);
    result[strlen(str)] = '/';
    return result;
}
