// Define structures and tags
typedef struct {
    RX_UE_INFORMATION_TAG rxtag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG ctag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint32_t key;
    NFAPI_CRC_INDICATION_PDU_T value;
} CACHE_ENTRY;

// Cache structure and functions
static inline size_t hash(uint32_t key) {
    return key % CACHE_SIZE;
}

static CACHE_ENTRY* cache = NULL;
static const size_t CACHE_SIZE = 1024;

static bool cache_init = false;
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_cache() {
    if (cache_init) return;
    cache = calloc(CACHE_SIZE, sizeof(CACHE_ENTRY));
    cache_init = true;
}

void free_cache() {
    if (!cache_init) return;
    free(cache);
    cache_init = false;
}

static CACHE_ENTRY* get_cache_entry(uint32_t key) {
    pthread_mutex_lock(&cache_mutex);
    CACHE_ENTRY *entry = &cache[hash(key)];
    if (entry->key == key) {
        pthread_mutex_unlock(&cache_mutex);
        return &entry->value;
    }
    pthread_mutex_unlock(&cache_mutex);
    return NULL;
}

// CRC_INDICATION_REL8_TAG function with pseudo-random CRCFLAG generation
static void generate_ctag(CRC_INDICATION_REL8_TAG *tag, uint32_t seed) {
    tag->CRCFLAG = (seed & 0x80000000) >> 31;
}

// Function to dynamically allocate and populate the array of structures
NFAPI_CRC_INDICATION_PDU_T* create_pdu(size_t N, uint32_t seed) {
    if (N == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdus = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    init_cache();

    for (size_t i = 0; i < N; ++i) {
        uint32_t rnti = (i * seed + 123456789); // Example pseudo-random RNTI generation

        if (rnti >= MAX_RNTI || rnti < MIN_RNTI) {
            fprintf(stderr, "Invalid RNTI value: %u\n", rnti);
            free_cache();
            free(pdus);
            return NULL;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus[i];
        pdu->rxtag.id = RX_UE_INFORMATION_TAG_ID;
        pdu->rnti = rnti;

        CACHE_ENTRY *entry = get_cache_entry(pdu->rnti);
        if (entry) {
            *pdu = *entry;
        } else {
            generate_ctag(&pdu->ctag, seed);
            entry = get_cache_entry(pdu->rnti);
            if (!entry) {
                entry->key = pdu->rnti;
                *entry = *pdu;
            }
        }
    }

    return pdus;
}
