NFAPI_CRC_INDICATION_PDU_T* processRadioIndicationsAndDecrypt(const void* messages, size_t msg_len, const unsigned char* key, const unsigned char* iv, size_t* decrypted_size) {
    size_t num_msgs = msg_len / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(num_msgs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        return NULL;
    }

    memcpy(indications, messages, num_msgs * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    unsigned char* decrypted = malloc(*decrypted_size);
    if (!decrypted) {
        free(indications);
        return NULL;
    }

    AES_KEY aes_key;
    AES_set_encrypt_key((const unsigned char*)key, 128, &aes_key);

    size_t i;
    for (i = 0; i < num_msgs; ++i) {
        const NFAPI_CRC_INDICATION_PDU_T* msg = indications + i;
        if (msg->ue_id == 0 || msg->crc_status > 31) {
            free(indications);
            free(decrypted);
            return NULL;
        }
    }

    AES_cbc_encrypt((const unsigned char*)messages, decrypted, *decrypted_size, &aes_key, iv, AES_ENCRYPT);

    free(indications);
    (*decrypted_size) += sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_msgs;

    return indications;
}
