typedef struct __ue {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    sem_t *mutex;
    uint32_t rnti;
} UE;

UE *ues;
size_t ue_count = 0;
const size_t page_size = sysconf(_SC_PAGE_SIZE);

// Custom allocator for efficient memory management
void* custom_malloc(size_t size) {
    void *ptr = mmap(NULL, size + page_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (ptr == MAP_FAILED)
        return NULL;
    return ptr;
}

// Custom free function for custom allocator
void custom_free(void *ptr) {
    munmap(ptr, page_size + sizeof(ptr));
}

// Synchronization for multi-threading access to ue structures
sem_t pool_mutex;

// Function to initialize the pool of UEs
void init_ue_pool(size_t initial_num_ues) {
    if (initial_num_ues < MIN_UE)
        initial_num_ues = MIN_UE;
    ues = malloc(initial_num_ues * sizeof(UE));
    sem_init(&pool_mutex, 0, 1);

    for (size_t i = 0; i < initial_num_ues; ++i) {
        UE *ue = &ues[i];
        ue->pdu = custom_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ue->mutex = sem_init(sem_t*, 0, 1);
    }
}

// Function to add a new UE to the pool
UE* add_ue() {
    UE *ue;

    if (ue_count == ues) {
        size_t new_size = ue_count * 2 + MIN_UE;
        UE *new_ues = realloc(ues, new_size * sizeof(UE));
        if (!new_ues)
            return NULL;
        ues = new_ues;
    }

    ue = &ues[ue_count++];
    sem_init(ue->mutex, 0, 1);
    ue->pdu = custom_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return ue;
}

// Function to remove a UE from the pool
void remove_ue(UE *ue) {
    sem_destroy(ue->mutex);
    custom_free(ue->pdu);
    --ue_count;
}
