#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define NUM_BUCKETS 1024
#define AGE_THRESHOLD 10 * 60 // 10 minutes in seconds

typedef struct {
    time_t timestamp;
    enum { DEBUG, INFO, WARNING, ERROR } level;
    int id;
    char message[256];
} NFAPI_LOG_PDU_T;

struct log_bucket {
    pthread_mutex_t lock;
    struct list_head entries;
};

struct log_manager {
    struct log_bucket* buckets;
    struct list_head free_list;
    size_t capacity;
    int current_size;
    pthread_mutex_t global_lock;
};

static inline void log_init(struct log_manager *manager) {
    manager->capacity = NUM_BUCKETS;
    manager->buckets = calloc(manager->capacity, sizeof(struct log_bucket));
    manager->current_size = 0;

    pthread_mutex_init(&manager->global_lock, NULL);
    for (int i = 0; i < manager->capacity; ++i) {
        pthread_mutex_init(&manager->buckets[i].lock, NULL);
    }
}

static inline void log_destroy(struct log_manager *manager) {
    for (int i = 0; i < manager->capacity; ++i) {
        pthread_mutex_destroy(&manager->buckets[i].lock);
    }
    free(manager->buckets);
    pthread_mutex_destroy(&manager->global_lock);
}

static inline int hash(const NFAPI_LOG_PDU_T *log) {
    return abs((uint32_t)log->id % manager->capacity);
}

static inline void log_insert(struct log_manager *manager, NFAPI_LOG_PDU_T *log) {
    pthread_mutex_lock(&manager->global_lock);

    int bucket = hash(log);
    struct list_head *list = &manager->buckets[bucket].entries;
    struct list_entry *e;

    list_for_each_entry_reverse(e, list, log) {
        NFAPI_LOG_PDU_T *tmp = container_of(e, typeof(*tmp), entry);
        if (time(NULL) - tmp->timestamp >= AGE_THRESHOLD) {
            list_del_init(e);
            manager->current_size--;
        } else {
            break;
        }
    }

    if (!list->prev) {
        list->next = &manager->buckets[bucket].entries;
        manager->buckets[bucket].entries.prev = NULL;
    } else {
        list_add_tail(&log->entry, list);
    }

    pthread_mutex_unlock(&manager->global_lock);
}

static inline NFAPI_LOG_PDU_T* log_alloc() {
    pthread_mutex_lock(&manager->global_lock);

    struct list_head *free_list = &manager->free_list;
    struct list_entry *e;

    if (!list_empty(free_list)) {
        e = free_list->next;
        list_del_init(e);
    } else {
        if (manager->current_size >= manager->capacity) {
            printf("Log Manager: Out of memory.\n");
            pthread_mutex_unlock(&manager->global_lock);
            return NULL;
        }

        for (int i = 0; i < manager->capacity; ++i) {
            if (!list_empty(&manager->buckets[i].entries)) {
                e = list_entry(manager->buckets[i].entries.next, typeof(*e), entry);
                break;
            }
        }
    }

    NFAPI_LOG_PDU_T *log = container_of(e, typeof(*log), entry);
    memset(log, 0, sizeof(*log));

    pthread_mutex_unlock(&manager->global_lock);
    return log;
}

static inline void log_free(struct log_manager *manager, NFAPI_LOG_PDU_T *log) {
    if (!log) return;

    pthread_mutex_lock(&manager->global_lock);
    manager->current_size++;
    list_add_tail(&log->entry, &manager->free_list);
    pthread_mutex_unlock(&manager->global_lock);
}
```

This code is a basic implementation of a dynamic log manager using a hash table to store the logs. The `log_manager` structure manages a pool of `NFAPI_LOG_PDU_T` structures, which are dynamically allocated and deallocated as needed. Older entries are purged based on an age threshold, and the system supports filtering by log level using the hash function and linear search through the linked list.

The code uses a global mutex to protect access to the shared data structures, but it does not provide comprehensive monitoring or logging capabilities, which should be added for providing insights into memory usage, throughput, and performance bottlenecks as needed. Additionally, consider implementing additional features such as extensibility, handling of different log backends, or strategies to mitigate memory fragmentation.']

