SensorData sensor_data_init(unsigned long id, Timestamp timestamp, SensorReading reading, int quality_score, bool status_flag) {
    if (id < 1 || quality_score < 0 || quality_score > 100 || status_flag != true && status_flag != false) {
        fprintf(stderr, "Error: Invalid sensor data values\n");
        exit(EXIT_FAILURE);
    }

    SensorData sd;
    sd.id = id;
    sd.timestamp = timestamp;
    sd.reading = reading;
    sd.quality_score = quality_score;
    sd.status_flag = status_flag;
    return sd;
}

// Function for adding a sensor data record to the cache, if not already present
SensorData* get_sensor_data(unsigned long id) {
    CacheNode *cur = cache;
    while (cur != NULL) {
        if (cur->data->id == id) {
            return cur->data;
        }
        cur = cur->next;
    }

    // If not found in the cache, allocate new memory and add to the cache
    SensorData* sd = malloc(sizeof(SensorData));
    *sd = (SensorData) { .id = id };

    if (!sd) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }

    CacheNode* new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        free(sd);
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }

    new_node->data = sd;

    if (cache == NULL) {
        cache = new_node;
    } else {
        CacheNode* last = cache;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = new_node;
    }

    return sd;
}
