        if (listSize == 0) {
            insertPos = 0;
        } else if (insertPos >= listSize) {
            insertPos = listSize;
        }
    }

    // Insert the new string element at the optimal position
    auto newIter = ueList.begin();
    std::advance(newIter, insertPos);
