// Define the main data structure as an unordered map, using our custom comparator function and cache blocks for value storage
std::unordered_map<RX_UE_INFORMATION_TAG, std::pair<CacheBlock*, unsigned int>, CompareTagRnti> collection;

// Define atomic counters for unique RX_UE_INFORMATION_TAGs and RTNIs
std::atomic<unsigned int> uniqueTags(0), uniqueRNTIs(0);

// Function to generate a random CRCFLAG value
unsigned short randomCRCFlag() {
    return rand() % 256;
}

// Function to initialize a new NFAPI_CRC_INDICATION_PDU_T with a valid RNTI and randomly set CRCFLAG
NFAPI_CRC_INDICATION_PDU_T generatePDU(unsigned short rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = uniqueTags++;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = randomCRCFlag();
    return pdu;
}

// Function to add a new PDU to the collection, handling external data source failures gracefully and maintaining data integrity
void insertPDU(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Handle failure from external API
    if (!pdu.RNTI) {
        printf("Failed to retrieve RNTI from external API\n");
        return;
    }

    // Find the appropriate cache block and insert the PDU into it
    CacheBlock* block = &collection[pdu.RX_UE_INFORMATION_TAG].first;
    if (block->data.size() >= block->capacity) {
        // If the current block is full, allocate a new one and link them together
        CacheBlock* newBlock = static_cast<CacheBlock*>(malloc(sizeof(CacheBlock)));
        newBlock->capacity = collection.load() / 2 > 15000 ? 15000 : collection.load() / 2;
        newBlock->next = nullptr;
        while (block->next && block->next->data.size() >= block->next->capacity) {
            block = block->next;
        }
        if (!block) {
            // If no suitable block is found, link the new block at the beginning of the list
            newBlock->next = collection.begin()->second.first;
            collection.begin()->second.first = newBlock;
        } else {
            // Otherwise, insert the new block after the current one
            newBlock->next = block->next;
            block->next = newBlock;
        }
    }

    block->data.push_back(pdu);
    uniqueRNTIs++;
}

// Function to remove a PDU from the collection based on a specific RNTI value, maintaining data integrity and returning the removed PDU
NFAPI_CRC_INDICATION_PDU_T deletePDUByRNTI(unsigned short rnti) {
    auto it = collection.find(std::make_pair(RX_UE_INFORMATION_TAG{}, rnti));
    if (it == collection.end()) {
        printf("No PDU found with RNTI %hu\n", rnti);
        return {};
    }

    CacheBlock* block = it->second.first;
    auto itPDU = std::find_if(block->data.begin(), block->data.end(),
                              [rnti](const NFAPI_CRC_INDICATION_PDU_T& pdu) { return pdu.RNTI == rnti; });
    if (itPDU == block->data.end()) {
        printf("No PDU found with RNTI %hu in the current block\n", rnti);
        return {};
    }

    uniqueRNTIs--;
    NFAPI_CRC_INDICATION_PDU_T pdu = std::move(*itPDU);
    block->data.erase(itPDU);
    if (block->data.empty()) {
        CacheBlock* nextBlock = block->next;
        free(block);
        collection.erase(it);
        if (nextBlock) {
            collection[nextBlock->data.front().RX_UE_INFORMATION_TAG].first = nextBlock;
        } else {
            collection.erase(collection.begin());
        }
    }
    return pdu;
}

// Function to retrieve a PDU based on a specific RNTI value, logging the operation and returning the found PDU or an empty one if not found
NFAPI_CRC_INDICATION_PDU_T getPDUByRNTI(unsigned short rnti) {
    auto it = collection.find(std::make_pair(RX_UE_INFORMATION_TAG{}, rnti));
    if (it == collection.end()) {
        printf("No PDU found with RNTI %hu\n", rnti);
        return {};
    }

    for (const auto& pdu : it->second.first->data) {
        if (pdu.RNTI == rnti) {
            printf("Retrieved PDU with RNTI %hu and RX_UE_INFORMATION_TAG %u\n", pdu.RNTI, pdu.RX_UE_INFORMATION_TAG);
            return pdu;
        }
    }

    printf("No PDU with RNTI %hu found in the current block\n", rnti);
    return {};
}

// Function to log and print some statistics about the collection
void printStats() {
    printf("Total PDUs: %zu\n", collection.size());
    printf("Unique RNTIs: %zu\n", uniqueRNTIs);
}

int main() {
    // Initialize the collection with a few generated PDUs and an external one
    insertPDU(generatePDU(1));
    insertPDU(generatePDU(2));
    insertPDU(generatePDU(3));

    NFAPI_CRC_INDICATION_PDU_T pdu = getPDUByRNTI(1);
    printf("Retrieved PDU: RX_UE_INFORMATION_TAG %u, RNTI %hu, CRCFLAG %hhu\n", pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);

    insertPDU(generatePDU(1)); // External API returns the same PDU again

