// Custom hash table structure
typedef struct HashTable {
    unsigned long size;
    unsigned long capacity;
    unsigned long *keys;
    void **values;
    pthread_mutex_t lock;
} HashTable;

// Helper function to handle memory allocation failures
void *safe_malloc(unsigned long size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Helper function to calculate hash key using a divisive hash function
unsigned long hash_key(const void *key, unsigned long capacity) {
    const unsigned char *k = (const unsigned char *) key;
    unsigned long h = 0;
    for (size_t i = 0; i < sizeof(*key); ++i)
        h = ((h << 5) + h) + k[i];
    return h % capacity;
}

// Function to manage the array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* init_array(size_t size) {
