    ht->capacity = 13;
    ht->size = 0;
    ht->keys = safe_malloc(ht->capacity * sizeof(unsigned long));
    ht->values = safe_malloc(ht->capacity * sizeof(void*));
    for (size_t i = 0; i < ht->capacity; ++i) {
        ht->keys[i] = ~0UL; // Using all-ones as a placeholder for empty slots
        ht->values[i] = NULL;
    }
    ht->lock = PTHREAD_MUTEX_INITIALIZER;

    NFAPI_CRC_INDICATION_PDU_T *elements = safe_malloc(size * sizeof(*elements));
