        elements[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        insert(ht, &elements[i]);
    }

    return elements;
}

// Function to insert an element into the hash table based on its RNTI
void insert(HashTable *ht, const void *element) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_key(element->RNTI, ht->capacity);
    for (size_t i = index; ht->keys[index] != ~0UL && ht->keys[index] == element->RNTI; ++i %= ht->capacity) {
        if (!ht->values[i]) {
            ht->keys[i] = element->RNTI;
            ht->values[i] = (void *)element;
            break;
        }
    }
    pthread_mutex_unlock(&ht->lock);
}

// Function to retrieve an element from the array based on its RNTI
NFAPI_CRC_INDICATION_PDU_T* get(HashTable *ht, unsigned long rnti) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_key( &rnti, ht->capacity );
    for (size_t i = index; ht->keys[index] != ~0UL && ht->keys[index] == rnti; ++i %= ht->capacity) {
        if (ht->values[i]) {
            NFAPI_CRC_INDICATION_PDU_T* element = ht->values[i];
            pthread_mutex_unlock(&ht->lock);
            return element;
        }
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

// Periodic compaction function to remove unused entries
void compact(HashTable *ht) {
    pthread_mutex_lock(&ht->lock);
    unsigned long new_capacity = ht->size > 0 ? ht->size / 2 : 13;
    void **new_values = safe_malloc(new_capacity * sizeof(void*));

    size_t index, old_index;
    for (size_t i = 0; i < new_capacity; ++i) {
        new_values[i] = NULL;
    }

    for (index = 0; index < ht->capacity; ++index) {
        if (ht->keys[index] != ~0UL) {
            old_index = index;
            while (ht->keys[old_index] == ht->keys[index]) {
                old_index = (old_index + 1) % ht->capacity;
            }

            void *element = ht->values[old_index];
            if (element) {
                size_t new_index = hash_key(element->RNTI, new_capacity);
                for (size_t i = new_index; new_values[new_index] != NULL; ++i %= new_capacity) {}
                new_values[new_index] = element;
            }
        }
    }

    free(ht->keys);
    free(ht->values);
    ht->keys = safe_malloc(new_capacity * sizeof(unsigned long));
    ht->values = new_values;
    ht->capacity = new_capacity;
    pthread_mutex_unlock(&ht->lock);
}
```

