void pdu_collection_init(PDU_COLLECTION_NODE_T** head, size_t initial_size) {
    *head = malloc(initial_size * sizeof(PDU_COLLECTION_NODE_T));
    if (!*head) {
        print_error("Memory allocation failure");
        return;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        (*head + i)->next = (*head + i + 1);
        if ((*head + i + 1) == *head) {
            // Last element, set end marker
            (*head + i)->next = NULL;
        }
    }
}

void pdu_collection_push(PDU_COLLECTION_NODE_T** head, MAC_PDU_T* pdu) {
