    PDU_COLLECTION_NODE_T *new_node = malloc(sizeof(PDU_COLLECTION_NODE_T));
    if (!new_node) {
        print_error("Memory allocation failure");
        return;
    }

    new_node->pdu = *pdu;
    new_node->next = (*head);
    *head = new_node;
}

void pdu_collection_pop(PDU_COLLECTION_NODE_T** head) {
    if (isEmpty(*head)) {
        print_error("Collection is empty");
        return;
    }

    PDU_COLLECTION_NODE_T *temp = *head;
    *head = (*head)->next;
    free(temp);
}

bool isEmpty(PDU_COLLECTION_NODE_T* head) {
    if (!head) return true;

    PDU_COLLECTION_NODE_T *current = head;
    while (current->next != head) current = current->next;
    return current->next == head;
}

void pdu_collection_validate(PDU_COLLECTION_NODE_T* head) {
    PDU_COLLECTION_NODE_T *current = head;
    while (current != NULL) {
        validate_pdu(&current->pdu);
        current = current->next;
    }
