void init_nfapi_crc_pdu(struct nfapi_crc_pdu *ncpdu, size_t initial_capacity) {
    if (initial_capacity > MAX_N) {
        fprintf(stderr, "Initial capacity exceeds system limit\n");
        return;
    }
    ncpdu->data = mmap(NULL, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ncpdu->data == MAP_FAILED) {
        perror("Memory allocation failed");
        return;
    }
    ncpdu->capacity = initial_capacity;
    ncpdu->size = 0;
    pthread_mutex_init(&(ncpdu->mutex), NULL);
}

bool add_nfapi_crc_pdu(struct nfapi_crc_pdu *ncpdu, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&(ncpdu->mutex));
    if (ncpdu->size >= ncpdu->capacity && ncpdu->capacity != 0) {
        NFAPI_CRC_INDICATION_PDU_T *new_data;
        size_t new_capacity = ncpdu->capacity * 2;
        if (new_capacity > MAX_N) {
            pthread_mutex_unlock(&(ncpdu->mutex));
            fprintf(stderr, "Resizing array exceeds system limit\n");
            return false;
        }
        new_data = realloc(ncpdu->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            pthread_mutex_unlock(&(ncpdu->mutex));
            perror("Memory allocation failed during resizing");
            return false;
        }
        ncpdu->data = new_data;
        ncpdu->capacity = new_capacity;
    }
    if (pdu->rnti < RNTI_MIN || pdu->rnti > RNTI_MAX) {
        pthread_mutex_unlock(&(ncpdu->mutex));
        fprintf(stderr, "Invalid RNTI value: %u\n", pdu->rnti);
        return false;
    }
    ncpdu->data[ncpdu->size] = *pdu;
    ++ncpdu->size;
    pthread_mutex_unlock(&(ncpdu->mutex));
    return true;
}

void get_info(const struct nfapi_crc_pdu *ncpdu, size_t *total_capacity, size_t *current_size) {
    pthread_mutex_lock(&(ncpdu->mutex));
    *total_capacity = ncpdu->capacity;
