        pool[i].rx_ue.init(); // Assume that RX_UE_INFORMATION_TAG has an initialization function
        pool[i].rnti = 0;
        pool[i].crc_indication.setRandomCRCFlag(); // Assume that CRC_INDICATION_REL8_TAG has a method to set random CRCFLAG
    }
}

// Function to get an element from the memory pool
NFAPI_CRC_INDICATION_PDU_T* get_element() {
    pthread_mutex_lock(&mutex);

    if (free_count > 0) {
        --free_count;
        NFAPI_CRC_INDICATION_PDU_T* element = &pool[allocated];
        ++allocated;
        pthread_mutex_unlock(&mutex);
        return element;
    }

    pthread_mutex_unlock(&mutex);
    return calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Function to release an element back to the memory pool
void release_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (element == NULL) return;

    pthread_mutex_lock(&mutex);

    if (free_count < POOL_SIZE) {
        // Copy the structure to the pool, as modifying it directly could cause issues with concurrent access
        NFAPI_CRC_INDICATION_PDU_T* pool_element = &pool[allocated];
        memcpy(pool_element, element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ++allocated;
        --free_count;
    } else {
        free(element);
    }

    pthread_mutex_unlock(&mutex);
}
