double calculate_avg_and_stddev(const double* data, size_t n) {
    double avg = 0.0;
    double sum_of_squares = 0.0;

    for (size_t i = 0; i < n; ++i) {
        avg += data[i];
    }

    avg /= n;

    for (size_t i = 0; i < n; ++i) {
        sum_of_squares += pow(data[i] - avg, 2);
