#define CHUNK_SIZE 100

int init_pdu_array(NFAPI_CRC_INDICATION_PDU_T** pdu_array, size_t num_pdus) {
    if (num_pdus % CHUNK_SIZE != 0 || num_pdus > UINT32_MAX / CHUNK_SIZE * CHUNK_SIZE) {
        return -1; // Invalid number of PDUs
    }

    size_t num_chunks = num_pdus / CHUNK_SIZE;
    *pdu_array = malloc(num_chunks * sizeof(NFAPI_CRC_INDICATION_PDU_T[CHUNK_SIZE]));

    if (*pdu_array == NULL) {
        return -2; // Out of memory
    }

    return 0;
}

size_t index_in_chunk(size_t index) {
    return index / CHUNK_SIZE;
}

size_t offset_within_chunk(size_t index) {
    return index % CHUNK_SIZE;
}

int get_pdu(const NFAPI_CRC_INDICATION_PDU_T* const pdu_array, size_t index, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (index_in_chunk(index) >= UINT32_MAX / CHUNK_SIZE || offset_within_chunk(index) >= CHUNK_SIZE) {
        return -1; // Out of bounds
    }

    memcpy(pdu, &pdu_array[index], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return 0;
}

int set_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t index, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (index_in_chunk(index) >= UINT32_MAX / CHUNK_SIZE || offset_within_chunk(index) >= CHUNK_SIZE) {
        return -1; // Out of bounds
    }

    memcpy(&pdu_array[index], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return 0;
}

int insert_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t index, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (index >= UINT32_MAX / CHUNK_SIZE * CHUNK_SIZE) {
        return -1; // Index out of bounds
    }

    size_t num_pdus = index + 1;
    if (num_pdus > UINT32_MAX / CHUNK_SIZE * CHUNK_SIZE) {
        return -2; // Insufficient memory for insertion
    }

    memmove(&pdu_array[index + 1], &pdu_array[index], (num_pdus - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(&pdu_array[index], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return 0;
}
