#include <chrono>

// Define your NFAPI_CRC_INDICATION_PDU_T structure here
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

class NFAPICrcIndicationGenerator {
public:
    NFAPICrcIndicationGenerator(size_t n, bool log, std::ofstream* logFile) : m_n(n), m_log(log), m_logFile(logFile) {}

    void generate(std::vector<NFAPI_CRC_INDICATION_PDU_T> &structures) {
        if (m_n == 0) return;

        std::uniform_int_distribution<> distribution(1, RANGE); // Define your range here
        std::mt19937 generator(m_seed); // Seed random number generator

        std::vector<NFAPI_CRC_INDICATION_PDU_T> structuresToCreate;
        auto lock = std::unique_lock<std::mutex>(m_mutex);

        for (size_t i = 0; i < m_n; ++i) {
            NFAPI_CRC_INDICATION_PDU_T structure;
            bool unique = true;

            while (unique) {
                structure.tag = static_cast<RX_UE_INFORMATION_TAG>(distribution(generator));
                structure.rnti = static_cast<uint32_t>(distribution(generator));
                unique = true;

                lock.unlock();
                for (auto &createdStructure : structures) {
                    if ((createdStructure.tag == structure.tag) && (createdStructure.rnti == structure.rnti)) {
                        unique = false;
                        break;
                    }
                }
                lock.lock();
            }

            structure.crc_indication.crcFlag = static_cast<uint8_t>(distribution(generator) % 2);
            structuresToCreate.emplace_back(structure);
        }

        {
            lock.unlock();
            for (auto &createdStructure : structuresToCreate) {
                if (m_log) m_logFile->write(reinterpret_cast<const char*>(&createdStructure), sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
        }

        structures.resize(structuresToCreate.size());
        std::copy(std::begin(structuresToCreate), std::end(structuresToCreate), std::begin(structures));
    }

private:
    size_t m_n;
    bool m_log;
    std::ofstream* m_logFile;
    std::mutex m_mutex;
    uint64_t m_seed = std::chrono::system_clock::now().time_since_epoch().count(); // Seed with current time
};
```

