} NFAPI_CRC_INDICATION_PDU_T;

struct array_context {
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

static void init_array(struct array_context *ctx, size_t size) {
    ctx->size = size;
    ctx->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!ctx->data) {
        fprintf(stderr, "Error: Failed to allocate memory for array\n");
        exit(EXIT_FAILURE);
    }

    ctx->mutex = PTHREAD_MUTEX_INITIALIZER;
    ctx->cond = PTHREAD_COND_INITIALIZER;
}

static void cleanup_array(struct array_context *ctx) {
    if (ctx->data) {
        free(ctx->data);
        ctx->data = NULL;
    }
}

static NFAPI_CRC_INDICATION_PDU_T *get_array(const struct array_context *ctx) {
    return ctx->data;
}

static size_t get_next_tag(struct array_context *ctx, size_t start) {
    size_t i = start;
    for (i = start; i < ctx->size; ++i) {
        if (!ctx->data[i].tag) {
            break;
        }
    }
    return i == ctx->size ? 0 : i;
}

static bool initialize_structure(NFAPI_CRC_INDICATION_PDU_T *pdu, unsigned int seed) {
    pdu->tag = (RX_UE_INFORMATION_TAG)i;
    pdu->rnti = RNTI_INITIALIZER;
    pdu->crc_indication.flag = rand_r(&seed);
    return true;
}

static void *update_array(void *ctx_) {
    struct array_context *ctx = ctx_;
    size_t idx, next_idx;
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    pthread_mutex_lock(&ctx->mutex);

    while (true) {
        // Wait for a slot to become available or be notified of changes
        pthread_cond_wait(&ctx->cond, &ctx->mutex);

        next_idx = get_next_tag(ctx, idx + 1);
        if (next_idx == idx) {
            // All slots are full, continue waiting
            continue;
        }

        pdu = &ctx->data[idx];

        if (!initialize_structure(pdu, ctx->seed)) {
            fprintf(stderr, "Error: Failed to initialize PDU\n");
            pthread_mutex_unlock(&ctx->mutex);
            return NULL;
        }

        idx = next_idx;
    }
}

void init_and_update_array(struct array_context *ctx, size_t size, unsigned int seed) {
    init_array(ctx, size);

    // Initialize the first structure with a seed value and start updating from the second one
    NFAPI_CRC_INDICATION_PDU_T *pdu = ctx->data;
    if (!initialize_structure(pdu++, seed)) {
        fprintf(stderr, "Error: Failed to initialize PDU\n");
        cleanup_array(ctx);
        return;
    }

    pthread_t thread_id;
    for (size_t i = 1; i < ctx->size; ++i) {
        if (pthread_create(&thread_id, NULL, update_array, ctx)) {
            fprintf(stderr, "Error: Failed to create update thread\n");
            cleanup_array(ctx);
            return;
        }
    }
}
