const UE_CONTEXT* UE_CONTEXT_MANAGER::getUEContext(unsigned int uid) const {
    std::lock_guard<std::mutex> lock(mtx);
    auto it = contexts.find(uid);
    return (it != contexts.end()) ? &it->second : nullptr;
}

bool UE_CONTEXT_MANAGER::addUEContext(const UE_CONTEXT& context) {
    std::lock_guard<std::mutex> lock(mtx);

    auto it = contexts.find(context.UE_ID);
    if (it != contexts.end()) {  // Duplicate UE_ID found
        for (const auto& pduSessionID : context.pduSessionIDs) {
            if (std::find(it->second.pduSessionIDs.begin(), it->second.pduSessionIDs.end(), pduSessionID) == it->second.pduSessionIDs.end()) {
                // PDUSession_ID is unique within this UE Context, but not unique across all UE Contexts
                failedAllocations++;
                return false;
            }
        }
    } else {   // New UE Context
        for (const auto& pduSessionID : context.pduSessionIDs) {
            if (contexts.count(pduSessionID)) {  // Duplicate PDUSession_ID found
                failedAllocations++;
                return false;
            }
        }
        contexts[context.UE_ID] = context;
        successfulAllocations++;
    }

    return true;
}
