```cpp
#include <iostream>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <atomic>
#include <boost/asio.hpp>
#include <boost/lockfree/queue.hpp>
#include <ctime>
#include <chrono>
#include <functional>

using namespace std;
using boost::asio::ip::tcp;

struct ConnectionRequest {
    int client_id;
    string ip_address;
    bool status = true; // pending
    time_t timestamp;
};

class NetworkService {
private:
    unordered_map<int, ConnectionRequest> connections;
    mutex mtx;
    boost::lockfree::queue<ConnectionRequest*> request_queue;
    tcp::acceptor acceptor;
    atomic<bool> running{true};

    void process_connections() {
        while (running) {
            if (!request_queue.empty()) {
                ConnectionRequest* req = request_queue.pop();
                auto start_time = chrono::steady_clock::now();
                process_request(*req);
                auto duration = chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now() - start_time).count();
                log_processing_duration(duration);

                // Clear inactive requests based on timeout threshold
                clear_inactive_requests();
            }
        }
    }

    void process_request(ConnectionRequest& req) {
        // Simulate network latency with a variable delay
        this_thread::sleep_for(chrono::milliseconds(rand() % MAX_DELAY + MIN_DELAY));

        // Perform actual request processing here
        req.status = false; // mark as active
    }

    void clear_inactive_requests() {
        time_t now = time(nullptr);
        auto it = connections.begin();
        while (it != connections.end()) {
            if (now - it->second.timestamp > TIMEOUT_THRESHOLD) {
                it = connections.erase(it);
                log_inactive_clear();
            } else {
                ++it;
            }
        }
    }

public:
    NetworkService(int port, int max_delay, int timeout_threshold)
        : MIN_DELAY(100), MAX_DELAY(max_delay), TIMEOUT_THRESHOLD(timeout_threshold) {
        tcp::endpoint endpoint(boost::asio::ip::make_address("0.0.0.0"), port);
        acceptor.open(endpoint.protocol());
        acceptor.set_option(acceptor.socket().reuse_address(true));
        acceptor.bind(endpoint);
        acceptor.listen();
    }

    void start() {
        thread process_thread(std::bind(&NetworkService::process_connections, this));
        for (;;) {
            tcp::socket socket = acceptor.accept();
            ConnectionRequest req{static_cast<int>(socket.native_handle()), socket.remote_endpoint().address().to_string(), false, time(nullptr)};
            request_queue.push(&req);
        }
    }

private:
    static const int MIN_DELAY;
    static const int MAX_DELAY;
    static const int TIMEOUT_THRESHOLD;

    void log_processing_duration(int duration) {
        // Implement logging mechanism here
    }

    void log_inactive_clear() {
        // Implement logging mechanism here
    }
};

const int NetworkService::MIN_DELAY = 100;
const int NetworkService::MAX_DELAY = 500;
const int NetworkService::TIMEOUT_THRESHOLD = 600;
```

