void processAndConvertImage(const char* inputImagePath, const char* outputPDFPath,
                             const char* backupConverterPath, bool debugMode) {
    if (!fileExists(inputImagePath)) {
        perror("Input image file does not exist");
        useBackupConverter(backupConverterPath, inputImagePath, outputPDFPath);
        return;
    }

    JPEG_DECODE_PARAMS jpegParams;
    jpegParams.src_data = readFile(inputImagePath);
    if (!jpegParams.src_data) {
        perror("Failed to read input image file");
        useBackupConverter(backupConverterPath, inputImagePath, outputPDFPath);
        return;
    }

    JPEG_DEC_HANDLE dec_handle = jpeg_create_decompress();
    jpeg_mem_src(&jpegParams, jpegParams.length);
    jpeg_read_header(dec_handle, TRUE);
    jpeg_start_decode(dec_handle, FALSE);

    pdf_document* pdfDoc = createPDFDocument(outputPDFPath);
    if (!pdfDoc) {
        perror("Failed to initialize PDF document");
        useBackupConverter(backupConverterPath, inputImagePath, outputPDFPath);
        jpeg_destroy_decompress(dec_handle);
        free(jpegParams.src_data);
        return;
    }

    pdf_page* page = createPDFPageFromJPEG(dec_handle, pdfDoc);
    if (!page) {
        perror("Failed to convert JPEG to PDF");
        destroyPDFDocument(pdfDoc);
        useBackupConverter(backupConverterPath, inputImagePath, outputPDFPath);
        jpeg_destroy_decompress(dec_handle);
        free(jpegParams.src_data);
        return;
    }

    appendPageToDocument(pdfDoc, page);
    destroyPDFPage(page);
    jpeg_finish_decode(dec_handle);
    jpeg_destroy_decompress(dec_handle);
