#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 1024
#define GROWTH_FACTOR 2

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct cache_node {
    time_t timestamp;
    NFAPI_CRC_INDICATION_PDU_T data;
    struct cache_node *next;
};

struct data_manager {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    struct cache_node *cache_head;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

void data_manager_init(struct data_manager *dm, size_t n) {
    dm->data = calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dm->data) {
        fprintf(stderr, "Memory allocation failure\n");
        return;
    }

    for (size_t i = 0; i < n; ++i) {
        dm->data[i].rx_ue_information.present = RX_UE_INFORMATION_PRESENT;
        dm->data[i].rx_ue_information.choice.tag = RX_UE_INFORMATION_TAG;
        dm->data[i].rnti.present = RNTI_PRESENT;
        dm->data[i].crc_indication.present = CRC_INDICATION_REL8_TAG_PRESENT;
        dm->data[i].crc_indication.choice.tag = CRC_INDICATION_REL8_TAG;
        dm->data[i].crc_indication.choice.field.crcflag = rand() % 2;
    }

    dm->capacity = n;
    dm->size = n;
    dm->cache_head = NULL;
    pthread_mutex_init(&dm->mutex, NULL);
    pthread_cond_init(&dm->cond, NULL);
}

void cache_push(struct data_manager *dm, NFAPI_CRC_INDICATION_PDU_T data) {
    struct cache_node *new_node = malloc(sizeof(struct cache_node));
    if (!new_node) return;

    new_node->data = data;
    new_node->timestamp = time(NULL);
    new_node->next = dm->cache_head;
    dm->cache_head = new_node;
}

NFAPI_CRC_INDICATION_PDU_T* data_manager_get(struct data_manager *dm) {
    pthread_mutex_lock(&dm->mutex);

    if (dm->size == 0) {
        dm->data[0].rx_ue_information.present = RX_UE_INFORMATION_PRESENT;
        dm->data[0].rx_ue_information.choice.tag = RX_UE_INFORMATION_TAG;
        dm->data[0].rnti.present = RNTI_PRESENT;
        dm->data[0].crc_indication.present = CRC_INDICATION_REL8_TAG_PRESENT;
        dm->data[0].crc_indication.choice.tag = CRC_INDICATION_REL8_TAG;
        dm->data[0].crc_indication.choice.field.crcflag = rand() % 2;
        ++dm->size;
    }

    size_t index = (dm->size - 1) % dm->capacity;

    NFAPI_CRC_INDICATION_PDU_T* data = &dm->data[index];
    if (dm->cache_head) {
        struct cache_node *current = dm->cache_head;
        for (size_t i = 0; i < dm->capacity && current != NULL; ++i) {
            if ((i + dm->size - 1) % dm->capacity == index) {
                *data = current->data;
                struct cache_node *temp = current;
                current = current->next;
                free(temp);
                break;
            }
            if (current->timestamp + MAX_CACHE_SIZE < time(NULL)) {
                struct cache_node *temp = current;
                current = current->next;
                free(temp);
            } else {
                current = current->next;
            }
        }
    }

    pthread_mutex_unlock(&dm->mutex);

    if (dm->size == dm->capacity) {
        resize_data_manager(dm, dm->capacity * GROWTH_FACTOR);
    }

    return data;
}

void data_manager_release(struct data_manager *dm) {
    free(dm->data);
    pthread_mutex_destroy(&dm->mutex);
    pthread_cond_destroy(&dm->cond);
}

void resize_data_manager(struct data_manager *dm, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(dm->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) return;

    dm->data = new_data;
    dm->capacity = new_capacity;
}

void* serialize_function(void *arg) {
    struct data_manager *dm = arg;
    // Implement serialization logic here
}

int main() {
    struct data_manager dm;
    data_manager_get(&dm);  // Get a random initialized element
    data_manager_get(&dm);  // Get an element from the cache if available, otherwise initialize a new one

    pthread_t serialization_thread;
    pthread_create(&serialization_thread, NULL, serialize_function, &dm);

    // Use the data_manager as needed

    data_manager_release(&dm);
    return 0;
}

The above code provides a simple example of a data manager that initializes a predefined number of elements and offers a way to get new random initialized or cached elements. It also includes a basic cache mechanism and the possibility to serialize the data. The actual serialization logic is not implemented here but can be added in the serialize_function().

