            pdu_list[i].CRCFLAG = status == NETWORK_NORMAL ? rand() % 2 : true; // Set CRCFLAG to true for poor or failure network conditions
        } else if (rc != SQLITE_DONE) {
            fprintf(stderr, "Failed to fetch API key: %s\n", sqlite3_errmsg(db->db));
            return 3;
        }
    }

    rc = sqlite3_prepare_v2(db->db, "COMMIT;", -1, &api_key_stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Can't prepare statement: %s\n", sqlite3_errmsg(db->db));
        return 4;
    }

    rc = sqlite3_exec(db->db, "PRAGMA synchronous=OFF;", NULL, 0, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Can't set synchronous mode: %s\n", sqlite3_errmsg(db->db));
        return 5;
    }

    rc = prepare_and_bind_insert_statements(db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare insert statements: %s\n", sqlite3_errmsg(db->db));
        return 6;
    }

    for (int i = 0; i < N; ++i) {
        rc = batch_insert_crc_indications(db, pdu_list + i);
        if (rc != SQLITE_OK) {
            fprintf(stderr, "Failed to insert CRC indication: %s\n", sqlite3_errmsg(db->db));
            return 7;
        }
    }

    rc = sqlite3_finalize(api_key_stmt);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to finalize statement: %s\n", sqlite3_errmsg(db->db));
        return 8;
    }

    free(pdu_list);
    return 0;
}

// Implement the remaining functions as needed
