static int max_structures = 1000;
static int num_structures = 0;
static NFAPI_CRUC_INDICATION_PDU_T *list = NULL;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
static pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void generate_and_add(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_lock);

    // Generate random values for RNTI, CRC_INDICATION_REL8_TAG, and CRCFLAG
    uint32_t seed = (uint32_t)time(NULL);
    srand(seed);
    pdu->rnti = rand();
    pdu->crc_indication_tag = rand() % 0x10000;
    pdu->crcflag = rand() % 2;

    // Add the PDU to the list if there is room
    if (num_structures < max_structures) {
        list[num_structures] = *pdu;
        num_structures++;
        pthread_cond_signal(&not_full);
    } else {
        // Wait if the list is full
        pthread_cond_wait(&not_empty, &list_lock);
    }

    pthread_mutex_unlock(&list_lock);
}

bool pop_and_validate(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_lock);

    // Check if the list is not empty
    if (num_structures == 0) {
        pthread_cond_wait(&not_full, &list_lock);
    }

    // Pop a PDU from the list and validate it
    if (num_structures > 0) {
        *pdu = list[--num_structures];

        // Check if the RNTI, CRC_INDICATION_REL8_TAG, and CRCFLAG are valid
        if (pdu->rnti != rand() &&
            pdu->crc_indication_tag != (rand() % 0x10000) &&
            pdu->crcflag != (rand() % 2)) {
            printf("Invalid PDU: rnti=%d, crc_indication_tag=%d, crcflag=%d\n",
                   pdu->rnti, pdu->crc_indication_tag, pdu->crcflag);
            return false;
        }
    }

    pthread_mutex_unlock(&list_lock);
    return true;
}
