void insert_node(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!*head) {
        *head = create_node(data);
        return;
    }

    Node* current = *head;
    while (current->next) {
        current = current->next;
    }
    current->next = create_node(data);
}

bool remove_node_by_RNTI(Node** head, uint16_t rnti) {
    if (!*head) return false;

    Node* current = *head;
    if (current->data.RNTI == rnti) {
        *head = current->next;
        free(current);
        return true;
    }

    while (current->next && current->next->data.RNTI != rnti) {
        current = current->next;
    }

    if (!current->next) return false;

