typedef struct MAC_PDU {
    uint32_t PDCP_SN;
    uint32_t PDCP_CC;
    struct MAC_PDU *prev;
    struct MAC_PDU *next;
} MAC_PDU;

static const uint32_t ACCEPTABLE_RANGE = 0xFFFFFFFF; // Update this value as per your requirement

sem_t list_lock; // Semaphore for synchronization
FILE *log_file; // Log file pointer

void log(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
    }
}

MAC_PDU* create_node(uint32_t PDCP_SN, uint32_t PDCP_CC) {
    MAC_PDU *new_node = (MAC_PDU *) mmap(NULL, sizeof(MAC_PDU), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_node == MAP_FAILED) {
        log("Memory allocation failed for new node.");
        return NULL;
    }
    new_node->PDCP_SN = PDCP_SN;
    new_node->PDCP_CC = PDCP_CC;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void add_node(MAC_PDU **head, MAC_PDU *new_node) {
    if (new_node == NULL || head == NULL) {
        return;
    }

    sem_wait(&list_lock);

    if ((*head) != NULL) {
        (*head)->prev = new_node;
        new_node->next = *head;
        *head = new_node;
    } else {
        *head = new_node;
    }

    sem_post(&list_lock);
}

MAC_PDU* find_node(MAC_PDU **head, uint32_t PDCP_SN) {
    MAC_PDU *current = *head;

    if (current == NULL || PDCP_SN > ACCEPTABLE_RANGE || PDCP_SN < 0) {
        log("Invalid PDCP_SN value.");
        return NULL;
    }

    sem_wait(&list_lock);

    while (current != NULL) {
        if (current->PDCP_SN == PDCP_SN) {
            MAC_PDU *temp = current;
            sem_post(&list_lock);
            return temp;
        }
        current = current->next;
    }

    sem_post(&list_lock);
    return NULL;
}

void delete_node(MAC_PDU **head, MAC_PDU *node) {
    if (node == NULL || head == NULL || *head == NULL) {
        return;
    }

    sem_wait(&list_lock);

    if ((*head) == node) {
        *head = node->next;
    } else if (node->next != NULL) {
        node->prev->next = node->next;
    } else if (node->prev != NULL) {
        node->prev->next = NULL;
    }

    munmap(node, sizeof(MAC_PDU));

    sem_post(&list_lock);
}

void init_doubly_linked_list() {
    log_file = fopen("debug.log", "w"); // Update the filename as needed
    if (log_file == NULL) {
        log("Failed to open log file.");
        return;
    }

    sem_init(&list_lock, 0, 1);
}
```

