#define MAX_ENTRIES 1000
#define CRC_RANGE_MIN 0
#define CRC_RANGE_MAX 65535

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint16_t crcflag;
    time_t timestamp;
    pthread_mutex_t lock;
    struct list_node* prev;
    struct list_node* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct list_node* prev;
    struct list_node* next;
} LIST_NODE;

static LIST_NODE head = { .data = NULL, .prev = &head, .next = &head };
static size_t num_entries = 0;
static int max_entries = MAX_ENTRIES;
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;
extern void* log_function(void* args); // External API for logging and monitoring purposes

void init_list() {
    if (pthread_mutex_init(&global_lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize global lock\n");
        exit(EXIT_FAILURE);
    }
}

void insert_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&global_lock);
    if (num_entries >= max_entries) {
        size_t i;
        for (i = 0; i < num_entries - 1; ++i) {
            LIST_NODE* current = &head.next;
            while (current->next != &head) {
                current = current->next;
            }
            if (current->data->timestamp > entry->timestamp) {
                break;
            }
        }
        LIST_NODE* node_to_remove = current->next;
        free(node_to_remove->data);
        free(node_to_remove);
        num_entries--;
    }
    entry->crcflag = rand() % (CRC_RANGE_MAX - CRC_RANGE_MIN) + CRC_RANGE_MIN;
    if (!entry->crcindication.crci.isValid || !entry->crcindication.rnti.isValid || entry->crcindication.crci.value < 0 || entry->crcindication.rnti.value < 0) {
        fprintf(stderr, "Invalid entry: %p\n", entry);
        free(entry);
    } else {
        pthread_mutex_init(&entry->lock, NULL);
        entry->prev = &head;
        entry->next = head.next;
        head.next->prev = entry;
        head.next = entry;
        num_entries++;
        log_function((void*)entry); // Integration with external logging API
    }
    pthread_mutex_unlock(&global_lock);
}

void runtime_reconfigure(int new_max_entries) {
    if (new_max_entries <= 0) {
        fprintf(stderr, "Invalid maximum entries limit: %d\n", new_max_entries);
        return;
    }
    max_entries = new_max_entries;
}
