// Initialize dynamic array with given capacity, returning an error code if insufficient memory is available.
int init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    array->array = malloc(initial_capacity * sizeof(PacketCaptureEvent*));
    if (!array->array) return -1; // Out of memory

    array->capacity = initial_capacity;
    array->count = 0;
    sem_init(&array->mutex, 0, 1);
    return 0;
}

// Add an event to the dynamic array, handling null pointers and edge cases.
int add_event(DynamicArray *array, const PacketCaptureEvent *event) {
    if (!array || !event) return -1; // Invalid arguments

    sem_wait(&array->mutex);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        PacketCaptureEvent **new_array = realloc(array->array, new_capacity * sizeof(PacketCaptureEvent*));
        if (!new_array) { // Out of memory
            sem_post(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->count] = malloc(sizeof(PacketCaptureEvent));
    if (!array->array[array->count]) { // Out of memory
        sem_post(&array->mutex);
        return -1;
    }

    memcpy(array->array[array->count], event, sizeof(PacketCaptureEvent));
    array->count++;

    log_event("Added event", event);
    serialize_data(stdout, array->array, array->count); // For debugging purposes

    sem_post(&array->mutex);

    return 0;
}

// Thread-safe iterative function to walk through the dynamic array and perform operations on each element.
void for_each_event(DynamicArray *array, void (*operation)(const PacketCaptureEvent *)) {
    if (!array || !operation) return; // Invalid arguments

    sem_wait(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        operation(array->array[i]);
    }

    sem_post(&array->mutex);
}
