#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct SignalMeasurement {
    time_t timestamp;
    int signalStrength;
    int frequencyBand;
    double noiseLevel; // optional, can be omitted
} SignalMeasurement;

struct SignalStorage {
    size_t capacity;
    size_t count;
    SignalMeasurement* measurements;
    pthread_mutex_t mutex;
};

void SignalStorageInit(struct SignalStorage* storage, size_t initialCapacity) {
    storage->capacity = initialCapacity;
    storage->count = 0;
    storage->measurements = calloc(initialCapacity, sizeof(SignalMeasurement));
    storage->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void SignalStoragePush(struct SignalStorage* storage, const SignalMeasurement* measurement) {
    pthread_mutex_lock(&storage->mutex);

    if (storage->count >= storage->capacity) {
        // Resize array when it reaches capacity
        size_t newCapacity = storage->capacity * 2;
        SignalMeasurement* newArr = realloc(storage->measurements, newCapacity * sizeof(SignalMeasurement));
        if (!newArr) {
            fprintf(stderr, "Out of memory!\n");
            pthread_mutex_unlock(&storage->mutex);
            return;
        }
        storage->capacity = newCapacity;
        storage->measurements = newArr;
    }

    // Insert measurement at the end
    memcpy(&storage->measurements[storage->count], measurement, sizeof(SignalMeasurement));
    ++storage->count;

    pthread_mutex_unlock(&storage->mutex);
}

void SignalStorageRetain(struct SignalStorage* storage, time_t retentionPeriod) {
    pthread_mutex_lock(&storage->mutex);

    size_t i;
    for (i = 0; i < storage->count; ++i) {
        if (storage->measurements[i].timestamp + retentionPeriod <= time(NULL)) {
            // Shift all measurements before the one to be removed, and decrement count
            memmove(&storage->measurements[i], &storage->measurements[i+1], (storage->count - i - 1) * sizeof(SignalMeasurement));
            --storage->count;
        }
    }

    pthread_mutex_unlock(&storage->mutex);
}

double SignalStorageGetAverageStrength(const struct SignalStorage* storage, time_t startTime, time_t endTime) {
    double totalStrength = 0.0;
    size_t count = 0;

    pthread_mutex_lock(&storage->mutex);

    for (size_t i = 0; i < storage->count; ++i) {
        if (storage->measurements[i].timestamp >= startTime && storage->measurements[i].timestamp <= endTime) {
            totalStrength += storage->measurements[i].signalStrength;
            ++count;
        }
    }

    pthread_mutex_unlock(&storage->mutex);

    if (count != 0)
        return totalStrength / count;
    else
        return -1.0; // Return a special value to indicate no data within the specified time window
}
