#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ATTEMPTS 10
#define MIN_ELEMENTS 100
#define GROWTH_FACTOR 2
#define MEMORY_THRESHOLD 0.95

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct memory_block {
    size_t capacity;
    size_t used;
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct memory_block* next;
};

static struct memory_block* head = NULL;
static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char *msg) {
    fprintf(stderr, "[ERROR] %s\n", msg);
}

void free_memory() {
    struct memory_block* curr = head;
    while (curr != NULL) {
        struct memory_block* temp = curr;
        curr = curr->next;
        free(temp->data);
        free(temp);
    }
    head = NULL;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t elements) {
    if (elements <= 0) {
        log_error("Invalid number of elements");
        return NULL;
    }

    struct memory_block* curr = head;
    size_t required_capacity = elements * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    while (curr != NULL && curr->capacity < required_capacity) {
        curr = curr->next;
    }

    if (curr == NULL || curr->capacity < required_capacity) {
        size_t new_capacity = (required_capacity + 1) * GROWTH_FACTOR;
        struct memory_block* new_block = malloc(sizeof(struct memory_block));
        if (new_block == NULL) {
            log_error("Memory allocation failed");
            free_memory();
            return NULL;
        }

        new_block->capacity = new_capacity;
        new_block->used = 0;
        new_block->data = malloc(new_capacity);
        if (new_block->data == NULL) {
            log_error("Memory allocation failed");
            free(new_block);
            free_memory();
            return NULL;
        }
        new_block->next = head;
        head = new_block;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = &head->data[curr->used];
    curr->used += elements;
    return result;
}

void check_memory() {
    struct memory_block* curr = head;
    double total_used = 0.0;
    while (curr != NULL) {
        total_used += curr->used;
        curr = curr->next;
    }

    if ((double)total_used / head->capacity > MEMORY_THRESHOLD) {
        free_memory();
        log_error("Memory usage exceeded the threshold, releasing some memory.");
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(size_t attempts) {
    for (size_t i = 0; i < attempts; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_memory(1);
        if (pdu != NULL) {
            pdu->tag.field_value = i % 3;
            pdu->rnti.rnti_type = RNTI_TYPE_C_RNTI;
            pdu->rnti.length = sizeof(uint16_t);
            pdu->rnti.data = (uint8_t*)malloc(pdu->rnti.length);
            if (pdu->rnti.data == NULL) {
                log_error("Memory allocation for RNTI failed");
                free(pdu);
                continue;
            }
            *(uint16_t*)pdu->rnti.data = i + MIN_ELEMENTS;
            pdu->crc_indication.field_value = rand() % 2;

            check_memory();
            return pdu;
        }
    }

    log_error("Failed to allocate memory after multiple attempts");
    return NULL;
}

void* create_pdu_thread(void* arg) {
    create_pdu((size_t)arg);
    pthread_exit(NULL);
}

int main() {
    for (size_t i = 0; i < 10; ++i) {
        pthread_t thread;
        int rc = pthread_create(&thread, NULL, create_pdu_thread, (void*)(uintptr_t)i);
        if (rc) {
            log_error("Error creating thread");
            return 1;
        }
    }

    // Perform other tasks and monitor threads...

    pthread_exit(NULL);
}
