typedef struct {
    int type;
    uint32_t source_ip;
    uint32_t dest_ip;
    uint8_t ttl;
} PacketHeader;

struct packet_array {
    size_t capacity;
    size_t size;
    PacketHeader* data;
    pthread_mutex_t mutex;
};

void packet_array_init(struct packet_array* array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = calloc(initial_capacity, sizeof(PacketHeader));
    if (!array->data) {
        perror("calloc failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->mutex, NULL);
}

void packet_array_destroy(struct packet_array* array) {
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
}

size_t packet_array_find(const struct packet_array* array, int type) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].type == type) {
            return i;
        }
    }
    return SIZE_MAX;
}

void packet_array_add(struct packet_array* array, const PacketHeader* packet) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        PacketHeader* temp = realloc(array->data, array->capacity * sizeof(PacketHeader));
        if (!temp) {
            perror("realloc failed");
            pthread_mutex_unlock(&array->mutex);
            exit(EXIT_FAILURE);
        }
        array->data = temp;
    }
    array->data[array->size++] = *packet;
    pthread_mutex_unlock(&array->mutex);
}

void packet_array_update(struct packet_array* array, size_t index, const PacketHeader* new_packet) {
    if (index >= array->size) return;

    pthread_mutex_lock(&array->mutex);
    if (index < array->size) {
        array->data[index] = *new_packet;
    }
    pthread_mutex_unlock(&array->mutex);
}

const PacketHeader* packet_array_get(const struct packet_array* array, size_t index) {
    if (index >= array->size) return NULL;

    pthread_mutex_lock(&array->mutex);
    const PacketHeader* result = &array->data[index];
    pthread_mutex_unlock(&array->mutex);
    return result;
}
