void dynamic_array_resize(DynamicArray* array, size_t new_capacity) {
    if (new_capacity <= array->capacity) return;

    NFAPI_CRC_INDICATION_PDU_T* temp_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp_data) {
        fprintf(stderr, "Out of memory\n");
        exit(-1);
    }

    array->data = temp_data;
    array->capacity = new_capacity;
}

NFAPI_CRC_INDICATION_PDU_T* dynamic_array_get(const DynamicArray* array, size_t index) {
    if (index >= array->size) {
        fprintf(stderr, "Invalid index\n");
        return NULL;
    }
    return &(array->data[index]);
}

void dynamic_array_push(DynamicArray* array, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
