void init_pool(struct Pool* pool, size_t max_size) {
    pool->max_size = max_size;
    pool->current_size = 0;
    pool->pool = malloc(sizeof(Packet*) * max_size);
    pthread_mutex_init(&pool->lock, NULL);
}

Packet* acquire_packet(struct Pool* pool) {
    Packet* packet;
    pthread_mutex_lock(&pool->lock);
    if (pool->current_size < pool->max_size) {
