class PacketQueue {
private:
    std::mutex mtx_;
    std::vector<std::shared_ptr<PacketHeader>> packets_;
    std::vector<std::shared_ptr<PacketHeader>> pending_updates_;

public:
    void add_packet(const PacketHeader& packet) {
        // Add the new packet to the vector with a shared pointer.
        packets_.emplace_back(std::make_shared<PacketHeader>(packet));
    }

    void update_packet(const PacketHeader& packet) {
        std::unique_lock<std::mutex> lock(mtx_);
        pending_updates_.push_back(std::make_shared<PacketHeader>(packet));
    }

    void process_pending_updates() {
        // Process the pending updates atomically.
        std::unique_lock<std::mutex> lock(mtx_);

        for (auto& update : pending_updates_) {
            auto it = std::find_if(packets_.begin(), packets_.end(),
                [update](const auto& packet) { return *update->packet_type == *packet->packet_type; });

            if (it != packets_.end()) {
                *it = update;
            }
        }
        pending_updates_.clear();
    }

