[" Here's an example of a C function that manages a dynamic list of `PHY_RX_CONTEXT` structures using the doubly-linked list data structure, along with a mechanism to track the total number of elements without relying on global variables. This implementation utilizes lock-based synchronization, uses efficient memory management techniques for minimizing fragmentation and reallocations, and provides robustness in handling external data source failures.

```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct phy_rx_context {
    phy_rx_context_t context;
    struct phy_rx_context* next;
    struct phy_rx_context* prev;
} PHY_RX_CONTEXT;

typedef struct dynamic_list {
    size_t size;
    PHY_RX_CONTEXT* head;
    PHY_RX_CONTEXT* tail;
    pthread_mutex_t lock;
} DYNAMIC_LIST;

DYNAMIC_LIST* init_dynamic_list() {
    DYNAMIC_LIST* list = (DYNAMIC_LIST*)malloc(sizeof(DYNAMIC_LIST));
    if (!list) return NULL;
    list->size = 0;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DYNAMIC_LIST* list) {
    if (!list) return;
    PHY_RX_CONTEXT* current = list->head;
    while (current != NULL) {
        PHY_RX_CONTEXT* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

void add_element(DYNAMIC_LIST* list, phy_rx_context_t* new_element) {
    PHY_RX_CONTEXT* new_node = (PHY_RX_CONTEXT*)malloc(sizeof(PHY_RX_CONTEXT));
    if (!new_node) return;

    new_node->context = *new_element;
    new_node->next = NULL;
    new_node->prev = list->tail;

    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

phy_rx_context_t* get_element(DYNAMIC_LIST* list, size_t index) {
    if (index >= list->size || !list) return NULL;

    PHY_RX_CONTEXT* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }
    return &current->context;
}

void remove_element(DYNAMIC_LIST* list, size_t index) {
    if (index >= list->size || !list) return;

    pthread_mutex_lock(&list->lock);
    PHY_RX_CONTEXT* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }

    if (!current || !current->prev || !current->next) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    PHY_RX_CONTEXT* temp = current->prev;
    current->prev->next = current->next;
    if (current->next) current->next->prev = temp;
    else list->tail = temp;

    free(current);
    list->size--;
    pthread_mutex_unlock(&list->lock);
}
