// Memory pool for S1MessagePart structures
struct MemoryPool {
    size_t capacity;
    S1MessagePart **parts;
    int nextIndex;
};

void initMemoryPool(struct MemoryPool *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->nextIndex = 0;
    pool->parts = malloc(capacity * sizeof(S1MessagePart*));
}

S1MessagePart *getFromPool(struct MemoryPool *pool) {
    if (pool->nextIndex >= pool->capacity) {
        // Pool is empty, extend it if necessary
        size_t newCapacity = pool->capacity * 2;
        S1MessagePart **newParts = realloc(pool->parts, newCapacity * sizeof(S1MessagePart*));
        if (!newParts) {
            // Failed to allocate memory, handle error
            return NULL;
        }
        pool->parts = newParts;
        pool->capacity *= 2;
    }
    return pool->parts[pool->nextIndex++];
}

void putBackToPool(struct MemoryPool *pool, S1MessagePart *part) {
    pool->parts[--pool->nextIndex] = part;
}

