#include "sensor_reading_stats.h" // Custom structure definition for SensorReadingStats
#include "realtime_logging.h" // Interface to real-time logging module
#include "hardware_interrupt.h" // Interface to hardware-specific interrupt handler

void handleAndProcessSensorData(const sensor_reading_t* incoming_data, size_t num_readings) {
    static SensorReadingStats stats[100];
    static size_t window_index = 0;
    static bool is_initialized = false;

    if (!is_initialized) {
        // Initialize the buffer and other resources when first called
        memset(stats, 0, sizeof(SensorReadingStats) * 100);
        is_initialized = true;
    }

    size_t readings_processed = 0;
    for (size_t i = window_index; i < num_readings && readings_processed < 100; ++i) {
        const sensor_reading_t* curr_data = &incoming_data[i % num_readings];

        // Ensure data is valid and compatible with the system
        if (validateSensorData(curr_data)) {
            SensorReadingStats* curr_stats = &stats[(window_index + i) % 100];

            // Process the readings and update statistics
            curr_stats->num_readings++;
            curr_stats->sum += curr_data->value;
            curr_stats->variance += (curr_data->value - curr_stats->mean) * (curr_data->value - curr_stats->mean);

            readings_processed++;
        } else {
            // Log the error and continue with the next reading if possible
            logError("Invalid or corrupted sensor data");
        }
    }

    if (readings_processed > 0) {
        size_t num_valid_readings = readings_processed;
        if (num_valid_readings < 100)
            num_valid_readings = 100;

        SensorReadingStats* stats_ptr = &stats[(window_index + num_valid_readings - 100) % 100];

        // Calculate aggregated statistics over the window
        double rolling_mean = stats_ptr->sum / stats_ptr->num_readings;
        double variance = (stats_ptr->variance / stats_ptr->num_readings + (rolling_mean * rolling_mean - stats_ptr->mean * stats_ptr->mean) * (stats_ptr->num_readings - 1)) / num_valid_readings;
        double stddev = sqrt(variance);

        // Log the aggregated statistics for debugging and monitoring purposes
        logSensorDataStats(&rolling_mean, &variance, &stddev);

        window_index += readings_processed;
    }
}
```

