typedef struct {
    uint32_t rnti;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

static inline void set_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crcflag = (rand() % 2 == 0);
}

#define M 1048576 // Memory constraint in bytes
#define N 10000 // Array size limit

static int arr_size = 0;
static NFAPI_CRC_INDICATION_PDU_T *dynamic_array = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_dyn_arr(void) {
    if (dynamic_array != NULL) return;

    arr_size = 0;
    size_t total_bytes = M;
    dynamic_array = malloc(total_bytes);
    if (!dynamic_array) {
        fprintf(stderr, "Failed to allocate memory for dynamic array.\n");
        exit(EXIT_FAILURE);
    }
}

void add_entry(uint32_t rnti) {
    pthread_mutex_lock(&mutex);

    if (arr_size >= N) {
        prune_dyn_arr();
    }

    size_t offset = arr_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)((char*)dynamic_array + offset);

    entry->rnti = rnti;
    set_crcflag(entry);

    ++arr_size;
    pthread_mutex_unlock(&mutex);
}

void prune_dyn_arr() {
    if (arr_size <= N) return;

    pthread_mutex_lock(&mutex);

    size_t to_remove = arr_size - N;
    for (int i = 0; i < to_remove; ++i) {
        size_t offset = i * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)((char*)dynamic_array + offset);

        entry->rnti = 0;
    }

    arr_size -= to_remove;
    pthread_mutex_unlock(&mutex);
}
```

