    int port_id;
    struct STATUS_INFO *status_info;
    struct NICP_HEADER *prev, *next;
} NICP_HEADER;

typedef struct STATUS_INFO {
    int error_code;
    time_t last_seen_timestamp;
    struct PACKET* packet_list;
    struct STATUS_INFO* next;
} STATUS_INFO;

struct PACKET {
    // packet data structure
};

void create_nicp_header(NICP_HEADER** nicp_headers, int num_nicps) {
    NICP_HEADER *current = NULL, *next = NULL;
    STATUS_INFO* status_info = NULL;

    *nicp_headers = (NICP_HEADER*)calloc(num_nicps, sizeof(NICP_HEADER));
    if (!*nicp_headers) {
        perror("Error: Failed to allocate memory for NICP headers");
        return;
    }

    for (int i = 0; i < num_nicps; ++i) {
        current = *nicp_headers + i;
        status_info = calloc(1, sizeof(STATUS_INFO));
        if (!status_info) {
            perror("Error: Failed to allocate memory for STATUS_INFO");
            free(*nicp_headers);
            return;
        }
        current->status_info = status_info;

        // Initialize the circular doubly-linked list
        if (i == 0) {
            current->prev = current + num_nicps - 1;
            current->next = current + 1;
            (*(current + num_nicps - 1))->prev = current;
            (*(current + num_nicps - 1))->next = current;
        } else {
            next = *nicp_headers + (i + 1) % num_nicps;
            current->prev = *(current + num_nicps - 1);
            current->next = next;
            next->prev = current;
        }
    }
}

