int configure_network_interface(MAC_FRAME* frames, size_t* frame_sizes, int num_frames, size_t max_buffer_size) {
    size_t total_frame_size = 0;
    void* buffer;
    int i;

    // Validate inputs
    if(num_frames > MAX_FRAMES || max_buffer_size < num_frames * (sizeof(MAC_FRAME) + sizeof(MAC_FRAME).max_align_t)) {
        fprintf(stderr, "Invalid input: number of frames or maximum buffer size is too large.\n");
        return -1;
    }

    // Allocate buffer and initialize frames with random MAC addresses and payloads
    buffer = calloc(max_buffer_size, 1);
    if(!buffer) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    total_frame_size = 0;
    for(i = 0; i < num_frames; ++i) {
        MAC_FRAME* frame = (MAC_FRAME*)((uint8_t*)buffer + total_frame_size);

        // Generate random MAC address and fill payload with random data
        generate_random_mac(frame->mac_header);
        fill_random_data(frame->mac_payload, sizeof(frame->mac_payload));

        frame_sizes[i] = sizeof(MAC_FRAME);
        total_frame_size += frame_sizes[i];
    }

    // Check alignment and enforce IEEE standards
    if((uintptr_t)buffer % alignof(MAC_FRAME)) {
        fprintf(stderr, "Buffer is not properly aligned.\n");
        free(buffer);
        return -1;
    }

    // Calculate checksums for each frame and set flags as needed
    for(i = 0; i < num_frames; ++i) {
        uint16_t checksum = calculate_checksum((uint8_t*)&frames[i], sizeof(MAC_FRAME));
        frames[i].mac_checksum = htons(checksum);
    }

    // Validate frame integrity and report errors if necessary
    for(i = 0; i < num_frames; ++i) {
        if(!validate_frame(&frames[i])) {
            fprintf(stderr, "Frame %d is invalid.\n", i);
            free(buffer);
