struct heap {
    void *base;
    size_t capacity;
    size_t length;
};

void heap_init(struct heap *heap, size_t capacity) {
    heap->base = mmap(NULL, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (heap->base == MAP_FAILED) {
        return;
    }
    heap->capacity = capacity;
    heap->length = 0;
}

void *heap_push(struct heap *heap) {
    if (heap->length >= heap->capacity) {
        return NULL;
    }
    return (void*)((char*)heap->base + heap->length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void heap_pop(struct heap *heap, void *ptr) {
    heap->length--;
    memmove((char*)heap->base + sizeof(NFAPI_CRC_INDICATION_PDU_T) * heap->length, ptr, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void heap_sort(struct heap *heap) {
    for (size_t i = 0; i < heap->length - 1; ++i) {
        size_t minIndex = i;
        for (size_t j = i + 1; j < heap->length; ++j) {
            if ((*(NFAPI_CRC_INDICATION_PDU_T*)((char*)heap->base + sizeof(NFAPI_CRC_INDICATION_PDU_T) * j)).tag.sequenceNumber < (*(NFAPI_CRC_INDICATION_PDU_T*)((char*)heap->base + sizeof(NFAPI_CRC_INDICATION_PDU_T) * minIndex)).tag.sequenceNumber) {
                minIndex = j;
            }
        }
        if (minIndex != i) {
            NFAPI_CRC_INDICATION_PDU_T temp = *(NFAPI_CRC_INDICATION_PDU_T*)((char*)heap->base + sizeof(NFAPI_CRC_INDICATION_PDU_T) * minIndex);
            *(NFAPI_CRC_INDICATION_PDU_T*)((char*)heap->base + sizeof(NFAPI_CRC_INDICATION_PDU_T) * i) = temp;
        }
    }
}

void init_data_structures(NFAPI_CRC_INDICATION_PDU_T **data, size_t N) {
    struct heap heap;
    heap_init(&heap, N);
    if (heap.base == MAP_FAILED) {
        return;
    }

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *data_ptr = heap_push(&heap);
        if (data_ptr == NULL) {
            munmap(heap.base, heap.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            return;
        }
        data[i] = data_ptr;
        (*data[i])->tag.sequenceNumber = i + 1;
        (*data[i])->rnti = i;
        (*data[i])->crc_indication.crcFlag = rand() % 2;
    }

    heap_sort(&heap);
}
