// Custom linked list structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Alignment and padding attributes for custom data structures
#ifdef __linux__
    #define ATTRIBUTE __attribute__((aligned(64)))
#elif _WIN32
    #define ATTRIBUTE __declspec(align(64))
#endif

// Global variables for thread safety and resource management
ATTRIBUTE pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
ATTRIBUTE Node* head = NULL;
ATTRIBUTE size_t current_size = 0;
ATTRIBUTE size_t chunk_size = 128; // Adjust as needed

// Function to create a new NFAPI_CRC_INDICATION_PDU_T structure with given index
ATTRIBUTE NFAPI_CRC_INDICATION_PDU_T* create_pdu(size_t idx) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list_mutex);
    pdu->RX_UE_INFORMATION_TAG.sequenceNumber = idx;
    pdu->RNTI = idx % 256; // Set RNTI based on index modulo 256 for simplicity
    pdu->CRC_INDICATION_REL8_TAG.crcflag = rand() % 2;
    pthread_mutex_unlock(&list_mutex);

    return pdu;
}

// Function to dynamically allocate an array of NFAPI_CRC_INDICATION_PDU_T structures based on input size N
ATTRIBUTE Node** create_pdu_array(size_t N) {
    if (N == 0) return &head; // Special case: Return existing list for N=0
    if (N > INT_MAX - chunk_size) N = INT_MAX - chunk_size;

    Node** pdu_arr = malloc(sizeof(Node*) * ((N + chunk_size - 1) / chunk_size));
    size_t i, j;

    for (i = 0; i < (N + chunk_size - 1) / chunk_size; ++i) {
        pdu_arr[i] = malloc(chunk_size * sizeof(Node));
        for (j = 0; j < chunk_size; ++j) {
            pdu_arr[i][j].next = &pdu_arr[i][(j + 1) % chunk_size];
            pdu_arr[i][j].data = *create_pdu(current_size++);
        }
        pdu_arr[i][chunk_size - 1].next = NULL; // End of chunk
    }

    return pdu_arr;
}

// Lock-free or spinlock mechanism for managing shared resources
static inline void atomic_inc(volatile size_t* var) {
    asm volatile("" ::: "memory");
    __sync_add_and_fetch(var, 1);
}

// Helper function to insert a new structure at the end of the custom linked list
void push_back(Node* new_node) {
    pthread_mutex_lock(&list_mutex);

    if (!head) {
        head = new_node;
    } else {
        Node* tail = head;
        while (tail->next) tail = tail->next;
        tail->next = new_node;
    }

    atomic_inc(&current_size);
    pthread_mutex_unlock(&list_mutex);
}

// Helper function to delete a structure from the custom linked list by index
void erase(size_t idx) {
    if (idx >= current_size) return;

    Node* current = head, *prev = NULL;
    size_t i = 0;

    while (current && i < idx) {
        prev = current;
        current = current->next;
        ++i;
    }

    if (!current) return; // Element not found

    if (prev == NULL) head = current->next;
    else prev->next = current->next;

    free(current);
    atomic_dec(&current_size);
}

// Helper function to find a structure by index in the custom linked list
ATTRIBUTE Node* find(size_t idx) {
    if (idx >= current_size) return NULL;

    Node* current = head;
    size_t i = 0;

    while (current) {
        if (i == idx) break;
        current = current->next;
        ++i;
    }

    return current;
}
