} NFAPI_CRC_INDICATION_PDU_T;

struct pool {
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* array;
    pthread_mutex_t mutex;
};

void init_pool(struct pool* pool, size_t size) {
    pool->size = size;
    pool->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!pool->array) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        exit(1);
    }
    pthread_mutex_init(&pool->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_pool(struct pool* pool) {
    pthread_mutex_lock(&pool->mutex);
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    if (pool->size > 0) {
        pdu = &pool->array[--pool->size];
    }
    pthread_mutex_unlock(&pool->mutex);
    return pdu;
}

void put_back_to_pool(struct pool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->mutex);
    if (pdu != NULL) {
        pool->size++;
    }
    pthread_mutex_unlock(&pool->mutex);
}

void randomize(unsigned int* value, unsigned int seed) {
    *value = seed + (*value & 0x7FFFFF);
}

void create_pdus(struct pool* pool, size_t count, unsigned int seed) {
    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = get_from_pool(pool);
        if (pdu != NULL) {
            pdu->rx_ue_information_tag.value = i + 1;
