#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint64_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct list {
    Node** array;
    size_t length;
    pthread_mutex_t mutex;
};

void init_list(struct list* list) {
    list->length = 0;
    list->array = malloc(MAX_ELEMENTS * sizeof(Node*));
    for (size_t i = 0; i < MAX_ELEMENTS; ++i)
        list->array[i] = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void destroy_list(struct list* list) {
    for (size_t i = 0; i < list->length; ++i) {
        Node* node = list->array[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(list->array);
    pthread_mutex_destroy(&list->mutex);
}

void add_element(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->mutex);
    size_t index = list->length % MAX_ELEMENTS;
    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Out of memory!\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    node->data = *data;
    node->next = list->array[index];
    list->array[index] = node;
    ++list->length;
    pthread_mutex_unlock(&list->mutex);
}

void remove_element(struct list* list, size_t index) {
    pthread_mutex_lock(&list->mutex);
    if (index >= MAX_ELEMENTS || index >= list->length) {
        fprintf(stderr, "Index out of bounds!\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    Node* node = list->array[index];
    if (node == NULL) {
        fprintf(stderr, "Element not found!\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->array[index] = node->next;
    free(node);
    --list->length;
    pthread_mutex_unlock(&list->mutex);
}

void update_crcflag(struct list* list, size_t index, void (*update_func)(CRC_INDICATION_REL8_TAG*)) {
    pthread_mutex_lock(&list->mutex);
    if (index >= MAX_ELEMENTS || index >= list->length) {
        fprintf(stderr, "Index out of bounds!\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    Node* node = list->array[index];
    if (node == NULL) {
        fprintf(stderr, "Element not found!\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    update_func(&node->data.crc_indication);
    pthread_mutex_unlock(&list->mutex);
}

