void nfapi_crc_pdu_init(NFAPI_CRC_INDICATION_PDU_T** arr, size_t N, uint32_t seed) {
    *arr = (NFAPI_CRC_INDICATION_PDU_T*) calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*arr) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T* current = *arr;
    int rntis[MAX_RNTIS] = { 0 };

    for (size_t i = 0; i < N; ++i) {
        size_t j;
        do {
            current->rnti = rand() % MAX_RNTIS;
            j = 0;
        } while (rntis[current->rnti]);

        rntis[current->rnti] = 1;
        current->crc_indication.crcflag = (rand() & FLAG_MASK) >> 31;
    }
}

void validate(NFAPI_CRC_INDICATION_PDU_T* arr, size_t N) {
    for (size_t i = 0; i < N; ++i) {
