    for (size_t i = 0; i < max_elements; ++i) {
        size_t read = fread(&tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
        if (read != 1) break;
        read = fread(&rnti, sizeof(unsigned int), 1, file);
        if (read != 1) break;
