["```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

struct node {
    long key;
    int value;
    struct node *next;
};

typedef struct node Node;

// Function to initialize and manage the dynamic linked list
Node* create_list(long size, int min, int max) {
    if (size <= 0 || min > max) return NULL;

    srand(time(NULL));
    Node *head = NULL, *current = NULL, *temp;

    for (long i = 0; i < size; ++i) {
        temp = malloc(sizeof(Node));
        if (!temp) {
            free_list(head);
            return NULL;
        }
        temp->key = i;
        temp->value = rand() % (max - min + 1) + min;
        temp->next = NULL;

        if (!head) {
            head = current = temp;
        } else {
            current->next = temp;
            current = temp;
        }
    }

    return head;
}

// Function to free memory of the dynamic linked list
void free_list(Node *head) {
    Node *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Thread-safe version of create_list using pthread_mutex_t for synchronization
void* thread_create_list(void *args) {
    long size, min, max;
    Node *head = NULL, *current = NULL, *temp;

    if (pthread_mutex_lock((pthread_mutex_t*) args)) return NULL;

    if (get_config(&size, &min, &max) != 0) {
        pthread_mutex_unlock((pthread_mutex_t*) args);
        return NULL;
    }

    srand(time(NULL));
    for (long i = 0; i < size; ++i) {
        temp = malloc(sizeof(Node));
        if (!temp) {
            free_list_threadsafe(head, (pthread_mutex_t*) args);
            pthread_mutex_unlock((pthread_mutex_t*) args);
            return NULL;
        }
        temp->key = i;
        temp->value = rand() % (max - min + 1) + min;
        temp->next = NULL;

        if (!head) {
            head = current = temp;
        } else {
            pthread_mutex_lock((pthread_mutex_t*) args);
            current->next = temp;
            current = temp;
            pthread_mutex_unlock((pthread_mutex_t*) args);
        }
    }

    pthread_mutex_unlock((pthread_mutex_t*) args);
    return head;
}

// Thread-safe version of free_list using pthread_mutex_t for synchronization
void free_list_threadsafe(Node *head, pthread_mutex_t *mutex) {
    Node *temp;
    pthread_mutex_lock(mutex);
    while (head != NULL) {
        temp = head;
        head = head->next;
        pthread_mutex_unlock(mutex);
        free(temp);
        pthread_mutex_lock(mutex);
    }
    pthread_mutex_unlock(mutex);
}
