#include "list_manager.h"

ListManager* list_manager_create() {
    ListManager *manager = malloc(sizeof(ListManager));
    if (!manager) return NULL;
    manager->head = NULL;
    manager->tail = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void list_manager_destroy(ListManager *manager) {
    if (!manager) return;
    NFAPI_CRC_INDICATION_PDU_T *node = list_manager_get_head(manager);
    while (node) {
        NFAPI_CRC_INDICATION_PDU_T *next = node->next;
        free(node);
        node = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

NFAPI_CRC_INDICATION_PDU_T* list_manager_get_head(const ListManager *manager) {
    return manager->head;
}

bool list_manager_add(ListManager *manager, const NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&manager->lock);
    if (!manager) {
        pthread_mutex_unlock(&manager->lock);
        return false;
    }
    if (manager->head == NULL) {
        manager->head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->head) {
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
        memcpy(manager->head, node, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->tail = manager->head;
    } else {
        manager->tail->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->tail->next) {
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
        memcpy(manager->tail->next, node, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->tail = manager->tail->next;
    }
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return true;
}

void list_manager_remove_by_tag(ListManager *manager, uint32_t tag) {
    pthread_mutex_lock(&manager->lock);
    if (!manager || manager->count == 0) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *node = manager->head;
    while (node && node->RX_UE_INFORMATION_TAG != tag) {
        node = node->next;
    }
    if (!node) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    if (node == manager->head) {
        manager->head = node->next;
    } else if (node == manager->tail) {
        node->prev->next = NULL;
        manager->tail = node->prev;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    free(node);
    manager->count--;
    pthread_mutex_unlock(&manager->lock);
}

void list_manager_iterate(const ListManager *manager, void (*action)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!manager || !action) return;
    pthread_mutex_lock(&manager->lock);
    NFAPI_CRC_INDICATION_PDU_T *node = manager->head;
    while (node) {
        NFAPI_CRC_INDICATION_PDU_T *next = node->next;
        action(node);
        node = next;
    }
    pthread_mutex_unlock(&manager->lock);
}
