typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
    pthread_mutex_t lock;
} Node;

struct List {
    unsigned int capacity, size;
    Node *head, *tail;
    pthread_mutex_t list_lock;
};

static void init_list(struct List *list, unsigned int capacity) {
    list->capacity = capacity;
    list->size = 0;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->list_lock, NULL);
}

static Node* create_node(const NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = *data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    return new_node;
}

static bool is_unique(struct List *list, RNTI rnti) {
    Node *current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti)
            return false;
        current = current->next;
    }
    return true;
}

static bool add_to_list(struct List *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    if (list->size >= list->capacity && list->capacity < 10000) {
        unsigned int new_capacity = list->capacity * 2;
        Node **new_nodes = realloc(list->head, sizeof(Node) * new_capacity);
        if (!new_nodes) return false;
        list->head = new_nodes;
        list->capacity = new_capacity;
    }

    if (is_unique(list, data->rnti)) {
        pthread_mutex_lock(&list->list_lock);

        Node *new_node = create_node(data);
        if (!new_node) {
            pthread_mutex_unlock(&list->list_lock);
            return false;
        }

        if (list->size == 0) {
            list->head = new_node;
            list->tail = new_node;
        } else {
            list->tail->next = new_node;
            list->tail = new_node;
        }
        list->size++;

        pthread_mutex_unlock(&list->list_lock);
        return true;
    }

    pthread_mutex_unlock(&list->list_lock);
    return false;
}

static void delete_from_list(struct List *list, RNTI rnti) {
    pthread_mutex_lock(&list->list_lock);

    Node *current = list->head;
    Node **prev = &list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            *prev = current->next;
            free(current);
            list->size--;
            break;
        }
        prev = &current->next;
        current = current->next;
    }

    pthread_mutex_unlock(&list->list_lock);
}
```

