            // Handle potential hash collisions...

            TCP_CONNECTION_RECORD* record = &*it;
            data[hash].erase(it);
            --num_connections;
            pthread_mutex_unlock(&lock);
            return record;
        }

        TCP_CONNECTION_RECORD* record = new TCP_CONNECTION_RECORD();
        memset(record, 0, sizeof(TCP_CONNECTION_RECORD));
        record->addr = addr;
        record->status = status;
        record->connection_id = hash;
        ++num_connections;

        if (static_cast<float>(num_connections) / MAX_HASH_BUCKETS >= HASH_LOAD_FACTOR) {
            resize_hash_buckets();
        }

        pthread_mutex_unlock(&lock);
        return record;
    }

private:
    void resize_hash_buckets() {
        // Resize hash buckets and rehash existing connections...
    }
};
