['Here is a basic implementation of the requested C function using doubly-linked list for record storage and dynamic memory allocation. This code does not include LRU cache compression or benchmarking, but it serves as a starting point for further optimization.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    struct Record *prev;
    struct Record *next;
} Record;

Record* create_record() {
    Record *new = malloc(sizeof(Record));
    if (!new) return NULL;
    new->value = 0;
    new->prev = NULL;
    new->next = NULL;
    return new;
}

void insert_record(Record **head, Record *new) {
    if (*head == NULL) {
        *head = new;
    } else {
        new->next = *head;
        (*head)->prev = new;
        *head = new;
    }
}

void delete_record(Record **head, Record *to_delete) {
    if (to_delete == NULL || *head == NULL) return;
    if (to_delete == *head) {
        *head = to_delete->next;
        if (*head) (*head)->prev = NULL;
        free(to_delete);
    } else {
        Record *curr = *head;
        while (curr && curr != to_delete) {
            curr = curr->next;
        }
        if (!curr) return;
        if (curr->next == to_delete) {
            curr->next = to_delete->next;
            free(to_delete);
        } else {
            curr->prev->next = to_delete->next;
            to_delete->next->prev = curr->prev;
            free(to_delete);
        }
    }
}

int** init_memory(size_t initial_records, size_t min, size_t max, float capacity) {
    int *keys = malloc(initial_records * sizeof(int));
    if (!keys) return NULL;
    for (size_t i = 0; i < initial_records; ++i) keys[i] = min + rand() % (max - min + 1);

    Record **offsets = malloc(initial_records * sizeof(Record*));
    if (!offsets) {
        free(keys);
        return NULL;
    }
    for (size_t i = 0; i < initial_records; ++i) offsets[i] = create_record();

    size_t capacity_size = (initial_records * capacity + 1.0) / capacity;
    Record **records = malloc(capacity_size * sizeof(Record*));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }
    for (size_t i = 0; i < initial_records; ++i) insert_record(&records[i / capacity], offsets[i]);

    return &keys, records;
}

void cleanup(int *keys, Record **records) {
    free(keys);
    for (size_t i = 0; i < capacity_size; ++i) delete_record(&records[i], records[i]);
    free(records);
}
```

