[' Here's a basic implementation of the requested functions in C using a linked list for memory efficiency and ease of expansion. I've also included a simple sorting function based on quicksort algorithm for sorting tasks by priority.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct task {
    int priority;
    char* description;
    struct task* next;
} Task;

Task* create_task(int priority, const char* description) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) return NULL;

    new_task->priority = priority;
    new_task->description = strdup(description);
    if (!new_task->description) {
        free(new_task);
        return NULL;
    }

    new_task->next = NULL;
    return new_task;
}

Task* add_task(Task** head, Task* new_task) {
    if (!head || !(*head)) {
        *head = new_task;
        return new_task;
    }

    Task* current = *head;
    while (current->next) current = current->next;
    current->next = new_task;
    return new_task;
}

void sort_tasks(Task** head) {
    if (!head || !(*head)) return;

    void swap(Task* a, Task* b) {
        Task temp = *a;
        *a = *b;
        *b = temp;
    }

    Task* pivot = (*head)->priority;
    Task* high = NULL, *low = NULL, *current = (*head);

    while (current) {
        if (current->priority < pivot) {
            if (!low) low = current;
            high = current;
        } else if (high && current->priority >= pivot) {
            swap(low, high);
            low = low->next;
            high = high->next;
        }

        current = current->next;
    }

    if (low) sort_tasks(&low);
    if (high) sort_tasks(&high);
}

void iterate_tasks(const Task** head) {
    if (!head || !(*head)) return;

    const Task* current = *head;
    while (current) {
        printf("Priority: %d, Description: %s\n", current->priority, current->description);
        current = current->next;
    }
}
```

