NFAPI_CRC_INDICATION_PDU_T *populate_crc_indications(int *input_arr, size_t arr_size) {
    static NFAPI_CRC_INDICATION_PDU_T indications[NUM_ENTRIES];
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    sem_t semaphore;
    int largest_input = 0;

    // Initialize the semaphore
    sem_init(&semaphore, 0, NUM_ENTRIES);

    for (size_t i = 0; i < arr_size; ++i) {
        if (arr_output[i] > largest_input)
            largest_input = arr_output[i];
    }

    // Populate the indications array in a thread-safe manner
    for (size_t i = 0; i < NUM_ENTRIES; ++i) {
        pthread_mutex_lock(&mutex);
        while (semaphore.sem_value >= NUM_ENTRIES - i) {
            pthread_cond_wait(&cond, &mutex);
        }
        sem_post(&semaphore);

        indications[i].rx_ue_information_tag = rand();
        indications[i].rnti = rand();
        indications[i].crc_indication_rel8_tag = rand();
        indications[i].crcflag = (rand() % 2) * 256 + 128; // Ensure the value is within expected range

        pthread_mutex_unlock(&mutex);
    }

    return indications;
}

