    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU;

#define MAX_STRUCTURES 10000
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int allocate_pdus(NFAPI_CRC_INDICATION_PDU** pdu_array) {
    *pdu_array = (NFAPI_CRC_INDICATION_PDU*) malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (*pdu_array == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return 1;
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        (*pdu_array)[i].crc_indication.crcflag = rand() % 2;
    }
    pthread_mutex_unlock(&mutex);

    return 0;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU* pdu_array) {
    if (pdu_array != NULL) {
        free(pdu_array);
    }
}
