typedef struct _LIST_HEAD {
    NFAPI_CRC_INDICATION_PDU *next;
    NFAPI_CRC_INDICATION_PDU *prev;
} LIST_HEAD;

LIST_HEAD *list_head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void init_list() {
    if (list_head == NULL) {
        list_head = malloc(sizeof(LIST_HEAD));
        if (list_head == NULL) {
            fprintf(stderr, "Failed to allocate memory for list head.\n");
            exit(EXIT_FAILURE);
        }
        list_head->next = list_head;
        list_head->prev = list_head;
    }
}

NFAPI_CRC_INDICATION_PDU *get_new_node() {
    NFAPI_CRC_INDICATION_PDU *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (new_node == NULL) {
        fprintf(stderr, "Failed to allocate memory for new node.\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU *new_node) {
    pthread_mutex_lock(&list_lock);
    LIST_HEAD *temp = list_head->next;
    new_node->next = temp;
    new_node->prev = list_head;
    temp->prev->next = new_node;
    temp->prev = new_node;
    pthread_mutex_unlock(&list_lock);
}

NFAPI_CRC_INDICATION_PDU *remove_from_list(NFAPI_CRC_INDICATION_PDU *node) {
    pthread_mutex_lock(&list_lock);
    LIST_HEAD *temp = node->prev;
    temp->next = node->next;
    node->next->prev = temp;
