#include <stdbool.h>

typedef struct {
    uint8_t* data;
    size_t length;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

static const size_t MAX_POOL_SIZE = 1024; // Adjust as per your requirements
static NFAPI_CRC_INDICATION_PDU_T* pool;
static size_t pool_size = 0, used_pool_size = 0;
static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    if (used_pool_size >= MAX_POOL_SIZE) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool[used_pool_size];
    pthread_mutex_init(&(pdu->lock), NULL);
    pdu->data = malloc(4096); // Adjust the buffer size as per your needs
    if (!pdu->data) return NULL;
    pdu->length = 0;

    used_pool_size++;
    return pdu;
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || !pool) return;

    free(pdu->data);
    pthread_mutex_destroy(&(pdu->lock));

    pmemmove(&pool[used_pool_size - 1], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    used_pool_size--;
}

void reset_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || !pool) return;

    pthread_mutex_lock(&(pdu->lock));
    free(pdu->data);
    pdu->data = malloc(4096); // Adjust the buffer size as per your needs
    if (!pdu->data) {
        pthread_mutex_unlock(&(pdu->lock));
        destroy_pdu(pdu);
        return;
    }
    pdu->length = 0;
    pthread_mutex_unlock(&(pdu->lock));
}

void manage_pool() {
    if (used_pool_size > MAX_POOL_SIZE * 0.9) {
        size_t new_pool_size = used_pool_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pool = realloc(pool, new_pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) return;
        pool = new_pool;
        MAX_POOL_SIZE = new_pool_size;
    }
}
