void* parse_logfile(void *arg) {
    LOG_FILE_CONTEXT_T *ctx = arg;

    char line[LINE_BUFFER_SIZE];
    size_t pos = 0;
    while (true) {
        if (sem_wait(ctx->sem_file)) break;

        memset(line, 0, LINE_BUFFER_SIZE);
        size_t read = fgets(line + pos, LINE_BUFFER_SIZE - pos, ctx->file);
        if (!read) {
            sem_post(ctx->sem_file);
            break;
        }

        size_t len = strlen(line);
        if (len <= pos || line[pos] != ',') continue;

        // Parse the numerical fields and calculate average
        double sum = 0.0;
        int num_fields = 0;
        for (size_t i = pos + 1; i < len && line[i] != ','; ++i) {
            if (line[i] >= '0' && line[i] <= '9') {
                sum += atof(&line[pos + 1]);
                num_fields++;
                if (num_fields == 2) break;
            }
