        // Store the average in the PDUs
        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu();
        pdu->rxti += sum / num_fields;
        free_pdu(pdu);

        pos = len;
        sem_post(ctx->sem_file);
    }

    fclose(ctx->file);
    free(ctx->filename);
    free(ctx->sem_file);
    free(ctx);
}

