size_t load_config_file(struct config_file* file, NFAPI_CRC_INDICATION_PDU_T** data, size_t* num_entries) {
    size_t num_processed = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_t threads[256]; // Adjust the number of threads as needed for concurrency
    NFAPI_CRC_INDICATION_PDU_T* entries = NULL;
    size_t entry_count = 0;

    while (!feof(file->file)) {
        size_t read = fread(file->buffer, sizeof(char), sizeof(file->buffer) - 1, file->file);
        if (read == 0 && !feof(file->file)) {
            perror("Error reading from configuration file");
            exit(1);
        }
        file->pos += read;
