    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_create(&threads[i], NULL, process_config_line, &entries, &entry_count, file);
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }

    *data = malloc(entry_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(*data, entries, entry_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    free(entries);
    *num_entries = entry_count;

    pthread_mutex_destroy(&lock);

    return num_processed;
}

void* process_config_line(void* arg, void* aux_arg) {
    NFAPI_CRC_INDICATION_PDU_T** data = arg;
    size_t* entry_count = aux_arg;
    struct config_file* file = (struct config_file*)calloc(1, sizeof(struct config_file));
    char line[256];

    pthread_mutex_lock(&lock);

    while (!feof(file->file)) {
        size_t read = fread(line, sizeof(char), sizeof(line) - 1, file->file);
        if (read == 0 && !feof(file->file)) {
            perror("Error reading from configuration file");
            exit(1);
        }
        line[read] = '\0';

        if (strstr(line, "RX_UE_INFORMATION_TAG") != NULL) {
            sscanf(line, "%s %u", line, &((*data)[*entry_count]->rx_ue_information_tag));
        } else if (strstr(line, "RNTI") != NULL) {
            sscanf(line, "%s %hu", line, &(unsigned short int)&((*data)[*entry_count]->rnti));
        } else if (strstr(line, "CRC_INDICATION_REL8_TAG") != NULL) {
            sscanf(line, "%s %u", line, &((*data)[*entry_count]->crc_indication_rel8_tag));
        }

        file->pos += read;
    }

    pthread_mutex_unlock(&lock);

    (*data)[*entry_count]->crcflag = rand() % 2 == 0 ? true : false;

    (*entry_count)++;

    free(file);

    return NULL;
}
