// Custom memory allocator (for integration with existing packet processing framework)
void* custom_malloc(size_t size);
void custom_free(void* ptr);

typedef struct MAC_PACKET {
    uint32_t PACKET_IDENTIFIER;
    uint16_t SEQUENCE_NUMBER;
    bool ACK_INDICATION;
    bool ACKFLAG;
} MAC_PACKET_T;

// Global variables for packet loss detection and sequence number validation
volatile bool enable_loss_detection = true;
pthread_mutex_t seq_num_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned int highest_seq_num = 0;

MAC_PACKET_T* initialize_dynamic_array(size_t size) {
    MAC_PACKET_T* packets = (MAC_PACKET_T*)custom_malloc(sizeof(MAC_PACKET_T) * size);
    if (!packets) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        packets[i].PACKET_IDENTIFIER = i + 1;
        packets[i].SEQUENCE_NUMBER = highest_seq_num++;
        packets[i].ACK_INDICATION = rand() % 2 == 0;
        packets[i].ACKFLAG = rand() % 2 == 0;
    }

    return packets;
}

void destroy_dynamic_array(MAC_PACKET_T* packets, size_t size) {
    custom_free(packets);
}

// Validates sequence numbers and detects reordering or packet loss
void validate_sequence_numbers(MAC_PACKET_T* packets, size_t size) {
    pthread_mutex_lock(&seq_num_mutex);
    for (size_t i = 1; i < size; ++i) {
        if (packets[i].SEQUENCE_NUMBER <= packets[i - 1].SEQUENCE_NUMBER) {
            // Packet loss or reordering detected
            if (enable_loss_detection) {
                fprintf(stderr, "Packet loss or reordering detected!\n");
            }
        }
    }
    pthread_mutex_unlock(&seq_num_mutex);
}
