#include <iostream>
#include <memory>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <boost/asio.hpp>
#include <boost/log/trivial.hpp>

struct MACEntityConfig {
    std::string id;
    std::vector<std::shared_ptr<PDCPContext>> pdcpContexts;
    std::vector<std::weak_ptr<RLCMode>> rlcModes;
};

class MACEntityManager {
private:
    std::unordered_map<std::string, std::shared_ptr<MACEntityConfig>> entities_;
    mutable std::mutex entities_mutex_;
    boost::asio::io_context ioContext_;

public:
    void add(const std::string& id, const MACEntityConfig& config) {
        std::lock_guard lock(entities_mutex_);

        if (entities_.find(id) != entities_.end()) {
            BOOST_LOG_TRIVIAL(warning) << "MAC entity ID already exists: " << id;
            return;
        }

        auto entity = std::make_shared<MACEntityConfig>(config);
        entities_[id] = entity;
    }

    void update(const std::string& id, const MACEntityConfig& config) {
        std::lock_guard lock(entities_mutex_);

        auto it = entities_.find(id);
        if (it == entities_.end()) {
            BOOST_LOG_TRIVIAL(error) << "MAC entity not found: " << id;
            return;
        }

        (*it->second) = config;
    }

    void remove(const std::string& id) {
        std::lock_guard lock(entities_mutex_);

        auto it = entities_.find(id);
        if (it == entities_.end()) {
            BOOST_LOG_TRIVIAL(error) << "MAC entity not found: " << id;
            return;
        }

        entities_.erase(it);
    }

    // ... other functions for managing PDCP contexts and RLC modes
};
