void init_pool() {
    sem_init(&pool_mutex, 0, 1);
    pthread_mutex_init(&log_mutex, NULL);
}

LTE_PHY_RRC_INTERFACE_STRUCT* acquire_from_pool() {
    LTE_PHY_RRC_INTERFACE_STRUCT* data;
    sem_wait(&pool_mutex);

    if (head != NULL) {
        Node* temp = head;
        head = head->next;
        data = temp->data;
        free(temp);
    } else {
        data = malloc(sizeof(LTE_PHY_RRC_INTERFACE_STRUCT));
        if (data == NULL) {
            fprintf(stderr, "Out of memory\n");
            sem_post(&pool_mutex);
            return NULL;
        }
    }

    sem_post(&pool_mutex);
    return data;
}

void release_to_pool(LTE_PHY_RRC_INTERFACE_STRUCT* data) {
    sem_wait(&pool_mutex);

    if (head == NULL) {
        head = malloc(sizeof(Node));
        if (head == NULL) {
            fprintf(stderr, "Out of memory\n");
            sem_post(&pool_mutex);
            return;
        }
        head->data = data;
        head->next = NULL;
    } else {
        Node* temp = malloc(sizeof(Node));
        if (temp == NULL) {
            fprintf(stderr, "Out of memory\n");
            sem_post(&pool_mutex);
            return;
        }
        temp->data = data;
        temp->next = head;
        head = temp;
