        *memory_usage = 0;
        return NULL;
    }
    *memory_usage = size * sizeof(long);
    return array;
}

int* create_int_array(size_t size, bool unique, size_t* memory_usage) {
    int i, j, found;
    int* array = (int*)malloc(size * sizeof(int));
    if (!array) {
        // Handle allocation failure and return error code or NULL
        *memory_usage = 0;
        return NULL;
    }
    *memory_usage = size * sizeof(int);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (i = 0; i < size; ++i) {
        found = false;
        for (j = 0; j < i; ++j) {
            if (array[j] == array[i]) {
                found = true;
                break;
            }
        }
        if (!found && unique) {
            pthread_mutex_lock(&mutex);
            // Check for duplicates again, as another thread might have added a duplicate since the first check.
            found = false;
            for (j = 0; j < i; ++j) {
