    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct array {
    unsigned long size;
    Node** data;
    pthread_mutex_t lock;
};

void init_array(struct array* arr, unsigned long size) {
    arr->size = size;
    arr->data = calloc(arr->size, sizeof(Node*));
    if (arr->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for array.\n");
        exit(EXIT_FAILURE);
    }
    arr->lock = PTHREAD_MUTEX_INITIALIZER;
}

void resize_array(struct array* arr, unsigned long new_size) {
    if (new_size <= arr->size) return;

    Node** temp = calloc((unsigned int)new_size, sizeof(Node*));
    if (temp == NULL) {
        fprintf(stderr, "Failed to allocate memory for expanded array.\n");
        exit(EXIT_FAILURE);
    }

    unsigned long i;
    pthread_mutex_lock(&arr->lock);
    for (i = 0; i < arr->size && i < new_size; ++i) {
        if (arr->data[i]) temp[i] = arr->data[i];
        else temp[i] = NULL;
    }
    free(arr->data);
    arr->data = temp;
    arr->size = new_size;
    pthread_mutex_unlock(&arr->lock);
}

void insert_at(struct array* arr, unsigned long index, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (index >= arr->size) return;

    pthread_mutex_lock(&arr->lock);
    if (index < arr->size && !arr->data[index]) {
        arr->data[index] = malloc(sizeof(Node));
        if (!arr->data[index]) {
            fprintf(stderr, "Failed to allocate memory for new element.\n");
            pthread_mutex_unlock(&arr->lock);
            exit(EXIT_FAILURE);
        }
        arr->data[index]->data = *data;
        arr->data[index]->next = NULL;
    } else {
        unsigned long i = index;
        for (Node* curr = arr->data[i]; curr != NULL; curr = curr->next) i++;

        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for new element.\n");
            pthread_mutex_unlock(&arr->lock);
            exit(EXIT_FAILURE);
        }
        new_node->data = *data;
        new_node->next = curr;
        arr->data[i] = new_node;
    }
    pthread_mutex_unlock(&arr->lock);
}

void delete_at(struct array* arr, unsigned long index) {
    if (index >= arr->size) return;

    pthread_mutex_lock(&arr->lock);
    if (index < arr->size && arr->data[index]) {
        Node* to_free = arr->data[index];
        arr->data[index] = to_free->next;
        free(to_free);
    }
    pthread_mutex_unlock(&arr->lock);
}

bool get_at(const struct array* arr, unsigned long index, NFAPI_CRC_INDICATION_PDU_T* data) const {
    if (index >= arr->size || !arr->data[index]) return false;

    *data = arr->data[index]->data;
    return true;
}

void free_array(struct array* arr) {
    pthread_mutex_lock(&arr->lock);
    for (unsigned long i = 0; i < arr->size; ++i) if (arr->data[i]) free(arr->data[i]);
    free(arr->data);
    arr->data = NULL;
    pthread_mutex_unlock(&arr->lock);
}
