const fs = require('fs');
const readline = require('readline');

function readLargeFile(directory, callback) {
    const fileStream = fs.createReadStream(directory);
    const rl = readline.createInterface({
        input: fileStream,
        crlfDelay: Infinity
    });

    let lineCount = 0;
    let wordSet = new Set();

    rl.on('line', (line) => {
        ++lineCount;
        [...line.split(/\s+/)].forEach((word) => wordSet.add(word));
    });

    fileStream.on('error', (err) => {
        console.error(`Error reading file: ${err}`);
        callback({ error: err });
    });

    rl.on('close', () => {
        const uniqueWords = wordSet.size;
        callback({ lineCount, uniqueWords });
    });
}
