namespace nfapi {
struct CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    std::bitset<8> CRC_INDICATION_REL8_TAG;
};

class DynamicList final {
public:
    DynamicList() : pool_{[](){
        auto p = std::make_unique<CRC_INDICATION_PDU_T>();
        p->RX_UE_INFORMATION_TAG = ++nextTag_;
        p->RNTI = nextRNTI_++;
        p->CRC_INDICATION_REL8_TAG.reset();
        boost::random::shuffle(p->CRC_INDICATION_REL8_TAG);
        return std::move(p);
    }},
    dataSource_(nullptr), updateCallback_(nullptr) {
        nextTag_.store(0, std::memory_order_relaxed);
        nextRNTI_.store(0, std::memory_order_relaxed);
    }

    ~DynamicList() {
        if (pool_) pool_.reset();
    }

    std::shared_ptr<CRC_INDICATION_PDU_T> addElement() {
        auto p = pool_.lock();
        if (!p) {
            try {
                p = pool_.emplace();
            } catch (...) {
                std::cerr << "Failed to allocate new element" << std::endl;
                return {};
            }
        }
        dataSource_(this);
        return p;
    }

    void updateDataSource(std::function<void(DynamicList*)> callback) {
        boost::tss_thread_key<DynamicList*> key{[](){return new DynamicList();}};
        dataSource_ = [callback](DynamicList* list){
            auto local = key.local();
            if (local != list) return; // Prevent multiple updates from different threads
            callback(list);
        };
    }

private:
    std::atomic<uint32_t> nextTag_;
    std::atomic<uint16_t> nextRNTI_;
    std::unique_ptr<std::shared_ptr<CRC_INDICATION_PDU_T>> pool_;
    std::function<void(DynamicList*)> dataSource_;
    std::function<void(DynamicList*)> updateCallback_;
};
} // namespace nfapi
