    if (num_elements >= MAX_ELEMENTS) {
        log_message("Failed to allocate array due to limit reached\n");
        pthread_mutex_unlock(&array_lock);
        return 0;
    }

    uint32_t tag = MIN_TAG + num_elements;
    while (find_tag(tag)) {
        tag++;
        if (num_elements >= MAX_ELEMENTS) {
            log_message("Failed to allocate array due to limit reached\n");
            pthread_mutex_unlock(&array_lock);
            return 0;
        }
    }

    num_elements++;
    pthread_mutex_unlock(&array_lock);
    return tag;
}

bool find_tag(uint32_t tag) {
