    pthread_mutex_lock(&array_lock);
    element->RX_UE_INFORMATION_TAG = tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG = crcflag;
    elements[num_elements - 1] = *element;
    pthread_mutex_unlock(&array_lock);

    return element;
