        return;
    }

    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        node->next = NULL;
        list->tail->next = node;
        list->tail = node;
    }

    ++list->count;
    pthread_mutex_unlock(&list->mutex);
}

