// largeFileIO.js
const fs = require('fs');

function readLargeFile(filePath) {
    let buffer = Buffer.allocUnsafe(10485760); // 10 MB buffer
    let fileBuffer = Buffer.from([]);

    return new Promise((resolve, reject) => {
        const readStream = fs.createReadStream(filePath, { highWaterMark: 10485760 });
        let pos = 0;

        readStream.on('data', chunk => {
            const remainingBufferSpace = buffer.byteLength - pos;
            if (chunk.length > remainingBufferSpace) {
                fileBuffer = Buffer.concat([fileBuffer, chunk]);
                pos = 0;
            } else {
                buffer.write(chunk, pos);
                pos += chunk.length;
            }
        });

        readStream.on('end', () => resolve(fileBuffer));

        readStream.on('error', err => reject(err));
    });
}
