function MonitorDirectory(directory, options) {
    timeWindow = options.timeWindow || 60 * 60 * 1000; // Default to 1 hour

    const watcher = chokidar.watch(directory, { persistent: true });

    watcher.on('add', (filePath) => processFile(filePath));
    watcher.on('change', (filePath) => processFile(filePath));

    function processFile(filePath) {
        fs.stat(filePath, (err, stats) => {
            if (err) {
                console.error(`Error processing file ${filePath}:`, err);
                return;
            }

            const contentType = mimetype(path.extname(filePath));
            currentDirStatistics[contentType] = (currentDirStatistics[contentType] || 0) + 1;

            if (!stats.isDirectory()) {
                fs.readFile(filePath, 'utf8', (err, data) => {
                    if (err) {
                        console.error(`Error reading file ${filePath}:`, err);
                        return;
                    }

                    // Perform additional processing here as needed
                });
            }

            if (moment().isAfter(moment().subtract(timeWindow, 'milliseconds'))) {
                const mostFrequentContentType = Object.entries(currentDirStatistics)
                    .reduce((prev, [type, count]) => prev[count] > count ? prev : [count, type], [Infinity, null])[1];

                console.log(`Most frequent content type: ${mostFrequentContentType}`);
                currentDirStatistics = {};
            }
        });
    }
}

function mimetype(ext) {
    switch (ext.toLowerCase()) {
        case '.html':
        case '.htm':
            return 'text/html';
        // Add additional cases as needed for other file types
    }

    return 'application/octet-stream';
}
