#define MAX_ENTRIES 10000
#define TIMEOUT 10 // in seconds

struct PDCP_RX_UNIT_T {
    enum PDCP_RX_UNIT tag;
    uint32_t SN;
    time_t lastUpdated;
};

typedef struct {
    struct PDCP_RX_UNIT_T *entries;
    size_t capacity;
    size_t size;
    pthread_rwlock_t rwlock; // Read-Write Lock for thread safety
} RxUnitArray;

RxUnitArray* createRxUnitArray() {
    RxUnitArray *array = malloc(sizeof(RxUnitArray));
    array->entries = malloc(MAX_ENTRIES * sizeof(struct PDCP_RX_UNIT_T));
    array->capacity = MAX_ENTRIES;
    array->size = 0;
    array->rwlock = PTHREAD_RWLOCK_INITIALIZER;
    return array;
}

void removeStaleEntries(RxUnitArray *array) {
    time_t currentTime = time(NULL);
    for (size_t i = 0; i < array->size; ++i) {
        if (currentTime - array->entries[i].lastUpdated > TIMEOUT) {
            memmove(&array->entries[i], &array->entries[i+1], sizeof(struct PDCP_RX_UNIT_T) * (array->size-i-1));
            --array->size;
        }
    }
}

void logInfo(const char* message, RxUnitArray *array) {
    printf("%s: entries=%zu, removed=%zu\n", message, array->size, array->capacity - array->size);
}

void* updateEntry(void* data) {
    RxUnitArray *array = (RxUnitArray*)data;
    pthread_rwlock_wrlock(&array->rwlock);
    // Update the structure with new data and update lastUpdated timestamp
    struct PDCP_RX_UNIT_T *entry = &array->entries[array->size];
    entry->tag = PDCP_RX_UNIT; // Assuming PDCP_RX_UNIT is an enumeration value
    entry->SN = 123456;
    entry->lastUpdated = time(NULL);
    ++array->size;
    pthread_rwlock_unlock(&array->rwlock);
    return NULL;
}

void startLoggingAndUpdating(RxUnitArray *array) {
    pthread_t loggingThread, updatingThread;
    pthread_create(&loggingThread, NULL, logInfo, array);
    pthread_create(&updatingThread, NULL, updateEntry, array);
}
