```cpp
#include <boost/dynamic_bitset.hpp>
#include <pthread.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct LTE_PHY_FRAME_INFO_T {
    TX_FRAME_INFO tx;
    RX_FRAME_INFO rx;
    PHY_STATS phy_stats;
} LTE_PHY_FRAME_INFO;

// Third-party analytics platform callback function
typedef void (*analyticsCallback)(LTE_PHY_FRAME_INFO* frame);

struct MEMORY_MANAGER {
    size_t maxSizeBytes;
    size_t allocatedBytes;
    LTE_PHY_FRAME_INFO** frames;
    pthread_mutex_t mutex;
    sem_t semaphore;
};

MEMORY_MANAGER* memoryManagerInit(size_t maxSizeBytes) {
    MEMORY_MANAGER *mm = malloc(sizeof(MEMORY_MANAGER));
    mm->maxSizeBytes = maxSizeBytes;
    mm->allocatedBytes = 0;
    mm->frames = NULL;
    pthread_mutex_init(&mm->mutex, NULL);
    sem_init(&mm->semaphore, 0, 1);
    return mm;
}

void memoryManagerFree(MEMORY_MANAGER* mm) {
    free(mm->frames);
    pthread_mutex_destroy(&mm->mutex);
    sem_destroy(&mm->semaphore);
    free(mm);
}

LTE_PHY_FRAME_INFO* memoryManagerAllocFrame(MEMORY_MANAGER *mm) {
    if (mm->allocatedBytes + sizeof(LTE_PHY_FRAME_INFO) > mm->maxSizeBytes)
        return NULL;

    pthread_mutex_lock(&mm->mutex);
    LTE_PHY_FRAME_INFO* frame = &mm->frames[mm->allocatedBytes / sizeof(LTE_PHY_FRAME_INFO)];
    mm->allocatedBytes += sizeof(LTE_PHY_FRAME_INFO);
    pthread_mutex_unlock(&mm->mutex);

    return frame;
}

void memoryManagerFreeFrame(MEMORY_MANAGER *mm, LTE_PHY_FRAME_INFO* frame) {
    pthread_mutex_lock(&mm->mutex);
    if (frame >= mm->frames && frame < mm->frames + mm->allocatedBytes / sizeof(LTE_PHY_FRAME_INFO)) {
        memset(frame, 0, sizeof(LTE_PHY_FRAME_INFO));
        mm->allocatedBytes -= sizeof(LTE_PHY_FRAME_INFO);
    }
    pthread_mutex_unlock(&mm->mutex);
}

void processFrames(MEMORY_MANAGER *mm, analyticsCallback callback) {
    pthread_mutex_lock(&mm->mutex);
    LTE_PHY_FRAME_INFO* frame = mm->frames;
    size_t framesCount = mm->allocatedBytes / sizeof(LTE_PHY_FRAME_INFO);
    mm->allocatedBytes = 0;
    pthread_mutex_unlock(&mm->mutex);

    for (size_t i = 0; i < framesCount; ++i) {
        if (callback)
            callback(frame++);
    }
}
