    let currentBatch = 1;
    let fileCount = 0;

    function processDirectoryRecursively(dirPath) {
        fs.readdirSync(dirPath).forEach((file) => {
            const fullPath = path.join(dirPath, file);

            if (fs.statSync(fullPath).isDirectory()) {
                processDirectoryRecursively(fullPath);
