void create_log(const char *filename) {
    logfile = fopen(filename, "w");
    if (!logfile) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }
}

void log_entry(const NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&log_mutex);
    fprintf(logfile, "%u %u %u %d\n", entry->rxi_tag, entry->rnti, entry->crc_indication_tag, (int)entry->crcflag);
    pthread_mutex_unlock(&log_mutex);
}

void* create_entries(void *arg) {
    int num_entries = *(int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu) {
        perror("Error allocating memory for PDUs");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_entries; ++i) {
        pdu[i].rxi_tag = i % 16 + 1; // Assign RX_UE_INFORMATION_TAG values according to the specified range
        pdu[i].rnti = rand() % (MAX_RNTI + 1); // Generate random RNTI within the specified range
        pdu[i].crc_indication_tag = i;
        pdu[i].crcflag = rand() % 2 == 0 ? true : false; // Default to random CRCFLAG, or true for performance analysis

        log_entry(&pdu[i]);
    }

    return NULL;
}

int create_list(int num_entries) {
    pthread_t threads[NUM_THREADS];
    int chunk_size = num_entries / NUM_THREADS;
    int remaining = num_entries % NUM_THREADS;
    int start, end;

    create_log("debug.log");

    pthread_mutex_init(&log_mutex, NULL);

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (i < remaining) {
            start = i * chunk_size;
            end = (i + 1) * chunk_size;
        } else {
            start = i * chunk_size;
            end = num_entries;
        }

        if (pthread_create(&threads[i], NULL, create_entries, &start)) {
            perror("Error creating thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Error joining thread");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_destroy(&log_mutex);

    return num_entries;
}
