// Define the function prototype
void insertAfterOrAppend(std::forward_list<std::string>& flist, const std::string& str1, const std::string& str2, bool insertBefore, const std::string& performanceConstraint);

// Helper function to batch updates when possible to reduce overhead
void batchUpdate(std::forward_list<std::string>& flist, const std::string& searchValue) {
    if (flist.size() > 1 && (flist.cbegin() != flist.end())) {
        auto it = std::next(flist.cbegin());
        if (*it == searchValue) {
            std::vector<std::string> batch;
            while (it != flist.end()) {
                batch.push_back(*it);
                if (++it != flist.end() && *it == searchValue) continue;
                flist.erase(it, flist.end());
                it = std::next(flist.cbegin());
            }
            if (!batch.empty()) {
                // Insert batch elements based on insertBefore flag
                auto newBegin = flist.insert(std::prev(flist.end(), batch.size()), batch.rbegin(), batch.rend());
                flist.erase(newBegin, std::next(newBegin));
            }
        }
    }
}

// Main insertAfterOrAppend function implementation
void insertAfterOrAppend(std::forward_list<std::string>& flist, const std::string& str1, const std::string& str2, bool insertBefore, const std::string& performanceConstraint) {
    auto it = flist.begin();
    if (performanceConstraint == "maximize throughput") {
        // Prefer batch updates for better throughput
        while (it != flist.end()) {
            if (*it == str1) break;
            ++it;
            if (it != flist.begin()) batchUpdate(flist, str1);
        }
        if (it == flist.end()) flist.push_back(str2);
    } else if (performanceConstraint == "minimize latency") {
        // Prefer individual insertions for lower latency
        while (it != flist.end() && *it != str1) ++it;
        if (it == flist.end()) flist.push_back(str2);
        else if (!insertBefore) it = std::next(it);
    }
    if (it != flist.end()) {
        // Perform insertion based on the insertBefore flag
        if (!insertBefore) flist.insert(it, str2);
        else flist.insert(it, 1, str2);
    }
}
```

