class RollingChecksum {
private:
    uint32_t checksum = 0;
    uint32_t max_allowed_checksum_error = 1000; // Adjust this value as needed

public:
    uint32_t get_checksum() const { return checksum; }

    void add(uint32_t value) {
        checksum += value;
        if (std::abs(checksum) > max_allowed_checksum_error) {
            LOG_ERROR("CRC Integrity Error: Checksum exceeded the threshold");
            checksum = 0;
        }
    }
};

class ThreadSafeQueue {
private:
    std::queue<NFAPI_CRC_INDICATION_PDU_T> data;
    pthread_mutex_t mutex;

public:
    void push(const NFAPI_CRC_INDICATION_PDU_T& item) {
        pthread_mutex_lock(&mutex);
        data.push(item);
        if (data.size() > MAX_SIZE) {
            data.pop(); // Handle underflow gracefully
        }
        pthread_mutex_unlock(&mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T pop() {
        pthread_mutex_lock(&mutex);
        NFAPI_CRRC_INDICATION_PDU_T front = data.front();
        data.pop();
        pthread_mutex_unlock(&mutex);
        return front;
    }
};

