typedef boost::circular_buffer<NFAPI_CRC_INDICATION_PDU_T> NFAPIQueue;
typedef boost::circular_buffer<NFAPI_UL_CCCH_INDICATION_PDU_T> ULCCCHQueue;

class Monitor {
public:
    Monitor(size_t maxListSize, uint16_t checksumThreshold) : maxListSize_(maxListSize), checksumThreshold_(checksumThreshold) {}

    void push(NFAPI_CRC_INDICATION_PDU_T data) {
        // Update the rolling checksum and enforce maximum limits.
        updateChecksum(data);
        if (NFAPIQueue_.size() >= maxListSize_) {
            BOOST_LOG_TRIVIAL(error) << "Error: NFAPI queue exceeded maximum size.";
            exit(EXIT_FAILURE);
        }
        NFAPIQueue_.push_back(data);
    }

    void push(NFAPI_UL_CCCH_INDICATION_PDU_T data) {
        updateChecksum(data);
        if (ULCCCHQueue_.size() >= maxListSize_) {
            BOOST_LOG_TRIVIAL(error) << "Error: ULCCCH queue exceeded maximum size.";
            exit(EXIT_FAILURE);
        }
        ULCCCHQueue_.push_back(data);
    }

private:
    void updateChecksum(const NFAPI_CRC_INDICATION_PDU_T& data) {
        // Update rolling checksum. If the checksum exceeds the threshold, log an error and exit gracefully.
        currentChecksum_ += data.CRC;
        if (currentChecksum_ > checksumThreshold_) {
            BOOST_LOG_TRIVIAL(error) << "Error: Data integrity checksum exceeded threshold.";
            exit(EXIT_FAILURE);
        }
    }

    void updateChecksum(const NFAPI_UL_CCCH_INDICATION_PDU_T& data) {
        // Update rolling checksum. If the checksum exceeds the threshold, log an error and exit gracefully.
        currentChecksum_ += data.CRC;
        if (currentChecksum_ > checksumThreshold_) {
            BOOST_LOG_TRIVIAL(error) << "Error: Data integrity checksum exceeded threshold.";
            exit(EXIT_FAILURE);
        }
    }

    size_t maxListSize_;
    uint16_t checksumThreshold_;
    uint16_t currentChecksum_;
    NFAPIQueue NFAPIQueue_;
    ULCCCHQueue ULCCCHQueue_;
};

