Key* acquire_key() {
    Key *key;

    pthread_mutex_lock(&key_pool_mutex);
    if (key_count < key_allocated) {
        key = &key_pool[--key_count];
    } else {
        key = realloc(key_pool, ++key_allocated * MAX_POOL_SIZE * sizeof(Key));
        if (!key) {
            pthread_mutex_unlock(&key_pool_mutex);
            return NULL;
        }
        key_pool = key;
        key = &key_pool[--key_count];
    }
    pthread_mutex_unlock(&key_pool_mutex);

    return key;
}

Record* acquire_record(Offset *offset) {
    Record *record;

    pthread_mutex_lock(&record_cache_mutex);
    if (record_cache_count < record_cache_allocated) {
        record = &record_cache[--record_cache_count];
    } else {
        // Implement cache expansion here
        record = NULL;
    }
    pthread_mutex_unlock(&record_cache_mutex);

    if (!record) {
        record = malloc(sizeof(Record));
