int random(int min, int max) {
    static unsigned long seed = 0;

    if (!seed) seed = (unsigned long)time(NULL);

    // Use a good quality random number generator here, e.g., xoroshiro128+
    seed = (seed * 9301 + 49297) % INT_MAX;

