    struct Product *next;
} Product;

typedef struct ListLock {
    pthread_mutex_t mutex;
} ListLock;

struct ListLock list_lock;
ListLock lock = &list_lock;

Product* initialize_products() {
    // Initialize the predefined set of products from an external data source
    Product *products[] = {
        {"Product1", 1, 9.99, NULL},
        {"Product2", 2, 19.99, NULL},
        // Add more products here...
    };
    int num_products = sizeof(products) / sizeof(Product);
    Product *head = NULL;
    for (int i = 0; i < num_products; ++i) {
        Product *product = &products[i];
        product->next = head;
        head = product;
        pthread_mutex_init(&product->name, NULL); // Lock the name for thread safety
    }
    return head;
}

void add_product(Product **head, const char *name, int id, float price) {
    Product *new_product = (Product*) malloc(sizeof(Product));
    strcpy(new_product->name, name);
    new_product->id = id;
    new_product->price = price;
    new_product->next = NULL;
    pthread_mutex_init(&new_product->name, NULL); // Lock the name for thread safety

    Product *current = *head;
    Product **prev = head;
    while (current != NULL) {
        if (strcmp(current->name, new_product->name) == 0) {
            free(new_product);
            return; // Name already exists, do not add the product
        }
        prev = &current->next;
        current = current->next;
    }

    pthread_mutex_lock(lock);
    *prev = new_product;
    pthread_mutex_unlock(lock);
}

void traverse_and_print_products(Product *head) {
    Product *current = head;
    while (current != NULL) {
        printf("Product name: %s, ID: %d, Price: %.2f\n", current->name, current->id, current->price);
        current = current->next;
    }
}
