typedef struct {
    char source_ip[16];
    char destination_ip[16];
    unsigned short port;
} packet_t;

double calculate_average(int *num, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; ++i) {
        sum += num[i];
    }
    return sum / size;
}

unsigned short calculate_checksum(const packet_t *packet, int size) {
    unsigned long sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += *(unsigned short*)(&packet[i]);
        if ((i & 1) == 1) {
            sum = (sum >> 16) + (sum & 0xFFFF);
            sum = (sum & 0xFFFF) + (sum >> 16);
        }
    }
    return ~sum;
}

int read_floats(double **arr, int *size) {
    double temp;
    int count = 0;
    while (scanf("%lf", &temp) == 1) {
        (*size)++;
        if ((*size) > count) {
            (*arr) = realloc(*arr, sizeof(double)*(*size));
        } else {
            double *tmp = realloc((*arr), sizeof(double)*count + sizeof(double));
            memcpy(tmp, *arr, sizeof(double)*count);
            free(*arr);
            (*arr) = tmp;
        }
        (*arr)[count++] = temp;
    }
    if (feof(stdin)) {
        return -1; // end of file reached
    } else {
        return count;
    }
}

int read_packets(packet_t **arr, int *size) {
    char ip[32];
    packet_t temp_packet;
    int count = 0;
    while (fscanf(stdin, "%s %hu", ip, &temp_packet.port) == 2 && strlen(ip) < 16) {
        strncpy((*arr + count)->source_ip, ip, sizeof((*arr + count)->source_ip));
        (*arr + count)->destination_ip[0] = '\0'; // reset destination_ip for next scan
        if ((count + 1) > *size) {
            (*arr) = realloc(*arr, sizeof(packet_t)*(*size + 8)); // reserve space for 7 new packets
        } else {
            packet_t *tmp = realloc((*arr), sizeof(packet_t)*(*size + count + 1));
            memcpy(tmp, *arr, sizeof(packet_t)*(*size));
            free(*arr);
            (*arr) = tmp;
        }
        strncpy((*arr + count)->destination_ip, ip, sizeof((*arr + count)->destination_ip));
        (*arr + count++)->source_ip[15] = '\0'; // null-terminate source_ip
        (*arr + count)->destination_ip[15] = '\0'; // null-terminate destination_ip
    }
    if (feof(stdin)) {
        return -1; // end of file reached
    } else {
        return count;
    }
}

int main() {
    int float_size, packet_size;
    double *float_arr;
    packet_t *packet_arr;

    if (read_floats(&float_arr, &float_size) == -1 || read_packets(&packet_arr, &packet_size) == -1) {
        fprintf(stderr, "Error: premature end of file.\n");
        return 1;
    }

    double avg = calculate_average(float_arr, float_size);
    printf("Average value: %.6f\n", avg);

    for (int i = 0; i < packet_size; ++i) {
        unsigned short checksum = calculate_checksum(packet_arr + i, sizeof(packet_t)/sizeof(packet_t->source_ip));
        printf("Packet %d: Source IP - %s, Destination IP - %s, Port - %hu, Checksum - %hu\n", i+1, packet_arr[i].source_ip, packet_arr[i].destination_ip, packet_arr[i].port, checksum);
    }

    free(float_arr);
    free(packet_arr);

    return 0;
}
```

