// Function to read and validate input numbers
void read_and_validate_numbers(float* numbers, int count, float min, float max) {
    for (int i = 0; i < count; ++i) {
        scanf("%f", &numbers[i]);
        while (!validate_number(numbers[i], min, max)) {
            printf("Invalid number! Please enter a number within [%f, %f]: ", min, max);
            scanf("%f", &numbers[i]);
        }
    }
}

// Allocate dynamically-sized array of MAC_FRAME structures
MAC_FRAME* allocate_mac_frames(int count) {
    MAC_FRAME* frames = (MAC_FRAME*)malloc(count * sizeof(MAC_FRAME));

    if (!frames) {
        perror("Memory allocation failure!");
        exit(EXIT_FAILURE);
    }

    return frames;
}

// Function to calculate average and standard deviation of an array of floats
void calc_stats(float* numbers, int count, float* avg, float* stddev) {
    float sum = 0.0f;

    for (int i = 0; i < count; ++i) {
        sum += numbers[i];
    }

    *avg = sum / count;
    float temp_sum = 0.0f, square_diff = 0.0f;

    for (int i = 0; i < count; ++i) {
        square_diff += pow((numbers[i] - *avg), 2);
    }

    *stddev = sqrt(square_diff / count);
}

// Utility function to handle potential memory allocation failures
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);

    if (!ptr) {
        perror("Memory allocation failure!");
        exit(EXIT_FAILURE);
    }

    return ptr;
}

// Function to process user-defined number of floating-point numbers and MAC frames
void process_data(int num_numbers, int num_frames, float min, float max) {
    float* numbers = safe_malloc(num_numbers * sizeof(float));
    MAC_FRAME* frames = allocate_mac_frames(num_frames);

    read_and_validate_numbers(numbers, num_numbers, min, max);

    float avg, stddev;
    calc_stats(numbers, num_numbers, &avg, &stddev);
    printf("Average: %.6f\n", avg);
    printf("Standard Deviation: %.6f\n", stddev);

    free(numbers); // Free the array of floats after processing
}
