```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <cstdlib>
#include <algorithm>
#include <functional>
#include <mutex>
#include <boost/circular_buffer.hpp>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
};

class CustomAllocator {
public:
    static std::allocator<NFAPI_CRC_INDICATION_PDU_T> allocator;
    static void* allocate(std::size_t n, std::size_t alignment) {
        auto p = allocator.allocate(n);
        std::allocator<char>::construct((char*)p, n * sizeof(NFAPI_CRC_INDICATION_PDU_T), n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        return p;
    }

    static void deallocate(void* p, std::size_t n) {
        allocator.deallocate((char*)p, n);
    }
};
std::allocator<NFAPI_CRC_INDICATION_PDU_T> CustomAllocator::allocator;

class AVLTreeNode {
public:
    NFAPI_CRC_INDICATION_PDU_T data;
    int balanceFactor = 0;
    AVLTreeNode* left = nullptr;
    AVLTreeNode* right = nullptr;

    AVLTreeNode(const NFAPI_CRC_INDICATION_PDU_T& data) : data(data) {}
};

class AVLTree {
private:
    std::unique_ptr<AVLTreeNode> root;
    CustomAllocator allocator;

    int getHeight(const AVLTreeNode* node) const {
        if (!node) return 0;
        return 1 + std::max(getHeight(node->left), getHeight(node->right));
    }

    void rotateLeft(AVLTreeNode*& node) {
        auto tmp = node->right;
        node->right = tmp->left;
        tmp->left = node;
        node = tmp;
    }

    void rotateRight(AVLTreeNode*& node) {
        auto tmp = node->left;
        node->left = tmp->right;
        tmp->right = node;
        node = tmp;
    }

    int getBalanceFactor(const AVLTreeNode* node) const {
        return getHeight(node->right) - getHeight(node->left);
    }

    void rebalance(AVLTreeNode*& node) {
        if (getBalanceFactor(node) == 2) {
            if (getBalanceFactor(node->right) <= 0) rotateLeft(node->right);
            rotateRight(node);
        } else if (getBalanceFactor(node) == -2) {
            if (getBalanceFactor(node->left) >= 0) rotateRight(node->left);
            rotateLeft(node);
        }
    }

public:
    AVLTree() : root(nullptr) {}

    void insert(const NFAPI_CRC_INDICATION_PDU_T& data) {
        auto newNode = std::make_unique<AVLTreeNode>(data);
        if (!root) root.reset(newNode.release());
        else insertHelper(root.get(), newNode.release());
    }

    void erase(uint32_t rnti) {
        std::unique_ptr<AVLTreeNode> erasedNode;
        if (eraseHelper(root.get(), rnti, erasedNode)) root = std::move(erasedNode);
    }

private:
    bool insertHelper(AVLTreeNode* node, AVLTreeNode* newNode) {
        if (!node) {
            node = std::make_unique<AVLTreeNode>(*newNode);
            return true;
        }

        if (newNode->data.rnti < node->data.rnti) {
            if (node->left) return insertHelper(node->left.get(), newNode);
            else {
                node->left = std::make_unique<AVLTreeNode>(*newNode);
                return false;
            }
        } else {
            if (node->right) return insertHelper(node->right.get(), newNode);
            else {
                node->right = std::make_unique<AVLTreeNode>(*newNode);
                return false;
            }
        }
    }

    bool eraseHelper(AVLTreeNode* node, uint32_t rnti, std::unique_ptr<AVLTreeNode>& erasedNode) {
        if (!node) return false;

        if (node->data.rnti == rnti) {
            erasedNode = std::move(std::unique_ptr<AVLTreeNode>(node));
            delete node;

            if (!node->left && !node->right) {
                return true;
            } else if (!node->left) rotateLeft(node);
            else if (!node->right) rotateRight(node);
            else {
                auto minValue = std::min_element(node->right->begin(), node->right->end(),
                    [](const NFAPI_CRC_INDICATION_PDU_T& l, const NFAPI_CRC_INDICATION_PDU_T& r) {
                        return l.rnti < r.rnti;
                    });
                *minValue = node->data;
                eraseHelper(node->right.get(), minValue->rnti, erasedNode);
            }
            rebalance(node);
            return false;
        } else if (node->data.rnti < rnti) {
            return eraseHelper(node->right.get(), rnti, erasedNode);
        } else {
            return eraseHelper(node->left.get(), rnti, erasedNode);
        }
    }
};

std::unique_ptr<AVLTree> tree;

void init() {
    // Initialize the AVL tree with dummy data for proper tree height calculation
    tree = std::make_unique<AVLTree>();
    for (int i = 0; i < 15; ++i) tree->insert({ .rnti = i, .data = { 0, 0 } });
}

void insert(uint32_t rnti, const NFAPI_CRC_INDICATION_PDU_T& data) {
    tree->insert({ .rnti = rnti, .data = data });
}

void erase(uint32_t rnti) {
    tree->erase(rnti);
}

uint32_t height() {
    return tree ? getHeight(tree->root.get()) : 0;
}

bool isBalanced() {
    if (!height()) return true;

    int leftHeight = getHeight(tree->root->left.get());
    int rightHeight = getHeight(tree->root->right.get());
    return abs(leftHeight - rightHeight) <= 1;
}

void printData() {
    std::cout << "Printing data:" << std::endl;
    auto it = tree->root->begin();
    while (it != tree->root->end()) {
        std::cout << it->rnti << ", ";
        it++;
    }
}

int main() {
    init();

    insert(0, { 1, 2 });
    printData();
    std::cout << std::endl;

    insert(1, { 3, 4 });
    printData();
    std::cout << std::endl;

    erase(0);
    printData();
    std::cout << std::endl;

    erase(1);
    printData();
    std::cout << std::endl;

    insert(2, { 5, 6 });
    printData();
    std::cout << std::endl;

    insert(3, { 7, 8 });
    printData();
    std::cout << std::endl;

    erase(2);
    printData();
    std::cout << std::endl;

    return 0;
}

