    time_t timestamp;
    int rssi;
    struct ChannelUsage channels[10]; // Adjust the number of channels as needed
} FrameStats;

struct Logger {
    FILE *file;
    int level;
};

void log_frame(const FrameStats *frame, const struct Logger *logger) {
    if (logger->level <= LOG_DEBUG) {
        fprintf(logger->file, "[%lld] RSSI: %d\n", frame->timestamp, frame->rssi);
        for (int i = 0; i < 10; ++i) { // Adjust the number of channels as needed
            if (frame->channels[i].used) {
                fprintf(logger->file, "    Channel %d: %d\n", i, frame->channels[i].usage);
            }
        }
    }
}

void *generate_frames(void *args) {
    FrameStats *frame_buffer = args;
    double mean = 80.0;
    double stddev = 5.0;
    double rssi;
    time_t timestamp;

    while (true) {
        rssi = rand() * 1.0 / RAND_MAX * 2 * stddev + mean;
        timestamp = time(NULL);

        for (int i = 0; i < 10000; ++i) { // Adjust the number of frames per second as needed
            frame_buffer[i % ARRAY_SIZE].timestamp = timestamp;
            frame_buffer[i % ARRAY_SIZE].rssi = rssi;

            if (rssi > THRESHOLD) {
                for (int j = 0; j < 10; ++j) { // Adjust the number of channels as needed
                    if (!frame_buffer[i % ARRAY_SIZE].channels[j].used && rand() * 1.0 / RAND_MAX < PROBABILITY) {
                        frame_buffer[i % ARRAY_SIZE].channels[j].used = true;
                        frame_buffer[i % ARRAY_SIZE].channels[j].usage = rand() * 1.0 / RAND_MAX * MAX_USAGE;
                    }
                }
            }

            usleep(1000); // Adjust the sleep duration as needed
        }
    }

    return NULL;
}

void init_frame_buffer(FrameStats **frame_buffer, size_t frame_count, struct Logger *logger) {
    *frame_buffer = malloc(frame_count * sizeof(**frame_buffer));

    if (*frame_buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for frame buffer\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < frame_count; ++i) {
        log_frame(&((*frame_buffer)[i]), logger);
    }
}

void free_frame_buffer(FrameStats *frame_buffer, size_t frame_count) {
    free(frame_buffer);
}
