        if (!temp_data) {
            sem_post(&list->resize_mutex);
            return false;
        }
        list->data = temp_data;
        list->capacity = new_capacity;
    }
    sem_post(&list->resize_mutex);

    sem_wait(&list->read_write_mutex);
    if (list->num_elements < list->max_size) {
        list->data[list->num_elements] = *pdu;
