#define MAX_POOL_SIZE 1024
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct pool {
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
    int head;
    int tail;
    bool is_initialized;
};

struct pool *create_pool(size_t initial_capacity) {
    struct pool *pool = (struct pool *)malloc(sizeof(struct pool));
    if (!pool) {
        fprintf(stderr, "Error: Failed to allocate memory for the pool\n");
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->not_empty, NULL);
    pthread_cond_init(&pool->not_full, NULL);

    pool->size = 0;
    pool->capacity = initial_capacity;
    pool->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        fprintf(stderr, "Error: Failed to allocate memory for the pool data\n");
        free(pool);
        return NULL;
    }

    pool->head = 0;
    pool->tail = 0;
    pool->is_initialized = true;

    return pool;
}

bool resize_pool(struct pool *pool, size_t new_capacity) {
    if (new_capacity <= pool->size || new_capacity < MAX_POOL_SIZE) {
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        fprintf(stderr, "Error: Failed to resize the pool data\n");
        return false;
    }
    pool->data = new_data;
    pool->capacity = new_capacity;

    return true;
}

void free_pool(struct pool *pool) {
    if (pool && pool->data) {
        free(pool->data);
        pthread_mutex_destroy(&pool->lock);
        pthread_cond_destroy(&pool->not_empty);
        pthread_cond_destroy(&pool->not_full);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* acquire_from_pool(struct pool *pool) {
    pthread_mutex_lock(&pool->lock);

    while (pool->size >= pool->capacity && !resize_pool(pool, pool->size + (pool->size >> 1))) {
        pthread_cond_wait(&pool->not_full, &pool->lock);
    }

    if (!pool->is_initialized) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    int next = (pool->head + 1) % pool->capacity;
    NFAPI_CRC_INDICATION_PDU_T *item = &pool->data[pool->head];

    pool->size++;
    pool->head = next;
    if (next == pool->tail) {
        pthread_cond_signal(&pool->not_empty);
    }

    pthread_mutex_unlock(&pool->lock);

    // Set random CRCFLAG for the acquired item
    srand(time(NULL));
    item->crcflag = rand() % 2;

    return item;
}

size_t pool_size(struct pool *pool) {
    if (!pool || !pool->is_initialized) {
        return 0;
    }

    pthread_mutex_lock(&pool->lock);
    size_t size = pool->size;
    pthread_mutex_unlock(&pool->lock);

    return size;
}
