    unsigned long rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
} ListNode;

// Custom memory allocator to reduce fragmentation and improve performance
void* custom_malloc(size_t size) {
    void* result = malloc(size);
    if (result == NULL) return NULL;

    // Zero the allocated memory
    memset(result, 0, size);

    return result;
}

// Custom free function to ensure proper deallocation of custom_malloc'd memory
void custom_free(void* ptr) {
    if (ptr != NULL) free(ptr);
}

ListNode* create_list_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    ListNode *new_node = (ListNode*)custom_malloc(sizeof(ListNode));
    if (!new_node) return NULL;

    new_node->data = *data;
    new_node->next = NULL;

    return new_node;
}

// Thread-safe list structure using a linked list and a lock
struct thread_list {
    ListNode* head;
    ListNode* tail;
    pthread_mutex_t mutex;
    size_t size;
};

ThreadList* init_thread_list() {
    ThreadList *list = (ThreadList*)custom_malloc(sizeof(ThreadList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_thread_list(ThreadList* list) {
    if (!list) return;

    ListNode *current = list->head;
    while (current != NULL) {
        ListNode *next = current->next;
        custom_free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    custom_free(list);
}

bool thread_list_push(ThreadList* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    ListNode *new_node = create_list_node(data);
    if (!new_node) return false;

    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    ++(list->size);
    pthread_mutex_unlock(&list->mutex);

    return true;
}

ThreadList* thread_list_pop(ThreadList* list) {
