```cpp
#include <vector>
#include <atomic>
#include <memory>
#include <stdexcept>
#include <cstdint>
#include <new>

enum class StatusCode {
    SUCCESS,
    MEMORY_ERROR,
    INVALID_OPERATION,
    OTHER_ERROR
};

struct MACEntityStats {
    uint64_t meid; // MEID
    std::vector<uint8_t> sdu; // SDU
    std::atomic<uint64_t> transmitted{0}; // Transmitted frames counter
    std::atomic<uint64_t> received{0}; // Received frames counter
};

class MACEntities {
public:
    explicit MACEntities(size_t n) : capacity_(n), data_(capacity_ ? new MACEntityStats[capacity_]() : nullptr) {}

    ~MACEntities() { clear(); }

    StatusCode resize(size_t n);
    StatusCode push_back(const MACEntityStats& stats);
    const MACEntityStats* get(size_t index) const;
    size_t size() const { return data_ ? std::min<size_t>(capacity_, data_->size()) : 0; }

private:
    void clear();

    struct CustomAllocator {
        static void* allocate(std::size_t n, std::size_t) {
            return ::operator new[](n);
        }
        static void deallocate(void* p, std::size_t, std::size_t) {
            ::operator delete[](p);
        }
    };

    size_t capacity_;
    std::unique_ptr<MACEntityStats[], CustomAllocator> data_;
};

StatusCode MACEntities::resize(size_t n) {
    if (n <= 0 || !data_)
        return StatusCode::INVALID_OPERATION;

    size_t oldCapacity = capacity_;
    auto newData = std::unique_ptr<MACEntityStats[], CustomAllocator>(new MACEntityStats[n]());

    try {
        if (oldCapacity > 0)
            std::copy(data_.get(), data_.get() + oldCapacity, newData.get());

        capacity_ = n;
        data_.swap(newData);
    } catch (...) {
        // Deallocate newly allocated memory in case of exceptions
        data_.reset();
        capacity_ = oldCapacity;
        throw;
    }

    return StatusCode::SUCCESS;
}

StatusCode MACEntities::push_back(const MACEntityStats& stats) {
    if (!data_)
        return resize(1);

    data_->emplace_back(stats);
    capacity_++;
    return StatusCode::SUCCESS;
}

const MACEntityStats* MACEntities::get(size_t index) const {
    if (index >= size())
        throw std::out_of_range("Index out of range");

    return &data_[index];
}

void MACEntities::clear() {
    if (data_) {
        data_.reset();
        capacity_ = 0;
    }
}
```

