#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    pthread_mutex_t mutex;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

void insert_node(Node** head_ref, Node* new_node) {
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    Node* last = *head_ref;
    while (last->next != NULL)
        last = last->next;

    last->next = new_node;
}

void sort(Node** head) {
    if (!(*head)) return;

    Node* temp;
    for (Node* current = *head; current != NULL; current = current->next) {
        for (Node* next = current->next; next != NULL; next = next->next) {
            if (current->data.crc_indication.crcflag < next->data.crc_indication.crcflag) {
                temp = current->next;
                current->next = next->next;
                next->next = temp;

                if (current == *head) *head = next;
            }
        }
    }
}

void* populate_list(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* buffer = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    int i, randomRNTI;

    for (i = 0; i < *(int*)buffer; i++) {
        randomRNTI = rand() % MAX_RNTI + MIN_RNTI;
        while (i > 1 && buffer[i - 2].rnti == randomRNTI)
            randomRNTI = rand() % MAX_RNTI + MIN_RNTI;
        buffer[i].rnti = randomRNTI;
        buffer[i].crc_indication.crcflag = (rand() % 2) ? 1 : 0;
    }
}

Node* dynamic_list(int max_size, int* size) {
    Node* head = NULL;
    Node** current = &head;
    pthread_t threads[max_size];
    NFAPI_CRC_INDICATION_PDU_T buffer[max_size];

    *size = 0;

    for (int i = 0; i < max_size; ++i) {
        buffer[i].rnti = -1;
    }

    int num_threads = (max_size > 10) ? max_size / 10 : 1;

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, populate_list, &buffer[i * (max_size / num_threads]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    sort(current);

    return head;
}
```

