```cpp
#include <iostream>
#include <vector>
#include <random>
#include <unordered_map>
#include <functional>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

// External data source interface
struct DataSource {
    virtual void getRTNIs(std::vector<uint32_t>& rtnis, std::function<void()> callback) = 0;
};

// Define the NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ueTag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

class Allocator {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::unordered_map<uint32_t, bool> rntiUsage;
    DataSource& source;
    uint64_t nextId = 0;
    int maxConcurrentRequests = 5;
    std::mutex requestsMutex;
    std::condition_variable requestsCV;
    std::vector<std::function<void()>> pendingRequests;
    bool isPaused = false;

public:
    Allocator(DataSource& source) : source(source) {}

    void allocateData(size_t count, std::vector<NFAPI_CRC_INDICATION_PDU_T>& out) {
        if (count > data.size()) {
            resize(count);
        }

        std::lock_guard<std::mutex> lock(requestsMutex);
        pendingRequests.push_back([&]() { this->fillData(out); });

        if (pendingRequests.size() >= maxConcurrentRequests && !isPaused) {
            isPaused = true;
            std::unique_lock<std::mutex> uniqueLock(requestsMutex);
            requestsCV.wait(uniqueLock, [&]() { return pendingRequests.size() < maxConcurrentRequests || isPaused; });
            isPaused = false;
        }
    }

    void resize(size_t newSize) {
        // Dynamically allocate memory for the new array size
        data.resize(newSize);
        rntiUsage.clear();
        for (auto& item : data) {
            generateRandomData(&item);
        }
    }

    void fillData(std::vector<NFAPI_CRC_INDICATION_PDU_T>& out) {
        std::lock_guard<std::mutex> lock(requestsMutex);

        for (size_t i = 0; i < data.size() && i < out.size(); ++i) {
            if (!rntiUsage[data[i].rnti]) {
                out[i] = std::move(data[i]);
                rntiUsage[data[i].rnti] = true;
                break;
            }
        }

        if (out.size() < data.size()) {
            fetchRTNIs(data.size() - out.size());
        }
    }

    void generateRandomData(NFAPI_CRC_INDICATION_PDU_T* item) {
        // Generate unique ueTag within a specified range
        item->ueTag = nextId++;

        // Set randomly generated CRCFLAG value in the CRC_INDICATION_REL8_TAG
        item->crcIndication.crcFlag = (rand() % 2);
    }

    void fetchRTNIs(size_t count) {
        auto startTime = std::chrono::high_resolution_clock::now();
        source.getRTNIs({}, [this, count](const auto& rtnis) {
            for (auto rnti : rtnis) {
                if (!rntiUsage[rnti]) {
                    data[count++].rnti = rnti;
                    rntiUsage[rnti] = true;
                }
            }

            if (count < data.size()) {
                fetchRTNIs(data.size() - count);
            } else {
                std::lock_guard<std::mutex> lock(requestsMutex);
                pendingRequests.erase(std::remove_if(pendingRequests.begin(), pendingRequests.end(),
                    [this](const auto& request) { return &request == this; }), pendingRequests.end());
            }
        });

        std::unique_lock<std::mutex> uniqueLock(requestsMutex);
        requestsCV.wait_for(uniqueLock, std::chrono::seconds(5), [this, count]() { return pendingRequests.size() <= count; });
    }
};
```

