#include <boost/thread/mutex>
#include <boost/thread.hpp>
#include <memory>

class PacketManager {
public:
    void addPacket(const PacketHeader& packet) {
        { // Lock to ensure thread safety
            lock_.lock();

            auto it = std::find_if(headers_.begin(), headers_.end(), [packet](const PacketHeader& hdr) { return hdr.id == packet.id; });

            if (it != headers_.end()) { // Duplicate identifier, ignore the request
                lock_.unlock();
                return;
            }

            headers_.emplace_back(packet);
            lock_.unlock();
        }
    }

    void updatePacket(uint64_t id, const PacketHeader& newHeader) {
        { // Lock to ensure thread safety
            lock_.lock();

            auto it = std::find_if(headers_.begin(), headers_.end(), [id](const PacketHeader& hdr) { return hdr.id == id; });

            if (it != headers_.end()) {
                *it = newHeader;
                lock_.unlock();
                return;
            }

            lock_.unlock();
        }
    }

    void removePacket(uint64_t id, const condition_t& condition) {
        { // Lock to ensure thread safety
            lock_.lock();

            auto it = std::find_if(headers_.begin(), headers_.end(), [id](const PacketHeader& hdr) { return hdr.id == id; });

            if (it != headers_.end()) {
                if (condition(*it)) { // Based on specified condition, remove the packet
                    headers_.erase(it);
                    lock_.unlock();
                    return;
                }
            }

            lock_.unlock();
        }
    }

