void create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) return;
    new_node->data = *data;
    new_node->next = NULL;
}

bool is_rnti_unique(const RNTI rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti && current->next != NULL && current->next->data.rnti == rnti)
            return false;
        current = current->next;
    }
    return true;
}

Node* find_or_create_node(const RNTI rnti) {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    while (current != NULL) {
        if (is_rnti_unique(rnti)) {
            if (total_rnti_instances < max_rnti_instances) {
                create_node(&(NFAPI_CRC_INDICATION_PDU_T){.rnti = rnti, .crc_indication = {.crcflag = rand() % 2}});
                if (!tail) head = tail = new_node;
                else tail->next = new_node;
                tail = new_node;
                total_rnti_instances++;
            } else {
                pthread_mutex_unlock(&list_mutex);
                return NULL; // memory constraint error
            }
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
    return current;
}

void compact_list() {
    Node* current = head;
    Node* temp = NULL;
    while (current != NULL) {
        Node* next = current->next;
        if (!next || !is_rnti_unique(current->data.rnti)) {
            if (current == head) head = next;
            else temp->next = next;
            free(current);
            current = next;
        } else {
            temp = current;
            current = next;
        }
    }
}

void init_list(unsigned int max_size, unsigned int max_instances) {
