void populateNfarxIndications(NFAPI_CRC_INDICATION_PDU_T** indications, size_t num_ue_instances, const char* log_file) {
    *indications = calloc(num_ue_instances, sizeof(**indications));

    if (!*indications) {
        perror("Memory allocation failed");
        return;
    }

    pid_t bg_pid;
    char log_msg[256];

    snprintf(log_msg, sizeof(log_msg), "Executing command in background: %s\n", getenv("COMMAND"));
    fprintf(stderr, "%s", log_msg);
    FILE* logfile = fopen(log_file, "a");
    if (logfile) {
        fprintf(logfile, "%s", log_msg);
        fclose(logfile);
    }

    bg_pid = fork();
    if (bg_pid < 0) {
        perror("Failed to fork process");
        return;
    } else if (bg_pid > 0) {
        int status;
        waitpid(bg_pid, &status, 0);

        snprintf(log_msg, sizeof(log_msg), "Command execution completed with status: %d\n", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
        fprintf(stderr, "%s", log_msg);
        if (logfile) {
            fprintf(logfile, "%s", log_msg);
            fclose(logfile);
        }
    } else {
        char* command = getenv("COMMAND");
        char temp_log_path[256];
        snprintf(temp_log_path, sizeof(temp_log_path), "%stemp.log", log_file);

        FILE *temp_log = fopen(temp_log_path, "w");
        if (temp_log) {
            dup2(fileno(temp_log), STDOUT_FILENO);
            dup2(fileno(temp_log), STDERR_FILENO);
            execl("/bin/sh", "/bin/sh", "-c", command, NULL);
            perror("Error executing command");
        } else {
            perror("Failed to open temp log file");
        }
    }

    for (size_t i = 0; i < num_ue_instances; ++i) {
        (*indications)[i].rnti = i + 1;
        (*indications)[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        (*indications)[i].crc_indication_rel8_tag = rand() & 0xff;
    }
}
