    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

void initList(NFAPI_CRC_INDICATION_PDU_T **list, size_t N, unsigned seed) {
    srand(seed);
    *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < N; ++i) {
        (*list)[i].crcflag = rand() % 2;
        (*list)[i].next = i + 1 < N ? &((*list)[i + 1]);
    }
    (*list)[N - 1] = NULL;
}

void insertHead(NFAPI_CRC_INDICATION_PDU_T **list, RX_UE_INFORMATION_TAG tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->tag = tag;
    newNode->rnti = rnti;
    newNode->crc_indication = crc_indication;
    newNode->next = *list;
    newNode->crcflag = rand() % 2;
    *list = newNode;
}

void deleteNode(NFAPI_CRC_INDICATION_PDU_T **list, size_t index) {
    if (index >= listLength(*list)) return;
    NFAPI_CRC_INDICATION_PDU_T *current = *list;
    for (size_t i = 0; i < index; ++i) {
        if (!current) return; // handle edge case: deleting the last node
        current = current->next;
    }
    NFAPI_CRC_INDICATION_PDU_T *toDelete = current;
    current = current->next;
    free(toDelete);
}

size_t listLength(NFAPI_CRC_INDICATION_PDU_T *list) {
    size_t len = 0;
    for (NFAPI_CRC_INDICATION_PDU_T *current = list; current; current = current->next) ++len;
    return len;
}

void traverseList(NFAPI_CRC_INDICATION_PDU_T *list) {
    for (NFAPI_CRC_INDICATION_PDU_T *current = list; current; current = current->next) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: 0x%04X, CRC_INDICATION_REL8_TAG: 0x%06X, CRCFLAG: %d\n",
               current->tag, current->rnti, current->crc_indication, current->crcflag);
    }
}

void resetCRCFlags(NFAPI_CRC_INDICATION_PDU_T *list) {
    for (NFAPI_CRC_INDICATION_PDU_T *current = list; current; current = current->next) {
        current->crcflag = 0;
    }
}

// background processing thread that periodically resets CRC flags
void* backgroundProcessing(void* arg) {
    while (1) {
        resetCRCFlags((NFAPI_CRC_INDICATION_PDU_T*)arg);
        sleep(timeout * 1000); // timeout in seconds
    }
}
