#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct mem_manager {
    size_t max_memory;
    size_t used_memory;
    void* aligned_buffer;
    size_t alignment;
    FILE *log_file;
} MemManager;

MemManager* create_mem_manager(size_t max_memory, size_t alignment) {
    MemManager* mm = malloc(sizeof(MemManager));
    if (!mm) return NULL;
    mm->max_memory = max_memory;
    mm->used_memory = 0;
    mm->alignment = alignment;
    mm->log_file = fopen("mem_log.txt", "w");
    return mm;
}

void* aligned_malloc(size_t size, MemManager *mm) {
    void* ptr = malloc(size + mm->alignment);
    if (!ptr) {
        fprintf(mm->log_file, "Failed to allocate memory for alignment %zu\n", mm->alignment);
        return NULL;
    }
    if ((uintptr_t)(ptr) % mm->alignment != 0) {
        free(ptr);
        fprintf(mm->log_file, "Allocation at %p not properly aligned\n", ptr);
        return NULL;
    }
    mm->used_memory += size + mm->alignment;
    if (mm->used_memory > mm->max_memory) {
        fprintf(mm->log_file, "Exceeded maximum memory limit of %zu bytes\n", mm->max_memory);
        return NULL;
    }
    return ptr;
}

void aligned_free(void* ptr, MemManager *mm) {
    if (!ptr) return;
    free(ptr);
    mm->used_memory -= (uintptr_t)(ptr) + mm->alignment;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfapi_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = aligned_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), mm);
    if (!pdu) return NULL;
    pdu->crc_indication.crcflag = rand() % 2;
    return pdu;
}

void destroy_nfapi_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    aligned_free(pdu, mm);
}

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
size_t num_successfully_allocated = 0;
size_t num_failures = 0;
NFAPI_CRC_INDICATION_PDU_T** list;

void* pdu_generator(void *arg) {
    while (true) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_nfapi_pdu();
        if (!pdu) continue;

        pthread_mutex_lock(&list_lock);
        if (num_successfully_allocated < N && !list[num_successfully_allocated]) {
            list[num_successfully_allocated] = pdu;
            num_successfully_allocated++;
        } else {
            destroy_nfapi_pdu(pdu);
        }
        pthread_mutex_unlock(&list_lock);
    }
}

int main() {
    srand(time(NULL));

    MemManager *mm = create_mem_manager(1048576, 64); // Example configuration: 1MB memory limit, 64-byte alignment

    size_t N = 10;
    list = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        fprintf(mm->log_file, "Failed to allocate memory for the list\n");
        num_failures++;
    }

    pthread_t threads[N];
    for (size_t i = 0; i < N; ++i)
        if (pthread_create(&threads[i], NULL, &pdu_generator, NULL)) {
            fprintf(mm->log_file, "Failed to create thread %zu\n", i);
            num_failures++;
        }

    for (size_t i = 0; i < N; ++i) pthread_join(threads[i], NULL);

    printf("Successfully allocated: %zu\n", num_successfully_allocated - num_failures);
    printf("Failures encountered: %zu\n", num_failures);

    fclose(mm->log_file);
    free(list);
    free(mm);
}
