    }
}

int createNfadbPduList(int N, sqlite3 *db, void *config) {
    sqlite3_stmt *stmt;
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int retries = *(int *) config;
    double backoff = *(double *) ((char *) config + sizeof(int));
    time_t last_retry = 0;

    for (int i = 0; i < N; ++i) {
        nfapi_crc_indication_pdu_validate(&pdus[i]);

        if (!sqlite3_prepare_v2(db, "INSERT INTO crc_indications VALUES (?, ?, ?, ?)", -1, &stmt, 0)) {
            pdus[i].rnti = i + 1;
            pdus[i].crc_indication_rel8_tag[0] = rand() % 256;
            pdus[i].crc_indication_rel8_tag[1] = rand() % 256;
            pdus[i].crcflag = rand() % 2;

            sqlite3_bind_int(stmt, 1, pdus[i].rnti);
            sqlite3_bind_blob(stmt, 2, pdus[i].crc_indication_rel8_tag, sizeof(pdus[i].crc_indication_rel8_tag), SQLITE_TRANSIENT);
            sqlite3_bind_int(stmt, 3, pdus[i].crcflag);

            int rc = sqlite3_step(stmt);
            sqlite3_finalize(stmt);

            if (rc == SQLITE_BUSY || rc == SQLITE_LOCKED) {
                // Implement exponential backoff logic and retry insert operation
                double elapsed = time(0) - last_retry;
                if (elapsed < backoff * pow(2, retries)) {
                    sleep(backoff * pow(2, retries - elapsed / backoff) - elapsed);
                }
                last_retry = time(0);
                --retries;
            } else if (rc != SQLITE_OK) {
                // Handle database connection failure and return appropriate status code
                free(pdus);
                return rc;
            }
        }
    }

    free(pdus);
    return SQLITE_OK;
}
