void array_resize(struct array_data* arr, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T* tmp = realloc(arr->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!tmp) {
