        }

        if (array_key_exists('sub_action', $request) && $request['sub_action'] === 'delete') {
            // Delete the user's profile from the database
            $stmt = $db->prepare("DELETE FROM users WHERE id=?");
            $stmt->execute([$request['id']]);
        }

        // Commit transaction and log the operation
        $db->commit();
        logEvent('Profile updated: ' . $request['id']);

        // Return success response
        $response = ['status' => 'success', 'message' => 'Operation successful'];
    } catch (Exception $e) {
        // Rollback transaction and log the error
        $db->rollBack();
