using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Web.Caching;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

public class ContentUpdater
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<ContentUpdater> _logger;
    private readonly OutputCacheProvider _outputCache;

    public ContentUpdater(HttpClient httpClient, ILogger<ContentUpdater> logger, OutputCacheProvider outputCache)
    {
        _httpClient = httpClient;
        _logger = logger;
        _outputCache = outputCache;
    }

    public async Task<string> UpdateElementAsync(int pageSectionId, int elementId, string htmlContent)
    {
        var cacheKey = GenerateCacheKey(pageSectionId, elementId);
        object cachedData = _outputCache.Get(cacheKey);

        if (cachedData != null)
            return "Refresh"; // Return refresh command if data is already in cache

        var serviceResponse = await SendPostRequestAsync($"api/service/{pageSectionId}/{elementId}", htmlContent);

        if (!serviceResponse.IsSuccessStatusCode)
        {
            _logger.LogError("Failed to update element: {@PageSectionId}: {@ElementId} with status code: {@StatusCode}", pageSectionId, elementId, serviceResponse.StatusCode);
            throw new Exception($"Failed to update element: {@PageSectionId}: {@ElementId} with status code: {@serviceResponse.StatusCode}");
        }

        _outputCache.Set(cacheKey, DateTime.UtcNow.AddMinutes(5), htmlContent); // Cache response for 5 minutes
        return "Refresh";
    }

    private string GenerateCacheKey(int pageSectionId, int elementId) => $"{nameof(UpdateElementAsync)}_{pageSectionId}_{elementId}";

    private async Task<HttpResponseMessage> SendPostRequestAsync(string requestUri, string content)
    {
        var httpRequestMessage = new HttpRequestMessage
        {
            Method = HttpMethod.Post,
            RequestUri = new Uri(requestUri),
            Content = new StringContent(content, System.Text.Encoding.UTF8, "application/json")
        };

        return await _httpClient.SendAsync(httpRequestMessage);
    }
}
```

