    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node *next;
} Node;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static Node* head = NULL;
static Node* tail = NULL;
static size_t size = 0;
static size_t capacity = 0;
static int probability = 10; // Probability of setting CRCFLAG to 1 (in percentage)
static time_t seed = time(NULL);

void log(const char* message, int verbosity) {
    if (verbosity <= LOG_VERBOSITY)
        printf("%s\n", message);
}

void check_rnti(RNTI rnti) {
    if (rnti < MIN_RNTI || rnti >= MAX_RNTI) {
        log("Invalid RNTI value", 1);
        exit(EXIT_FAILURE);
    }
}

void set_crcflag() {
    int random = rand_r(&seed) % 100;
    if (random < probability)
        crc_indication_rel8_tag.CRCFLAG = true;
    else
        crc_indication_rel8_tag.CRCFLAG = false;
}

void add(const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&mutex);

    if (size == capacity) {
        log("Out of memory", 0);
        // Implement fallback mechanism here, e.g., releasing less-important resources or reducing load
    }

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        log("Out of memory", 0);
        // Implement fallback mechanism here, e.g., releasing less-important resources or reducing load
    }

    new_node->data = *data;
    set_crcflag();
    check_rnti(new_node->data.rnti);
    new_node->next = NULL;

    if (!head) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    size++;

    pthread_mutex_unlock(&mutex);
}

const NFAPI_CRC_INDICATION_PDU_T* get(size_t index) {
    pthread_mutex_lock(&mutex);

    if (index >= size) {
        log("Index out of bounds", 0);
        // Implement fallback mechanism here, e.g., returning a default value or throwing an exception
    }

    Node *current = head;
    for (size_t i = 0; i < index; i++)
        current = current->next;

    pthread_mutex_unlock(&mutex);

    return &current->data;
}

void free_memory() {
    pthread_mutex_lock(&mutex);

    Node *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    size = 0;
    capacity = 0;

    pthread_mutex_unlock(&mutex);
}
```

