    for (let i = 0; i < testCases.length && promises.length < concurrencyLevel; i++) {
      if (testCases[i]) { // Check if the current test case is defined
        promises.push(executeTest(testCases[i]));
      }
    }

    let results = [];
    try {
      results = await Promise.all(promises);
    } catch (error) {
      console.error('An error occurred while executing tests:', error);
      throw error;
    }

    return results;
  }

  // Main function to manage the test suite execution
  async function runTestSuite(concurrencyLevel) {
    try {
      activityLogger = new (require('your-logging-utility')).LoggingUtility(logLevel); // Initialize the logging utility with a specified log level

      const testResults = await executeTestsInParallel(testCases, concurrencyLevel);
      return testResults;
    } catch (error) {
      console.error('An error occurred while running the test suite:', error);
      throw error;
    } finally {
      activityLogger?.dispose(); // Clean up the logging utility instance
    }
  }

  // Check if the server load is acceptable before executing tests
  const isAcceptableLoad = checkServerLoad();

  if (!isAcceptableLoad) {
    console.log('Test execution temporarily disabled due to high server load');
    return Promise.resolve([]);
  }

  // Execute the test suite with a balanced concurrency level considering the current server load and user experience
  const concurrencyLevel = calculateConcurrencyLevel();
  return runTestSuite(concurrencyLevel);
}
