#include <stdlib.h>
#include <stdio.h>
#include <vector>
#include <synchapi/synchapi.h> // For CRITICAL_SECTION and EnterCriticalSection/LeaveCriticalSection

typedef struct {
    HDC context;
    std::vector<HDC> command_buffers;
} device_context;

typedef struct {
    void* raw_memory;
    size_t size;
    unsigned int usage; // 0 for constant, 1 for dynamic, 2 for stream
} buffer_object;

typedef struct {
    std::vector<device_context*> device_contexts;
    std::vector<buffer_object> buffer_objects;
    CRITICAL_SECTION lock; // For efficient resource management
} resource_manager;

// Initialize resource manager with given capacity for device contexts and buffer objects.
resource_manager* initializeResourceManager(int num_contexts, int num_buffers) {
    resource_manager* rm = (resource_manager*)malloc(sizeof(resource_manager));
    if (!rm) return nullptr;

    InitializeCriticalSection(&rm->lock);

    rm->device_contexts.resize(num_contexts);
    for (int i = 0; i < num_contexts; ++i) {
        rm->device_contexts[i] = nullptr;
        rm->device_contexts[i]->command_buffers.resize(MAX_COMMAND_BUFFERS);
    }

    rm->buffer_objects.reserve(num_buffers);

    return rm;
}

// Allocate a new buffer object with the specified size and usage.
buffer_object* allocateBufferObject(resource_manager* rm, size_t size, unsigned int usage) {
    buffer_object* bo = &rm->buffer_objects[rm->buffer_objects.size()];
    bo->raw_memory = malloc(size);
    if (!bo->raw_memory) return nullptr;

    bo->size = size;
    bo->usage = usage;

    EnterCriticalSection(&rm->lock);
    rm->buffer_objects.push_back(bo);
    LeaveCriticalSection(&rm->lock);

    return bo;
}

// Free all allocated resources in the resource manager.
void freeResourceManager(resource_manager* rm) {
    EnterCriticalSection(&rm->lock);
    for (device_context* dc : rm->device_contexts) {
        if (!dc) continue;

        for (HDC cb : dc->command_buffers) {
            DeleteDC(cb);
        }
        free(dc);
    }

    for (buffer_object* bo : rm->buffer_objects) {
        free(bo->raw_memory);
    }

    DeleteCriticalSection(&rm->lock);
    free(rm);
}
```
