import hashlib
import os
from concurrent.futures import ThreadPoolExecutor

class FileIntegrityChecker:
    def __init__(self, chunk_size=64 * (1024 ** 2), temp_dir='./temp'):
        self.chunk_size = chunk_size
        self.temp_dir = temp_dir

    def check(self, log_file_path, expected_checksum):
        if not os.path.isfile(log_file_path):
            raise FileNotFoundError(f"Log file '{log_file_path}' does not exist.")

        temp_file_path = self._create_temp_file()
        with open(log_file_path, 'rb') as f:
            with open(temp_file_path, 'ab') as t:
                self._process_chunks(f, t)

        temp_checksum = self._calculate_checksum(temp_file_path)
        os.remove(temp_file_path)

        return_data = {'checksum': temp_checksum, 'size': os.path.getsize(log_file_path)}
        if expected_checksum == temp_checksum:
            return 'pass', return_data
        else:
            raise ValueError(f"Checksum mismatch for log file '{log_file_path}'.")

    def _process_chunks(self, f, t, executor=None):
        if not executor:
            executor = ThreadPoolExecutor()

        while True:
            data = f.read(self.chunk_size)
            if not data:
                break
            executor.submit(lambda d, t: t.write(d), data, temp_file)

    def _calculate_checksum(self, file_path):
        with open(file_path, 'rb') as f:
            hasher = hashlib.md5()
            while True:
                data = f.read(8192)
                if not data:
                    break
                hasher.update(data)
            return hasher.hexdigest()

    def _create_temp_file(self):
        file_name = os.path.join(self.temp_dir, f"{os.path.basename(os.getcwd())}_{hashlib.md5(os.urandom(16)).hex[:8]}.tmp")
        with open(file_name, 'ab') as f:
            pass
        return file_name
