#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct FrameInfo {
    time_t timestamp;
    int cell_id;
    int measurements_count;
    struct ChannelQualityMeasurement** measurements;
    pthread_mutex_t mutex;
} FrameInfo;

typedef struct ChannelQualityMeasurement {
    time_t timestamp;
    int quality;
} ChannelQualityMeasurement;

static const size_t MAX_MEASUREMENTS = 10000;

void init_frame(FrameInfo** frame, time_t timestamp, int cell_id) {
    *frame = malloc(sizeof(FrameInfo));
    if (!*frame) return;

    (*frame)->timestamp = timestamp;
    (*frame)->cell_id = cell_id;
    (*frame)->measurements_count = 0;
    (*frame)->measurements = calloc(MAX_MEASUREMENTS, sizeof(ChannelQualityMeasurement*));
    if (!(*frame)->measurements) {
        free(*frame);
        *frame = NULL;
        return;
    }

    (*frame)->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void add_measurement(FrameInfo* frame, time_t timestamp, int quality) {
    pthread_mutex_lock(&frame->mutex);
    if (frame->measurements_count >= MAX_MEASUREMENTS) {
        free(frame->measurements);
        frame->measurements = calloc(MAX_MEASUREMENTS * 2, sizeof(ChannelQualityMeasurement*));
        if (!frame->measurements) {
            pthread_mutex_unlock(&frame->mutex);
            return;
        }
    }

    frame->measurements[frame->measurements_count] = malloc(sizeof(ChannelQualityMeasurement));
    if (!frame->measurements[frame->measurements_count]) {
        free(frame->measurements);
        frame->measurements = NULL;
        pthread_mutex_unlock(&frame->mutex);
        return;
    }

    frame->measurements[frame->measurements_count]->timestamp = timestamp;
    frame->measurements[frame->measurements_count]->quality = quality;
    frame->measurements_count++;
    pthread_mutex_unlock(&frame->mutex);
}
```

