using System;
using System.Data;
using System.Data.Common;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Text.RegularExpressions;

namespace QueryExecutor
{
    public class QueryTemplate
    {
        public string Template { get; set; }
        public Type ParameterType { get; set; }
        public List<Constraint> Constraints { get; set; }
        public string ExternalSource { get; set; }
    }

    public class Constraint
    {
        public string Name { get; set; }
        public Func<object, bool> Predicate { get; set; }
    }

    public interface IDataAccessor
    {
        IDbConnection GetConnection();
    }

    public class QueryExecutor : IDataAccessor
    {
        private readonly Dictionary<string, QueryTemplate> _templates;
        private readonly Func<IDataReader, T> _externalValueProvider;

        public QueryExecutor(Dictionary<string, QueryTemplate> templates, Func<IDataReader, T> externalValueProvider)
        {
            _templates = templates;
            _externalValueProvider = externalValueProvider;
        }

        private IDbCommand CreateCommand(QueryTemplate template, params object[] parameters)
        {
            var command = GetConnection().CreateCommand();
            command.CommandText = template.Template;

            for (int i = 0; i < parameters.Length; i++)
            {
                var param = command.CreateParameter();
                param.Value = parameters[i];
                command.Parameters.Add(param);
            }

            return command;
        }

        private T ExtractValue<T>(IDataReader reader, int index)
        {
            var valueType = Nullable.GetUnderlyingType(typeof(T)) ?? typeof(T);
            if (reader[index] == DBNull.Value) return default;

            if (valueType == typeof(string))
                return reader[index].ToString();

            return (T)Convert.ChangeType(reader[index], valueType);
        }

        public IDataReader ExecuteQuery(string queryTemplateName, params object[] parameters)
        {
            if (!_templates.TryGetValue(queryTemplateName, out var template))
                throw new ArgumentException($"Unknown query template '{queryTemplateName}'.");

            ValidateParameters(parameters, template);

            using (var connection = GetConnection())
            {
                var command = CreateCommand(template, parameters);

                var externalParameterIndexes = new List<int>();
                for (int i = 0; i < command.Parameters.Count; i++)
                {
                    if (command.Parameters[i].Source == ParameterSource.User) continue;

                    if (template.Constraints.Any(c => c.Name == command.Parameters[i].ParameterName))
                        externalParameterIndexes.Add(i);
                }

                var externalValues = new Dictionary<int, object>();

                foreach (var index in externalParameterIndexes)
                {
                    if (!CanExecuteExternalQuery(command, index)) continue;

                    var dataReader = ExecuteExternalQuery(command, index);
                    if (dataReader == null) continue;

                    externalValues[index] = _externalValueProvider(dataReader);
                }

                foreach (var externalValue in externalValues.Values)
                    command.Parameters[externalParameterIndexes.Find(i => externalValues.Keys.Contains(i))].Value = externalValue;

                using var reader = command.ExecuteReader();
                return reader;
            }
        }

        private void ValidateParameters(object[] parameters, QueryTemplate template)
        {
            if (parameters.Length != template.Constraints.Count)
                throw new ArgumentException("Incorrect number of parameters.");

            for (int i = 0; i < parameters.Length; i++)
            {
                var constraint = template.Constraints[i];
                if (!constraint.Predicate(parameters[i]))
                    throw new ArgumentException($"Invalid parameter '{constraint.Name}'.");
            }
        }

        private bool CanExecuteExternalQuery(IDbCommand command, int index)
        {
            var param = command.Parameters[index];
            return param.Source == ParameterSource.Expression && Regex.IsMatch(param.ParameterName, @"^\w+\.\w+$");
        }

        private IDataReader ExecuteExternalQuery(IDbCommand command, int index)
        {
            // Implementation for executing queries against external data sources
            throw new NotImplementedException();
        }
    }
}
