#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>

#define MAX_STRUCTURES 1024
#define PAGE_SIZE getpagesize(0, 0)

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct memory_manager {
    size_t allocated_size;
    size_t max_memory_bytes;
    void *mem_block;
    pthread_mutex_t lock;
    bool is_full;
};

void* allocate_aligned(size_t size, size_t alignment) {
    void *ptr = mmap(NULL, size + alignment - 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        return NULL;
    }
    size_t aligned_offset = alignment - ((size_t)ptr % alignment);
    return (char*)ptr + aligned_offset;
}

struct memory_manager* create_memory_manager(size_t max_memory_bytes) {
    struct memory_manager *mm = malloc(sizeof(struct memory_manager));
    if (!mm) {
        return NULL;
    }
    mm->max_memory_bytes = max_memory_bytes;
    mm->allocated_size = 0;
    mm->mem_block = allocate_aligned(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T), PAGE_SIZE);
    if (!mm->mem_block) {
        free(mm);
        return NULL;
    }
    pthread_mutex_init(&mm->lock, NULL);
    mm->is_full = false;
