typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

struct list {
    int size;
    Node** buckets;
    pthread_mutex_t mutex;
};

void init_list(struct list* list, int capacity) {
    list->size = 0;
    list->buckets = malloc(capacity * sizeof(Node*));
    for (int i = 0; i < capacity; ++i)
        list->buckets[i] = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("malloc failed");
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

bool find_and_update(struct list* list, const RNTI rnti, const NFAPI_CRC_INDICATION_PDU_T new_data) {
    pthread_mutex_lock(&list->mutex);
    int hash = rnti % list->buckets'length;
    Node* current = list->buckets[hash];
    Node** prev = &list->buckets[hash];

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            *prev = current->next;
            current->next = NULL;
            *prev = new_data;
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
        prev = &current->next;
        current = current->next;
    }

    Node* new_node = create_node(new_data);
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    *prev = new_node;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool remove(struct list* list, const RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    int hash = rnti % list->buckets'length;
    Node* current = list->buckets[hash];
    Node** prev = &list->buckets[hash];

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            *prev = current->next;
            pthread_mutex_unlock(&list->mutex);
            free(current);
            return true;
        }
        prev = &current->next;
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return false;
}

