// Define the NFAPI_CRC_INDICATION_PDU_T structure and required tags
typedef struct {
    uint32_t rxi_information_tag;
    uint16_t rnti;
    uint16_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a thread-safe container for the list of PDUs
using PDU_CONTAINER = tbb::concurrent_vector<NFAPI_CRC_INDICATION_PDU_T>;

// Global variables for logging and synchronization
static sem_t log_mutex;
static spdlog::logger g_logger;

// Function to create and populate the list of PDUs
void create_pdu_list(PDU_CONTAINER& pdu_list, size_t num_pdus) {
    // Initialize semaphore for logging synchronization
    if (sem_init(&log_mutex, 0, 1) != 0) {
        printf("Error initializing log mutex\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the logger
    g_logger = spdlog::get("pdu_list_logger");
    g_logger->set_level(spdlog::level::info);

    // Populate the list with PDUs
    for (size_t i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rxi_information_tag = i * 123456789; // Generate a unique RXI tag for each PDU
        pdu.rnti = i + 12345; // Generate a unique RNTI for each PDU
        pdu.crc_indication_rel8_tag = rand() % (1 << 16); // Randomly set CRC_INDICATION_REL8_TAG
        pdu.crcflag = rand() % 2; // Randomly set CRCFLAG

        // Lock the log mutex to ensure logs are written atomically
        sem_wait(&log_mutex);
        g_logger->info("Inserting PDU: {}", i);
        sem_post(&log_mutex);

        pdu_list.emplace_back(pdu);
    }
}

// Function to log critical events such as successful insertions and deletions
void log_event(const char* event, size_t index) {
    // Lock the log mutex to ensure logs are written atomically
    sem_wait(&log_mutex);
    g_logger->info("{}: {}", event, index);
    sem_post(&log_mutex);
}
```

