// Initialize S3 client
const s3 = new AWS.S3();

// Initialize Redis client for queueing and rate limiting
const redisClient = new Redis({ /* Your Redis connection configuration */ });

async function uploadFile(url) {
  let promise;

  // Check if more than 5 uploads are currently in progress, if so, enqueue the task
  const queue = redisClient.lpush('upload_queue', JSON.stringify({ url }));

  if (queue > 5) {
    // If the queue is full, return a promise that resolves after a short delay and enqueues itself again
    promise = new Promise((resolve, reject) => {
      setTimeout(() => {
        uploadFile(url).then(resolve).catch(reject);
      }, 1000); // Adjust the delay according to your system's requirements
    });
    return promise;
  }

  // Dequeue a task if available, otherwise wait for one to become available
  const task = await redisClient.rpop('upload_queue');

  try {
    if (task) {
      const { url: taskUrl } = JSON.parse(task);

      // Upload the file using S3 or your cloud storage service's SDK
      const params = { /* Your S3 upload parameters configuration */ };
      params.Bucket = 'your-bucket';
      params.Key = getFilenameFromURL(url);
      params.Body = await getFileFromURL(url);

      const result = await s3.upload(params).promise();

      // Log the upload progress and status
      console.log(`Uploaded ${result.Key} from ${taskUrl}`);

      return result.Location;
    } else {
      throw new Error('No tasks available in the queue');
    }
  } catch (error) {
    console.error(`Failed to upload file: ${url}, Error: ${error.message}`);

    // Re-enqueue the task with an error, so it can be retried later if needed
    await redisClient.lpush('upload_queue', JSON.stringify({ url, error }));

    // Return a rejected promise with an appropriate error message
    return Promise.reject(error);
  }
}

