public class ConfigHasher
{
    private readonly Dictionary<string, (object Value, string Hash)> _settings = new();
    private readonly JsonSerializerSettings _jsonSettings = new() { ContractResolver = new CamelCasePropertyNamesContractResolver() };
    private readonly ILogger _logger; // External logging system interface

