    public void AddSetting(string key, object value)
    {
        if (value == null || string.IsNullOrEmpty(key)) throw new ArgumentException("Key or value cannot be empty or null.");

        var serializedValue = JsonConvert.SerializeObject(value);
        var hash = BitConverter.ToString(MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(serializedValue)).Reverse()).ToLowerInvariant();

        _settings[key] = (value, hash);
    }

    public async Task<IEnumerable<KeyValuePair<string, object>>> VerifyHashesAsync()
    {
        var potentialCorruptions = new List<KeyValuePair<string, object>>();

        foreach (var setting in _settings)
        {
            var serializedSetting = JsonConvert.SerializeObject(setting.Value.Value);
            if (!BitConverter.ToString(MD5.Create().ComputeHash(Encoding.UTF8.GetBytes(serializedSetting)).Reverse()).ToLowerInvariant().Equals(setting.Value.Hash))
            {
                potentialCorruptions.Add(setting);
                _logger.LogError($"Potential data corruption detected for '{setting.Key}': Hash mismatch.", DateTime.UtcNow);
            }
        }

        return potentialCorruptions;
    }

    public async Task ExportCorruptedAsync(string outputFilePath, FileFormat format)
