                await JsonConvert.SerializeObjectAsync(corruptedSettings, _jsonSettings, writer);
                break;
            // Add more formats as needed (e.g., XML)
            default:
                throw new ArgumentOutOfRangeException(nameof(format), $"Unsupported format: {format}.");
        }
    }

    private enum FileFormat
    {
        Json,
        // Add more formats as needed (e.g., XML)
    }
}
