import java.nio.*;
import java.util.*;
import java.net.*;

class ConnectionPool {
    private final NetworkRandomGenerator generator;
    private int maxPoolSize = 100; // Configurable max pool size
    private ScheduledExecutorService executor;
    private ConcurrentHashMap<Integer, SelectionKey> connections;
    private AtomicInteger nextSocketId;

    public ConnectionPool(NetworkRandomGenerator generator) {
        this.generator = generator;
        this.connections = new ConcurrentHashMap<>();
        this.nextSocketId = new AtomicInteger(0);
        this.executor = Executors.newScheduledThreadPool(1);
        // Initialize periodic cleanup task (omitted for brevity)
    }

    public SelectionKey establishConnection(String host, int port, SocketChannel.Provider provider) throws IOException {
        int socketId = generator.nextInt();
        while (connections.containsKey(socketId)) {
            socketId = generator.nextInt();
        }
        Selector selector = Selector.open();
        SelectionKey key = provider.newChannel().register(selector, 0);
        key.attach(this);
        key.interestOps(SelectionKey.OP_CONNECT);
        SocketAddress address = new InetSocketAddress(host, port);
        key.connect(address);
        connections.put(socketId, key);
        return key;
    }

    // Implement connection state change handlers and graceful disconnection logic (omitted for brevity)
}
