#include <semaphore.h>
#include "logservice.h" // Central logging service interface
#define CONFIG_FILE "clinics.conf"
#define MAX_CLINICS 10000
#define CLEANUP_INTERVAL 60
typedef struct {
    int id;
    char status[32];
    char last_modified_ip[32];
    time_t last_modified;
    time_t timestamp;
} ClinicRecord;

sem_t lock; // Synchronization for concurrent updates
pthread_mutex_t config_lock; // Lock for config data access
void* config = NULL;
size_t config_len = 0;
bool loaded_config = false;

ClinicRecord clinics[MAX_CLINICS];
int next_id = 0;

void load_config() {
    int fd = open(CONFIG_FILE, O_RDONLY);
    if (fd == -1) {
        log("Error: Unable to open configuration file.");
        return;
    }
    config_len = lseek(fd, 0, SEEK_END);
    config = mmap(NULL, config_len, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    loaded_config = true;
}

void cleanup() {
    time_t now = time(NULL);
    for (int i = 0; i < next_id; ++i) {
        if ((now - clinics[i].last_modified) > CLEANUP_INTERVAL) {
            memmove(&clinics[i], &clinics[i+1], (next_id-i-1)*sizeof(ClinicRecord));
            --next_id;
        }
    }
}

void process_and_manage_clinic_data(int clinic_id, char *status) {
    sem_wait(&lock);
    if (!loaded_config && !load_config()) return;

    ClinicRecord *record = &clinics[next_id];
    strcpy(record->last_modified_ip, getenv("REMOTE_ADDR"));
    record->id = clinic_id;
    strcpy(record->status, status);
    record->timestamp = time(NULL);
    record->last_modified = record->timestamp;
    next_id++;

    logservice_log(clinic_id, status);

    sem_post(&lock);
}

int main() {
    load_config();
    pthread_mutex_init(&config_lock, NULL);

    while (1) {
        cleanup();
        sleep(CLEANUP_INTERVAL);
    }

    return 0;
}
```
