import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Deserializer {
    private static final int CHUNK_SIZE = 1024; // Adjust as needed for memory optimization

    public <T> T deserialize(byte[] data, Class<T> clazz) throws IOException, ClassNotFoundException, NoSuchAlgorithmException {
        ByteBuffer byteBuffer = ByteBuffer.wrap(data);
        MessageDigest md = MessageDigest.getInstance("MD5"); // Custom checksum mechanism
        byte[] checksum = new byte[md.digest().length];
        while (byteBuffer.hasRemaining()) {
            md.update(byteBuffer.get());
        }

        byte[] dataChunk = new byte[CHUNK_SIZE];
        int read;
        byte[] currentData = new byte[data.length]; // Buffer for deserialization
        int offset = 0;
        while ((read = byteBuffer.get(dataChunk)) != -1) {
            System.arraycopy(dataChunk, 0, currentData, offset, read);
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(currentData));
            try {
                T obj = clazz.getDeclaredConstructor().newInstance(); // Instantiate the class
                ois.resolveClass(clazz); // Ensure we're using the correct class for deserialization
                ois.defaultReadObject(); // Deserialize the object
                return obj;
            } catch (InstantiationException | IllegalAccessException | InvocationTargetException | NoSuchMethodException e) {
                throw new RuntimeException("Error instantiating or initializing deserialized object: " + clazz.getName(), e);
            } finally {
                ois.close();
            }
            offset += read;
        }

        // If the checksum is incorrect, handle it accordingly and throw an exception with a meaningful error message
        if (!Arrays.equals(checksum, md.digest())) {
            throw new IntegrityViolationException("Checksum mismatch in deserialized data");
        }
    }
}
