using Newtonsoft.Json;
using HttpClientFactory = Microsoft.Extensions.Http.HttpClientFactory;
using Metrics = YourNamespace.PerformanceMetrics;

public class DataService
{
    private readonly HttpClient _httpClient;
    private const string BaseUrlKey = "DataServiceBaseUrl";
    private const string AuthHeaderKey = "DataServiceAuthHeader";
    private const int MaxRetries = 5;
    private const double InitialBackoffSeconds = 1.0;
    private readonly TimeSpan _backoffIncrementSeconds = TimeSpan.FromSeconds(Math.Pow(2, MaxRetries));

    public DataService()
    {
        var httpFactory = new HttpClientFactory();
        _httpClient = httpFactory.CreateClient();
        ConfigureClient();
    }

    private void ConfigureClient()
    {
        _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd("YourApp/1.0");
        _httpClient.DefaultRequestHeaders.Accept.Add(new System.Net.Http.Headers.MediaTypeWithQualityHeaderValue("application/json"));
        _httpClient.DefaultRequestHeaders.TryAddWithoutValidation($"Authorization", Environment.GetEnvironmentVariable(AuthHeaderKey));
        _httpClient.BaseAddress = new Uri(Environment.GetEnvironmentVariable(BaseUrlKey));
    }

    public async Task<IDataReader> FetchDataAsync(byte[] data)
    {
        var semaphoreSlim = new SemaphoreSlim(1);
        CancellationTokenSource cancellationTokenSource = null;
        HttpResponseMessage response = null;

        try
        {
            cancellationTokenSource = new CancellationTokenSource();
            using (var content = new ByteArrayContent(data))
            {
                await semaphoreSlim.WaitAsync();
                response = await _httpClient.PostAsJsonAsync("/api/query", content, cancellationTokenSource.Token);
            }
        }
        finally
        {
            semaphoreSlim.Release();
        }

        if (!response.IsSuccessStatusCode)
        {
            var retryAttempt = MaxRetries - Interlocked.Decrement(ref _retriesOnError);
            if (retryAttempt > 0 && response.StatusCode != HttpStatusCode.NotFound)
            {
                await Task.Delay((int)(Backoff * TimeSpan.TicksPerSecond), cancellationTokenSource.Token);
                return await FetchDataAsync(data, cancellationTokenSource.Token);
            }
        }

        var queryResults = JsonConvert.DeserializeObject<QueryResponse>(await response.Content.ReadAsStringAsync());
        Metrics.RecordQueryDuration(queryResults.QueryDuration);
        return queryResults.Data;
    }

    private int _retriesOnError = MaxRetries;
    private double Backoff => Math.Min(_backoffIncrementSeconds.TotalSeconds, InitialBackoffSeconds + _backoffIncrementSeconds * (double)_retriesOnError);
}

public class QueryResponse
{
    public TimeSpan QueryDuration { get; set; }
    public DataTableReader Data { get; set; }
}
```

